#!/usr/bin/env node

// One janitor pass, as one command.
//
// `janitor.md` used to specify four separate invocations — `report.mjs`,
// `release-claim.mjs`, `cleanup.mjs`, `lease.mjs --sweep` — with nothing
// verifying that all four ran. On 2026-08-03 they did not: session
// `rp-janitor-20260803b` held `refs/heads/rallypoint-sessions/janitor` from
// 17:19:55Z while three leases sat `targetGone` (`pr-888-merger`,
// `pr-888-reviewer`, `pr-892-reviewer`), every one of them deletable by the
// sweep step. A pass ran and a step was skipped, and the only way to notice was
// to read the next report by hand.
//
// A checklist that is followed four times out of five is a checklist that
// silently drops a fifth of the maintenance. This makes the pass mechanical:
// one command, every step, each step's exit code reported. Priority labels are
// audited here too: the rubric is only authoritative while every open issue
// carries exactly one of them.
//
// Two properties matter more than tidiness:
//
// - **A failing step does not abort the rest.** The steps are independent
//   maintenance, not a pipeline: a stale claim that cannot be released is no
//   reason to leave dead leases behind. Every step runs, and the pass reports
//   the worst outcome at the end.
// - **Nothing here decides eligibility.** It dispatches to the commands that
//   already prove it, and each keeps its own refusals and exit codes. This
//   file must never grow a rule of its own about when a claim is stale — that
//   judgement lives in `release-claim.mjs`, which refuses rather than guesses.
//
// `--dry-run` is passed through to every step that has one, so a whole pass can
// be previewed before any of it is performed.

import { spawnSync } from "node:child_process";
import process from "node:process";
import { fileURLToPath } from "node:url";

export const EXIT = {
  ok: 0,
  usage: 1,
  incomplete: 2, // at least one step did not complete cleanly
};

const USAGE = "Usage: janitor-pass.mjs --agent-id <id> [--dry-run]";

/**
 * An empty or flag-shaped agent id is a usage error here, not something to pass
 * along. `release-claim.mjs` drops an empty `--agent-id` value and exits `1`,
 * which is outside this pass's tolerated set, so every issue in the survey
 * would fail in turn and print a usage banner. Catching it once is the whole
 * fix. `--agent-id --dry-run` is the same mistake wearing a value.
 *
 * @param {string[]} argv
 */
export const parseArgs = (argv) => {
  const dryRun = argv.includes("--dry-run");
  const at = argv.indexOf("--agent-id");
  const value = at === -1 ? undefined : argv[at + 1];
  const agentId =
    value === undefined || value === "" || value.startsWith("-")
      ? null
      : value;
  const rest = argv.filter(
    (candidate, index) =>
      candidate !== "--dry-run" && index !== at && index !== at + 1,
  );

  return { dryRun, agentId, ok: agentId !== null && rest.length === 0 };
};

/**
 * The issues a pass should *offer* to `release-claim.mjs`, from a
 * `report.mjs --json` survey.
 *
 * Offer, not release: this list is deliberately wider than the set that will
 * actually be released, because the command proves eligibility itself and
 * refuses harmlessly when a claim is not releasable. Deciding here which of
 * them qualifies would put a second copy of that rule in the repository, and
 * `provenance.mjs` already records how those copies drift apart.
 *
 * Two sources feed it:
 *
 * - `claimCandidates` — every `status:claimed` issue with no open pull request,
 *   whatever its age. Wider than the report's own `janitorCandidate` list on
 *   purpose: a session that claims, pushes, merges, and ends inside the window
 *   is releasable on settled-pull-request grounds while the age-based
 *   classification would never nominate it.
 * - `unclaimable` — an orphaned reservation on an issue that was moved to
 *   `status:blocked` without releasing it.
 *
 * Everything else the report classifies is deliberately not acted on:
 * `unreservedWithOpenPr` and `unclaimedWithOpenPr` take no janitor action at
 * all, and `stranded` is refused by the command by design so the fix stays
 * auditable. `wouldFailRecord` is likewise inert here: its recovery is
 * an edit to a pull request body, which is authoring work rather than
 * coordination-state repair.
 *
 * @param {{
 *   disagreements?: { kind?: string, issue?: string }[],
 *   claimCandidates?: string[],
 * }} survey
 * @returns {string[]}
 */
export const releasableIssues = (survey) => [
  ...new Set([
    ...(survey.claimCandidates ?? []),
    ...(survey.disagreements ?? [])
      .filter((item) => item.kind === "unclaimable")
      .flatMap((item) => (item.issue === undefined ? [] : [item.issue])),
  ]),
];

/**
 * `report.mjs` remains the read-only nominator for stale assignees.
 * The release command re-reads the issue and proves the reservation ref absent
 * before it mutates anything; including every drift here deliberately avoids a
 * second, weaker copy of that eligibility rule in the pass.
 *
 * @param {{ disagreements?: { kind?: string, issue?: string }[] }} survey
 * @returns {string[]}
 */
export const staleAssigneeIssues = (survey) => [
  ...new Set(
    (survey.disagreements ?? [])
      .filter((item) => item.kind === "assigneeDrift")
      .flatMap((item) => (item.issue === undefined ? [] : [item.issue])),
  ),
];

/**
 * Cleared dependency holds nominated by the read-only report.
 * @param {{ disagreements?: { kind?: string, issue?: string }[] }} survey
 * @returns {string[]}
 */
export const clearedBlockerIssues = (survey) => [
  ...new Set(
    (survey.disagreements ?? [])
      .filter((item) => item.kind === "blockedWithClearedDependencies")
      .flatMap((item) => (item.issue === undefined ? [] : [item.issue])),
  ),
];

/**
 * The issues whose reservation `cleanup.mjs` should be offered.
 *
 * `cleanup.mjs` takes one closed issue at a time rather than sweeping, and the
 * survey does not report issue state directly — but an `unclaimable`
 * reservation is precisely one whose issue does not carry `status:claimed`,
 * which is the shape a closed issue leaves behind. Offering it the whole set
 * and letting it refuse an open one with its own `notClosed` exit keeps the
 * "is this closed" judgement in the command that already makes it.
 *
 * @param {{ disagreements?: { kind?: string, issue?: string }[] }} survey
 * @returns {string[]}
 */
export const cleanableIssues = (survey) => [
  ...new Set(
    (survey.disagreements ?? [])
      .filter((item) => item.kind === "unclaimable")
      .flatMap((item) => (item.issue === undefined ? [] : [item.issue])),
  ),
];

/**
 * Closed issues the survey found still carrying a stale `status:*` label
 * — `report.mjs`'s `closedWithStatusLabel` classification. Unlike
 * `cleanableIssues` above, this needs no cross-check against another source:
 * `classify` only ever emits this kind for an issue GitHub itself reports as
 * closed, so there is nothing here for a second command to confirm.
 *
 * @param {{ disagreements?: { kind?: string, issue?: string }[] }} survey
 * @returns {string[]}
 */
export const staleClosedLabelIssues = (survey) => [
  ...new Set(
    (survey.disagreements ?? [])
      .filter((item) => item.kind === "closedWithStatusLabel")
      .flatMap((item) => (item.issue === undefined ? [] : [item.issue])),
  ),
];

/**
 * @param {{
 *   steps: { name: string, code: number | null, tolerated?: number[] }[],
 * }} input
 * @returns {number}
 */
export const passExit = ({ steps }) =>
  steps.every((step) => step.code === 0 || (step.tolerated ?? []).includes(step.code ?? -1))
    ? EXIT.ok
    : EXIT.incomplete;

/**
 * @param {{
 *   argv: string[],
 *   run?: (script: string, args: string[]) => { code: number | null, stdout: string },
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const janitorPass = ({
  argv,
  run = defaultRun,
  stdout = console.log,
  stderr = console.error,
}) => {
  const args = parseArgs(argv);

  if (!args.ok) {
    stderr(USAGE);
    return EXIT.usage;
  }

  const dry = args.dryRun ? ["--dry-run"] : [];
  /** @type {{ name: string, code: number | null, tolerated?: number[] }[]} */
  const steps = [];

  /**
   * @param {string} name
   * @param {string} script
   * @param {string[]} scriptArgs
   * @param {number[]} [tolerated] Exit codes that are an outcome, not a fault.
   */
  const step = (name, script, scriptArgs, tolerated = []) => {
    const { code, stdout: output } = run(script, scriptArgs);
    stdout(`\n## ${name} (exit ${code})\n`);
    if (output.trim() !== "") stdout(output.trimEnd());
    steps.push({ name, code, tolerated });
    return { code, output };
  };

  // 1. Survey. `--json` because the release step below acts on the
  //    classifications; the prose form is for a human reading the same pass.
  //    Exit 2 is "disagreements found", which is the normal reason to run a
  //    pass at all, and 3 is "a source could not be read" — both are findings,
  //    not failures of the step.
  const survey = step("Coordination state", "report.mjs", ["--json"], [2, 3]);

  /** @type {{ disagreements?: { kind?: string, issue?: string }[] }} */
  let parsed = {};

  try {
    parsed = JSON.parse(survey.output);
  } catch {
    stderr(
      "The survey could not be parsed, so no claim release was attempted. The remaining steps still run.",
    );
    steps.push({ name: "Survey parse", code: 1 });
  }

  // 2. Release what the survey says is releasable. Every refusal code is
  //    tolerated: the command proves eligibility itself and refusing is the
  //    correct outcome for a claim that is not releasable yet. Only a code
  //    outside that set — a reservation that would not go (6), or a half-done
  //    release (7) — is a fault a pass should report.
  const releaseIssues = releasableIssues(parsed);

  for (const issue of releaseIssues) {
    step(
      `Release claim on #${issue}`,
      "release-claim.mjs",
      // `args.ok` above guarantees a non-empty, non-flag id; the fallback is
      // only here to satisfy the type, and an empty one can no longer reach it.
      ["--issue", issue, "--agent-id", args.agentId ?? "", ...dry],
      [2, 3, 4, 5],
    );
  }

  // 3. Assignees left after their claim reservation disappeared.
  //    The survey only offers the disagreement. `release-claim.mjs` uses the
  //    same exact-ref lookup as every other release path and acts immediately
  //    only when that ref is established absent. A live ref (exit 3) or an
  //    already-clean issue (exit 2) is a harmless refusal; unreadable evidence
  //    and a failed edit keep the pass visibly incomplete.
  for (const issue of staleAssigneeIssues(parsed).filter(
    (issue) => !releaseIssues.includes(issue),
  )) {
    step(
      `Stale assignee on #${issue}`,
      "release-claim.mjs",
      ["--issue", issue, "--agent-id", args.agentId ?? "", ...dry],
      [2, 3, 4, 5],
    );
  }

  // Cleared dependency holds. The command re-reads the body, labels, blockers,
  // and needs:human veto; the survey only nominates candidates.
  for (const issue of clearedBlockerIssues(parsed)) {
    step(
      `Cleared blockers on #${issue}`,
      "unblock-cleared.mjs",
      ["--issue", issue, ...dry],
      [2],
    );
  }

  // 4. Reservation refs for issues that are already closed. Exit 2 is
  //    `notClosed` — the issue is still open, so there is nothing here for this
  //    command — and 3 is a presence it could not establish. Both are the
  //    command declining, not failing.
  //
  //    `cleanup.mjs` has no `--dry-run`, and its argument parser reads only
  //    `--issue` and ignores everything else, so passing the flag through would
  //    not preview the delete — it would perform it. A dry run says what it
  //    would have offered instead.
  for (const issue of cleanableIssues(parsed)) {
    if (args.dryRun) {
      stdout(
        `\n## Closed-issue reservation for #${issue} (skipped)\n\nWould offer #${issue} to \`cleanup.mjs\`, which has no --dry-run of its own.`,
      );
      continue;
    }

    step(
      `Closed-issue reservation for #${issue}`,
      "cleanup.mjs",
      ["--issue", issue],
      [2, 3],
    );
  }

  // 5. Stale status:* labels left on issues that closed without passing
  //    through the claim protocol. `clearStatusLabels` re-confirms the
  //    issue is closed and re-reads its labels itself before touching
  //    anything, so an issue reopened between the survey and this step is
  //    refused with `notClosed` rather than acted on against a survey that is
  //    already stale.
  for (const issue of staleClosedLabelIssues(parsed)) {
    step(
      `Stale status label on closed #${issue}`,
      "clear-status-labels.mjs",
      ["--issue", issue, ...dry],
      [2, 3],
    );
  }

  // 6. Session leases whose target is gone or whose TTL has passed. Last
  //    because it is the step most easily forgotten when a pass is run as
  //    separate commands by hand, which is the whole reason this file exists.
  step("Session leases", "lease.mjs", ["--sweep", ...dry]);

  const code = passExit({ steps });

  stdout(`\n## Pass summary\n`);
  for (const { name, code: stepCode } of steps) {
    stdout(`- ${name}: exit ${stepCode}`);
  }
  stdout(
    code === EXIT.ok
      ? "\nEvery step completed."
      : "\nAt least one step did not complete cleanly; see its output above.",
  );

  return code;
};

/**
 * @param {string} script
 * @param {string[]} args
 */
const defaultRun = (script, args) => {
  const result = spawnSync(
    process.execPath,
    [fileURLToPath(new URL(script, import.meta.url)), ...args],
    { encoding: "utf8" },
  );

  return {
    code: result.status,
    stdout: `${result.stdout ?? ""}${result.stderr ?? ""}`,
  };
};

const invokedDirectly =
  process.argv[1] !== undefined &&
  import.meta.url === new URL(`file://${process.argv[1]}`).href;

if (invokedDirectly) {
  process.exit(janitorPass({ argv: process.argv.slice(2) }));
}

export default janitorPass;

#!/usr/bin/env node

// Acquires, releases, and sweeps session leases: the record of what an
// orchestrator has already dispatched, so a second survey over an unchanged
// board does not recommend the same session twice.
//
// Every rule — the ref shapes, the head binding, the TTL, and the refusal to
// read a failed lookup as a free target — lives in `lib/lease.mjs`; this file
// supplies argv, the parsed config, and a real `gh`.

import process from "node:process";

import { gh, loadConfig } from "./lib/gh.mjs";
import { lease } from "./lib/lease.mjs";

process.exit(lease({ argv: process.argv.slice(2), config: loadConfig(), gh }));

// A `gh`-shaped transport that speaks the GitHub REST API directly.
//
// Every Rallypoint script reaches GitHub through one seam — `gh(...args) =>
// string` — and until now the only implementation of it shelled out to the `gh`
// binary. Cloud agent sessions have no `gh`, so those scripts failed outright
// with `spawnSync gh ENOENT`. This is a second implementation of the same
// seam: same synchronous signature, same stringly JSON output, same throw-on-
// failure contract, so no script logic changes.
//
// Three parts of the contract matter more than they look:
//
//  1. **It must throw on a failed request.** `claim.mjs` takes its atomic
//     reservation by POSTing a ref and treating a throw as "another session got
//     there first". A transport that returned an error object instead would hand
//     two sessions the same issue.
//  2. **Output must match `gh --json` exactly**, not the REST shapes underneath.
//     `gh` reports issue state as `CLOSED` where REST says `closed`, and
//     `cleanup.mjs` compares against the former — get this wrong and a
//     reservation is never released. Each translation below is there because a
//     caller depends on that spelling.
//  3. **An unrecognised command throws by name.** Guessing at a command this
//     module has not been taught is how a coordination script silently does
//     something other than what it says.
//
// The surface is deliberately only what `claim.mjs`, `cleanup.mjs`, and
// `review.mjs` actually call. `close-referenced-issues.mjs` is not included: it
// runs in Actions where `gh` exists, and has never been affected by any of this.

/** An API call the transport wants performed. */
/**
 * @typedef {{
 *   method: string,
 *   path: string,
 *   body?: unknown,
 * }} ApiRequest
 */

/**
 * @typedef {{
 *   status: number,
 *   body: unknown,
 *   nextPath?: string | null,
 * }} ApiResponse
 */

/**
 * A request this module was not taught. Thrown rather than approximated: the
 * scripts read stdout as JSON, so a plausible-looking guess would be acted on.
 */
export class UnsupportedCommand extends Error {
  /** @param {string[]} args */
  constructor(args) {
    super(
      `The API transport does not implement \`gh ${args.join(" ")}\`. Add it to ` +
        ".rallypoint/scripts/lib/api.mjs rather than working around it — a " +
        "coordination command that half-runs is worse than one that fails.",
    );
    this.name = "UnsupportedCommand";
  }
}

/** A request that GitHub refused. Mirrors a non-zero `gh` exit. */
export class ApiError extends Error {
  /**
   * @param {ApiRequest} request
   * @param {ApiResponse} response
   */
  constructor(request, response) {
    const detail =
      typeof response.body === "object" && response.body !== null
        ? /** @type {{ message?: string }} */ (response.body).message
        : undefined;

    super(
      `${request.method} ${request.path} failed with ${response.status}` +
        (detail ? `: ${detail}` : "") +
        // The failure a cloud agent session actually hits, and the one whose
        // remedy is not in this repository. Saying so here saves the next
        // session rediscovering it.
        (detail?.includes("not enabled for this session")
          ? "\n\nThis session's credential is not authorized for the repository " +
            "API, so no Rallypoint command can reach GitHub from here. The " +
            "remedy is an org admin connecting the GitHub App for the " +
            "organization."
          : ""),
    );
    this.name = "ApiError";
    this.status = response.status;
  }
}

/**
 * Flags of the form `--flag value`, in order. Repeated flags are kept, because
 * `issue list --label a --label b` means both.
 *
 * @param {string[]} args
 * @param {string} flag
 */
const values = (args, flag) =>
  args.flatMap((entry, index) =>
    entry === flag && args[index + 1] !== undefined ? [args[index + 1]] : [],
  );

/**
 * @param {string[]} args
 * @param {string} flag
 */
const value = (args, flag) => values(args, flag).at(0);

/**
 * `gh --json a,b,c` returns only the requested fields. Building the full record
 * and then picking keeps each translation in one place and makes an unmapped
 * field an explicit failure rather than a silent `undefined`.
 *
 * @param {Record<string, unknown>} available
 * @param {string | undefined} requested
 * @param {string[]} args
 */
const pick = (available, requested, args) => {
  if (!requested) throw new UnsupportedCommand(args);

  /** @type {Record<string, unknown>} */
  const result = {};

  for (const field of requested.split(",")) {
    if (!(field in available)) throw new UnsupportedCommand(args);
    result[field] = available[field];
  }

  return result;
};

/**
 * `-f key=value` pairs, as `gh api` takes them. Values are strings; `gh` also
 * accepts typed `-F`, which no caller here uses.
 *
 * @param {string[]} args
 */
const fields = (args) => {
  /** @type {Record<string, string>} */
  const body = {};

  for (const pair of values(args, "-f")) {
    const at = pair.indexOf("=");
    if (at === -1) continue;
    body[pair.slice(0, at)] = pair.slice(at + 1);
  }

  return body;
};

/**
 * The transport. `request` performs one call and reports the status, the parsed
 * body, and the `Link: rel="next"` path when there is one; everything about how
 * that happens — sockets, proxies, credentials — stays outside this module so it
 * can be tested without any of them.
 *
 * @param {{
 *   request: (call: ApiRequest) => ApiResponse,
 *   repository: string,
 * }} input
 * @returns {(...args: string[]) => string}
 */
export const createTransport = ({ request, repository }) => {
  /**
   * @param {ApiRequest} call
   * @returns {unknown}
   */
  const send = (call) => {
    const response = request(call);

    // Mirrors `gh`: a failed request is a non-zero exit, which `execFileSync`
    // turns into a throw. Callers depend on that — see the reservation POST.
    if (response.status < 200 || response.status >= 300) {
      throw new ApiError(call, response);
    }

    return response.body;
  };

  /**
   * Follows `Link: rel="next"` and concatenates the pages, which is what
   * `gh api --paginate` does for an array response.
   *
   * @param {ApiRequest} call
   * @returns {unknown[]}
   */
  const sendPaginated = (call) => {
    /** @type {unknown[]} */
    const pages = [];
    /** @type {string | null | undefined} */
    let path = call.path;

    while (path) {
      const response = request({ ...call, path });

      if (response.status < 200 || response.status >= 300) {
        throw new ApiError({ ...call, path }, response);
      }

      pages.push(response.body);
      path = response.nextPath;
    }

    return pages;
  };

  const authenticatedLogin = () =>
    /** @type {{ login: string }} */ (send({ method: "GET", path: "/user" })).login;

  /** @param {string} assignee `@me`, which is the only form any caller uses. */
  const resolveAssignee = (assignee, /** @type {string[]} */ args) => {
    if (assignee !== "@me") throw new UnsupportedCommand(args);
    return authenticatedLogin();
  };

  return (...args) => {
    const [group, command, ...rest] = args;
    const base = `/repos/${repository}`;

    // gh repo view --json nameWithOwner[,defaultBranchRef]
    if (group === "repo" && command === "view") {
      const repo = /** @type {{ full_name: string, default_branch: string }} */ (
        send({ method: "GET", path: base })
      );

      return JSON.stringify(
        pick(
          {
            nameWithOwner: repo.full_name,
            defaultBranchRef: { name: repo.default_branch },
          },
          value(args, "--json"),
          args,
        ),
      );
    }

    // gh issue list --state open --label … --limit … --json …
    if (group === "issue" && command === "list") {
      const query = new URLSearchParams({
        state: value(args, "--state") ?? "open",
        per_page: value(args, "--limit") ?? "30",
      });
      const labels = values(args, "--label");

      if (labels.length > 0) query.set("labels", labels.join(","));

      const issues = /** @type {Record<string, unknown>[]} */ (
        send({ method: "GET", path: `${base}/issues?${query}` })
      );

      return JSON.stringify(
        issues
          // The REST issues list includes pull requests; `gh issue list` does
          // not. Without this, `claim.mjs` could reserve a pull request number.
          .filter((issue) => !("pull_request" in issue))
          .map((issue) => pick(issueFields(issue), value(args, "--json"), args)),
      );
    }

    // gh issue view <n> --json state|comments|…
    if (group === "issue" && command === "view") {
      const issue = /** @type {Record<string, unknown>} */ (
        send({ method: "GET", path: `${base}/issues/${rest[0]}` })
      );
      const requested = value(args, "--json")?.split(",") ?? [];
      const available = issueFields(issue);

      // Comments are a separate resource, so only fetch them when asked.
      if (requested.includes("comments")) {
        available.comments = /** @type {unknown[]} */ (
          sendPaginated({
            method: "GET",
            path: `${base}/issues/${rest[0]}/comments?per_page=100`,
          }).flat()
        );
      }

      return JSON.stringify(pick(available, value(args, "--json"), args));
    }

    // gh issue comment <n> --body <text>
    if (group === "issue" && command === "comment") {
      send({
        method: "POST",
        path: `${base}/issues/${rest[0]}/comments`,
        body: { body: value(args, "--body") },
      });
      return "";
    }

    // gh issue edit <n> [--add-assignee @me] [--remove-assignee @me]
    //                   [--add-label L] [--remove-label L]
    //
    // `gh` performs this as one mutation; REST needs up to four calls. A failure
    // partway through throws, which `claim.mjs` compensates for by restoring the
    // issue and releasing its reservation — the same handling it already has for
    // a failed `gh issue edit`.
    if (group === "issue" && command === "edit") {
      const issue = rest[0];

      for (const assignee of values(args, "--add-assignee")) {
        send({
          method: "POST",
          path: `${base}/issues/${issue}/assignees`,
          body: { assignees: [resolveAssignee(assignee, args)] },
        });
      }

      for (const assignee of values(args, "--remove-assignee")) {
        send({
          method: "DELETE",
          path: `${base}/issues/${issue}/assignees`,
          body: { assignees: [resolveAssignee(assignee, args)] },
        });
      }

      const added = values(args, "--add-label");

      if (added.length > 0) {
        send({
          method: "POST",
          path: `${base}/issues/${issue}/labels`,
          body: { labels: added },
        });
      }

      for (const label of values(args, "--remove-label")) {
        // A label that is not present is not an error for `gh`, and callers
        // remove a label without first checking it is there.
        try {
          send({
            method: "DELETE",
            path: `${base}/issues/${issue}/labels/${encodeURIComponent(label)}`,
          });
        } catch (error) {
          if (!(error instanceof ApiError) || error.status !== 404) throw error;
        }
      }

      return "";
    }

    // gh pr view <n> --json …
    if (group === "pr" && command === "view") {
      const pull =
        /** @type {{ number: number, body: string | null, labels: unknown[], head: { sha: string, ref: string }, base?: { ref: string }, user: { login: string, type: string } | null }} */ (
          send({ method: "GET", path: `${base}/pulls/${rest[0]}` })
        );

      return JSON.stringify(
        pick(
          {
            number: pull.number,
            body: pull.body,
            labels: pull.labels,
            headRefOid: pull.head.sha,
            headRefName: pull.head.ref,
            // Read by `isPromotionBranch` for the snapshot promotion shape
            //: a `promotion/*` head is a promotion only when it
            // targets the promotion branch.
            baseRefName: pull.base?.ref ?? null,
            // `gh pr view --json author` reports `{ login, is_bot, ... }` with
            // the `[bot]` suffix stripped; REST reports
            // `user: { login: "dependabot[bot]", type: "Bot" }`. Only `login`
            // and `is_bot` are read (`isDependabotAuthor` in provenance.mjs),
            // and it accepts either spelling of the login, so the two
            // transports agree on whether a pull request is bot-authored.
            author: pull.user
              ? { login: pull.user.login, is_bot: pull.user.type === "Bot" }
              : null,
          },
          value(args, "--json"),
          args,
        ),
      );
    }

    // gh pr edit <n> --add-label|--remove-label <label>
    //
    // Labels on a pull request are issue labels, which is also why this needs no
    // pull-request-specific route.
    if (group === "pr" && command === "edit") {
      const added = values(args, "--add-label");

      if (added.length > 0) {
        send({
          method: "POST",
          path: `${base}/issues/${rest[0]}/labels`,
          body: { labels: added },
        });
      }

      for (const label of values(args, "--remove-label")) {
        try {
          send({
            method: "DELETE",
            path: `${base}/issues/${rest[0]}/labels/${encodeURIComponent(label)}`,
          });
        } catch (error) {
          if (!(error instanceof ApiError) || error.status !== 404) throw error;
        }
      }

      return "";
    }

    // gh pr review <n> --comment --body <text>
    //
    // Only COMMENT. APPROVE and REQUEST_CHANGES are refused by GitHub from a
    // pull request's own author, and every session here shares one identity
    //, so `review.mjs` never asks for them.
    if (group === "pr" && command === "review") {
      if (!args.includes("--comment")) throw new UnsupportedCommand(args);

      send({
        method: "POST",
        path: `${base}/pulls/${rest[0]}/reviews`,
        body: { event: "COMMENT", body: value(args, "--body") },
      });
      return "";
    }

    // gh api [--method M] [--paginate] [--slurp] <path> [-f k=v]…
    if (group === "api") {
      const method = value(args, "--method") ?? "GET";
      // The path is the first bare argument: everything else is a flag or a
      // flag's value.
      const flagged = new Set(
        args.flatMap((entry, index) =>
          ["--method", "-f", "--jq"].includes(entry) ? [index + 1] : [],
        ),
      );
      const path = args
        .slice(1)
        .find(
          (entry, index) => !entry.startsWith("-") && !flagged.has(index + 1),
        );

      if (!path) throw new UnsupportedCommand(args);

      const body = fields(args);
      const call = {
        method,
        path: path.startsWith("/") ? path : `/${path}`,
        ...(Object.keys(body).length > 0 ? { body } : {}),
      };

      if (args.includes("--paginate")) {
        const pages = sendPaginated(call);
        // `--slurp` keeps the pages as an array of arrays; without it `gh`
        // concatenates them.
        return JSON.stringify(args.includes("--slurp") ? pages : pages.flat());
      }

      const response = send(call);

      // A 204 has no body. `gh` prints nothing, and the DELETE callers ignore
      // stdout entirely.
      return response === undefined || response === null
        ? ""
        : JSON.stringify(response);
    }

    throw new UnsupportedCommand(args);
  };
};

/**
 * The `gh issue`-flavoured view of a REST issue.
 *
 * `state` is the one to be careful with: `gh` reports `OPEN`/`CLOSED` and
 * `cleanup.mjs` compares against `CLOSED`, so lower-casing it here would stop
 * every reservation from being released.
 *
 * @param {Record<string, unknown>} issue
 * @returns {Record<string, unknown>}
 */
const issueFields = (issue) => ({
  number: issue.number,
  title: issue.title,
  body: issue.body,
  labels: issue.labels,
  assignees: issue.assignees,
  state: String(issue.state ?? "").toUpperCase(),
});

export default createTransport;

// Making a claim visible on the remote from its first minute.
//
// ## Why this exists
//
// A janitor decides whether a claim is abandoned from what it can see, and
// almost everything it can see comes from GitHub. A worker, meanwhile, commits
// locally and pushes late — so a live session doing real work is indis-
// tinguishable from a dead one until it pushes something. A janitor running on
// the worker's own machine can consult `git worktree list` and tell the
// difference; a janitor running anywhere else cannot, and is left with exactly
// the GitHub-only evidence that was misleading in the first place.
//
// The beacon closes that gap at the one moment the protocol still has the
// session's attention. When `claim.mjs` records a claim, it also publishes the
// branch it just prescribed, pointing at the integration branch tip. From then
// on the claim is visible to every observer on every host, not just the one the
// worker happens to be sitting at.
//
// ## What this does not do
//
// It does not keep the signal fresh. A beacon pushed at the moment of the claim
// goes stale at exactly the same moment the claim comment does, so it extends
// `release-claim.mjs`'s "no issue branch moved inside `staleClaimHours`" guard
// by precisely zero minutes. Only a branch that keeps moving does that, and
// nothing here can make a worker push again — `claim.mjs` is the last point
// where the protocol holds the session's hand.

/**
 * @typedef {{
 *   integrationBranch?: string,
 *   branchPrefix: string,
 * }} BeaconPushConfig
 */

/** @param {unknown} error */
const describe = (error) =>
  error instanceof Error ? error.message.split("\n")[0] : String(error);

/**
 * Publish the branch a claim just prescribed, pointing at the integration
 * branch tip.
 *
 * Best-effort by design: every failure path reports and returns rather than
 * throwing, because the claim itself has already succeeded by the time this
 * runs and an unpublished branch is a weaker signal, not a broken claim.
 *
 * @param {{
 *   branch: string,
 *   config: BeaconPushConfig,
 *   git: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} options
 * @returns {{ pushed: boolean, reason: string }}
 */
export const beaconPush = ({
  branch,
  config,
  git,
  stdout = () => {},
  stderr = () => {},
}) => {
  const integration = config.integrationBranch ?? "main";
  const remoteIntegration = `origin/${integration}`;

  let head;
  try {
    head = git("rev-parse", "HEAD");
  } catch (error) {
    const reason = `HEAD could not be read (${describe(error)})`;
    stderr(`No beacon push: ${reason}.`);
    return { pushed: false, reason };
  }

  // The whole justification for the `--no-verify` below. Not a heuristic and
  // not advisory: a HEAD the remote integration branch does not already contain
  // is a commit this repository's pre-push checks have a real opinion about, so
  // it does not get a free ride. Nothing is pushed in that case — falling back
  // to a verified push would block a claim for however long those checks take,
  // which is worse than no beacon.
  try {
    git("merge-base", "--is-ancestor", head, remoteIntegration);
  } catch {
    const reason =
      `HEAD (${head.slice(0, 8)}) is not already contained in ` +
      `${remoteIntegration}, so pushing it would skip this repository's ` +
      "pre-push checks for commits they have not seen";
    stderr(`No beacon push: ${reason}. Push the branch yourself instead.`);
    return { pushed: false, reason };
  }

  // Created so the worker can `git checkout` it immediately. An existing branch
  // of the same name is left exactly as it is — it may be another worktree's
  // checkout, and this is not the place to move anybody's branch.
  try {
    git("rev-parse", "--verify", "--quiet", `refs/heads/${branch}`);
  } catch {
    try {
      git("branch", branch, head);
    } catch (error) {
      stderr(`Local branch ${branch} could not be created: ${describe(error)}.`);
    }
  }

  // An explicit refspec rather than a checkout: `claim.mjs` runs in the
  // worker's own tree and must not move it. `--no-verify` is safe here and only
  // here, by the ancestry proof above.
  try {
    git("push", "--no-verify", "origin", `${head}:refs/heads/${branch}`);
  } catch (error) {
    const reason = `push failed (${describe(error)})`;
    stderr(
      `No beacon push: ${reason}. The claim stands; push ${branch} yourself.`,
    );
    return { pushed: false, reason };
  }

  stdout(`CLAIM_BRANCH_PUSHED=${branch}`);
  return { pushed: true, reason: "published at the integration branch tip" };
};

export default beaconPush;

// The `Blocked-By:` trailer, and the rule that clears `status:blocked` once
// every issue it names has closed. Every call to `gh` is injected, so the
// decision is testable without a live GitHub.
//
// `docs/AGENT_LOOP.md` has always defined `status:blocked` as "a dependency
// prevents progress; work resumes on its own once that dependency clears".
// Nothing implemented "on its own". Every consumer of the label —
// `lib/claim.mjs`, `lib/release-claim.mjs`, `close-referenced-issues.mjs`,
// `janitor-pass.mjs`, `lib/report.mjs` — either filters the issue out or
// refuses to remove a hold label over it, and no code path anywhere removed
// the label when a dependency closed, so every removal was a human noticing by
// hand. The cost compounds: three issues naming one blocker stay invisible to
// `claim.mjs` after that blocker closes, until somebody goes looking, and
// anything gated behind those three inherits the stall transitively. An epic
// arc gated on `status:blocked` has no mechanism to advance past its own first
// merge, and nothing reports the stall — a blocked issue whose blocker closed
// is indistinguishable on every board from one whose blocker is still open.
//
// Two rules carry the whole design, and both fail closed:
//
// - **An issue with no `Blocked-By:` trailer is never auto-unblocked.** The
//   absence of a declaration is not evidence that nothing blocks it. Blockers
//   are routinely declared in prose, and frequently without a number at all —
//   a complete-looking declaration may name no issue anywhere in the body — so
//   a sweep that guessed would guess wrong on most of the board.
// - **A partially-cleared trailer changes nothing.** All or nothing, so an
//   issue behind two dependencies is not queued the moment the first lands.
//
// `needs:human` vetoes the flip outright, and that long-standing precedent is not
// weakened here: a worker that stood down and recorded
// `needs:human` recorded a judgement no automated writer may overrule, and
// putting such an issue back in the claimable pool is precisely the loop this
// protocol has gone round before. The veto still posts its comment, because an operator
// wanting to know the trailer cleared is exactly who the veto is holding the
// issue for.

// Exit codes are a public interface, as they are for `cleanup.mjs`,
// `clear-status-labels.mjs`, and `release-claim.mjs`. Keep them in sync with
// the table in docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  declined: 2, // nothing to do: no trailer, not blocked, or a blocker still open
  inconclusive: 3, // a source could not be read, or the trailer is unparseable
  editFailed: 4, // the flip was decided and the edit failed
};

/**
 * Stamped into every comment this module posts, so a later pass can tell it has
 * already spoken. The unblocking path is idempotent without it — it removes the
 * label, so the issue leaves the swept set — but the `needs:human` veto is not:
 * that issue keeps `status:blocked` on purpose and would otherwise collect one
 * identical comment per janitor pass, forever.
 */
export const BLOCKED_BY_MARKER = "<!-- rallypoint:blocked-by -->";

/**
 * Matches a `Blocked-By:` trailer on **one line of the original body**, which
 * `visibleLines` below has already judged to be outside every code and comment
 * construct. Applied per line and deliberately not global or multiline: the
 * only line start it can ever see is one the author's own newline put there.
 *
 * The anchor carries two of the exclusions on its own, and both are properties
 * of the line's own leading characters rather than of anything around it:
 *
 * - **Inline** — `` `Blocked-By: #42` `` — a backtick is not leading
 *   whitespace, so the anchor never reaches the keyword.
 * - **Indented** — `    Blocked-By: #42` — excluded by the `{0,3}` bound,
 *   which is not an arbitrary line: it is CommonMark's own indented-code rule,
 *   where four or more spaces of indentation opens a code block. Three still
 *   parse, because three render as prose. A **tab** is excluded outright rather
 *   than counted, for the same rule: CommonMark expands a tab to the next
 *   four-column stop, so a leading tab is already four columns of indentation
 *   however it is written. `>` for a blockquote is likewise not whitespace.
 *
 * The bound errs toward not matching in the one place CommonMark's rule is
 * softer than this — an indented line cannot interrupt a paragraph, so
 * `    Blocked-By: #1` on the line directly below prose is a lazy continuation
 * rather than a code block, and is live text this regex nonetheless skips. That
 * is the fail-closed direction: a missed declaration leaves `status:blocked` in
 * place and `report.mjs` says so, where a false one issues a real label edit.
 */
const TRAILER = /^[ ]{0,3}blocked-by[ \t]*:(.*)$/i;

// A fence opener: up to three spaces of indentation, then three or more
// backticks or tildes. The run length is captured because CommonMark requires a
// closing fence to be **at least as long** as the opener — the rule three
// rounds of this parser did not implement, and the one a four-backtick fence
// quoting a three-backtick fence depends on. For a backtick fence the info
// string may not itself contain a backtick.
const FENCE_OPEN = /^ {0,3}(`{3,}|~{3,})(.*)$/;

/**
 * Whether `line` closes a fence opened by `marker`: the same character, at
 * least as many of them, and nothing after it but spaces and tabs. A fence line
 * with trailing content — ` ```Blocked-By: #42 ` — is content of the open
 * block, not a closing fence, so this returns false and the line stays code.
 *
 * @param {string} line
 * @param {string} marker
 */
const closesFence = (line, marker) => {
  const match = line.match(/^ {0,3}(`+|~+)[ \t]*$/);
  return (
    match !== null && match[1][0] === marker[0] && match[1].length >= marker.length
  );
};

// The characters a backslash can escape, which is CommonMark's ASCII
// punctuation set. A backslash before anything else — a letter, a space, a
// newline — is a literal backslash and consumes nothing.
const ASCII_PUNCTUATION = /[!"#$%&'()*+,\-./:;<=>?@[\\\]^_`{|}~]/;

// The angle-bracket constructs that outrank a code span when they start first:
// CommonMark's autolinks and raw HTML. Written as one sticky alternation so the
// scan below can ask "does an inert construct start exactly here?" in place.
//
// Every production is CommonMark's own, and two details of them are load-
// bearing rather than incidental. An unquoted attribute value **excludes** the
// backtick, so `<span id=`z>` is not a tag and its backtick stays a real run —
// `gh api /markdown` agrees. And an unterminated `<span title=x` is not a tag
// either, so nothing there is taken out of play.
const TAG_NAME = "[A-Za-z][A-Za-z0-9-]*";
const ATTRIBUTE_NAME = "[A-Za-z_:][A-Za-z0-9_.:-]*";
const ATTRIBUTE_VALUE = "[^\"'=<>`\\s]+|'[^']*'|\"[^\"]*\"";
const ATTRIBUTE = `(?:\\s+${ATTRIBUTE_NAME}(?:\\s*=\\s*(?:${ATTRIBUTE_VALUE}))?)`;
const INERT_ANGLE = new RegExp(
  [
    // A URI autolink, then an email autolink; a backtick is legal in both.
    "<[A-Za-z][A-Za-z0-9+.-]{1,31}:[^<>\\x00-\\x20]*>",
    "<[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9]" +
      "(?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?" +
      "(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*>",
    // An open tag, a closing tag, a comment, a processing instruction, a
    // declaration, and a CDATA section.
    `<${TAG_NAME}${ATTRIBUTE}*\\s*/?>`,
    `</${TAG_NAME}\\s*>`,
    "<!--[\\s\\S]*?-->",
    "<\\?[\\s\\S]*?\\?>",
    "<![A-Za-z][\\s\\S]*?>",
    "<!\\[CDATA\\[[\\s\\S]*?\\]\\]>",
  ].join("|"),
  "y",
);

/**
 * The ranges of `text` covered by a **closed** inline code span, so a paragraph
 * that opens a span on one line and closes it on a later one hides everything
 * between — including a line that begins at column zero.
 *
 * This approximates CommonMark's backtick pairing rule: each run is tried as an
 * opener against the next later run of equal length. When none exists, that
 * opener is literal text and the next run is tried instead. That restart is
 * load-bearing for `[1, 2, 2]`: the unmatched one-backtick run is literal, then
 * the two-backtick runs form the real span. It also preserves `[1, 2, 1]`, where
 * the first and last runs pair across the unequal middle run.
 *
 * **The pairing rule above is exact CommonMark and was verified against
 * `gh api /markdown` over every arrangement of one to four runs of length one
 * to three across a three-line paragraph — 546 bodies, zero disagreements.** Do
 * not tune it. What round five found wrong was not the pairing but the *run
 * scan* feeding it, which matched every backtick character in the raw text and
 * so counted runs CommonMark never created: a backslash-escaped backtick, a
 * backtick in an autolink destination, and a backtick in a quoted raw-HTML
 * attribute value. Three tests pinned the case where such a phantom run *forms*
 * a bogus span, which is the harmless direction. The dangerous one is that a
 * phantom run **pairs off a real one**, leaving a genuine run free to open a
 * multi-line span that swallows the trailer — GitHub renders the declaration as
 * code, this parser read it as live, and it drove a real label edit.
 *
 * So the scan is a single left-to-right pass rather than a regex over the whole
 * text, because which characters are even eligible to be a run depends on what
 * precedes them. At each position, in CommonMark's own precedence order:
 *
 * - A **backslash escape** consumes the punctuation character after it, so an
 *   escaped backtick opens nothing.
 * - An **autolink or raw HTML tag** consumes itself, because both outrank a
 *   code span that has not already opened.
 * - A **backtick run** searches forward for its equal-length partner.
 *
 * The forward search for a closer is deliberately **raw** — it sees neither
 * escapes nor angle constructs — because code span content is literal, so a
 * span that opened first swallows both. `` `foo\`bar` `` closing on the escaped
 * backtick is CommonMark's own worked example, and
 * `` `x <https://e.com/`b> c` `` closing inside the autolink was confirmed
 * against the renderer. Precedence here is purely first-come-first-served, and
 * a single pass is what expresses that.
 *
 * @param {string} text
 * @returns {{ start: number, end: number }[]}
 */
const codeSpans = (text) => {
  /** @type {{ start: number, end: number }[]} */
  const spans = [];
  let cursor = 0;

  while (cursor < text.length) {
    if (text[cursor] === "\\") {
      cursor += ASCII_PUNCTUATION.test(text[cursor + 1] ?? "") ? 2 : 1;
      continue;
    }

    if (text[cursor] === "<") {
      INERT_ANGLE.lastIndex = cursor;
      const inert = INERT_ANGLE.exec(text);
      cursor += inert === null ? 1 : inert[0].length;
      continue;
    }

    if (text[cursor] !== "`") {
      cursor += 1;
      continue;
    }

    let openerEnd = cursor;
    while (text[openerEnd] === "`") openerEnd += 1;

    const length = openerEnd - cursor;
    let closerIndex = -1;

    for (let scan = openerEnd; scan < text.length; scan += 1) {
      if (text[scan] !== "`") continue;

      let runEnd = scan;
      while (text[runEnd] === "`") runEnd += 1;

      if (runEnd - scan === length) {
        closerIndex = runEnd;
        break;
      }

      scan = runEnd - 1;
    }

    if (closerIndex === -1) {
      // No equal-length partner, so this run is literal text and the next run
      // is tried as an opener instead.
      cursor = openerEnd;
      continue;
    }

    spans.push({ start: cursor, end: closerIndex });
    // Scanning resumes *after* the closer, so a run consumed as a closer is
    // never also tried as an opener.
    cursor = closerIndex;
  }

  return spans;
};

/**
 * The lines of `body` a reader of the rendered issue can actually see as prose,
 * paired with their 1-based line numbers.
 *
 * **This is the whole of the fix for a defect class that recurred three
 * times**, and the reason it cannot recur is the shape of the function rather
 * than the cases it happens to enumerate. The
 * previous approach rewrote the body — `withoutCode` **deletes** fenced regions
 * — and then anchored a pattern to `^` in the result. A deletion joins the text
 * either side of it, so it can manufacture a line start the source never had,
 * which is precisely the one thing a line-start anchor is trusted not to see.
 * Every round found a new way to make it do so: a fence, then an indented
 * block, then a four-backtick fence whose inner three-backtick line was
 * mistaken for its close, promoting the trailer to column zero of a line that
 * does not exist in the body at all.
 *
 * So nothing here rewrites anything. The body is split on its own newlines
 * once, each line is classified where it stands, and the trailer pattern is
 * applied to whole lines that survived. Line identity comes from the author's
 * newlines and from nowhere else, so no transformation exists that could invent
 * one. Construct classification is a separate, deliberately approximate layer:
 * when it skips too much, the missed declaration leaves `status:blocked` in
 * place and `report.mjs` says so under `holdWithoutReason`; it must never be
 * described as a complete CommonMark renderer.
 *
 * Four constructs hide a line, and the residual limits are stated exactly
 * rather than as a general assurance about "every form markdown offers" — the
 * documentation overclaimed in each of the three rounds, so it is enumerated
 * here and in `docs/AGENT_LOOP.md` and nowhere else:
 *
 * - **Fenced code**, opener length tracked, closing fence required to be at
 *   least as long and to carry nothing but trailing whitespace, per CommonMark.
 * - **An unterminated fence**, which CommonMark ends at the end of the
 *   document — so its tail is code and is hidden. This module can take that
 *   reading where `withoutCode` deliberately cannot: `linkedIssues` would lose
 *   the `Closes #<issue>` line after a stray fence in a pull request body,
 *   which fails **open** for that caller, whereas hiding the tail fails closed
 *   for this one.
 * - **HTML comments**, including multi-line and unterminated ones. A commented
 *   trailer renders as nothing at all, so reading it would let invisible text
 *   issue a label edit. For a multi-line comment, the closing line's tail is
 *   deliberately skipped too even though CommonMark renders that tail; this is
 *   a documented fail-closed missed declaration, not invisible text.
 * - **A multi-line inline code span**, approximated by `codeSpans`, which a code
 *   fence scanner alone does not see. Equal-length backtick runs pair across
 *   lines; an unmatched candidate is literal and scanning restarts at the next
 *   run. This is the subset needed to keep a rendered code line from declaring.
 *
 * Indented code and a leading backtick or `>` are the anchor's, not this
 * function's; see `TRAILER`.
 *
 * **The residual limit is this function's, not `codeSpans`'s**, and it is a
 * block boundary rather than an inline one. A paragraph ends here only at a
 * blank line or a fence, so a list item boundary and an ATX heading are both
 * invisible to it and a run either side of one can pair across it where GitHub
 * pairs nothing. Both are pinned in the test file and both hide more than the
 * renderer does, which is the fail-closed direction — but that is the state of
 * the evidence, not a proof that no fail-open case is left. Five consecutive
 * rounds wrote a sentence here promising more than the code did, and each was
 * falsified by the next review.
 *
 * The alternative weighed and rejected was to read the trailer only from the
 * body's last paragraph, the way Git trailers and this repository's own
 * `Migration-Removal-Ok:` convention work. It narrows the surface by
 * construction rather than by enumeration, and all five trailers on the board
 * are the last non-empty line of their
 * body, so nothing live would have stopped parsing on the day. It is rejected
 * on two counts. It does not replace this scan — a body whose pasted example is
 * the last thing in it puts a fenced trailer in the last paragraph — so it
 * would be a second rule on top, not instead. And it silently unparses a
 * declaration the moment anybody appends a note below it, which is the failure
 * the reviewer of round three named as worse than the hole: a declaration that
 * stops being read reports nothing to the operator who wrote it.
 *
 * @param {string} body
 * @returns {{ number: number, text: string }[]}
 */
const visibleLines = (body) => {
  /** @type {{ number: number, text: string }[]} */
  const visible = [];
  /** @type {string | null} */
  let fence = null;
  let inComment = false;
  /** @type {{ number: number, text: string }[]} */
  let paragraph = [];

  // A code span cannot contain a blank line, so a paragraph is the largest
  // region one can hide, and resolving them a paragraph at a time keeps an
  // unmatched backtick from reaching past the blank line below it.
  const flush = () => {
    if (paragraph.length === 0) return;

    const text = paragraph.map((line) => line.text).join("\n");
    const spans = codeSpans(text);
    let offset = 0;

    for (const line of paragraph) {
      const start = offset;
      offset += line.text.length + 1;

      if (spans.some((span) => span.start < start && start < span.end)) continue;

      visible.push(line);
    }

    paragraph = [];
  };

  let number = 0;

  for (const raw of String(body ?? "").split("\n")) {
    number += 1;
    // A CRLF body is the same document; the carriage return is not content.
    const text = raw.endsWith("\r") ? raw.slice(0, -1) : raw;

    if (fence !== null) {
      if (closesFence(text, fence)) fence = null;
      continue;
    }

    if (inComment) {
      // Deliberately skip the whole closing line. CommonMark renders text after
      // `-->`, so this may miss a live declaration; keeping the issue blocked is
      // the safer error than reconstructing a tail into an automated label edit.
      if (text.includes("-->")) inComment = false;
      continue;
    }

    const opener = text.match(FENCE_OPEN);

    if (opener !== null && !(opener[1][0] === "`" && opener[2].includes("`"))) {
      fence = opener[1];
      flush();
      continue;
    }

    // Complete comments on this line are removed before asking whether an
    // unterminated one opens; `<!-- note --> Blocked-By: #1` does not.
    const withoutComments = text.replace(/<!--[\s\S]*?-->/g, "");

    if (withoutComments.includes("<!--")) {
      inComment = true;
      // The text before `<!--` is visible, and a trailer may live in it.
      paragraph.push({ number, text: withoutComments.split("<!--")[0] });
      flush();
      continue;
    }

    if (withoutComments.trim() === "") {
      flush();
      continue;
    }

    paragraph.push({ number, text: withoutComments });
  }

  flush();

  return visible;
};

/**
 * The first informative line of a `gh` failure. `execFileSync` puts the useful
 * part on `stderr` and leaves `message` as the command line. Copied from
 * `lib/clear-status-labels.mjs` rather than shared, for the same reason that
 * one copied it: a two-line helper is cheaper duplicated than a module every
 * Rallypoint script has to import.
 *
 * @param {unknown} error
 */
export const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr ?? detail.message ?? error ?? "").trim();
  return (
    text
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/**
 * @typedef {(
 *   | { kind: "absent" }
 *   | { kind: "declared", blockers: string[], line: string }
 *   | { kind: "unparseable", line: string | null, reason: string }
 * )} Declaration
 */

/**
 * The `Blocked-By:` declaration in an issue body.
 *
 * Three outcomes, and only `declared` can ever lead to a mutation. `absent` is
 * the common case and is silent — most `status:blocked` issues predate this
 * convention and several are held for reasons no trailer could express.
 * `unparseable` is reported and never acted on: a trailer somebody meant to
 * write and got wrong is the one case where guessing at intent would put a held
 * issue back in the pool.
 *
 * Two trailers are unparseable rather than merged. A second line is as likely
 * to be a stale copy as an addition, and "which of these two lists is the
 * blocker set" is not a question this module may answer by concatenation.
 *
 * The parser approximates the CommonMark constructs relevant to a declaration;
 * it is not a renderer. The named exclusions are fenced code (of any fence
 * length), an unterminated fence's tail, indented code, equal-run inline code
 * spans on one line or across several, HTML comments, and blockquotes.
 * `visibleLines` carries the block-level ones and `TRAILER`'s anchor the
 * line-leading ones. It also deliberately skips the visible tail on a
 * multi-line HTML comment's closing line. Every skipped live declaration fails
 * closed by leaving `status:blocked` in place, so this list describes the
 * approximation rather than promising equivalence with a CommonMark renderer.
 *
 * The reason any of it matters is that this repository quotes its own
 * conventions in the text it then parses, and `docs/AGENT_LOOP.md` documents
 * the trailer with an example any issue may paste. Left unstripped, a body
 * reading "held pending an operator ruling" plus that example resolved to
 * `action: "unblock"` and issued a real
 * `gh issue edit --remove-label status:blocked`, which
 * is the exact failure this module exists to prevent: a block cleared that
 * nobody cleared. No body on the board tripped any of the three holes, and the
 * fix was cheaper each time than the first body that would have.
 *
 * @param {string | null | undefined} body
 * @returns {Declaration}
 */
export const parseBlockedBy = (body) => {
  // `match` returns an array, so it is collected rather than flat-mapped: a
  // `flatMap` would spread each match's own capture groups into the list.
  const matches = visibleLines(String(body ?? ""))
    .map((line) => line.text.match(TRAILER))
    .filter((match) => match !== null);

  if (matches.length === 0) return { kind: "absent" };

  if (matches.length > 1) {
    return {
      kind: "unparseable",
      line: matches.map((match) => match[0].trim()).join(" / "),
      reason: `${matches.length} \`Blocked-By:\` lines are present; exactly one is expected, and merging them would guess at which list is current`,
    };
  }

  const line = matches[0][0].trim();
  const value = matches[0][1].trim();

  if (value === "") {
    return {
      kind: "unparseable",
      line,
      reason: "the `Blocked-By:` line names no issue",
    };
  }

  /** @type {string[]} */
  const blockers = [];
  /** @type {string[]} */
  const bad = [];

  for (const entry of value.split(",")) {
    const trimmed = entry.trim();
    const number = trimmed.match(/^#?(\d+)$/)?.[1];

    if (number === undefined) {
      bad.push(trimmed === "" ? "(empty entry)" : trimmed);
      continue;
    }

    if (!blockers.includes(number)) blockers.push(number);
  }

  if (bad.length > 0) {
    return {
      kind: "unparseable",
      line,
      reason: `${bad.map((entry) => `\`${entry}\``).join(", ")} is not an issue number; the trailer takes comma-separated \`#<number>\` entries only`,
    };
  }

  return { kind: "declared", blockers, line };
};

/**
 * @typedef {(
 *   | { state: "OPEN" | "CLOSED", pullRequests: number[] }
 *   | { state: "unknown", reason: string }
 * )} BlockerState
 */

/**
 * Each blocker's state, and the pull requests GitHub records as having closed
 * it, read one issue at a time.
 *
 * The closing pull requests come from `closedByPullRequestsReferences`, which
 * older `gh` builds do not offer. A field a `gh` cannot serve must not turn the
 * whole read into an unknown — that would fail the sweep closed on every host
 * with an older CLI — so the call is retried without it and the evidence
 * comment says the pull request was not recorded instead of naming one.
 *
 * A read that fails outright is `unknown`, never folded into "closed". This is
 * the module's whole safety property: an unreadable blocker holds the issue
 * exactly where it is.
 *
 * @param {{ gh: (...args: string[]) => string, blockers: string[] }} input
 * @returns {Map<string, BlockerState>}
 */
export const readBlockerStates = ({ gh, blockers }) => {
  /** @type {Map<string, BlockerState>} */
  const states = new Map();

  for (const blocker of blockers) {
    /** @type {{ state?: string, closedByPullRequestsReferences?: unknown } | null} */
    let details = null;
    /** @type {string | null} */
    let failure = null;

    try {
      details = JSON.parse(
        gh(
          "issue",
          "view",
          blocker,
          "--json",
          "state,closedByPullRequestsReferences",
        ),
      );
    } catch (error) {
      failure = describeError(error);

      try {
        details = JSON.parse(gh("issue", "view", blocker, "--json", "state"));
        failure = null;
      } catch (fallbackError) {
        failure = describeError(fallbackError);
      }
    }

    if (details === null) {
      states.set(blocker, {
        state: "unknown",
        reason: `\`gh issue view ${blocker}\` failed: ${failure ?? "no detail reported"}`,
      });
      continue;
    }

    const state = details.state;

    if (state !== "OPEN" && state !== "CLOSED") {
      states.set(blocker, {
        state: "unknown",
        reason: `#${blocker} reported state \`${String(state)}\`, which is neither OPEN nor CLOSED`,
      });
      continue;
    }

    const references = Array.isArray(details.closedByPullRequestsReferences)
      ? details.closedByPullRequestsReferences
      : [];

    states.set(blocker, {
      state,
      pullRequests: references.flatMap(
        (/** @type {{ number?: unknown }} */ reference) =>
          typeof reference?.number === "number" ? [reference.number] : [],
      ),
    });
  }

  return states;
};

/**
 * @typedef {{
 *   action: "unblock" | "veto" | "hold" | "skip" | "report",
 *   reason: string,
 *   blockers: string[],
 *   open: string[],
 *   unknown: string[],
 * }} Decision
 */

/**
 * Whether an issue's `status:blocked` may be cleared, from state already read.
 *
 * Ordered so that every fail-closed reason is reached before any reason to act.
 * `report` means a human should look and nothing is touched; `skip` and `hold`
 * are ordinary silence.
 *
 * @param {{
 *   issue: string,
 *   labels: unknown,
 *   declaration: Declaration,
 *   blockerStates: Map<string, BlockerState>,
 *   config: { labels: { blocked: string, human: string } },
 * }} input
 * @returns {Decision}
 */
export const resolveUnblock = ({
  issue,
  labels,
  declaration,
  blockerStates,
  config,
}) => {
  /** @type {Decision} */
  const base = { action: "skip", reason: "", blockers: [], open: [], unknown: [] };

  // Presence is decided from what was read, never inferred from a removal's own
  // failure — `close-referenced-issues.mjs`'s `restoreToQueue` states the same
  // rule. A payload that is not an array is not an empty one.
  if (!Array.isArray(labels)) {
    return {
      ...base,
      action: "report",
      reason: `#${issue}'s labels could not be read as a list, so whether it carries \`${config.labels.blocked}\` cannot be established.`,
    };
  }

  const names = labels.flatMap((label) =>
    typeof label?.name === "string" ? [label.name] : [],
  );

  if (!names.includes(config.labels.blocked)) {
    return {
      ...base,
      reason: `#${issue} does not carry \`${config.labels.blocked}\`.`,
    };
  }

  if (declaration.kind === "absent") {
    return {
      ...base,
      reason: `#${issue} carries no \`Blocked-By:\` trailer, so nothing establishes what blocks it; it is left alone.`,
    };
  }

  if (declaration.kind === "unparseable") {
    return {
      ...base,
      action: "report",
      reason: `#${issue}'s \`Blocked-By:\` trailer could not be parsed — ${declaration.reason}. The line reads \`${declaration.line}\`. Nothing was changed.`,
    };
  }

  const { blockers } = declaration;
  const unknown = blockers.filter(
    (blocker) => (blockerStates.get(blocker)?.state ?? "unknown") === "unknown",
  );

  if (unknown.length > 0) {
    return {
      ...base,
      action: "report",
      blockers,
      unknown,
      reason: `#${issue}'s blockers could not all be read (${unknown
        .map((blocker) => `#${blocker}`)
        .join(", ")}), so whether its trailer has cleared cannot be established. Nothing was changed.`,
    };
  }

  const open = blockers.filter(
    (blocker) => blockerStates.get(blocker)?.state === "OPEN",
  );

  if (open.length > 0) {
    return {
      ...base,
      action: "hold",
      blockers,
      open,
      reason: `#${issue} stays blocked: ${open
        .map((blocker) => `#${blocker}`)
        .join(", ")} of its \`Blocked-By:\` trailer ${open.length === 1 ? "is" : "are"} still open.`,
    };
  }

  if (names.includes(config.labels.human)) {
    return {
      ...base,
      action: "veto",
      blockers,
      reason: `#${issue}'s \`Blocked-By:\` trailer has cleared, but it carries \`${config.labels.human}\`, which holds it out of the pool regardless.`,
    };
  }

  return {
    ...base,
    action: "unblock",
    blockers,
    reason: `#${issue}'s \`Blocked-By:\` trailer has cleared; every issue it names is closed.`,
  };
};

/**
 * How one blocker reads in the evidence comment: the issue, and the pull
 * request GitHub records as having closed it where there is one.
 *
 * @param {{ blocker: string, state: BlockerState | undefined }} input
 * @returns {string}
 */
const describeBlocker = ({ blocker, state }) => {
  const pulls =
    state && state.state !== "unknown" ? state.pullRequests : [];

  return pulls.length === 0
    ? `#${blocker} (closed; no closing pull request recorded)`
    : `#${blocker} (closed by ${pulls.map((pull) => `#${pull}`).join(", ")})`;
};

/**
 * The comment posted when a trailer clears — every Rallypoint mutation leaves
 * its evidence on the issue, and this one has to name what it read, because the
 * next reader's question is always "which dependency, and how do you know".
 *
 * The vetoed wording says plainly that the issue is **not** back in the pool.
 * An older `close-referenced-issues.mjs` bug was a comment asserting a
 * requeue that had not happened; a comment here that read as a requeue would be
 * the same defect in a new place.
 *
 * @param {{
 *   issue: string,
 *   decision: Decision,
 *   blockerStates: Map<string, BlockerState>,
 *   config: { labels: { blocked: string, human: string } },
 * }} input
 * @returns {string}
 */
export const unblockComment = ({ issue, decision, blockerStates, config }) => {
  const evidence = decision.blockers.map(
    (blocker) => `- ${describeBlocker({ blocker, state: blockerStates.get(blocker) })}`,
  );

  if (decision.action === "veto") {
    return [
      BLOCKED_BY_MARKER,
      `**\`Blocked-By:\` cleared, and the issue is still held.** Every issue #${issue}'s trailer names is now closed:`,
      "",
      ...evidence,
      "",
      `\`${config.labels.blocked}\` was **not** removed because this issue carries \`${config.labels.human}\`. That label records a judgement an automated writer may not overrule, so the dependency clearing changes nothing about who may act next.`,
      "",
      `Whoever clears \`${config.labels.human}\` owns the requeue: remove it then. Claimability is derived from the absence of hold labels. This comment exists so the signal is not lost — the dependency this issue was waiting on has landed.`,
    ].join("\n");
  }

  return [
    BLOCKED_BY_MARKER,
    `**Unblocked.** Every issue #${issue}'s \`Blocked-By:\` trailer names is now closed:`,
    "",
    ...evidence,
    "",
    `\`${config.labels.blocked}\` removed, so \`claim.mjs\` can offer this issue again. Claimability is derived from the absence of hold labels. Nothing else about it was changed — no assignee was touched and no reservation was created.`,
    "",
    "If something still blocks this issue, add `status:blocked` back and say what in a `Blocked-By:` line; a trailer naming an open issue is never cleared.",
  ].join("\n");
};

/**
 * Whether this module has already commented on an issue. Only the veto path
 * needs it — see `BLOCKED_BY_MARKER`.
 *
 * @param {unknown} comments
 * @returns {boolean}
 */
export const alreadyCommented = (comments) =>
  Array.isArray(comments) &&
  comments.some((comment) =>
    String(comment?.body ?? "").includes(BLOCKED_BY_MARKER),
  );

/**
 * Performs a decision. Returns the exit code the decision maps to, so both
 * callers — the single-issue command and the sweep — agree on what each outcome
 * means without restating the mapping.
 *
 * The label edit goes first and the comment second, deliberately. A failure
 * between them leaves an issue that is genuinely queued with no comment saying
 * why, which a reader can still act on; the reverse leaves a comment asserting a
 * requeue that did not happen, which is that defect exactly.
 *
 * @param {{
 *   gh: (...args: string[]) => string,
 *   issue: string,
 *   decision: Decision,
 *   blockerStates: Map<string, BlockerState>,
 *   comments: unknown,
 *   config: { labels: { blocked: string, human: string } },
 *   dryRun?: boolean,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number}
 */
export const applyDecision = ({
  gh,
  issue,
  decision,
  blockerStates,
  comments,
  config,
  dryRun = false,
  stdout = console.log,
  stderr = console.error,
}) => {
  if (decision.action === "report") {
    stderr(decision.reason);
    return EXIT.inconclusive;
  }

  if (decision.action === "skip" || decision.action === "hold") {
    stdout(decision.reason);
    return EXIT.declined;
  }

  if (decision.action === "veto") {
    if (alreadyCommented(comments)) {
      stdout(
        `${decision.reason} A \`Blocked-By:\` comment is already on the issue, so nothing was posted again.`,
      );
      return EXIT.declined;
    }

    if (dryRun) {
      stdout(`Would comment on #${issue}: ${decision.reason}`);
      return EXIT.declined;
    }

    try {
      gh(
        "issue",
        "comment",
        issue,
        "--body",
        unblockComment({ issue, decision, blockerStates, config }),
      );
    } catch (error) {
      stderr(
        `Could not comment on #${issue} (${describeError(error)}). No label was changed.`,
      );
      return EXIT.editFailed;
    }

    stdout(decision.reason);
    return EXIT.declined;
  }

  if (dryRun) {
    stdout(
      `Would remove \`${config.labels.blocked}\` from #${issue}: ${decision.reason}`,
    );
    return EXIT.ok;
  }

  try {
    gh(
      "issue",
      "edit",
      issue,
      "--remove-label",
      config.labels.blocked,
    );
  } catch (error) {
    stderr(
      `Could not requeue #${issue} (${describeError(error)}). No comment was posted.`,
    );
    return EXIT.editFailed;
  }

  try {
    gh(
      "issue",
      "comment",
      issue,
      "--body",
      unblockComment({ issue, decision, blockerStates, config }),
    );
  } catch (error) {
    stderr(
      `#${issue} was requeued, but its evidence comment could not be posted (${describeError(error)}).`,
    );
    return EXIT.editFailed;
  }

  stdout(
    `Requeued #${issue}: removed \`${config.labels.blocked}\` (blockers ${decision.blockers
      .map((blocker) => `#${blocker}`)
      .join(", ")} are all closed).`,
  );
  return EXIT.ok;
};

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  const index = argv.indexOf("--issue");
  return {
    issue: index === -1 ? undefined : argv[index + 1],
    dryRun: argv.includes("--dry-run"),
  };
};

/**
 * The single-issue command, `unblock-cleared.mjs`. `janitor-pass.mjs` offers it
 * every issue `report.mjs` classified as `blockedWithClearedDependencies`, and
 * it re-proves the condition itself against a fresh read rather than trusting a
 * survey that is already seconds old — the same shape `clear-status-labels.mjs`
 * follows for `closedWithStatusLabel`.
 *
 * @param {{
 *   argv: string[],
 *   gh: (...args: string[]) => string,
 *   config: { labels: { blocked: string, human: string } },
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const unblockCleared = ({
  argv,
  gh,
  config,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { issue, dryRun } = parseArgs(argv);

  if (!issue) {
    stderr("Usage: unblock-cleared.mjs --issue <issue-number> [--dry-run]");
    return EXIT.usage;
  }

  /** @type {{ state?: string, labels?: unknown, body?: string, comments?: unknown } | null} */
  let details = null;

  try {
    details = JSON.parse(
      gh("issue", "view", issue, "--json", "state,labels,body,comments"),
    );
  } catch (error) {
    stderr(`#${issue} could not be read (${describeError(error)}).`);
    return EXIT.inconclusive;
  }

  if (details?.state !== "OPEN") {
    stdout(
      `#${issue} is ${String(details?.state ?? "unknown").toLowerCase()}; a closed issue has no queue entry to restore.`,
    );
    return EXIT.declined;
  }

  const declaration = parseBlockedBy(details.body);
  const blockerStates =
    declaration.kind === "declared"
      ? readBlockerStates({ gh, blockers: declaration.blockers })
      : new Map();

  const decision = resolveUnblock({
    issue,
    labels: details.labels,
    declaration,
    blockerStates,
    config,
  });

  return applyDecision({
    gh,
    issue,
    decision,
    blockerStates,
    comments: details.comments,
    config,
    dryRun,
    stdout,
    stderr,
  });
};

/**
 * Every open `status:blocked` issue, with the fields a decision needs.
 *
 * @param {{ gh: (...args: string[]) => string, config: { labels: { blocked: string } } }} input
 * @returns {{ ok: true, items: { number: number, labels?: unknown, body?: string, comments?: unknown }[] } | { ok: false, reason: string }}
 */
export const listBlockedIssues = ({ gh, config }) => {
  try {
    const parsed = JSON.parse(
      gh(
        "issue",
        "list",
        "--state",
        "open",
        "--label",
        config.labels.blocked,
        "--limit",
        "100",
        "--json",
        "number,labels,body,comments",
      ),
    );

    return Array.isArray(parsed)
      ? { ok: true, items: parsed }
      : {
          ok: false,
          reason: `\`gh issue list --label ${config.labels.blocked}\` returned no list`,
        };
  } catch (error) {
    return {
      ok: false,
      reason: `\`gh issue list --label ${config.labels.blocked}\` failed: ${describeError(error)}`,
    };
  }
};

/**
 * Sweeps the `status:blocked` board for trailers a set of just-closed issues
 * cleared. This is what `close-referenced-issues.mjs` runs on every push to the
 * integration branch, which is the path that catches the ordinary case: a
 * dependency closes on merge, and its dependents are claimable in the same
 * minute rather than whenever somebody next goes looking.
 *
 * Scoped to issues whose trailer actually names one of `closedIssues`. A merge
 * has no standing to requeue an issue it had nothing to do with, and the
 * unscoped sweep is `janitor-pass.mjs`'s job — a blocker closed by hand, as a
 * duplicate, or by GitHub's own keyword handling never passes through here at
 * all, which is exactly why that backstop exists.
 *
 * A failure on one issue never stops the rest: these are independent repairs,
 * not a pipeline.
 *
 * `unparseable` is returned **separately from `reported`**, because an
 * unparseable trailer is the one finding here that cannot be scoped. Every
 * other outcome is reached only for an issue whose trailer names something this
 * merge closed; a trailer that does not parse has no blocker list to compare
 * against, so it is noticed board-wide or not at all. Folding it into `reported`
 * made `close-referenced-issues.mjs` exit non-zero on every push to the
 * integration branch for as long as one typo sat anywhere on the board — and
 * that exit code is the operator's only signal that the closing and reservation
 * cleanup this script exists for actually worked, currently read by hand after
 * every merge while the workflow is down. A permanent red for an unrelated
 * issue's typo is a signal nobody can read. It is still written to `stderr`, and
 * `report.mjs` surfaces it as an unknown, which is where a board-wide finding
 * belongs.
 *
 * @param {{
 *   gh: (...args: string[]) => string,
 *   config: { labels: { blocked: string, human: string } },
 *   closedIssues: string[],
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {{ requeued: string[], reported: string[], unparseable: string[], failed: string[] }}
 */
export const sweepClearedBlockers = ({
  gh,
  config,
  closedIssues,
  stdout = console.log,
  stderr = console.error,
}) => {
  /** @type {{ requeued: string[], reported: string[], unparseable: string[], failed: string[] }} */
  const outcome = { requeued: [], reported: [], unparseable: [], failed: [] };

  if (closedIssues.length === 0) return outcome;

  const listed = listBlockedIssues({ gh, config });

  if (!listed.ok) {
    stderr(
      `Could not sweep \`${config.labels.blocked}\` issues for cleared \`Blocked-By:\` trailers: ${listed.reason}`,
    );
    outcome.failed.push("listing");
    return outcome;
  }

  for (const item of listed.items) {
    const issue = String(item.number);
    const declaration = parseBlockedBy(item.body);

    if (declaration.kind === "unparseable") {
      stderr(
        `#${issue}'s \`Blocked-By:\` trailer could not be parsed — ${declaration.reason}. The line reads \`${declaration.line}\`. Nothing was changed.`,
      );
      outcome.unparseable.push(issue);
      continue;
    }

    if (declaration.kind === "absent") continue;

    if (!declaration.blockers.some((blocker) => closedIssues.includes(blocker))) {
      continue;
    }

    try {
      const blockerStates = readBlockerStates({
        gh,
        blockers: declaration.blockers,
      });
      const decision = resolveUnblock({
        issue,
        labels: item.labels,
        declaration,
        blockerStates,
        config,
      });
      const code = applyDecision({
        gh,
        issue,
        decision,
        blockerStates,
        comments: item.comments,
        config,
        stdout,
        stderr,
      });

      if (code === EXIT.ok) outcome.requeued.push(issue);
      else if (code === EXIT.inconclusive) outcome.reported.push(issue);
      else if (code === EXIT.editFailed) outcome.failed.push(issue);
    } catch (error) {
      stderr(
        `Could not evaluate #${issue}'s \`Blocked-By:\` trailer: ${describeError(error)}`,
      );
      outcome.failed.push(issue);
    }
  }

  return outcome;
};

export default unblockCleared;

// The atomic claim, with every call to `gh` injected.
//
// Assignment is not a lock: several agent sessions may share one GitHub
// identity, so `--add-assignee @me` proves nothing about who got there first.
// Creating `refs/heads/<claimRefPrefix><issue>` does, because GitHub refuses a
// second creation of the same ref. Everything in this module exists to keep that
// one guarantee: reserve before mutating, skip a contended issue without
// touching it, and release the reservation if the follow-up mutation fails.
//
// The ref cannot see one collision, though: an issue whose work is already in
// flight under an open pull request that never reserved anything. There is no
// ref to collide with, so a second session claims it, branches, implements, and
// opens a second pull request. `partitionCandidates` below filters those out in
// front of the reservation; it does not replace it.

import {
  referencingPullRequests,
  SAFE_AGENT_ID,
} from "../provenance.mjs";
import { ISSUE_PAGE, explainHold, isClaimable } from "./claimable.mjs";
import { openPullRequests } from "./release-claim.mjs";

/**
 * @typedef {{
 *   number: number,
 *   title: string,
 *   labels: { name: string }[],
 *   assignees: unknown[],
 * }} Issue
 */

/**
 * @typedef {{
 *   integrationBranch?: string,
 *   branchPrefix: string,
 *   claimRefPrefix: string,
 *   labels: { claimed: string, blocked?: string, deferred?: string, human?: string },
 * }} ClaimConfig
 */

export const EXIT = {
  ok: 0,
  usage: 1,
  noneAvailable: 2,
};

// Flags this parser recognises as taking a value. A bare issue number typed
// after the script name — `claim.mjs 858 --agent-id x` — reads, in English, as
// "claim issue 858", but nothing here ever consumed it: `values("--issue")`
// only looks for `--issue`, so the token was silently dropped and the run
// fell through to "claim whatever is next", handing out a different issue
// with no error. `strays` below is what makes that loud instead of
// silent.
const FLAGS_WITH_VALUE = ["--agent-id", "--issue", "--plan"];

/**
 * @param {string[]} argv Arguments after the script path.
 */
export const parseArgs = (argv) => {
  /** @param {string} flag */
  const values = (flag) =>
    argv.flatMap((value, index) =>
      value === flag && argv[index + 1] ? [argv[index + 1]] : [],
    );

  // Every argv index a recognised flag consumed as its value, so it is not
  // also counted as a stray positional below.
  const consumedValueIndices = new Set(
    FLAGS_WITH_VALUE.flatMap((flag) =>
      argv.flatMap((value, index) =>
        value === flag && argv[index + 1] !== undefined ? [index + 1] : [],
      ),
    ),
  );

  // Anything left that is not a `--flag` itself and was not consumed as one's
  // value is a positional argument this command has never supported. Report
  // it rather than discard it — an unrecognised `--flag` still passes through
  // untouched (the tolerant-scanner behaviour every Rallypoint entry point
  // documents), but a bare positional reads as an instruction and must not be
  // silently ignored.
  const strays = argv.filter(
    (value, index) =>
      !consumedValueIndices.has(index) && !value.startsWith("--"),
  );

  return {
    agentId: values("--agent-id").at(0),
    requestedIssue: values("--issue").at(0),
    // Three is the documented plan length; a longer list is truncated rather
    // than refused, because a verbose caller is not a broken one.
    plans: values("--plan").slice(0, 3),
    strays,
  };
};

/**
 * The rank an unlabelled issue sorts at: after every `prio:p0` … `prio:p9`.
 *
 * Deliberately not the middle of the scale. An issue nobody has prioritised
 * carries no claim about its own urgency, and the old two-level `priority()`
 * returned `2` for it — which under a ten-level scheme would have placed it
 * above seven real levels on the strength of having no label at all.
 */
const UNPRIORITISED = 10;

const PRIORITY_LABEL = /^prio:p([0-9])$/;

/**
 * The numeric level from an issue's `prio:p<n>` label.
 *
 * Parsed rather than enumerated, so adding a level to the scheme is a label and
 * a documentation change and not also a change here. It used to test for
 * `prio:p0` and `prio:p1` by name and return `2` for everything else, which was
 * lossy at one boundary while three levels existed and collapsed eight of them
 * into one rank once P0–P9 landed — a P9 nitpick would then have been
 * offered ahead of a P2 bug whenever it held the lower issue number, since that
 * is the tie-break this falls through to.
 *
 * Two `prio:` labels resolve to the more urgent, so ordering does not depend on
 * the order GitHub happens to return labels in. That is damage control for a
 * mislabelled issue, not a supported way to label one.
 *
 * @param {Issue} issue
 */
const priority = (issue) =>
  issue.labels.reduce((lowest, label) => {
    const match = PRIORITY_LABEL.exec(label?.name ?? "");
    return match ? Math.min(lowest, Number(match[1])) : lowest;
  }, UNPRIORITISED);

/**
 * Why a specifically-named issue was not offered, decided from a read of the
 * issue itself.
 *
 * Thin wrapper over `explainHold`, kept as a named export because it is the
 * shape `claim.mjs`'s refusal path and its tests both address. The whole of the
 * judgement lives in `lib/claimable.mjs` so that this command and `report.mjs`
 * cannot drift on what "claimable" means — the drift that produced
 * `readyWithoutTask`, an issue the report advertised and this command could
 * never offer.
 *
 * Returns `null` when nothing explains it, so the caller falls back to its
 * ordinary message rather than asserting a cause it did not establish.
 *
 * @param {{
 *   issue: { state?: string, labels?: unknown, assignees?: unknown } | null,
 *   number: string,
 *   config: { labels: Record<string, string | undefined> },
 * }} input
 * @returns {string | null}
 */
export const explainUnavailable = ({ issue, number, config }) =>
  explainHold({ issue, number, config });

/**
 * Highest priority first, then oldest issue number.
 *
 * Every exclusion is now a *negative* label test, which is why this filters in
 * JavaScript rather than in the `gh issue list` query: that query can only
 * express labels an issue must **have**. Before the readiness label was removed the positive
 * `task` + `status:ready` pair carried most of the work and only `needs:human`
 * was filtered here; now the hold set — `status:claimed`, `status:blocked`,
 * `status:deferred`, `needs:human` — is the whole of the rule, so all of it
 * lives here.
 *
 * `config` is **required**, and deliberately not optional the way the previous
 * `humanLabel` parameter was. That allowance was safe only because the query
 * pre-narrowed candidates to `task` + `status:ready`: an un-updated caller still
 * got a sane pool, and the missing label merely failed to narrow it further.
 * With the pool defined by absence, the same fallback would *widen* it to every
 * open unassigned issue — handing out `status:claimed` and `needs:human` work —
 * so the failure mode inverted from "slightly too broad" to "no exclusions at
 * all". A fallback that fails open is worse than a missing argument that
 * throws.
 *
 * @param {{
 *   issues: Issue[],
 *   requestedIssue?: string,
 *   config: { labels: Record<string, string | undefined> },
 * }} input
 */
export const selectCandidates = ({ issues, requestedIssue, config }) =>
  issues
    .filter((issue) => isClaimable(issue, config))
    .filter(
      (issue) => !requestedIssue || String(issue.number) === requestedIssue,
    )
    .sort(
      (left, right) =>
        priority(left) - priority(right) || left.number - right.number,
    );

/**
 * Splits the ordered candidate list into the issues nothing is already working
 * and the ones an open pull request already references.
 *
 * The reservation ref is the only real atomicity guarantee and this does not
 * touch it; this is a filter in front of it, for the state the ref cannot see.
 * A claimable issue with an open pull request and no reservation —
 * `report.mjs`'s `unclaimedWithOpenPr`, or `unreservedWithOpenPr` when a claim
 * comment survives the missing ref — passes both of `claim.mjs`'s
 * existing filters, so a second session is handed work that is already in
 * flight and only finds out when somebody next runs the report.
 *
 * A listing that could not be established fires nothing. The same rule
 * cuts both ways: an error, a non-array body, or a response that filled its
 * page is no more evidence of a pull request's *presence* than of its absence,
 * so an unreadable listing leaves every candidate claimable and the claim rests
 * on the reservation ref alone, exactly as it did before this check existed.
 *
 * @template {{ number: number }} Candidate
 * @param {{
 *   candidates: Candidate[],
 *   pullRequests: { ok: true, items: { number: number, headRefName: string, body: string | null }[] } | { ok: false, reason: string },
 *   branchPrefix: string,
 * }} input
 * @returns {{ claimable: Candidate[], covered: { issue: number, pulls: number[] }[] }}
 */
export const partitionCandidates = ({
  candidates,
  pullRequests,
  branchPrefix,
}) => {
  /** @type {Candidate[]} */
  const claimable = [];
  /** @type {{ issue: number, pulls: number[] }[]} */
  const covered = [];

  for (const candidate of candidates) {
    const referencing = pullRequests.ok
      ? referencingPullRequests({
          pulls: pullRequests.items,
          issue: String(candidate.number),
          branchPrefix,
        })
      : [];

    if (referencing.length > 0) {
      covered.push({
        issue: candidate.number,
        pulls: referencing.map((pull) => pull.number),
      });
      continue;
    }

    claimable.push(candidate);
  }

  return { claimable, covered };
};

/** @param {{ issue: number, pulls: number[] }[]} covered */
const describeCovered = (covered) =>
  covered
    .map(
      ({ issue, pulls }) =>
        `#${issue} (pull request ${pulls.map((pull) => `#${pull}`).join(", ")})`,
    )
    .join("; ");

/**
 * A branch name component derived from an issue title. Titles are free text and
 * arrive with slashes, quotes, and non-Latin scripts in them; anything that is
 * not a lowercase alphanumeric collapses to a single hyphen.
 *
 * @param {string | null | undefined} title
 */
export const branchSlug = (title) =>
  (title ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 42);

/**
 * @param {{
 *   argv: string[],
 *   config: ClaimConfig,
 *   gh: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 *   afterClaim?: (claimed: { issue: number, branch: string }) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const claim = ({
  argv,
  config,
  gh,
  stdout = console.log,
  stderr = console.error,
  afterClaim = () => {},
}) => {
  const { agentId, requestedIssue, plans, strays } = parseArgs(argv);

  if (strays.length > 0) {
    stderr(
      `Unsupported argument${strays.length > 1 ? "s" : ""} ${strays.map((value) => `"${value}"`).join(", ")}: this command takes no positional issue number. ` +
        "Pass the issue with `--issue <n>` to claim it specifically, or omit " +
        "it to take the highest-priority claimable issue. Nothing was reserved.",
    );
    return EXIT.usage;
  }

  if (!agentId) {
    stderr("Missing required --agent-id <unique-session-id>.");
    return EXIT.usage;
  }

  // The claim comment is what `review.mjs` reads to identify a branch's author,
  // so an id containing a backtick or a newline would break that record.
  if (!SAFE_AGENT_ID.test(agentId)) {
    stderr(
      `Agent id "${agentId}" must match ${SAFE_AGENT_ID}: letters, digits, dot, underscore, and hyphen only.`,
    );
    return EXIT.usage;
  }

  const repository = JSON.parse(
    gh("repo", "view", "--json", "nameWithOwner,defaultBranchRef"),
  );
  const baseBranch =
    config.integrationBranch || repository.defaultBranchRef.name;
  const base = JSON.parse(
    gh("api", `repos/${repository.nameWithOwner}/git/ref/heads/${baseBranch}`),
  );
  // Every open issue, filtered in `selectCandidates`. The query carries no
  // `--label` at all now: the pool is defined by the *absence* of a hold label
  // and `gh issue list` cannot express that.
  //
  // Truncation is detected here rather than by `listing()`, deliberately.
  // `listing()` drops the items when a page fills, which is right for a report
  // — a possibly-truncated listing is not evidence about what exists — and
  // wrong here: a listing that is complete as far as it goes is still correct
  // for every issue in it, and discarding them would stop the claim loop dead
  // over a condition that raising `ISSUE_PAGE` fixes. So this warns and
  // proceeds, and the refusal messages below say so rather than asserting an
  // empty board.
  //
  // It must never be silent. `gh issue list` sorts newest-first, so an over-full
  // page drops the *oldest* issues, and `selectCandidates` tie-breaks ascending
  // by number — the dropped tail is precisely what this command would otherwise
  // have offered first. Undetected that is not a delay; it is a permanently
  // unclaimable and permanently invisible tail that grows as issues are filed.
  /** @type {Issue[]} */
  const issues = JSON.parse(
    gh(
      "issue",
      "list",
      "--state",
      "open",
      "--limit",
      String(ISSUE_PAGE),
      "--json",
      "number,title,labels,assignees",
    ),
  );

  const truncated = issues.length >= ISSUE_PAGE;

  if (truncated) {
    stderr(
      `The open-issue listing filled its page of ${ISSUE_PAGE}, so it may be ` +
        "truncated and this claim may be drawn from an incomplete backlog. " +
        "`gh issue list` returns newest first, so what is missing is the " +
        "oldest work — the end this command offers from first. Raise " +
        "`ISSUE_PAGE` in `lib/claimable.mjs`, which shares it with `report.mjs` " +
        "so the two cannot describe different populations.",
    );
  }

  // Appended to every "nothing to claim" message when the listing was full, so
  // an incomplete read is never reported as an empty board.
  const truncationCaveat = truncated
    ? ` (Note: the open-issue listing filled its page of ${ISSUE_PAGE}, so this` +
      " may not be the whole backlog.)"
    : "";

  // Read once per run, before anything is reserved, so a candidate an open pull
  // request already covers is left completely untouched — no ref, no label, no
  // assignee, no comment.
  const pullRequests = openPullRequests(gh);

  if (!pullRequests.ok) {
    stderr(
      `Skipped the open-pull-request check on every candidate: ${pullRequests.reason}. ` +
        "An unreadable listing is not evidence either way, so this claim rests " +
        "on the reservation ref alone.",
    );
  }

  const { claimable, covered } = partitionCandidates({
    candidates: selectCandidates({ issues, requestedIssue, config }),
    pullRequests,
    branchPrefix: config.branchPrefix,
  });

  for (const issue of claimable) {
    const ref = `refs/heads/${config.claimRefPrefix}${issue.number}`;
    let issueMutated = false;

    try {
      gh(
        "api",
        "--method",
        "POST",
        `repos/${repository.nameWithOwner}/git/refs`,
        "-f",
        `ref=${ref}`,
        "-f",
        `sha=${base.object.sha}`,
      );
    } catch {
      // Another session holds it. Move on without touching this issue at all —
      // editing labels on somebody else's claim is the failure this guards.
      continue;
    }

    try {
      gh(
        "issue",
        "edit",
        String(issue.number),
        "--add-assignee",
        "@me",
        "--add-label",
        config.labels.claimed,
      );
      issueMutated = true;
      const body = [
        `Claimed by Rallypoint agent \`${agentId}\`.`,
        "",
        ...plans.map((plan) => `- ${plan}`),
      ].join("\n");
      gh("issue", "comment", String(issue.number), "--body", body);
    } catch (error) {
      // Order matters here.
      //
      // If the issue edit already landed, the issue is claimed and assigned.
      // Deleting the reservation first would leave it in exactly the worst
      // state: held out of the pool by `status:claimed`, so nobody claims it,
      // and with no reservation ref, so the janitor has nothing to find.
      // Restore the issue first, and only release the reservation once that
      // has succeeded.
      //
      // Restoring is now purely subtractive — removing `status:claimed` and the
      // assignee is the whole of it, because claimability is derived from their
      // absence. Before the readiness label was removed this also had to re-add `status:ready`, a second
      // write that could itself fail and leave the issue claimable by nobody.
      if (issueMutated) {
        try {
          gh(
            "issue",
            "edit",
            String(issue.number),
            "--remove-assignee",
            "@me",
            "--remove-label",
            config.labels.claimed,
          );
        } catch {
          // Compensation failed, so the issue still reads as claimed. Keep the
          // reservation deliberately: it is the only signal left that tells the
          // janitor this issue needs recovering.
          stderr(
            `Claim failed and issue #${issue.number} plus reservation ${ref} require manual cleanup.`,
          );
          throw error;
        }
      }

      // A reservation with no claimed issue behind it is worse than no
      // reservation: nothing releases it except the janitor, and until then the
      // issue is unclaimable by anyone.
      try {
        gh(
          "api",
          "--method",
          "DELETE",
          `repos/${repository.nameWithOwner}/git/${ref}`,
        );
      } catch {
        stderr(`Claim failed and reservation ${ref} requires manual cleanup.`);
      }
      throw error;
    }

    stdout(`CLAIMED_ISSUE=${issue.number}`);
    stdout(
      `CLAIMED_URL=https://github.com/${repository.nameWithOwner}/issues/${issue.number}`,
    );
    const branch = `${config.branchPrefix}${issue.number}-${branchSlug(issue.title)}`;
    stdout(`CLAIM_BRANCH=${branch}`);

    // The beacon push. Deliberately after every GitHub mutation has
    // landed and outside the compensation block above: this touches only git,
    // it cannot leave the claim half-made, and a claim that succeeded with no
    // beacon behind it is exactly the state the protocol was in before. So it
    // never throws and never changes this exit code — `beaconPush` reports its
    // own refusals on stderr.
    afterClaim({ issue: issue.number, branch });

    return EXIT.ok;
  }

  // Exit code 2 covers both refusals — there is still nothing to claim — but
  // "every claimable issue already has a pull request" is a different board from
  // "the backlog is empty", and an operator naming one issue needs the pull
  // request number to act on it without re-deriving the link.
  if (covered.length > 0) {
    const detail = describeCovered(covered);

    if (claimable.length === 0) {
      stderr(
        `No claimable issue is available: an open pull request already ` +
          `references every candidate — ${detail}. Nothing was reserved. If a ` +
          "pull request there is missing its claim comment, recover it with " +
          "`node .rallypoint/scripts/reconcile.mjs --issue <n> --agent-id " +
          `<authoring-session-id>\`.${truncationCaveat}`,
      );
      return EXIT.noneAvailable;
    }

    stderr(
      "No unreserved claimable issue is available. Also skipped because an " +
        `open pull request already references them: ${detail}.${truncationCaveat}`,
    );
    return EXIT.noneAvailable;
  }

  // Only for an explicitly named issue, and only on the refusal path: one extra
  // read, on a path that is already terminal, to turn a message about the board
  // into a message about the issue the operator actually asked for.
  if (requestedIssue) {
    let named = null;

    try {
      named = JSON.parse(
        gh(
          "issue",
          "view",
          requestedIssue,
          "--json",
          "state,labels,assignees",
        ),
      );
    } catch {
      // Left null; `explainUnavailable` says so rather than guessing.
    }

    const reason = explainUnavailable({
      issue: named,
      number: requestedIssue,
      config,
    });

    if (reason !== null) {
      stderr(`Not claiming #${requestedIssue}: ${reason} Nothing was reserved.`);
      return EXIT.noneAvailable;
    }
  }

  stderr(`No unreserved claimable issue is available.${truncationCaveat}`);
  return EXIT.noneAvailable;
};

export default claim;

// Whether an issue is available for a worker to claim, derived rather than
// declared.
//
// The backlog used to be an *opt-in* set: an issue entered it when a
// planner added `status:ready` beside `task`, and `claim.mjs` listed candidates
// by asking GitHub for both labels at once. Two labels had to be present for
// work to be claimable, and the commonest board defect was one of them missing
// — `report.mjs` carried a whole `readyWithoutTask` classification for an issue
// advertised as ready that `claim.mjs` could never offer to anybody, found live
// more than once.
//
// Both labels are gone. The pool is now *opt-out*: every open issue is
// claimable unless something on it says otherwise. That inverts the default —
// a freshly filed issue is claimable the moment it is filed, where before it
// sat inert until a planner opened the gate — and the inversion is deliberate,
// decided by the owner. Nothing here restores a scoping gate; an
// issue that is not ready to be worked says so with a hold label.
//
// What this does *not* touch, and the reason the inversion is safe: the
// reservation ref `rallypoint-claims/issue-<N>` is still the only atomicity
// guarantee, exactly as it was. Labels were always advisory on top of it —
// `claim.mjs` creates the ref first and edits labels only once that succeeded,
// so two sessions racing one issue are separated by GitHub refusing the second
// ref, never by a label. Widening the pool changes which issues are offered,
// not what happens when two sessions are offered the same one.

/**
 * How many open issues a pool listing asks for.
 *
 * `claim.mjs` and `report.mjs` must use the **same** number or they describe
 * different populations, which is the drift this module exists to prevent — the
 * predicate agreeing is worth nothing if the two sets it runs over do not.
 *
 * It has to be a shared constant rather than two literals because the labels
 * that used to bound both queries are gone: `task` + `status:ready` narrowed the
 * listing to a handful of rows, so neither caller was anywhere near its page
 * limit and the limits were free to disagree. Listing every open issue removes
 * that accidental bound, and an early draft replaced it with 300 in
 * `claim.mjs` and an inherited 100 in `report.mjs` — 33 issues from the point
 * where every pool classification in the report would have gone dark at once.
 *
 * Truncation is **not** graceful, and both callers must detect it rather than
 * assume a full page is a complete one. `gh issue list` sorts newest-first by
 * default, so an over-full page drops the *oldest* issues — and
 * `selectCandidates` tie-breaks ascending by number, so the dropped tail is
 * exactly what it would have offered first. A silently truncated listing does
 * not delay old work, it makes it permanently unclaimable and permanently
 * invisible, and gets worse as new issues arrive.
 */
export const ISSUE_PAGE = 300;

/**
 * The label keys, in `config.labels`, that hold an issue out of the pool.
 *
 * Ordered most-specific first, because `explainHold` reports the first match
 * and the first match is what the operator most needs to hear: an issue that is
 * both claimed and blocked is somebody's live work before it is anything else.
 *
 * Read from `config` rather than hardcoded so a hold label added to the config
 * later is honoured here without editing this file — the same reasoning
 * `clear-status-labels.mjs` follows with its `startsWith("status:")` sweep.
 */
export const HOLD_LABEL_KEYS = ["claimed", "blocked", "deferred", "human"];

/**
 * Why each hold label keeps an issue out of the pool, in the operator's terms.
 * Keyed by `config.labels` key, not by label name, so renaming a label in the
 * config does not strand its explanation.
 *
 * @type {Record<string, (label: string) => string>}
 */
const HOLD_REASON = {
  claimed: (label) => `carries \`${label}\`; another session holds it`,
  blocked: (label) =>
    `carries \`${label}\`, so it cannot proceed until whatever blocks it is ` +
    `resolved. Removing that label is a planner decision, not this command's`,
  deferred: (label) =>
    `carries \`${label}\`, so it was consciously postponed and is not queued ` +
    `for work. Removing that label is a planner decision, not this command's`,
  human: (label) =>
    `carries \`${label}\`, so it is waiting on an operator action no agent ` +
    `session can perform. Removing that label is an operator decision, not ` +
    `this command's`,
};

/**
 * The hold label *names* configured on `config`, in `HOLD_LABEL_KEYS` order.
 *
 * A key absent from `config.labels` contributes nothing rather than an
 * `undefined` that would silently match a label with no name — the failure
 * `selectCandidates` guarded against by making its `humanLabel` optional.
 *
 * @param {{ labels?: Record<string, string | undefined> }} config
 * @returns {string[]}
 */
export const holdLabelNames = (config) =>
  HOLD_LABEL_KEYS.flatMap((key) => {
    const name = config?.labels?.[key];
    return typeof name === "string" && name !== "" ? [name] : [];
  });

/**
 * The names on `labels`, however GitHub shaped them.
 *
 * Returns `null` — never an empty array — when the labels could not be read as
 * a list, so a caller cannot mistake "unreadable" for "none". That is the
 * unreadable-is-not-absent rule this loop applies everywhere: a failed read is not
 * evidence of absence.
 *
 * @param {unknown} labels
 * @returns {string[] | null}
 */
export const labelNames = (labels) =>
  Array.isArray(labels)
    ? labels.flatMap((label) => {
        const name = /** @type {{ name?: unknown }} */ (label)?.name;
        return typeof name === "string" ? [name] : [];
      })
    : null;

/**
 * The configured hold labels present on `issue`, in `HOLD_LABEL_KEYS` order.
 *
 * @param {{ labels?: unknown }} issue
 * @param {{ labels?: Record<string, string | undefined> }} config
 * @returns {string[] | null} `null` when the labels could not be read.
 */
export const heldBy = (issue, config) => {
  const names = labelNames(issue?.labels);
  if (names === null) return null;
  return holdLabelNames(config).filter((label) => names.includes(label));
};

/**
 * Whether `issue` is in the claimable pool on its own labels and assignees.
 *
 * Deliberately *not* the whole of claimability. Two further filters live in
 * `claim.mjs` because they are not properties of the issue: a live reservation
 * ref, and an open pull request already referencing it. This answers the
 * question the label state can answer, and nothing more.
 *
 * An issue whose labels could not be read is **not** claimable. Erring the
 * other way would offer a session an issue that might carry `status:claimed`,
 * which is the one mistake the reservation ref cannot fully undo — the second
 * session would have already commented and assigned itself before finding out.
 *
 * @param {{ labels?: unknown, assignees?: unknown, state?: string }} issue
 * @param {{ labels?: Record<string, string | undefined> }} config
 * @returns {boolean}
 */
export const isClaimable = (issue, config) => {
  // A config naming no hold labels at all would make every open issue claimable
  // — the same fail-open hazard `selectCandidates` refuses its optional
  // `config` over. `loadConfig` validates these are present, so reaching here
  // without them is a programming error and is treated as one rather than
  // silently answering "claimable" for everything.
  if (holdLabelNames(config).length === 0) {
    throw new Error(
      "isClaimable was given a config naming no hold labels; refusing to " +
        "report every open issue as claimable.",
    );
  }

  if (issue?.state !== undefined && String(issue.state).toUpperCase() !== "OPEN") {
    return false;
  }

  // An assigned issue is somebody's work in progress even when no label says
  // so — the rule `selectCandidates` has always applied.
  if (Array.isArray(issue?.assignees) && issue.assignees.length > 0) return false;

  const held = heldBy(issue, config);
  return held !== null && held.length === 0;
};

/**
 * Why a specifically-named issue is not claimable, in one sentence, or `null`
 * when nothing here explains it and the caller should fall back to its own
 * message rather than assert a cause it did not establish.
 *
 * Callers pass the issue they read directly with `gh issue view`, not a row
 * from a search-backed listing — see `report.mjs`'s `viewIssue` on why the two
 * disagree.
 *
 * @param {{
 *   issue: { state?: string, labels?: unknown, assignees?: unknown } | null,
 *   number: string,
 *   config: { labels?: Record<string, string | undefined> },
 * }} input
 * @returns {string | null}
 */
export const explainHold = ({ issue, number, config }) => {
  if (issue === null) {
    return `#${number} could not be read, so why it was not offered cannot be established.`;
  }

  if (issue.state !== undefined && String(issue.state).toUpperCase() !== "OPEN") {
    return `#${number} is ${String(issue.state).toLowerCase()}, so it is not claimable.`;
  }

  const names = labelNames(issue.labels);

  if (names === null) {
    return `#${number}'s labels could not be read, so why it was not offered cannot be established.`;
  }

  for (const key of HOLD_LABEL_KEYS) {
    const label = config?.labels?.[key];
    if (typeof label !== "string" || label === "") continue;
    if (!names.includes(label)) continue;
    return `#${number} ${HOLD_REASON[key](label)}.`;
  }

  if (Array.isArray(issue.assignees) && issue.assignees.length > 0) {
    const logins = issue.assignees
      .map((/** @type {{ login?: string }} */ assignee) => assignee?.login)
      .filter(Boolean)
      .join(", ");
    return (
      `#${number} is assigned${logins ? ` to ${logins}` : ""}, and an assigned ` +
      `issue is somebody's work in progress.`
    );
  }

  return null;
};

// Reservation release, with every call to `gh` injected.
//
// The refusal below is the whole point: deleting a reservation for an issue that
// is still open re-opens it to a second claimant while the first is still
// working, which is precisely the collision the reservation exists to prevent.

import { reservationPresence } from "./release-claim.mjs";

// Exit codes are a public interface, as they are for `release-claim.mjs` and
// `review.mjs`. Keep them in sync with the table in docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  notClosed: 2,
  inconclusive: 3, // presence could not be established; no delete attempted
  deleteFailed: 4, // ref was confirmed present but the delete failed
};

/**
 * The first informative line of a `gh` failure. `execFileSync` puts the useful
 * part on `stderr` and leaves `message` as the command line.
 *
 * @param {unknown} error
 */
const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr ?? detail.message ?? error ?? "").trim();
  return (
    text
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  const index = argv.indexOf("--issue");
  return { issue: index === -1 ? undefined : argv[index + 1] };
};

/**
 * @param {{
 *   argv: string[],
 *   config: { claimRefPrefix: string },
 *   gh: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const cleanup = ({
  argv,
  config,
  gh,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { issue } = parseArgs(argv);

  if (!issue) {
    stderr("Usage: cleanup.mjs --issue <closed-issue-number>");
    return EXIT.usage;
  }

  const repository = JSON.parse(
    gh("repo", "view", "--json", "nameWithOwner"),
  ).nameWithOwner;
  const { state } = JSON.parse(gh("issue", "view", issue, "--json", "state"));

  if (state !== "CLOSED") {
    stderr(
      `Issue #${issue} is ${state.toLowerCase()}; reservation preserved.`,
    );
    return EXIT.notClosed;
  }

  const refName = `${config.claimRefPrefix}${issue}`;
  const refPath = `refs/heads/${refName}`;

  // Presence is established by listing, never inferred from a delete's
  // failure — a branch-scoped credential answers 403 whether or not the ref
  // is there, and an already-absent ref is a success, not a crash.
  // `release-claim.mjs` already solves this; reuse it rather than growing a
  // second presence check.
  const presence = reservationPresence(gh, repository, refName);

  if (presence.kind === "unknown") {
    stderr(
      `Whether \`${refPath}\` exists could not be established (${presence.reason}). No delete was attempted.`,
    );
    return EXIT.inconclusive;
  }

  if (presence.kind === "absent") {
    stdout(`No reservation for closed issue #${issue}; already clean.`);
    return EXIT.ok;
  }

  try {
    gh("api", "--method", "DELETE", `repos/${repository}/git/${refPath}`);
  } catch (error) {
    stderr(
      `\`${refPath}\` could not be deleted (${describeError(error)}).`,
    );
    return EXIT.deleteFailed;
  }

  stdout(`Removed reservation for closed issue #${issue}.`);
  return EXIT.ok;
};

export default cleanup;

// Clears stale `status:*` labels off a closed issue, with every call to `gh`
// injected.
//
// `report.mjs`'s survey only ever lists open issues, so a closed issue
// that never passed through `claim.mjs` — because a pull request closed it
// natively with `Closes #<issue>` — keeps whatever `status:*` label it last
// carried forever. The concrete case this fixes is an issue that closed with
// a stale status label still on it. This command is the repair `report.mjs` names in
// its `closedWithStatusLabel` detail; it never decides eligibility on its
// own — see the refusal below, the same shape as `cleanup.mjs`'s.

// Exit codes are a public interface, as they are for `cleanup.mjs`,
// `release-claim.mjs`, and `review.mjs`. Keep them in sync with the table in
// docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  notClosed: 2,
  inconclusive: 3, // labels could not be read; no removal attempted
  removeFailed: 4, // at least one label was confirmed present but failed to clear
};

/**
 * The first informative line of a `gh` failure. `execFileSync` puts the useful
 * part on `stderr` and leaves `message` as the command line.
 *
 * @param {unknown} error
 */
const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr ?? detail.message ?? error ?? "").trim();
  return (
    text
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  const index = argv.indexOf("--issue");
  return {
    issue: index === -1 ? undefined : argv[index + 1],
    dryRun: argv.includes("--dry-run"),
  };
};

/**
 * The `status:*` labels among `labels`, in the order they were given — never
 * a hardcoded label set, so a label added to `config.labels` later is covered
 * without editing this file, the same reasoning `report.mjs`'s own
 * `startsWith("status:")` check follows.
 *
 * @param {{ name?: string }[]} labels
 * @returns {string[]}
 */
export const staleLabels = (labels) =>
  labels.flatMap((label) =>
    typeof label?.name === "string" && label.name.startsWith("status:")
      ? [label.name]
      : [],
  );

/**
 * @param {{
 *   argv: string[],
 *   gh: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const clearStatusLabels = ({
  argv,
  gh,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { issue, dryRun } = parseArgs(argv);

  if (!issue) {
    stderr("Usage: clear-status-labels.mjs --issue <closed-issue-number> [--dry-run]");
    return EXIT.usage;
  }

  /** @type {{ state?: string, labels?: { name?: string }[] } | null} */
  let details = null;

  try {
    details = JSON.parse(
      gh("issue", "view", issue, "--json", "state,labels"),
    );
  } catch (error) {
    stderr(`#${issue}'s state and labels could not be read (${describeError(error)}).`);
    return EXIT.inconclusive;
  }

  const state = details?.state;

  if (state !== "CLOSED") {
    stderr(`Issue #${issue} is ${String(state ?? "unknown").toLowerCase()}; labels preserved.`);
    return EXIT.notClosed;
  }

  const labels = Array.isArray(details?.labels) ? details.labels : null;

  if (labels === null) {
    stderr(`#${issue}'s labels could not be read as a list. No removal was attempted.`);
    return EXIT.inconclusive;
  }

  const stale = staleLabels(labels);

  if (stale.length === 0) {
    stdout(`#${issue} carries no status:* label; already clean.`);
    return EXIT.ok;
  }

  if (dryRun) {
    stdout(
      `Would remove ${stale.map((name) => `\`${name}\``).join(", ")} from closed issue #${issue}.`,
    );
    return EXIT.ok;
  }

  const failures = [];

  for (const label of stale) {
    try {
      gh("issue", "edit", issue, "--remove-label", label);
    } catch (error) {
      failures.push(`\`${label}\` (${describeError(error)})`);
    }
  }

  if (failures.length > 0) {
    stderr(`Could not remove every stale label from #${issue}: ${failures.join(", ")}.`);
    return EXIT.removeFailed;
  }

  stdout(
    `Removed ${stale.map((name) => `\`${name}\``).join(", ")} from closed issue #${issue}.`,
  );
  return EXIT.ok;
};

export default clearStatusLabels;

// What GitHub's own closing-keyword parser would link for auto-close, set
// against what this loop *declares* a pull request closes.
//
// `provenance.mjs`'s `CLOSING_KEYWORD` is anchored to the start of a line on
// purpose: it is the loop's declaration format, and the anchor is what keeps a
// sentence of prose from being read as a declaration. GitHub's parser has no
// anchor and no notion of context. It scans the pull request body and the
// message of every commit in the pull request for a keyword followed by a
// number, wherever in the text that pair appears — so a sentence stating that a
// pull request deliberately leaves an issue open links that issue for
// auto-close anyway, and a commit message narrating a closure somebody else
// performed months ago links that one too.
//
// The two models disagree, and without something like this module nothing in a
// repository can see the disagreement. Left unseen, the gap silently reverses
// operator decisions: an issue reopened minutes earlier under a `needs:human`
// hold gets re-closed by an unrelated merge, on the strength of one sentence in
// a commit message describing a hand-close somebody performed long before — and
// the issue's claim reservation is stranded behind it.
//
// **This is deliberately a second parser, which anywhere else in this directory
// would be the defect.** `provenance.mjs`'s header, `close-referenced-issues.mjs`,
// and `preflight.mjs` all argue that a duplicated predicate drifts from the one
// that actually decides. That argument holds when the two are meant to agree.
// Here the disagreement *is* the measurement: `linkedIssues` models what the
// author declared, this models what GitHub will do, and the check is that the
// second contains nothing the first does not. One parser cannot answer that
// question, because a single parser is by construction always consistent with
// itself.
//
// Non-goals, stated so nobody reads more into a pass than is there:
//
//   - Cross-repository references (`owner/repo#<n>`) and full issue URLs are
//     not matched. GitHub honours both. Nothing in this repository's protocol
//     prose has ever used either form, and matching them would mean deciding
//     which repository a bare number belongs to.
//   - Whether GitHub links a reference inside a fenced or inline code span is
//     inferred from how its markdown renderer treats autolinks, not from
//     documentation that promises it. The body is scanned with those regions
//     blanked; a commit message is scanned whole, because a commit message is
//     not rendered as markdown at all.
//   - A pull request title is not scanned, because GitHub does not scan one.

/**
 * GitHub's closing keywords, matched anywhere in the text rather than at the
 * start of a line. The optional colon covers `Fixes: #<n>`, which GitHub
 * accepts and this repository's documented form does not use — a detector may
 * be more permissive than the thing it detects, never less.
 *
 * `\b` before the keyword so `unclosed #<n>` and `prefixes #<n>` do not match;
 * `\b` after the number so `#12` does not match inside `#123`.
 */
export const GITHUB_CLOSING_KEYWORD =
  /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)[^\S\n]*:?[^\S\n]+#(\d+)\b/gi;

/**
 * Fenced blocks and inline code spans blanked, for text GitHub renders as
 * markdown. Mirrors `provenance.mjs`'s `withoutCode` for fences and extends it
 * to inline spans: this repository's pull request bodies routinely quote the
 * `Closes #<issue>` convention inline, and counting those would make the check
 * fire on every body that explains itself.
 *
 * @param {string | null | undefined} text
 */
const withoutCode = (text) =>
  (text ?? "")
    .replace(/^[^\S\n]*(```|~~~)[\s\S]*?^[^\S\n]*\1/gm, "")
    .replace(/(`+)[^`\n]*?\1/g, "");

/**
 * Every issue number GitHub's parser would link for auto-close in one piece of
 * text.
 *
 * @param {string | null | undefined} text
 * @param {{ markdown?: boolean }} [options] `markdown: true` for a pull request
 *   body, which GitHub renders; leave it false for a commit message, which it
 *   does not.
 * @returns {string[]}
 */
export const githubClosedIssues = (text, { markdown = false } = {}) => [
  ...new Set(
    [
      ...(markdown ? withoutCode(text) : (text ?? "")).matchAll(
        GITHUB_CLOSING_KEYWORD,
      ),
    ].map((match) => match[1]),
  ),
];

/**
 * @typedef {{ kind: "body" }
 *   | { kind: "commit", sha: string, subject: string }} ClosureSource
 */

/**
 * Which issues GitHub would close that the author never declared, and where
 * each one comes from.
 *
 * `declared` is the loop's own answer — `linkedIssues(body)` — not a set the
 * caller composes by hand, so what this reports is exactly the divergence
 * between the two models and nothing else. An issue reached by both a declared
 * line and a stray sentence is not reported: GitHub closing it is what the
 * author asked for.
 *
 * Sources are collected rather than counted because the remedy differs by
 * source. A body can be edited after the pull request is open; a commit message
 * on a pushed branch effectively cannot, so a commit-sourced match is the one
 * that has to be caught before the pull request exists.
 *
 * @param {{
 *   body?: string | null,
 *   declared: string[],
 *   commits?: { sha: string, message: string }[],
 * }} input
 * @returns {{ issue: string, sources: ClosureSource[] }[]}
 */
export const closureDrift = ({ body, declared, commits = [] }) => {
  const known = new Set(declared);
  /** @type {Map<string, ClosureSource[]>} */
  const found = new Map();

  /**
   * @param {string} issue
   * @param {ClosureSource} source
   */
  const record = (issue, source) => {
    if (known.has(issue)) return;
    found.set(issue, [...(found.get(issue) ?? []), source]);
  };

  for (const issue of githubClosedIssues(body, { markdown: true })) {
    record(issue, { kind: "body" });
  }

  for (const commit of commits) {
    for (const issue of githubClosedIssues(commit.message)) {
      record(issue, {
        kind: "commit",
        sha: commit.sha,
        subject: commit.message.split("\n", 1)[0] ?? "",
      });
    }
  }

  return [...found.entries()]
    .map(([issue, sources]) => ({ issue, sources }))
    .sort((a, b) => Number(a.issue) - Number(b.issue));
};

/**
 * The refusal text for a drift result.
 *
 * There is deliberately **no escape hatch** — no pragma, no trailer, nothing of
 * the shape `Migration-Removal-Ok:` or `// supabase-audit-ok:`. Those hatches
 * work because the thing they suppress is a *guess* about consequences a human
 * can overrule with better information. This one is not a guess: GitHub will
 * close the issue, and asserting in writing that it is fine does not stop it.
 * The only remedy that changes the outcome is changing the text, so the only
 * remedy offered is changing the text.
 *
 * @param {ReturnType<typeof closureDrift>} drift
 * @param {{ declared: string[] }} input
 * @returns {string}
 */
export const closureDriftMessage = (drift, { declared }) => {
  const lines = [
    "GitHub's closing-keyword parser would close " +
      `${drift.map((entry) => `#${entry.issue}`).join(", ")} on merge, which ` +
      (declared.length
        ? `this pull request does not declare (it declares ${declared.map((issue) => `#${issue}`).join(", ")}).`
        : "this pull request declares nothing about."),
    "",
    "GitHub matches a closing keyword followed by an issue number anywhere in " +
      "the text — in the middle of a sentence, and in a sentence whose meaning " +
      "is that the issue stays open. It scans the pull request body and the " +
      "message of every commit in the pull request.",
    "",
  ];

  for (const entry of drift) {
    lines.push(`#${entry.issue}:`);

    for (const source of entry.sources) {
      lines.push(
        source.kind === "body"
          ? "  - the prepared pull request body"
          : `  - commit ${source.sha.slice(0, 8)} ${source.subject}`,
      );
    }
  }

  lines.push(
    "",
    "Reword so the keyword and the number are not adjacent. `issue 34`, " +
      "`#34 was closed`, and a bracketed `[#34]` all say the same thing and " +
      "none of them matches. If the closure is intended, declare it instead " +
      "with its own closing line at the start of a line in the body.",
    "",
    "A commit message on a pushed branch cannot be edited without rewriting " +
      "the branch, so a commit-sourced match is cheapest to fix now: " +
      "`git rebase -i` the message, force-push with `--force-with-lease`, and " +
      "run this again. There is no pragma to suppress this — GitHub closes the " +
      "issue whatever anybody writes about it here.",
  );

  return lines.join("\n");
};

/**
 * GitHub's own answer for a pull request that already exists, compared against
 * what the author declares.
 *
 * Advisory, never a refusal, and the asymmetry is the reason: this reads the
 * body **already on the pull request**, while `--body` is the body the session
 * is about to use. The two differ by exactly the edit being prepared, so a
 * difference here is as likely to be the fix in progress as a defect. What it
 * is good for is the case the local model cannot see at all — a form of
 * reference this module deliberately does not match, or a change in GitHub's
 * parser — reported by GitHub itself rather than inferred.
 *
 * @param {{ declared: string[], github: string[] }} input
 * @returns {{ extra: string[], missing: string[] }} `extra` is what GitHub
 *   links and the prepared body does not declare; `missing` is the reverse.
 */
export const closingReferenceDivergence = ({ declared, github }) => {
  const declaredSet = new Set(declared);
  const githubSet = new Set(github);

  return {
    extra: github.filter((issue) => !declaredSet.has(issue)),
    missing: declared.filter((issue) => !githubSet.has(issue)),
  };
};

export default closureDrift;

// Validation for `.rallypoint/config.json`.

import { validateImprovement } from "./improvement.mjs";
//
// The reservation ref is the only mutual exclusion primitive the loop has when
// several agent sessions share one GitHub identity, and its name comes entirely
// from this file. A config that names refs badly does not fail loudly — it fails
// as two agents claiming one issue, which looks like a coordination accident
// rather than a configuration error.

// `deferred` joined this list when `task` and `ready` left it. The
// claimable pool is now the *absence* of a hold label, so every hold label is
// load-bearing in a way it was not before: a missing `labels.deferred` would
// not narrow the pool, it would silently widen it to include work somebody
// deliberately postponed.
const REQUIRED_LABELS = [
  "claimed",
  "blocked",
  "deferred",
  "human",
  "approved",
];

/**
 * @param {unknown} value
 * @returns {value is string}
 */
const isNonEmptyString = (value) =>
  typeof value === "string" && value.trim() !== "";

// Mirrors the ref-name constraints enforced by `git check-ref-format` without
// spawning Git during config loading. Prefixes are checked after appending the
// safe suffix their callers add, while still rejecting a raw trailing dot or
// `.lock` that the suffix could otherwise conceal.
/**
 * @param {string} value
 * @param {string} [suffix]
 */
const isGitRefPath = (value, suffix = "") => {
  if (!isNonEmptyString(value)) return false;
  if (value.endsWith(".") || value.endsWith(".lock")) return false;

  const ref = `${value}${suffix}`;

  if (
    ref === "@" ||
    ref.startsWith("/") ||
    ref.endsWith("/") ||
    ref.includes("//") ||
    ref.includes("..") ||
    ref.includes("@{") ||
    /[\u0000-\u0020\u007f~^:?*[\]\\]/u.test(ref)
  ) {
    return false;
  }

  return ref
    .split("/")
    .every(
      (component) =>
        component !== "" &&
        !component.startsWith(".") &&
        !component.endsWith(".lock"),
    );
};

/**
 * @param {unknown} config Parsed `config.json`.
 * @returns {{ ok: true } | { ok: false, problems: string[] }}
 */
export const validateConfig = (config) => {
  const problems = [];

  if (typeof config !== "object" || config === null) {
    return { ok: false, problems: ["Config must be an object."] };
  }

  const {
    integrationBranch,
    promotionBranch,
    promotionSnapshotPrefix,
    branchPrefix,
    claimRefPrefix,
    sessionRefPrefix,
    labels,
  } = /** @type {Record<string, unknown>} */ (config);

  if (!isNonEmptyString(integrationBranch)) {
    problems.push("`integrationBranch` must be a non-empty string.");
  } else if (
    integrationBranch.startsWith("-") ||
    !isGitRefPath(integrationBranch)
  ) {
    problems.push("`integrationBranch` is not a valid Git branch name.");
  }

  // Optional: absent means one integration tier, and `integrationBranch` is
  // what promotes into the default branch. Present and malformed is worth
  // rejecting, because `verify-promotion-source.mjs` would compare the head
  // against a branch name that can never match and report every promotion as
  // unapproved.
  if (promotionBranch !== undefined) {
    if (!isNonEmptyString(promotionBranch)) {
      problems.push(
        "`promotionBranch` must be a non-empty string when present.",
      );
    } else if (
      promotionBranch.startsWith("-") ||
      !isGitRefPath(promotionBranch)
    ) {
      problems.push("`promotionBranch` is not a valid Git branch name.");
    }
  }

  // Optional: absent means `provenance.mjs` falls back to its built-in
  // `promotion/`, so an older config keeps working unchanged. Present and
  // malformed is worth rejecting for the same reason as `promotionBranch` above
  // — `isPromotionBranch` would then refuse every snapshot promotion as an
  // ordinary agent pull request with no claim, and `review.mjs` would call it
  // unidentifiable rather than saying the configuration is wrong.
  //
  // The overlap rule below is a **security** rule, not a hygiene one. The
  // snapshot shape is the one head shape that skips the self-review guard
  //, and containment is what makes it unforgeable. A prefix that is a
  // prefix of `branchPrefix`, or that `branchPrefix` is a prefix of, would let
  // an ordinary claimed branch be parsed as a snapshot head — the one way to
  // re-open the bypass without touching `provenance.mjs` at all. Reject it in
  // configuration rather than relying on the parse to reject it by accident.
  if (promotionSnapshotPrefix !== undefined) {
    if (!isNonEmptyString(promotionSnapshotPrefix)) {
      problems.push(
        "`promotionSnapshotPrefix` must be a non-empty string when present.",
      );
    } else if (
      promotionSnapshotPrefix.startsWith("-") ||
      // Validated with a suffix, the way the generated-ref prefixes below are:
      // a prefix that is only invalid once a snapshot name is appended is the
      // trap those avoid, and the same one applies here.
      !isGitRefPath(`${promotionSnapshotPrefix}release-2026-01-01`)
    ) {
      problems.push(
        "`promotionSnapshotPrefix` is not a valid Git branch name prefix.",
      );
    } else if (
      isNonEmptyString(branchPrefix) &&
      (promotionSnapshotPrefix.startsWith(branchPrefix) ||
        branchPrefix.startsWith(promotionSnapshotPrefix))
    ) {
      problems.push(
        "`promotionSnapshotPrefix` must not overlap `branchPrefix`: a claimed " +
          "agent branch would then parse as a promotion snapshot head, which " +
          "skips the self-review guard.",
      );
    }
  }

  /** @type {[string, unknown, string][]} */
  const generatedRefs = [
    ["branchPrefix", branchPrefix, "1-safe-title"],
    ["claimRefPrefix", claimRefPrefix, "1"],
    // The longest name `lease.mjs` generates under this prefix. Validating the
    // prefix alone would accept one that only produces an invalid ref once the
    // suffix is appended, which is the same trap the two above avoid.
    ["sessionRefPrefix", sessionRefPrefix, "pr-1-reviewer"],
  ];

  for (const [key, value, generatedSuffix] of generatedRefs) {
    if (!isNonEmptyString(value)) {
      problems.push(`\`${key}\` must be a non-empty string.`);
    } else if (
      (key === "branchPrefix" && value.startsWith("-")) ||
      !isGitRefPath(value, generatedSuffix)
    ) {
      problems.push(`\`${key}\` would not generate a valid Git ref.`);
    }
  }

  // No two namespaces may overlap in either direction. If a reservation ref
  // could also be read as an issue branch, `branchIssue` would resolve a
  // reservation to an author and the janitor could mistake live work for an
  // abandoned reservation — or delete a real branch while releasing a claim.
  // The session namespace joins the same rule: `report.mjs` lists reservations
  // and leases by prefix and classifies them differently, so an overlap would
  // have a lease counted as a claim (or swept as one) purely by name.
  /** @type {[string, unknown][]} */
  const namespaces = [
    ["branchPrefix", branchPrefix],
    ["claimRefPrefix", claimRefPrefix],
    ["sessionRefPrefix", sessionRefPrefix],
  ];

  for (const [leftKey, left] of namespaces) {
    for (const [rightKey, right] of namespaces) {
      if (leftKey >= rightKey) continue;
      if (!isNonEmptyString(left) || !isNonEmptyString(right)) continue;
      if (!left.startsWith(right) && !right.startsWith(left)) continue;

      problems.push(
        `\`${leftKey}\` (${left}) and \`${rightKey}\` (${right}) must not be prefixes of one another; their refs would share a namespace.`,
      );
    }
  }

  if (typeof labels !== "object" || labels === null) {
    problems.push("`labels` must be an object.");
  } else {
    const labelValues = /** @type {Record<string, unknown>} */ (labels);
    for (const key of REQUIRED_LABELS) {
      if (!isNonEmptyString(labelValues[key])) {
        problems.push(`\`labels.${key}\` must be a non-empty string.`);
      }
    }
  }

  // Optional, like the promotion keys: a config written before the
  // self-improvement layer existed keeps working on its defaults.
  problems.push(
    ...validateImprovement(
      /** @type {Record<string, unknown>} */ (config).improvement,
    ),
  );

  return problems.length === 0 ? { ok: true } : { ok: false, problems };
};

export default validateConfig;

// Deleting a merged issue branch from origin, with every call to `gh` and
// `git` injected.
//
// This exists because merges do not clean up after themselves, and the debris
// accumulates fast: an agent loop left unattended will happily leave hundreds
// of merged `agent/*` branches on origin. Three findings, each measured on a
// live merge, shape every decision below.
//
// 1. **`gh pr merge --delete-branch` couples the two deletes, and the local one
//    fails first.** A merger runs minutes after its worker, so the worker's
//    worktree is by definition still checked out on the branch:
//    `git branch -d` answers "cannot delete branch … used by worktree at …",
//    `gh pr merge` exits 1 there, and **never attempts the remote delete** —
//    which has no worktree dependency and would have succeeded. So the two
//    deletes are sequenced independently here, remote first, and the local one
//    is reported rather than fatal.
// 2. **`git push origin --delete` is not a usable fallback.** Any `git push`
//    fires a `pre-push` hook, and in a repository that gates pushes on lint,
//    typecheck, tests, and a build, that runs the whole gate before the command
//    ever reaches the network. `pre-push` cannot distinguish "pushing code"
//    from "deleting a ref", so it taxes routine ref maintenance at the price of
//    a full build.
// 3. **The GitHub API ref delete works.** No hook, no worktree dependency, no
//    local state consulted. That is the mechanism used here.
//
// Two safety properties are load-bearing and each has its own test:
//
// - **Merge containment is judged only after `git fetch`.** A genuinely merged
//   branch reads as unmerged against stale remote-tracking refs. The fetch is
//   not an optimisation; without it this refuses correct deletions.
// - **Only a branch carrying the configured branch prefix is ever deletable.**
//   The integration and promotion branches, and every `claimRefPrefix` and
//   `sessionRefPrefix` ref, fail that test by construction, so no argument,
//   typo, or surprising pull request payload can aim this at one.
//
// Everything below judges **the SHA the ref listing just returned**, never a
// ref *name*. A name is a level of indirection this script cannot afford:
//
// - `state === "MERGED"` is authoritative about the commit the pull request
//   merged, and about nothing else. A push to the branch after the merge — a
//   still-live worker session, a reopened follow-up, an older pull request
//   re-run — leaves commits on the ref that no merge ever contained. So the
//   `--pr` path compares `headRefOid` against the live ref's `object.sha` and
//   falls back to a containment check whenever they differ.
// - `origin/<branch>` is a remote-tracking ref, and a `git fetch` that exits 0
//   has not necessarily updated it (a non-default refspec, an odd remote
//   config). Judging containment against that name can read a stale ancestor as
//   `merged` while the live ref carries newer work — the one direction the
//   fetch note above calls dangerous. So containment is judged against the SHA.

import { matchingRefs } from "./release-claim.mjs";

// Exit codes are a public interface, as they are for `cleanup.mjs` and
// `review.mjs`. Keep them in sync with the table in docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  refused: 2, // not an issue branch, or not merged; nothing was deleted
  inconclusive: 3, // remote presence could not be established; no delete tried
  deleteFailed: 4, // ref was confirmed present but the delete failed
};

/**
 * The first informative line of a failure. `execFileSync` puts the useful part
 * on `stderr` and leaves `message` as the command line.
 *
 * @param {unknown} error
 */
export const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr ?? detail.message ?? error ?? "").trim();
  return (
    text
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  /** @param {string} flag */
  const value = (flag) => {
    const index = argv.indexOf(flag);
    return index === -1 ? undefined : argv[index + 1];
  };

  return { pr: value("--pr"), branch: value("--branch") };
};

/**
 * Whether a ref name is one this script is allowed to delete.
 *
 * Deliberately an allowlist on the configured branch prefix rather than a
 * denylist of protected names: a denylist has to anticipate every ref worth
 * protecting, and the reservation and session refs already outnumber the
 * branches it would have named.
 *
 * @param {string} branch
 * @param {{ branchPrefix: string }} config
 */
export const isDeletableBranch = (branch, config) =>
  typeof branch === "string" &&
  branch.startsWith(config.branchPrefix) &&
  branch.length > config.branchPrefix.length &&
  !branch.includes("..") &&
  !branch.endsWith("/");

/**
 * Whether the commit `sha` — the tip the ref listing reported for `branch` on
 * origin — is contained in the integration branch on origin.
 *
 * **Fetches first, always.** See the header: containment judged against stale
 * remote-tracking refs is wrong in the direction that refuses correct
 * deletions, and would be wrong in the dangerous direction if the test were
 * ever inverted.
 *
 * **Judged on `sha`, not on the name `origin/<branch>`**, for the reason the
 * header gives: a `git fetch` can exit 0 without moving the remote-tracking
 * ref, and then the name resolves to an older commit that reads `merged` while
 * the live ref carries unmerged work. A `sha` the fetch did not bring in is an
 * unknown revision, so `--is-ancestor` fails with a status other than 1 and
 * this answers `unknown` — the safe direction.
 *
 * @param {{
 *   git: (args: string[]) => string,
 *   branch: string,
 *   sha: string,
 *   integrationBranch: string,
 * }} input
 * @returns {{ kind: "merged" } | { kind: "unmerged" } | { kind: "unknown", reason: string }}
 */
export const mergeContainment = ({ git, branch, sha, integrationBranch }) => {
  if (typeof sha !== "string" || !/^[0-9a-f]{40}$/.test(sha)) {
    return {
      kind: "unknown",
      reason: `the ref listing reported no usable commit for \`${branch}\``,
    };
  }

  try {
    git(["fetch", "--quiet", "origin", branch, integrationBranch]);
  } catch (error) {
    // A branch already gone from origin cannot be fetched. That is not a
    // failure to establish containment — it is the desired end state, and the
    // caller's presence check reports it as already clean.
    return { kind: "unknown", reason: describeError(error) };
  }

  try {
    git(["merge-base", "--is-ancestor", sha, `origin/${integrationBranch}`]);
    return { kind: "merged" };
  } catch (error) {
    const detail = /** @type {{ status?: number }} */ (error ?? {});
    // `--is-ancestor` exits 1 for "no" and something else for "could not
    // answer". Conflating the two would let a broken repository read as a
    // clean refusal.
    if (detail.status === 1) return { kind: "unmerged" };
    return { kind: "unknown", reason: describeError(error) };
  }
};

/**
 * The tip commit of `branch` on origin, or that it is absent.
 *
 * Presence is established by listing, never inferred from a delete's failure —
 * a branch-scoped credential answers 403 whether or not the ref is there
 *, and an already-absent ref is a success, not a crash.
 *
 * Returns the SHA as well as the verdict, because every containment judgement
 * below is made against that SHA rather than against a ref name.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {string} branch
 * @returns {{ kind: "present", sha: string } | { kind: "absent" } | { kind: "unknown", reason: string }}
 */
export const remoteBranchTip = (gh, repository, branch) => {
  const refs = matchingRefs(gh, repository, branch);

  if (!refs.ok) return { kind: "unknown", reason: refs.reason };

  // `matching-refs` matches on prefix: asking for `agent/128-x` also returns
  // `agent/128-x-extra`. Only an exact hit is this branch, and taking a prefix
  // neighbour for one would delete somebody else's ref.
  const hit = refs.items.find((ref) => ref.ref === `refs/heads/${branch}`);

  if (!hit) return { kind: "absent" };

  return { kind: "present", sha: String(hit.object?.sha ?? "") };
};

/**
 * The branch a pull request merged, if it merged one, and the commit GitHub
 * recorded as its head.
 *
 * `headRefOid` is what makes the `--pr` path safe: `state === "MERGED"` says
 * the pull request's head at merge time went in, so it is evidence about that
 * commit and about no later one. Comparing it to the ref's live tip is how the
 * caller finds out whether it is still talking about the same commit.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} pr
 * @returns {{ ok: true, branch: string, merged: boolean, headSha: string } | { ok: false, reason: string }}
 */
export const pullRequestBranch = (gh, pr) => {
  try {
    // `state` and `mergedAt`, never a `merged` field: `gh pr view` rejects that
    // name outright ("Unknown JSON field") and the refusal arrives as an
    // unreadable pull request rather than as the usage error it is.
    const view = JSON.parse(
      gh("pr", "view", pr, "--json", "headRefName,headRefOid,state,mergedAt"),
    );
    return {
      ok: true,
      branch: String(view.headRefName ?? ""),
      merged: view.state === "MERGED" || Boolean(view.mergedAt),
      headSha: String(view.headRefOid ?? ""),
    };
  } catch (error) {
    return { ok: false, reason: describeError(error) };
  }
};

/**
 * Deletes the local branch if it exists, and reports what happened.
 *
 * **Never fatal, and deliberately runs after the remote delete.** A local
 * worktree still holding a just-merged branch is the normal state minutes after
 * a merge, not an error condition, and letting it decide the exit code is the
 * exact defect this guards against.
 *
 * **`force` is exactly "this run proved the branch merged".** Where it did —
 * the remote ref was present and contained — `-D` is right, because `-d` judges
 * containment against this checkout's own possibly-stale `release` and would
 * refuse a branch already proved merged against origin.
 *
 * Where it did not, `-d` is the only safe verb. A remote ref that was already
 * absent proves nothing: `agent/<typo>` reads as absent, and so does a branch
 * whose work was never pushed anywhere at all. `-D` there destroys unmerged
 * commits on a lookup that never examined them, so this path asks git to make
 * its own containment judgement and accepts a refusal.
 *
 * @param {{ git: (args: string[]) => string, branch: string, force: boolean }} input
 * @returns {{ kind: "deleted" | "absent" | "retained", detail?: string }}
 */
export const deleteLocalBranch = ({ git, branch, force }) => {
  try {
    git(["rev-parse", "--verify", "--quiet", `refs/heads/${branch}`]);
  } catch {
    return { kind: "absent" };
  }

  try {
    git(["branch", force ? "-D" : "-d", branch]);
    return { kind: "deleted" };
  } catch (error) {
    return { kind: "retained", detail: describeError(error) };
  }
};

/**
 * @param {{
 *   argv: string[],
 *   config: { branchPrefix: string, integrationBranch: string },
 *   gh: (...args: string[]) => string,
 *   git: (args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const deleteMergedBranch = ({
  argv,
  config,
  gh,
  git,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { pr, branch: branchFlag } = parseArgs(argv);

  if (!pr === !branchFlag) {
    stderr(
      "Usage: delete-merged-branch.mjs (--pr <merged-pull-request> | --branch <agent-branch>)",
    );
    return EXIT.usage;
  }

  /** @type {string} */
  let branch;
  // The commit a merged pull request vouches for, and only that commit. Empty
  // on the `--branch` path, where nothing vouches for anything yet.
  let mergedSha = "";

  if (pr) {
    const head = pullRequestBranch(gh, pr);
    if (!head.ok) {
      stderr(`Pull request #${pr} could not be read (${head.reason}).`);
      return EXIT.inconclusive;
    }
    if (!head.merged) {
      stderr(`Pull request #${pr} is not merged; \`${head.branch}\` retained.`);
      return EXIT.refused;
    }
    branch = head.branch;
    mergedSha = head.headSha;
  } else {
    branch = /** @type {string} */ (branchFlag);
  }

  if (!isDeletableBranch(branch, config)) {
    stderr(
      `\`${branch}\` does not carry the \`${config.branchPrefix}\` issue-branch prefix; refusing to delete it.`,
    );
    return EXIT.refused;
  }

  // Wrapped like every other `gh` call. Unwrapped, a transport or parse
  // failure threw out of this function and the process exited 1 — which the
  // exit-code table in docs/AGENT_LOOP.md publishes as "usage error", telling
  // the caller to fix its arguments about a problem in the network.
  /** @type {unknown} */
  let repository;

  try {
    repository = JSON.parse(gh("repo", "view", "--json", "nameWithOwner"))
      .nameWithOwner;
  } catch (error) {
    stderr(
      `The repository could not be identified (${describeError(error)}). No delete was attempted.`,
    );
    return EXIT.inconclusive;
  }

  if (typeof repository !== "string" || repository === "") {
    stderr(
      "The repository could not be identified (`gh repo view` reported no `nameWithOwner`). No delete was attempted.",
    );
    return EXIT.inconclusive;
  }

  const refPath = `refs/heads/${branch}`;

  const presence = remoteBranchTip(gh, repository, branch);

  if (presence.kind === "unknown") {
    stderr(
      `Whether \`${refPath}\` exists on origin could not be established (${presence.reason}). No delete was attempted.`,
    );
    return EXIT.inconclusive;
  }

  let exit = EXIT.ok;
  // Only a containment proof made in *this* run licenses `git branch -D`.
  let provedMerged = false;

  if (presence.kind === "absent") {
    // Checked before containment on purpose: a branch already gone from origin
    // is the end state this script exists to reach, and `git fetch` cannot
    // fetch it to prove anything about it. It is also why `provedMerged` stays
    // false here — absence is not evidence, and `agent/<typo>` is absent too.
    stdout(`\`${branch}\` is already absent from origin.`);
  } else {
    // The pull request vouches for one commit. Where the live ref still points
    // at it, that is the whole answer and the fetch buys nothing. Where it does
    // not — a push after the merge, a force-push, an older pull request re-run
    // — the pull request is evidence about a commit that is no longer there,
    // and the ref has to earn its own verdict.
    const vouchedFor = mergedSha !== "" && presence.sha === mergedSha;

    if (vouchedFor) {
      provedMerged = true;
    } else {
      if (mergedSha !== "") {
        stdout(
          `\`${branch}\` has moved since pull request #${pr} merged (${mergedSha.slice(0, 7)} → ${(presence.sha || "unknown").slice(0, 7)}); judging the live tip on its own.`,
        );
      }

      const containment = mergeContainment({
        git,
        branch,
        sha: presence.sha,
        integrationBranch: config.integrationBranch,
      });

      if (containment.kind === "unknown") {
        stderr(
          `Whether \`${branch}\` is merged into \`${config.integrationBranch}\` could not be established (${containment.reason}). No delete was attempted.`,
        );
        return EXIT.inconclusive;
      }

      if (containment.kind === "unmerged") {
        stderr(
          `\`${branch}\` is not contained in \`${config.integrationBranch}\`; refusing to delete it.`,
        );
        return EXIT.refused;
      }

      provedMerged = true;
    }

    try {
      // The mechanism, and the reason this script exists. Not
      // `git push --delete`: that fires `pre-push`, which is the repository's pre-push checks.
      gh("api", "--method", "DELETE", `repos/${repository}/git/${refPath}`);
      stdout(`Deleted \`${branch}\` from origin.`);
    } catch (error) {
      stderr(
        `\`${refPath}\` could not be deleted from origin (${describeError(error)}).`,
      );
      exit = EXIT.deleteFailed;
    }
  }

  // Strictly after the remote delete, and strictly non-fatal.
  const local = deleteLocalBranch({ git, branch, force: provedMerged });

  if (local.kind === "deleted") stdout(`Deleted local \`${branch}\`.`);
  if (local.kind === "retained") {
    stdout(
      provedMerged
        ? `Local \`${branch}\` retained (${local.detail}). Expected while a worktree still holds it; the remote is what matters.`
        : `Local \`${branch}\` retained (${local.detail}). Nothing on origin proved it merged, so it was offered to \`git branch -d\` rather than force-deleted.`,
    );
  }

  return exit;
};

export default deleteMergedBranch;

// Whether this checkout's copy of the coordination protocol is the one the
// integration branch currently defines.
//
// The case this exists for: a session finds its worktree missing a role prompt
// entirely, and carrying a retired `integrationBranch` value. It need not be a
// long-lived worktree that has drifted. Where worktrees are branched from the
// repository default branch, and the default branch is the *tail* of a
// promotion chain rather than the integration branch itself, it can sit
// hundreds of commits behind the branch the protocol is actually defined on. A
// session booting there reads a superseded
// role prompt, superseded docs, and a `.rallypoint/scripts/` directory missing
// entry points the role prompt tells it to run — a janitor's first instructed
// command died with `MODULE_NOT_FOUND` this way.
//
// Nothing in this repository creates those worktrees, so this cannot be fixed
// where it is caused. What it can do is refuse to proceed on a checkout whose
// protocol surface is stale, loudly and at the first command, instead of letting
// each role prompt ask sessions to verify by hand.
//
// The rule is deliberately narrower than "behind the integration branch". A
// worker branch is *supposed* to diverge — that is what a feature branch is —
// and being behind on `src/` is normal and harmless for a session that has just
// branched correctly. What is never acceptable is missing a commit that changed
// the coordination surface itself, so that is exactly what is measured:
// `HEAD..<remote>/<integrationBranch>` restricted to the paths below. Commits
// this branch adds to those paths are in the other direction and do not count,
// so the check does not fire on the very pull request that edits the protocol.
//
// That commit-range measurement alone refuses a whole legitimate class of
// session, unconditionally and by construction. A merger handling a promotion
// necessarily sits on the *base* branch, so it lags the head branch by exactly
// the batch being promoted — coordination-surface commits included. No
// re-created worktree can make that pass, because moving to the head branch
// would mean no longer being on the branch the promotion merges into.
// A check that always fails for a legitimate session class trains that class to
// proceed past it, which is worse than the inconvenience: this guarantee only
// holds while a refusal is believed.
//
// Two changes answer that, and both keep the substance of the question — is the
// protocol this session executes the one the integration branch defines? — by
// asking it of *content* rather than of commit identity:
//
//   1. A missing commit whose content the checkout already carries is not
//      drift. `HEAD...<ref>` restricted to the same paths is what several
//      reviewer sessions independently hand-rolled to decide the
//      drift they were being refused over was benign. Three dots, not two: it
//      measures only what `<ref>` added since the merge base, so a branch's own
//      protocol edits are not counted against it.
//   2. `--promoting <head>` names the branch being merged in, so the comparison
//      is made against the batch rather than against a branch the checkout is
//      not supposed to be on. Promotion is established from that argument
//      through `isPromotionBranch`, never inferred from what the checkout
//      happens to be — inferring from the checkout is precisely what would let
//      a genuinely stale worktree excuse itself.
//
// A promotion whose batch genuinely changes the coordination surface is still
// surfaced, under its own exit code: the scripts and role prompts that session
// runs are the base branch's, and that is the substance of what a merger would
// otherwise have to check by hand.

import { isPromotionBranch } from "../provenance.mjs";

/**
 * The files that define the protocol a session executes. A missing commit
 * touching any of them means this checkout is running instructions or tooling
 * that the integration branch has already replaced.
 *
 * `docs/` beyond `AGENT_LOOP.md` is deliberately absent: product and
 * architecture docs go stale harmlessly for the length of one session, and
 * including them would fire this check constantly for no protocol reason.
 */
export const COORDINATION_PATHS = [
  ".rallypoint",
  "docs/AGENT_LOOP.md",
  "AGENTIC_LOOP.md",
  "AGENTS.md",
];

export const EXIT = {
  ok: 0,
  usage: 1,
  // The checkout is provably behind on the coordination surface.
  stale: 2,
  // The comparison could not be established. Not "fresh": the same rule
  // `report.mjs`, `lease.mjs`, and `release-claim.mjs` keep — a lookup that
  // failed is never evidence of the reassuring answer.
  unknown: 3,
  // A promotion whose batch itself changes the coordination surface. Kept
  // distinct from `stale` because the two ask for opposite things: `stale`
  // says re-create the checkout from the integration branch, which for a
  // promotion session would abandon the promotion. This says read the diff —
  // the session's own tooling is the base branch's copy — and it is advisory,
  // not a re-created-worktree instruction.
  promotionCarriesProtocol: 4,
};

/**
 * `EX_TEMPFAIL` from sysexits.h: "temporary failure; the user is invited to
 * retry". Exactly right here — the checkout is not broken, it is behind, and
 * re-creating it from the integration branch makes the same command succeed.
 *
 * A separate code from every per-command exit table in `docs/AGENT_LOOP.md`
 * (none exceeds 11) and from `EXIT_MISSING_PREREQUISITE` (69), so a caller
 * branching on a claim's own exit codes cannot mistake a stale checkout for
 * "no issue available".
 */
export const EXIT_STALE_CHECKOUT = 75;

export const DEFAULT_REMOTE = "origin";

/** How many missing commits to name before summarising the rest. */
const SAMPLE_SIZE = 5;

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  const promotingIndex = argv.indexOf("--promoting");

  return {
    allowStale: argv.includes("--allow-stale"),
    // A session working offline, or a test, can skip the network round trip and
    // compare against whatever the remote-tracking ref already says.
    fetch: !argv.includes("--no-fetch"),
    // The head branch of a promotion pull request this session is handling.
    // `undefined` when the flag is absent; the empty string when it was passed
    // without a value, which is a usage error rather than a missing flag.
    promoting: promotingIndex === -1 ? undefined : (argv[promotingIndex + 1] ?? ""),
  };
};

/**
 * @param {string} text
 * @returns {string[]}
 */
const lines = (text) =>
  text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

/**
 * What `git rev-parse --abbrev-ref HEAD` prints on a detached checkout. Git
 * refuses to create a branch of that name, so it is unambiguous.
 */
const DETACHED = "HEAD";

/**
 * How to name the checkout in a message.
 *
 * The refusal used to assert flatly that "worktrees here are created at the tip
 * of `main`", which is false for every promotion session — a `release` ->
 * `staging` merger is on `staging` — and whose remediation, followed
 * literally, abandons the promotion. Say what HEAD is actually on
 * instead, and let the reader judge.
 *
 * @param {(...args: string[]) => string} git
 * @returns {string}
 */
export const checkoutDescription = (git) => {
  /** @type {string | undefined} */
  let branch;

  try {
    branch = lines(git("rev-parse", "--abbrev-ref", "HEAD")).at(0);
  } catch {
    return "a checkout whose HEAD could not be read";
  }

  if (branch && branch !== DETACHED) return `the branch \`${branch}\``;

  try {
    const sha = lines(git("rev-parse", "--short", "HEAD")).at(0);
    return sha ? `a detached HEAD at \`${sha}\`` : "a detached HEAD";
  } catch {
    return "a detached HEAD";
  }
};

/**
 * The coordination-surface files `ref` carries that this checkout does not.
 *
 * `HEAD...<ref>` — three dots — diffs the merge base against `ref`, so it
 * reports only what `ref` added and never counts the checkout's own protocol
 * edits against it. This is the exact comparison reviewer and merger sessions
 * kept reinventing by hand.
 *
 * @param {(...args: string[]) => string} git
 * @param {string} ref
 * @returns {{ ok: true, files: string[] } | { ok: false, files: [] }}
 */
export const surfaceDiff = (git, ref) => {
  try {
    return {
      ok: true,
      files: lines(
        git("diff", "--name-only", `HEAD...${ref}`, "--", ...COORDINATION_PATHS),
      ),
    };
  } catch {
    return { ok: false, files: [] };
  }
};

/**
 * @param {{
 *   argv?: string[],
 *   config: { integrationBranch: string, promotionBranch?: string },
 *   git: (...args: string[]) => string,
 *   remote?: string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {{
 *   state: "fresh" | "equivalent" | "stale" | "unknown" | "promotion-clean" | "promotion-protocol",
 *   missing: string[],
 *   differing: string[],
 *   behind: number,
 * }}
 */
export const inspect = ({
  argv = [],
  config,
  git,
  remote = DEFAULT_REMOTE,
  stderr = console.error,
}) => {
  const { fetch, promoting } = parseArgs(argv);
  // A promotion is measured against the batch being merged in, not against a
  // branch the checkout is deliberately not on.
  const target = promoting || config.integrationBranch;
  const ref = `${remote}/${target}`;

  if (fetch) {
    try {
      git("fetch", "--quiet", remote, target);
    } catch {
      // A failed fetch is not a failed check: the remote-tracking ref this
      // clone already has is still evidence, just possibly older than the
      // truth. Under-reporting staleness is the safe direction here — it can
      // only miss a drift, never invent one — and failing closed would stop
      // every offline session dead.
      stderr(
        `Could not fetch \`${ref}\`; comparing against the last known ` +
          "remote-tracking ref instead.",
      );
    }
  }

  try {
    git("rev-parse", "--verify", `${ref}^{commit}`);
  } catch {
    return { state: "unknown", missing: [], differing: [], behind: 0 };
  }

  // A promotion session is behind the head branch by definition, so counting
  // the commits it lacks answers nothing. The only question worth asking is
  // whether the batch changes the protocol the session is executing.
  if (promoting) {
    const diff = surfaceDiff(git, ref);

    if (!diff.ok) {
      return { state: "unknown", missing: [], differing: [], behind: 0 };
    }

    return {
      state: diff.files.length === 0 ? "promotion-clean" : "promotion-protocol",
      missing: [],
      differing: diff.files,
      behind: 0,
    };
  }

  const range = `HEAD..${ref}`;

  try {
    const missing = lines(
      git("log", "--oneline", `--max-count=${SAMPLE_SIZE + 1}`, range, "--", ...COORDINATION_PATHS),
    );

    if (missing.length === 0) {
      return { state: "fresh", missing, differing: [], behind: 0 };
    }

    const behind = Number(lines(git("rev-list", "--count", range)).at(0) ?? "0");
    // Commit identity is the cheap trigger; content is the question. A commit
    // the checkout lacks that changed nothing it does not already carry — a
    // revert, a change the branch itself already made — is not drift.
    const diff = surfaceDiff(git, ref);

    if (!diff.ok) {
      return { state: "unknown", missing: [], differing: [], behind: 0 };
    }

    return {
      state: diff.files.length === 0 ? "equivalent" : "stale",
      missing,
      differing: diff.files,
      behind: Number.isFinite(behind) ? behind : 0,
    };
  } catch {
    return { state: "unknown", missing: [], differing: [], behind: 0 };
  }
};

/**
 * @param {{
 *   ref: string,
 *   checkout: string,
 *   missing: string[],
 *   differing: string[],
 *   behind: number,
 * }} input
 */
export const staleMessage = ({ ref, checkout, missing, differing, behind }) =>
  [
    `This checkout is on ${checkout}, and is missing commits to the ` +
      `Rallypoint coordination surface that \`${ref}\` already carries, so its ` +
      `role prompts, docs, and \`.rallypoint/scripts/\` entry points are not ` +
      `the ones this protocol currently defines.`,
    "",
    ...missing
      .slice(0, SAMPLE_SIZE)
      .map((line) => `  ${line}`)
      .concat(
        missing.length > SAMPLE_SIZE ? [`  ... and more (HEAD is ${behind} commits behind ${ref})`] : [],
      ),
    "",
    `Coordination files that differ from \`${ref}\`:`,
    "",
    ...differing.slice(0, SAMPLE_SIZE).map((file) => `  ${file}`),
    ...(differing.length > SAMPLE_SIZE
      ? [`  ... and ${differing.length - SAMPLE_SIZE} more`]
      : []),
    "",
    "Re-create this worktree from the integration branch, or move onto it:",
    "",
    `  git fetch ${DEFAULT_REMOTE}`,
    `  git checkout -B <your-branch> ${ref}`,
    "",
    "Re-read the role prompt afterwards: it may have changed. If you are",
    "handling a promotion pull request, do neither — moving off this branch",
    "would abandon the promotion. Pass `--promoting <head-branch>` instead.",
    "Pass `--allow-stale` only when an operator has decided the drift is",
    "irrelevant.",
  ].join("\n");

/**
 * @param {{
 *   ref: string,
 *   checkout: string,
 *   promoting: string,
 *   differing: string[],
 * }} input
 */
export const promotionProtocolMessage = ({
  ref,
  checkout,
  promoting,
  differing,
}) =>
  [
    `The batch being promoted from \`${promoting}\` changes the Rallypoint ` +
      `coordination surface. This checkout is on ${checkout}, so the role ` +
      `prompts, docs, and \`.rallypoint/scripts/\` entry points this session ` +
      `runs are the pre-promotion copies, not the ones \`${ref}\` defines.`,
    "",
    ...differing.slice(0, SAMPLE_SIZE).map((file) => `  ${file}`),
    ...(differing.length > SAMPLE_SIZE
      ? [`  ... and ${differing.length - SAMPLE_SIZE} more`]
      : []),
    "",
    "This is the batch itself, not a stale worktree: do not re-create this",
    "checkout from the integration branch, which would abandon the promotion.",
    "Read the diff before acting on anything the pre-promotion protocol says:",
    "",
    `  git diff HEAD...${ref} -- ${COORDINATION_PATHS.join(" ")}`,
    "",
    "The check is advisory here. Proceeding is legitimate once the diff has",
    "been read and found not to change what this session is about to do.",
  ].join("\n");

/**
 * The standalone command, and the guard the entry points call.
 *
 * @param {{
 *   argv?: string[],
 *   config: { integrationBranch: string, promotionBranch?: string },
 *   git: (...args: string[]) => string,
 *   remote?: string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const freshness = ({
  argv = [],
  config,
  git,
  remote = DEFAULT_REMOTE,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { allowStale, promoting } = parseArgs(argv);

  // Promotion is established from the argument, through the same predicate
  // `preflight.mjs` uses, and never inferred from what
  // the checkout happens to be — inference from the checkout is exactly what
  // would let a genuinely stale worktree excuse itself.
  // A snapshot promotion head (`<promotionSnapshotPrefix><name>`) is
  // accepted here on containment alone: there is no pull request in view, so
  // there is no base to state and none to forge either — `baseRefName: null`
  // says exactly that. Containment is the whole guard, and it is a *stronger*
  // proof than the exact name ever was against the worry above, a stale worktree
  // excusing itself: a head reachable from `origin/<snapshotted>` is by
  // definition carrying no protocol the batch does not already have.
  const promotionEvidence = {
    /** @type {string | null} */
    baseRefName: null,
    /** @param {string} snapshotted */
    containedIn: (snapshotted) => {
      try {
        git("merge-base", "--is-ancestor", "HEAD", `${remote}/${snapshotted}`);
        return true;
      } catch {
        return false;
      }
    },
  };

  if (
    promoting !== undefined &&
    !isPromotionBranch(promoting, config, promotionEvidence)
  ) {
    stderr(
      promoting === ""
        ? "Usage: freshness.mjs [--promoting <head-branch>] [--allow-stale] [--no-fetch]"
        : `\`--promoting ${promoting}\` does not name a promotion head branch. ` +
            `A promotion's head is \`${config.integrationBranch}\`` +
            (config.promotionBranch ? ` or \`${config.promotionBranch}\`` : "") +
            ". Run the check without `--promoting` for any other session.",
    );
    return EXIT.usage;
  }

  const ref = `${remote}/${promoting || config.integrationBranch}`;
  const { state, missing, differing, behind } = inspect({
    argv,
    config,
    git,
    remote,
    stdout,
    stderr,
  });
  const checkout = checkoutDescription(git);

  if (state === "unknown") {
    stderr(
      `Could not establish whether this checkout carries the current ` +
        `coordination protocol: \`${ref}\` could not be read. Fetch it, or ` +
        "pass `--allow-stale` to proceed without the check.",
    );
    return allowStale ? EXIT.ok : EXIT.unknown;
  }

  if (state === "fresh") {
    stdout(`Coordination protocol matches \`${ref}\`.`);
    return EXIT.ok;
  }

  if (state === "equivalent") {
    stdout(
      `Coordination protocol matches \`${ref}\`. This checkout is on ` +
        `${checkout} and lacks ${missing.length === 1 ? "a commit" : `${missing.length} commits`} ` +
        `touching the coordination surface, but the surface's content is ` +
        `identical, so the protocol this session executes is the current one.`,
    );
    return EXIT.ok;
  }

  if (state === "promotion-clean") {
    stdout(
      `Coordination protocol matches \`${ref}\`. This checkout is on ` +
        `${checkout}, the base of a promotion from \`${promoting}\`, and the ` +
        "batch being promoted changes nothing on the coordination surface, so " +
        "the protocol this session executes is the one being promoted.",
    );
    return EXIT.ok;
  }

  if (state === "promotion-protocol") {
    stderr(
      promotionProtocolMessage({
        ref,
        checkout,
        promoting: /** @type {string} */ (promoting),
        differing,
      }),
    );
    return allowStale ? EXIT.ok : EXIT.promotionCarriesProtocol;
  }

  stderr(staleMessage({ ref, checkout, missing, differing, behind }));
  return allowStale ? EXIT.ok : EXIT.stale;
};

export default freshness;

// The real `gh` runner and the config load, kept out of the pure modules so no
// test can reach the live repository by importing one of them.

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import process from "node:process";
import { fileURLToPath } from "node:url";

import { createTransport } from "./api.mjs";
import { validateConfig } from "./config.mjs";
import { EXIT_MISSING_PREREQUISITE, checkGh } from "./prerequisites.mjs";
import { repositoryFrom, syncRequest } from "./request.mjs";

// Probed once per process, and lazily: importing this module must stay free of
// side effects, and a command that never reaches GitHub should not require a
// binary it will not use.
let ghAvailable = false;

/**
 * A deliberate testability seam: a fixture that sets this variable to
 * the absolute path of a `.mjs` file redirects every `gh` invocation below to
 * `process.execPath <that file>` instead of resolving a `gh` binary from
 * `PATH`. That sidesteps two POSIX-only assumptions the previous fixtures
 * made — that an extensionless file can be marked executable, and that `PATH`
 * is `:`-delimited — without touching how the real `gh` is invoked in
 * production, where this variable is never set.
 *
 * A default of `"gh"` rather than reading an ambient variable that might
 * already be set is deliberate: fixtures must opt in explicitly, so this
 * cannot become a way for an unrelated test, or a developer's environment, to
 * silently redirect a script at something other than the real `gh` CLI.
 */
const GH_SCRIPT_ENV = "RALLYPOINT_GH_SCRIPT";

/**
 * Resolves the command and leading arguments used to invoke `gh`, honouring
 * the `RALLYPOINT_GH_SCRIPT` override described above.
 *
 * @returns {{ command: string, prefixArgs: string[] }}
 */
const ghCommand = () => {
  const script = process.env[GH_SCRIPT_ENV];
  if (script) return { command: process.execPath, prefixArgs: [script] };
  return { command: "gh", prefixArgs: [] };
};

/**
 * Establishes that `gh` is runnable before the first call that needs it, so a
 * missing prerequisite is reported by name instead of arriving as an
 * `execFileSync` ENOENT several calls into a claim.
 */
export const ensureGh = () => {
  if (ghAvailable) return;

  const { command, prefixArgs } = ghCommand();
  const result = checkGh({
    probe: () =>
      execFileSync(command, [...prefixArgs, "--version"], {
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
      }),
  });

  if (!result.ok) {
    console.error(result.message);
    process.exit(EXIT_MISSING_PREREQUISITE);
  }

  ghAvailable = true;
};

/** @param {string[]} args */
export const gh = (...args) => {
  ensureGh();

  const { command, prefixArgs } = ghCommand();
  return execFileSync(command, [...prefixArgs, ...args], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
};

/** @param {string[]} args */
export const git = (...args) =>
  execFileSync("git", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();

/**
 * Whether the `gh` binary is on `PATH`, asked once and before any request so a
 * missing prerequisite is reported by name rather than three calls into a
 * claim — the missing-prerequisite failure mode, extended to the transport
 * choice itself.
 */
const hasGh = () => {
  try {
    const { command, prefixArgs } = ghCommand();
    execFileSync(command, [...prefixArgs, "--version"], { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
};

/**
 * The transport Rallypoint scripts should use here: `gh` when it is
 * installed, since it is the reference implementation and carries its own
 * auth; otherwise the REST transport in `api.mjs`, which needs no binary at
 * all — cloud agent sessions have none, and every coordination
 * command was failing with `spawnSync gh ENOENT`.
 *
 * Not pre-flighted: a request GitHub refuses reports GitHub's own reason,
 * which is more useful than any guess this could make beforehand.
 *
 * @param {{ remote?: string }} [input]
 * @returns {(...args: string[]) => string}
 */
export const resolveTransport = ({ remote } = {}) => {
  if (hasGh()) return gh;

  const repository = repositoryFrom({
    remote:
      remote ??
      (() => {
        try {
          return execFileSync("git", ["config", "--get", "remote.origin.url"], {
            encoding: "utf8",
            stdio: ["ignore", "pipe", "ignore"],
          }).trim();
        } catch {
          return "";
        }
      })(),
  });

  if (!repository) {
    console.error(
      "No `gh` on PATH and no repository could be read from the git remote, " +
        "so there is no way to reach GitHub. Set GITHUB_REPOSITORY to " +
        "`owner/repo`, or run this from a checkout with an `origin` remote.",
    );
    process.exit(1);
  }

  return createTransport({ request: syncRequest(), repository });
};

// Resolved on call rather than at module scope. `import.meta.url` is not a
// `file:` URL under every loader — vitest's is not — so doing this at import
// time made this module unimportable from anything a test touches, which is
// the opposite of what the header above intends. Only `checkPullRequest` needs
// the path, and only when it actually runs.
const reviewScript = () =>
  fileURLToPath(new URL("../review.mjs", import.meta.url));

/**
 * Runs `review.mjs check --pr <n>` and reports its exit code, rather than
 * reimplementing the exit-code table it already owns. `review.mjs check` is
 * itself read-only — it only ever removes a stale `review:approved` label
 * under `--strip-stale`, which this call never passes — so this stays within
 * the report's own read-only contract.
 *
 * @param {number} pr
 * @returns {{ code: number | null, output: string }}
 */
export const checkPullRequest = (pr) => {
  try {
    const stdout = execFileSync(
      process.execPath,
      [reviewScript(), "check", "--pr", String(pr)],
      { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    );
    return { code: 0, output: stdout.trim() };
  } catch (error) {
    const detail = /** @type {{ status?: unknown, stderr?: unknown, stdout?: unknown, message?: unknown }} */ (
      error ?? {}
    );
    return {
      code: typeof detail.status === "number" ? detail.status : null,
      output: String(detail.stderr ?? detail.stdout ?? detail.message ?? "").trim(),
    };
  }
};

/**
 * Reads and validates `.rallypoint/config.json`. A malformed config is fatal
 * here rather than a confusing failure three `gh` calls later.
 */
export const loadConfig = () => {
  const config = JSON.parse(
    readFileSync(new URL("../../config.json", import.meta.url), "utf8"),
  );
  const result = validateConfig(config);

  if (!result.ok) {
    for (const problem of result.problems) {
      console.error(`.rallypoint/config.json: ${problem}`);
    }
    process.exit(1);
  }

  return config;
};

// The self-improvement layer: what the loop measures about itself, and the
// rules a change to its own role prompts must pass before and after it merges.
//
// The role prompts were tuned by hand, from incidents an operator happened to
// notice. The improver role closes that loop: it reads the loop's own history,
// proposes one change to one tunable prompt, and lets the result decide whether
// the change stays. This module is every part of that the improver must not be
// trusted to judge for itself:
//
//  - **the metrics**, computed from merged and closed pull requests and the
//    verdicts `review.mjs` recorded on them, never from a session's account of
//    how its own work went;
//  - **the frozen paths**, which no improvement may touch without a person —
//    above all the reviewer's and merger's prompts and every script, because an
//    optimiser allowed to edit its own judge improves the score, not the work;
//  - **the before/after verdict** that decides whether a merged change is kept
//    or reverted, against a counter-metric the proposal had to name up front.
//
// One change at a time is a rule, not a preference. Two prompt changes under
// evaluation at once cannot be told apart, so `check` refuses a new proposal
// while the previous one is still being measured.
//
// The same rule as `lib/report.mjs` holds here: a source that could not be read
// is `unknown`, never "nothing there". A metric computed from a partial history
// is a wrong number with a confident face, and a wrong number decides a revert.
//
// Every `gh` call is injected. Only `evaluate --record` writes anything, and
// what it writes is one comment carrying the result.

import { parseVerdicts } from "../verdicts.mjs";

// Exit codes are a public interface, as they are for `review.mjs` and
// `report.mjs`. Keep these in sync with the tables in docs/AGENT_LOOP.md and
// `.rallypoint/roles/improver.md`.
export const EXIT = {
  ok: 0,
  usage: 1,
  // status: an evaluation or a revert is due · check: no valid improvement block
  // evaluate: the change is not kept, revert it
  second: 2,
  // status: the last change is still being measured · check: touches a path
  // that is not tunable · evaluate: inconclusive, not enough history yet
  third: 3,
  // status: an improvement pull request is already open · check: the previous
  // improvement has not been evaluated yet
  fourth: 4,
  // A source could not be read, so nothing was decided.
  unknown: 5,
};

export const MARKER = "rallypoint-improvement";
export const EVALUATION_MARKER = "rallypoint-evaluation";
/** The trailer, flush-left in a pull request body, that reverts a change. */
export const REVERT_TRAILER = "Reverts-Improvement";

/**
 * What the loop can measure about itself. `better` is the direction an
 * improvement has to move a metric in; nothing is "improved" by moving the
 * other way, however the proposal frames it.
 */
export const METRICS = {
  firstPassApprovalRate: {
    better: "up",
    describe: "share of merged pull requests that never drew a request-changes verdict",
  },
  meanReviewRounds: {
    better: "down",
    describe: "request-changes verdicts per merged pull request",
  },
  abandonRate: {
    better: "down",
    describe: "share of closed pull requests that closed without merging",
  },
  escalationRate: {
    better: "down",
    describe: "share of closed pull requests carrying the human label",
  },
  medianHoursToMerge: {
    better: "down",
    describe: "median hours from opening to merge",
  },
  mergedUnreviewedRate: {
    better: "down",
    describe: "share of merged pull requests labelled merged-unreviewed",
  },
};

/**
 * Checked on every evaluation whatever the proposal named. A change that
 * speeds the loop up by getting work merged past review has not improved it.
 */
const ALWAYS_GUARDED = "mergedUnreviewedRate";

/**
 * Paths no improvement may touch, whatever `improvement.tunablePaths` says.
 * Frozen wins over tunable: an operator widening the tunable set to
 * `.rallypoint/` must not thereby hand the improver the scripts that enforce
 * the protocol, the judge's own prompt, or this role's own boundaries.
 */
export const ALWAYS_FROZEN = [
  ".rallypoint/scripts/",
  ".rallypoint/config.json",
  ".rallypoint/roles/reviewer.md",
  ".rallypoint/roles/merger.md",
  ".rallypoint/roles/improver.md",
  ".github/",
  "AGENTIC_LOOP.md",
  "AGENTS.md",
  "docs/AGENT_LOOP.md",
];

const DEFAULTS = {
  label: "loop:improvement",
  tunablePaths: [".rallypoint/roles/"],
  evaluationSample: 10,
  windowDays: 14,
  counterTolerance: 0.1,
};

/**
 * The `improvement` settings with their defaults applied. Every field is
 * optional, so a config written before this layer existed keeps working.
 *
 * @param {{ labels?: Record<string, unknown>, improvement?: Record<string, unknown> }} config
 */
export const settings = (config) => {
  const improvement = config.improvement ?? {};
  return {
    label:
      typeof config.labels?.improvement === "string"
        ? config.labels.improvement
        : DEFAULTS.label,
    tunablePaths: Array.isArray(improvement.tunablePaths)
      ? /** @type {string[]} */ (improvement.tunablePaths)
      : DEFAULTS.tunablePaths,
    evaluationSample:
      typeof improvement.evaluationSample === "number"
        ? improvement.evaluationSample
        : DEFAULTS.evaluationSample,
    windowDays:
      typeof improvement.windowDays === "number"
        ? improvement.windowDays
        : DEFAULTS.windowDays,
    counterTolerance:
      typeof improvement.counterTolerance === "number"
        ? improvement.counterTolerance
        : DEFAULTS.counterTolerance,
  };
};

/**
 * Validation for the optional `improvement` block, called from
 * `lib/config.mjs`. Absent is fine; present and malformed is rejected, because
 * a sample size that reads as `undefined` would evaluate every change on no
 * history at all.
 *
 * @param {unknown} improvement
 * @returns {string[]} problems
 */
export const validateImprovement = (improvement) => {
  if (improvement === undefined) return [];
  if (typeof improvement !== "object" || improvement === null) {
    return ["`improvement` must be an object when present."];
  }

  const problems = [];
  const { tunablePaths, evaluationSample, windowDays, counterTolerance } =
    /** @type {Record<string, unknown>} */ (improvement);

  if (
    tunablePaths !== undefined &&
    (!Array.isArray(tunablePaths) ||
      !tunablePaths.every(
        (path) => typeof path === "string" && path.trim() !== "",
      ))
  ) {
    problems.push("`improvement.tunablePaths` must be an array of non-empty paths.");
  }

  for (const [key, value] of [
    ["evaluationSample", evaluationSample],
    ["windowDays", windowDays],
  ]) {
    if (value !== undefined && !(Number.isInteger(value) && Number(value) > 0)) {
      problems.push(`\`improvement.${key}\` must be a positive integer.`);
    }
  }

  if (
    counterTolerance !== undefined &&
    !(
      typeof counterTolerance === "number" &&
      counterTolerance >= 0 &&
      counterTolerance <= 1
    )
  ) {
    problems.push("`improvement.counterTolerance` must be a number from 0 to 1.");
  }

  return problems;
};

/**
 * @param {string} path
 * @param {string} entry A file, or a directory when it ends in `/`.
 */
const covers = (path, entry) =>
  entry.endsWith("/") ? path.startsWith(entry) : path === entry;

/**
 * Splits a pull request's changed files into the ones an improvement may make
 * and the ones that need a person. A file is tunable only when a tunable entry
 * covers it and no frozen entry does.
 *
 * @param {string[]} files
 * @param {string[]} tunablePaths
 */
export const classifyFiles = (files, tunablePaths) => {
  const frozen = files.filter((file) =>
    ALWAYS_FROZEN.some((entry) => covers(file, entry)),
  );
  const outside = files.filter(
    (file) =>
      !frozen.includes(file) &&
      !tunablePaths.some((entry) => covers(file, entry)),
  );
  return { frozen, outside };
};

/**
 * The single improvement block a proposal's pull request body must open with
 * a line of its own:
 *
 * ```text
 * <!-- rallypoint-improvement
 * metric: firstPassApprovalRate
 * counter-metric: medianHoursToMerge
 * baseline: 0.62
 * -->
 * ```
 *
 * `baseline` is what `retro` reported when the change was proposed. It is a
 * record for the reader, not an input to `evaluate`, which recomputes the
 * before window itself rather than trusting a number the proposer typed.
 *
 * @param {string | null | undefined} body
 * @returns {{ ok: true, metric: string, counterMetric: string, baseline: string | null }
 *   | { ok: false, reason: string }}
 */
export const parseImprovement = (body) => {
  const blocks = [
    ...(body ?? "").matchAll(new RegExp(`<!--\\s*${MARKER}\\b([\\s\\S]*?)-->`, "g")),
  ];

  if (blocks.length === 0) {
    return { ok: false, reason: `no \`${MARKER}\` block in the pull request body` };
  }
  if (blocks.length > 1) {
    return { ok: false, reason: `more than one \`${MARKER}\` block; there is no principled way to choose` };
  }

  /** @param {string} name */
  const field = (name) => {
    const found = [
      ...blocks[0][1].matchAll(new RegExp(`^[^\\S\\n]*${name}:[^\\S\\n]*(\\S+)[^\\S\\n]*$`, "gm")),
    ];
    return found.length === 1 ? found[0][1] : undefined;
  };

  const metric = field("metric");
  const counterMetric = field("counter-metric");

  if (!metric || !(metric in METRICS)) {
    return { ok: false, reason: `\`metric\` must name exactly one of: ${Object.keys(METRICS).join(", ")}` };
  }
  if (metric === ALWAYS_GUARDED) {
    return { ok: false, reason: `\`${ALWAYS_GUARDED}\` is guarded on every evaluation and cannot be the target` };
  }
  if (!counterMetric || !(counterMetric in METRICS)) {
    return { ok: false, reason: "`counter-metric` must name exactly one known metric" };
  }
  if (counterMetric === metric) {
    return { ok: false, reason: "`counter-metric` must differ from `metric`; a metric cannot audit itself" };
  }

  return { ok: true, metric, counterMetric, baseline: field("baseline") ?? null };
};

/**
 * @typedef {{
 *   number: number,
 *   title: string,
 *   body: string,
 *   headRefName: string,
 *   labels: string[],
 *   createdAt: string,
 *   closedAt: string | null,
 *   mergedAt: string | null,
 * }} Pull
 */

/**
 * @template T
 * @typedef {{ ok: true, value: T } | { ok: false, reason: string }} Lookup
 */

/**
 * @param {unknown} pull
 * @returns {Pull}
 */
const pullFields = (pull) => {
  const raw = /** @type {Record<string, any>} */ (pull);
  return {
    number: raw.number,
    title: raw.title ?? "",
    body: raw.body ?? "",
    headRefName: raw.head?.ref ?? "",
    labels: (raw.labels ?? []).map((/** @type {{ name: string }} */ label) => label.name),
    createdAt: raw.created_at,
    closedAt: raw.closed_at ?? null,
    mergedAt: raw.merged_at ?? null,
  };
};

/**
 * Every pull request in one state, through `gh api --paginate`, which both
 * transports implement and which reads every page rather than stopping at a
 * limit that could silently truncate the history.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {"open" | "closed"} state
 * @returns {Lookup<Pull[]>}
 */
export const listPulls = (gh, repository, state) => {
  try {
    const body = JSON.parse(
      gh(
        "api",
        "--paginate",
        `repos/${repository}/pulls?state=${state}&per_page=100&sort=created&direction=desc`,
      ),
    );
    if (!Array.isArray(body)) return { ok: false, reason: `${state} pull requests: not a list` };
    return { ok: true, value: body.map(pullFields) };
  } catch (error) {
    return { ok: false, reason: `${state} pull requests: ${String(/** @type {Error} */ (error).message ?? error).split("\n")[0]}` };
  }
};

/**
 * @param {(...args: string[]) => string} gh
 * @param {string} path
 * @param {string} what
 * @returns {Lookup<Record<string, any>[]>}
 */
const paginated = (gh, path, what) => {
  try {
    const body = JSON.parse(gh("api", "--paginate", path));
    if (!Array.isArray(body)) return { ok: false, reason: `${what}: not a list` };
    return { ok: true, value: body };
  } catch (error) {
    return { ok: false, reason: `${what}: ${String(/** @type {Error} */ (error).message ?? error).split("\n")[0]}` };
  }
};

/**
 * The verdicts and request-changes notes recorded on one pull request. Notes
 * are the `- ` lines `review.mjs record` writes under the block; only a review
 * that parses as a request-changes verdict contributes them, so ordinary
 * conversation never reads as reviewer friction.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {number} number
 * @returns {Lookup<{ requestChanges: number, notes: string[] }>}
 */
export const readReviews = (gh, repository, number) => {
  const reviews = paginated(gh, `repos/${repository}/pulls/${number}/reviews`, `reviews on #${number}`);
  if (!reviews.ok) return reviews;

  const shaped = reviews.value.map((review) => ({
    body: review.body ?? "",
    submittedAt: review.submitted_at ?? null,
    commitId: review.commit_id ?? null,
  }));

  const requestChanges = parseVerdicts(shaped).filter(
    (verdict) => verdict.verdict === "request-changes",
  ).length;

  const notes = shaped.flatMap((review) => {
    const [verdict] = parseVerdicts([review]);
    if (verdict?.verdict !== "request-changes") return [];
    const after = review.body.slice(review.body.indexOf("-->") + 3);
    return [...after.matchAll(/^- (.+)$/gm)].map((match) => match[1].trim());
  });

  return { ok: true, value: { requestChanges, notes } };
};

/**
 * Whether a pull request is agent work the loop should be measured on: an
 * issue branch under the configured prefix, and not itself an improvement,
 * which would have the loop grading its own tuning as delivery.
 *
 * @param {Pull} pull
 * @param {{ branchPrefix: string }} config
 * @param {string} label
 */
export const isMeasured = (pull, config, label) =>
  pull.headRefName.startsWith(config.branchPrefix) && !pull.labels.includes(label);

/** @param {number[]} values */
const median = (values) => {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2;
};

/**
 * @param {number} part
 * @param {number} whole
 */
const share = (part, whole) => (whole === 0 ? null : part / whole);

/**
 * The metrics over a set of closed pull requests. A rate over an empty set is
 * `null` — not `0`, which would read as a perfect score.
 *
 * @param {Pull[]} pulls closed pull requests
 * @param {Map<number, { requestChanges: number }>} reviews by pull request
 * @param {{ human: string, mergedUnreviewed?: string }} labels
 */
export const measure = (pulls, reviews, labels) => {
  const merged = pulls.filter((pull) => pull.mergedAt);
  const rounds = merged.map((pull) => reviews.get(pull.number)?.requestChanges ?? 0);

  return {
    closed: pulls.length,
    merged: merged.length,
    metrics: {
      firstPassApprovalRate: share(rounds.filter((count) => count === 0).length, merged.length),
      meanReviewRounds:
        merged.length === 0 ? null : rounds.reduce((sum, count) => sum + count, 0) / merged.length,
      abandonRate: share(pulls.length - merged.length, pulls.length),
      escalationRate: share(
        pulls.filter((pull) => pull.labels.includes(labels.human)).length,
        pulls.length,
      ),
      medianHoursToMerge: median(
        merged.map(
          (pull) => (Date.parse(String(pull.mergedAt)) - Date.parse(pull.createdAt)) / 3_600_000,
        ),
      ),
      mergedUnreviewedRate: share(
        merged.filter((pull) => pull.labels.includes(labels.mergedUnreviewed ?? "merged:unreviewed")).length,
        merged.length,
      ),
    },
  };
};

/**
 * Request-changes notes that recur across pull requests: the friction a role
 * prompt could have prevented. Normalised so `src/a.ts` and `src/b.ts` in an
 * otherwise identical note count as one, and counted once per pull request so
 * a single long review cannot dominate.
 *
 * @param {Map<number, { notes: string[] }>} reviews
 * @param {number} [limit]
 */
export const recurringNotes = (reviews, limit = 10) => {
  /** @type {Map<string, { note: string, pulls: number[] }>} */
  const groups = new Map();

  for (const [number, { notes }] of reviews) {
    for (const note of new Set(notes)) {
      const key = note
        .toLowerCase()
        .replace(/`[^`]*`/g, "`…`")
        .replace(/#?\d+/g, "#")
        .replace(/[^\p{L}\p{N}`…#]+/gu, " ")
        .trim()
        .slice(0, 120);
      if (key === "") continue;
      const group = groups.get(key) ?? { note, pulls: [] };
      if (!group.pulls.includes(number)) group.pulls.push(number);
      groups.set(key, group);
    }
  }

  return [...groups.values()]
    .filter((group) => group.pulls.length >= 2)
    .sort((left, right) => right.pulls.length - left.pulls.length)
    .slice(0, limit);
};

/**
 * Compares a metric before and after a change.
 *
 * @param {string} metric
 * @param {number | null} before
 * @param {number | null} after
 * @param {number} tolerance relative worsening allowed before it counts
 * @returns {"better" | "same" | "worse" | "unknown"}
 */
export const movement = (metric, before, after, tolerance = 0) => {
  if (before === null || after === null) return "unknown";
  const direction = METRICS[/** @type {keyof typeof METRICS} */ (metric)].better === "up" ? 1 : -1;
  const delta = (after - before) * direction;
  const scale = Math.max(Math.abs(before), 1e-9);
  if (delta > 0) return "better";
  if (-delta / scale > tolerance) return "worse";
  return "same";
};

/**
 * The decision `evaluate` reports. Kept only when the target metric moved the
 * right way and neither the named counter-metric nor the always-guarded one
 * worsened beyond tolerance. "Same" is not kept: a prompt change that buys
 * nothing is only more prompt.
 *
 * @param {{ metric: string, counterMetric: string }} proposal
 * @param {Record<string, number | null>} before
 * @param {Record<string, number | null>} after
 * @param {number} tolerance
 * @returns {{ result: "kept" | "reverted" | "inconclusive", reasons: string[] }}
 */
export const decide = (proposal, before, after, tolerance) => {
  const target = movement(proposal.metric, before[proposal.metric], after[proposal.metric]);
  const counter = movement(proposal.counterMetric, before[proposal.counterMetric], after[proposal.counterMetric], tolerance);
  const guard = movement(ALWAYS_GUARDED, before[ALWAYS_GUARDED], after[ALWAYS_GUARDED]);

  if (target === "unknown") {
    return { result: "inconclusive", reasons: [`\`${proposal.metric}\` has no value on one side of the change`] };
  }

  const reasons = [];
  if (target !== "better") reasons.push(`\`${proposal.metric}\` did not improve (${target})`);
  if (counter === "worse") reasons.push(`counter-metric \`${proposal.counterMetric}\` worsened beyond tolerance`);
  if (guard === "worse") reasons.push(`\`${ALWAYS_GUARDED}\` rose`);

  return reasons.length === 0
    ? { result: "kept", reasons: [`\`${proposal.metric}\` improved and no guard worsened`] }
    : { result: "reverted", reasons };
};

/**
 * Merged improvement pull requests, newest merge first.
 *
 * @param {Pull[]} closed
 * @param {string} label
 */
export const mergedImprovements = (closed, label) =>
  closed
    .filter((pull) => pull.mergedAt && pull.labels.includes(label))
    .sort((left, right) => Date.parse(String(right.mergedAt)) - Date.parse(String(left.mergedAt)));

/**
 * The before and after samples around one merged improvement: the
 * `evaluationSample` measured pull requests that closed last before it merged,
 * and the first that many *opened* after it — work begun earlier was written
 * under the old prompt — stopping at the next improvement's merge, so a later
 * change is never credited to this one. Equal-sized samples on
 * both sides, by count rather than by days, so a quiet week cannot be compared
 * against a busy one as if they were the same evidence.
 *
 * @param {Pull[]} closed
 * @param {Pull} improvement
 * @param {{ branchPrefix: string }} config
 * @param {ReturnType<typeof settings>} options
 */
export const samples = (closed, improvement, config, options) => {
  const pivot = Date.parse(String(improvement.mergedAt));
  const next = mergedImprovements(closed, options.label)
    .map((pull) => Date.parse(String(pull.mergedAt)))
    .filter((at) => at > pivot)
    .sort((a, b) => a - b)
    .at(0) ?? Number.POSITIVE_INFINITY;

  const measured = closed
    .filter((pull) => pull.closedAt && isMeasured(pull, config, options.label))
    .sort((left, right) => Date.parse(String(left.closedAt)) - Date.parse(String(right.closedAt)));

  const before = measured
    .filter((pull) => Date.parse(String(pull.closedAt)) < pivot)
    .slice(-options.evaluationSample);
  const after = measured
    .filter((pull) => {
      const at = Date.parse(pull.createdAt);
      return at >= pivot && at < next;
    })
    .slice(0, options.evaluationSample);

  return { before, after };
};

/**
 * Whether an evaluation has been recorded on a pull request, from its issue
 * comments. Only the first line of the comment is trusted as the marker,
 * the same rule `verdicts.mjs` applies to review blocks: a block quoted inside
 * somebody else's comment is a quotation, not a record.
 *
 * @param {Record<string, any>[]} comments
 * @returns {"kept" | "reverted" | null}
 */
export const recordedEvaluation = (comments) => {
  for (const comment of comments) {
    const body = String(comment.body ?? "").replace(/^﻿/, "");
    const match = body.match(new RegExp(`^<!--\\s*${EVALUATION_MARKER}\\b([\\s\\S]*?)-->`));
    const result = match?.[1].match(/^[^\S\n]*result:[^\S\n]*(kept|reverted)[^\S\n]*$/m)?.[1];
    if (result === "kept" || result === "reverted") return result;
  }
  return null;
};

/** @param {number | null} value */
const show = (value) =>
  value === null ? "—" : Number.isInteger(value) ? String(value) : value.toFixed(2);

/**
 * @param {ReturnType<typeof measure>} sample
 * @param {string} heading
 */
const table = (sample, heading) => [
  `## ${heading} (${sample.closed} closed, ${sample.merged} merged)`,
  "",
  ...Object.entries(sample.metrics).map(
    ([name, value]) =>
      `- ${name}: ${show(value)} (better ${METRICS[/** @type {keyof typeof METRICS} */ (name)].better})`,
  ),
];

const USAGE = [
  "Usage:",
  "  improvement.mjs retro [--days <n>] [--json]",
  "  improvement.mjs status",
  "  improvement.mjs check --pr <n>",
  "  improvement.mjs evaluate --pr <n> [--record --agent-id <id>]",
].join("\n");

/**
 * @param {{
 *   argv: string[],
 *   config: { branchPrefix: string, labels: { human: string, mergedUnreviewed?: string, [key: string]: any }, [key: string]: any },
 *   gh: (...args: string[]) => string,
 *   now?: number,
 *   log?: (line: string) => void,
 *   error?: (line: string) => void,
 * }} input
 * @returns {number} exit code
 */
export const improvement = ({
  argv,
  config,
  gh,
  now = Date.now(),
  log = console.log,
  error = console.error,
}) => {
  const [command, ...rest] = argv;
  /** @param {string} flag */
  const value = (flag) => {
    const index = rest.indexOf(flag);
    return index === -1 ? undefined : rest[index + 1];
  };
  const options = settings(config);

  if (!["retro", "status", "check", "evaluate"].includes(command ?? "")) {
    error(USAGE);
    return EXIT.usage;
  }

  /** @type {string} */
  let repository;
  try {
    repository = JSON.parse(gh("repo", "view", "--json", "nameWithOwner")).nameWithOwner;
  } catch (failure) {
    error(`Unknown: the repository could not be read: ${String(/** @type {Error} */ (failure).message ?? failure).split("\n")[0]}`);
    return EXIT.unknown;
  }

  const closed = listPulls(gh, repository, "closed");
  if (!closed.ok) {
    error(`Unknown: ${closed.reason}. Nothing was decided from a partial history.`);
    return EXIT.unknown;
  }

  /**
   * Reviews for every pull request in the set, or the first read that failed.
   * @param {Pull[]} pulls
   * @returns {Lookup<Map<number, { requestChanges: number, notes: string[] }>>}
   */
  const reviewsFor = (pulls) => {
    const map = new Map();
    for (const pull of pulls.filter((candidate) => candidate.mergedAt)) {
      const read = readReviews(gh, repository, pull.number);
      if (!read.ok) return read;
      map.set(pull.number, read.value);
    }
    return { ok: true, value: map };
  };

  if (command === "retro") {
    const days = value("--days") === undefined ? options.windowDays : Number(value("--days"));
    if (!Number.isInteger(days) || days <= 0) {
      error(USAGE);
      return EXIT.usage;
    }

    const since = now - days * 86_400_000;
    const window = closed.value.filter(
      (pull) => pull.closedAt && Date.parse(pull.closedAt) >= since && isMeasured(pull, config, options.label),
    );
    const reviews = reviewsFor(window);
    if (!reviews.ok) {
      error(`Unknown: ${reviews.reason}. Nothing was decided from a partial history.`);
      return EXIT.unknown;
    }

    const sample = measure(window, reviews.value, config.labels);
    const notes = recurringNotes(reviews.value);

    if (rest.includes("--json")) {
      log(JSON.stringify({ days, ...sample, recurringNotes: notes }, null, 2));
      return EXIT.ok;
    }

    log(
      [
        ...table(sample, `Last ${days} days`),
        "",
        "## Recurring request-changes notes",
        "",
        ...(notes.length === 0
          ? ["None recurred across two or more pull requests."]
          : notes.map((group) => `- ${group.pulls.length}× ${group.note} (${group.pulls.map((n) => `#${n}`).join(", ")})`)),
      ].join("\n"),
    );
    return EXIT.ok;
  }

  const open = listPulls(gh, repository, "open");
  if (!open.ok) {
    error(`Unknown: ${open.reason}.`);
    return EXIT.unknown;
  }

  /**
   * The newest merged improvement's evaluation state. A change evaluated as
   * `reverted` stays outstanding until a pull request carrying its
   * `Reverts-Improvement:` trailer is open or merged: a verdict nobody acts on
   * leaves the losing prompt in place, which is the outcome evaluation exists
   * to prevent.
   * @returns {Lookup<{ pull: Pull, state: "evaluated" | "revert-due" | "due" | "measuring", after: number } | null>}
   */
  const latest = () => {
    const [pull] = mergedImprovements(closed.value, options.label);
    if (!pull) return { ok: true, value: null };

    const comments = paginated(gh, `repos/${repository}/issues/${pull.number}/comments`, `comments on #${pull.number}`);
    if (!comments.ok) return comments;
    const recorded = recordedEvaluation(comments.value);
    if (recorded) {
      const trailer = new RegExp(`^${REVERT_TRAILER}:[^\\S\\n]*#${pull.number}[^\\S\\n]*$`, "m");
      const reverted = [...open.value, ...closed.value].some(
        (candidate) => (candidate.mergedAt || !candidate.closedAt) && trailer.test(candidate.body),
      );
      return {
        ok: true,
        value: {
          pull,
          state: recorded === "reverted" && !reverted ? "revert-due" : "evaluated",
          after: options.evaluationSample,
        },
      };
    }

    const { after } = samples(closed.value, pull, config, options);
    return {
      ok: true,
      value: { pull, state: after.length >= options.evaluationSample ? "due" : "measuring", after: after.length },
    };
  };

  if (command === "status") {
    const inFlight = open.value.filter((pull) => pull.labels.includes(options.label));
    if (inFlight.length > 0) {
      log(`Improvement in flight: ${inFlight.map((pull) => `#${pull.number}`).join(", ")}. Propose nothing until it merges or closes.`);
      return EXIT.fourth;
    }

    const state = latest();
    if (!state.ok) {
      error(`Unknown: ${state.reason}.`);
      return EXIT.unknown;
    }
    if (state.value?.state === "revert-due") {
      log(`Revert due: #${state.value.pull.number} was evaluated as not kept and nothing reverts it yet. Open a pull request carrying \`${REVERT_TRAILER}: #${state.value.pull.number}\`.`);
      return EXIT.second;
    }
    if (state.value?.state === "due") {
      log(`Evaluation due: #${state.value.pull.number} has ${state.value.after} measured pull requests after it. Run \`improvement.mjs evaluate --pr ${state.value.pull.number}\`.`);
      return EXIT.second;
    }
    if (state.value?.state === "measuring") {
      log(`Measuring: #${state.value.pull.number} has ${state.value.after} of ${options.evaluationSample} measured pull requests after it. Propose nothing yet.`);
      return EXIT.third;
    }

    log("Ready: no improvement in flight or under measurement. Run `improvement.mjs retro` and propose one change.");
    return EXIT.ok;
  }

  const pr = Number(value("--pr"));
  if (!Number.isInteger(pr) || pr <= 0) {
    error(USAGE);
    return EXIT.usage;
  }

  if (command === "check") {
    const pull = [...open.value, ...closed.value].find((candidate) => candidate.number === pr);
    if (!pull) {
      error(`Unknown: #${pr} is not among this repository's pull requests.`);
      return EXIT.unknown;
    }

    const proposal = parseImprovement(pull.body);
    if (!proposal.ok) {
      log(`Invalid: ${proposal.reason}.`);
      return EXIT.second;
    }

    const files = paginated(gh, `repos/${repository}/pulls/${pr}/files?per_page=100`, `files on #${pr}`);
    if (!files.ok) {
      error(`Unknown: ${files.reason}.`);
      return EXIT.unknown;
    }

    const { frozen, outside } = classifyFiles(
      files.value.map((file) => String(file.filename)),
      options.tunablePaths,
    );
    if (frozen.length > 0 || outside.length > 0) {
      log(
        [
          "Not tunable: this improvement needs a person to decide.",
          ...frozen.map((file) => `- frozen: ${file}`),
          ...outside.map((file) => `- outside improvement.tunablePaths: ${file}`),
        ].join("\n"),
      );
      return EXIT.third;
    }

    const state = latest();
    if (!state.ok) {
      error(`Unknown: ${state.reason}.`);
      return EXIT.unknown;
    }
    if (state.value && state.value.pull.number !== pr && state.value.state !== "evaluated") {
      const pending = {
        "revert-due": "evaluated as not kept and still unreverted",
        due: "due for evaluation",
        measuring: "still being measured",
      }[state.value.state];
      log(`One change at a time: #${state.value.pull.number} is ${pending}.`);
      return EXIT.fourth;
    }

    log(`OK: #${pr} targets \`${proposal.metric}\`, audited by \`${proposal.counterMetric}\`, and touches only tunable paths.`);
    return EXIT.ok;
  }

  // evaluate
  const pull = closed.value.find((candidate) => candidate.number === pr);
  if (!pull?.mergedAt || !pull.labels.includes(options.label)) {
    error(`#${pr} is not a merged improvement pull request.`);
    return EXIT.usage;
  }

  const proposal = parseImprovement(pull.body);
  if (!proposal.ok) {
    error(`#${pr} carries no valid improvement block (${proposal.reason}), so there is nothing to evaluate it against.`);
    return EXIT.second;
  }

  const sides = samples(closed.value, pull, config, options);
  if (sides.before.length < options.evaluationSample || sides.after.length < options.evaluationSample) {
    log(`Inconclusive: ${sides.before.length} before and ${sides.after.length} after; both need ${options.evaluationSample}.`);
    return EXIT.third;
  }

  const reviews = reviewsFor([...sides.before, ...sides.after]);
  if (!reviews.ok) {
    error(`Unknown: ${reviews.reason}. Nothing was decided from a partial history.`);
    return EXIT.unknown;
  }

  const before = measure(sides.before, reviews.value, config.labels);
  const after = measure(sides.after, reviews.value, config.labels);
  const decision = decide(proposal, before.metrics, after.metrics, options.counterTolerance);

  const report = [
    `**Evaluation of #${pr}: ${decision.result}.**`,
    "",
    ...decision.reasons.map((reason) => `- ${reason}`),
    "",
    ...table(before, "Before"),
    "",
    ...table(after, "After"),
  ];
  log(report.join("\n"));

  if (decision.result === "inconclusive") return EXIT.third;

  if (rest.includes("--record")) {
    const agentId = value("--agent-id");
    if (!agentId || !/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(agentId)) {
      error("--record needs a valid --agent-id.");
      return EXIT.usage;
    }
    try {
      gh(
        "issue",
        "comment",
        String(pr),
        "--body",
        [
          `<!-- ${EVALUATION_MARKER}`,
          `result: ${decision.result}`,
          `metric: ${proposal.metric}`,
          `counter-metric: ${proposal.counterMetric}`,
          `evaluator: ${agentId}`,
          "-->",
          "",
          ...report,
        ].join("\n"),
      );
    } catch (failure) {
      error(`The evaluation was not recorded: ${String(/** @type {Error} */ (failure).message ?? failure).split("\n")[0]}`);
      return EXIT.unknown;
    }
  }

  return decision.result === "kept" ? EXIT.ok : EXIT.second;
};

// The real `git` runner, kept out of the pure modules so no test can reach
// the actual repository by importing one of them. Mirrors `gh.mjs`'s shape:
// a thin wrapper the pure decision logic receives as a parameter, so a test
// can inject a real `git` pointed at a throwaway fixture repository, or a
// fake one, without either module knowing which it got.

import { execFileSync } from "node:child_process";

// A git hook (this repository's own `pre-push` included) runs with `GIT_DIR`,
// `GIT_WORK_TREE`, and related `GIT_*` variables pointed at the repository
// invoking it. Those leak into every child process by default, so a `git`
// call this module makes against an unrelated directory — a carry-forward
// comparison's own checkout, or a test fixture — would silently operate on
// the invoking repository instead, or fail outright with "this operation
// must be run in a work tree". Stripped here rather than left to each call
// site to remember.
const GIT_ENV_PREFIX = "GIT_";

const sanitisedEnv = () => {
  const env = { ...process.env };
  for (const key of Object.keys(env)) {
    if (key.startsWith(GIT_ENV_PREFIX)) delete env[key];
  }
  return env;
};

/**
 * @param {string[]} args
 * @param {{ input?: string, cwd?: string }} [options]
 */
export const git = (args, { input, cwd } = {}) =>
  execFileSync("git", args, {
    encoding: "utf8",
    stdio: ["pipe", "pipe", "pipe"],
    cwd,
    input,
    env: sanitisedEnv(),
  }).trim();

// Session leases, with every call to `gh` injected.
//
// `claim.mjs` makes one role's in-flight work visible the moment it starts: the
// reservation ref exists before any branch or pull request does, so a second
// session can see that a worker is already on an issue. No other role has that.
// A reviewer, fixer, merger, janitor, or planner becomes visible only when its
// work *lands* — a recorded verdict, a merge, a released claim — and in the
// interval between "the orchestrator recommended this session" and "that session
// had an effect", the board looks identical to nobody being on it. So a second
// orchestrator surveying an unchanged board recommends the same session again,
// in good faith, off correct data.
//
// A lease closes that interval. It is a claim on a *target*, written when a
// session is dispatched, that expires. It is orchestrator-to-orchestrator
// communication: the dispatched session never has to know it exists, never
// reads one, and never writes one.
//
//   rallypoint-sessions/pr-<N>-<role>  reviewer, fixer, merger — per pull request
//   rallypoint-sessions/<role>         janitor, planner — over everything, one at a time
//
// The ref name is deterministic, which is the whole guarantee: `POST /git/refs`
// refuses a second creation of the same ref, so exactly one caller wins a race,
// the same atomicity `claim.mjs` relies on. Refs are shared across operators,
// machines, and worktrees, which is what this needs — orchestrators here run on
// more than one machine and this repository is worked through `git worktree`, so
// the record can be neither process-local nor a file in a checkout.
//
// ## Why the ref points at a lease commit rather than at the head SHA
//
// A lease needs two facts: which revision it was dispatched against, and when.
// The first alone is not enough — a session dispatched but never booted, against
// a branch that never moves again, would hold its target forever, which is what
// the TTL exists to bound.
//
// GitHub records no creation time for a ref, so the time has to live in the
// object the ref points at. Both facts therefore go into a lease commit written
// at dispatch:
//
//   - its **first parent** is the head SHA the session was dispatched against,
//     which is the head-SHA binding `review.mjs` already lives by;
//   - its **committer date** is the dispatch time, which is the TTL's clock;
//   - its **message** carries the role, the agent id, and the target, so a lease
//     is self-describing rather than only meaningful next to the ref name.
//
// Pointing the ref at the head SHA directly would have made the head comparison
// free, but there would then be no dispatch time anywhere at all, and deriving
// one from the head commit's own date is unsound in the dangerous direction: a
// branch that has not moved for a day would read as an expired lease and be
// dispatched a second time, which is precisely the bug this module exists to
// stop. Creating the commit is the cost of a TTL that cannot lie.
//
// Naming is unaffected by any of this: the ref name is still deterministic, so
// the create is still atomic. Only what the winner's ref points at changed.
//
// ## The rule underneath everything here
//
// A lookup that failed resolves to **unknown**, never to "free". The same rule
// `report.mjs` and `release-claim.mjs` already state, and the one whose
// violation is how stale warnings get written: an error, a non-array body, or a response that
// filled its page is not evidence of absence. Presence is established by
// *listing* the ref, never inferred from a create's or a delete's failure.

import { SAFE_AGENT_ID } from "../provenance.mjs";
import { matchingRefs, openPullRequests } from "./release-claim.mjs";

// Exit codes are a public interface in this loop, as they are for `review.mjs`,
// `release-claim.mjs`, and `report.mjs`. Keep them in sync with the table in
// docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  held: 2, // a live lease already covers the target: somebody else has it
  inconclusive: 3, // a lookup could not be established; nothing was written
  writeFailed: 4, // the ref itself could not be created, updated, or deleted
  noTarget: 5, // the pull request a lease was asked for is not open
};

const HOUR_MS = 3_600_000;

// Roles whose work attaches to one pull request, and roles whose pass is over
// everything and so has nothing to attach to. The split decides both the ref
// name and whether `--pr` is required or refused.
export const PULL_REQUEST_ROLES = Object.freeze(["reviewer", "fixer", "merger"]);
export const TARGETLESS_ROLES = Object.freeze(["janitor", "planner"]);
export const ROLES = Object.freeze([
  ...PULL_REQUEST_ROLES,
  ...TARGETLESS_ROLES,
]);

/**
 * The first informative line of a `gh` failure. `execFileSync` puts the useful
 * part on `stderr` and leaves `message` as the command line.
 *
 * @param {unknown} error
 */
const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr ?? detail.message ?? error ?? "").trim();
  return (
    text
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/**
 * @template T
 * @typedef {{ ok: true, items: T[] } | { ok: false, reason: string }} Lookup
 */

/**
 * The ref name (without `refs/heads/`) a lease for this target occupies.
 *
 * @param {{ prefix: string, role: string, pr?: string | null }} input
 */
export const leaseRefName = ({ prefix, role, pr }) =>
  pr == null || pr === "" ? `${prefix}${role}` : `${prefix}pr-${pr}-${role}`;

/**
 * The target a lease ref names, or `null` when the ref does not fit either
 * shape. A ref outside the two shapes is never guessed at: `readLeases` reports
 * it as an unreadable lease, which is not "free".
 *
 * @param {string | null | undefined} refName With or without `refs/heads/`.
 * @param {string} prefix
 * @returns {{ role: string, pr: string | null } | null}
 */
export const parseLeaseRefName = (refName, prefix) => {
  const bare = (refName ?? "").replace(/^refs\/heads\//, "");

  if (!bare.startsWith(prefix)) return null;

  const rest = bare.slice(prefix.length);
  const targeted = rest.match(/^pr-(\d+)-([a-z][a-z-]*)$/);

  if (targeted) {
    return PULL_REQUEST_ROLES.includes(targeted[2])
      ? { role: targeted[2], pr: targeted[1] }
      : null;
  }

  return TARGETLESS_ROLES.includes(rest) ? { role: rest, pr: null } : null;
};

/**
 * The lease commit's message. Written as trailers so the record survives being
 * read by a human in `git log` and by `parseLeaseMessage` below, and so a lease
 * is self-describing rather than only meaningful next to its ref name.
 *
 * @param {{ role: string, pr: string | null, agentId: string, head: string }} input
 */
export const leaseMessage = ({ role, pr, agentId, head }) =>
  [
    `Rallypoint session lease: ${role}${pr == null ? "" : ` on #${pr}`}`,
    "",
    "Written when the session was dispatched, not when it started, so it also",
    "covers the interval before that session boots. Release it with",
    "`lease.mjs --release`, or leave it for the janitor sweep once its TTL",
    "expires. The dispatched session neither reads nor writes this.",
    "",
    `Rallypoint-Lease-Role: ${role}`,
    `Rallypoint-Lease-Agent: ${agentId}`,
    `Rallypoint-Lease-Target: ${pr == null ? "role" : `pr-${pr}`}`,
    `Rallypoint-Lease-Head: ${head}`,
  ].join("\n");

/** @param {string} name */
const trailer = (name) =>
  new RegExp(`^Rallypoint-Lease-${name}:[^\\S\\n]*(\\S+)[^\\S\\n]*$`, "m");

/**
 * @param {string | null | undefined} message
 * @returns {{ role: string, agent: string, pr: string | null, head: string } | null}
 */
export const parseLeaseMessage = (message) => {
  const text = message ?? "";
  const role = text.match(trailer("Role"))?.at(1);
  const agent = text.match(trailer("Agent"))?.at(1);
  const target = text.match(trailer("Target"))?.at(1);
  const head = text.match(trailer("Head"))?.at(1);

  if (!role || !agent || !target || !head) return null;
  if (!ROLES.includes(role)) return null;

  if (target === "role") {
    return TARGETLESS_ROLES.includes(role)
      ? { role, agent, pr: null, head }
      : null;
  }

  const pr = target.match(/^pr-(\d+)$/)?.at(1);

  return pr && PULL_REQUEST_ROLES.includes(role)
    ? { role, agent, pr, head }
    : null;
};

/**
 * @typedef {{
 *   refName: string,
 *   refPath: string,
 *   sha: string | null,
 *   role: string,
 *   pr: string | null,
 *   agent: string,
 *   head: string,
 *   dispatchedAt: string,
 * }} ReadableLease
 */

/**
 * @typedef {{ refName: string, refPath: string, sha: string | null, reason: string }} UnreadableLease
 */

/**
 * @typedef {({ readable: true } & ReadableLease) | ({ readable: false } & UnreadableLease)} ResolvedLease
 */

/**
 * Resolves one lease ref to the commit behind it. A lease this cannot read is
 * returned as `readable: false` rather than dropped: a ref that exists but
 * cannot be interpreted still means something is on that target, and dropping
 * it would silently turn an unreadable lease into a free one.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {{ ref?: string, object?: { sha?: string } }} ref
 * @param {string} prefix
 * @returns {ResolvedLease}
 */
export const resolveLease = (gh, repository, ref, prefix) => {
  const refName = String(ref.ref ?? "").replace(/^refs\/heads\//, "");
  const refPath = `refs/heads/${refName}`;
  const sha = ref.object?.sha ?? null;
  /** @param {string} reason */
  const unreadable = (reason) => ({
    readable: /** @type {false} */ (false),
    refName,
    refPath,
    sha,
    reason,
  });

  const target = parseLeaseRefName(refName, prefix);

  if (!target) {
    return unreadable(
      `\`${refName}\` is under the session namespace but names no role or target this understands`,
    );
  }

  if (!sha) {
    return unreadable(`\`${refName}\` was listed without a SHA`);
  }

  let commit;

  try {
    commit = JSON.parse(gh("api", `repos/${repository}/git/commits/${sha}`));
  } catch (error) {
    return unreadable(
      `the lease commit behind \`${refName}\` could not be read (${describeError(error)})`,
    );
  }

  const record = parseLeaseMessage(commit?.message);

  if (!record) {
    return unreadable(
      `the lease commit behind \`${refName}\` carries no readable Rallypoint lease record`,
    );
  }

  // The ref name and the commit's own record are two independent statements of
  // the same fact. Disagreement means one of them was written by something
  // other than this command, and guessing which to believe is exactly the kind
  // of inference this module refuses to make.
  if (record.role !== target.role || record.pr !== target.pr) {
    return unreadable(
      `\`${refName}\` and its lease commit disagree about the target (ref says ${target.role}/${target.pr ?? "role"}, commit says ${record.role}/${record.pr ?? "role"})`,
    );
  }

  // The dispatched head is recorded twice over — as the trailer and as the
  // commit's first parent — for the same reason `review.mjs` binds a verdict
  // both in its block and through GitHub's own submitted-commit record.
  const parent = commit?.parents?.at(0)?.sha;

  if (parent && parent !== record.head) {
    return unreadable(
      `the lease commit behind \`${refName}\` names head \`${record.head}\` but is parented on \`${parent}\``,
    );
  }

  const dispatchedAt = commit?.committer?.date ?? commit?.author?.date;

  if (typeof dispatchedAt !== "string") {
    return unreadable(
      `the lease commit behind \`${refName}\` reported no timestamp, so its TTL cannot be established`,
    );
  }

  return {
    readable: true,
    refName,
    refPath,
    sha,
    role: record.role,
    pr: record.pr,
    agent: record.agent,
    head: record.head,
    dispatchedAt,
  };
};

/**
 * Every lease under the session namespace.
 *
 * One `matching-refs` call establishes the namespace, then one commit read per
 * ref found resolves its dispatch time and head — the price of a TTL that is
 * recorded rather than inferred (see the header). That per-lease cost is bounded
 * by the number of sessions actually in flight, which is a handful; the listing
 * itself is the only call that scales with anything else.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {string} prefix
 * @returns {Lookup<ResolvedLease>}
 */
export const readLeases = (gh, repository, prefix) => {
  const refs = matchingRefs(gh, repository, prefix);

  if (!refs.ok) return refs;

  return {
    ok: true,
    items: refs.items.map((ref) => resolveLease(gh, repository, ref, prefix)),
  };
};

/**
 * @typedef {(
 *   | { kind: "live", detail: string }
 *   | { kind: "staleByHead", detail: string }
 *   | { kind: "staleByTtl", detail: string }
 *   | { kind: "targetGone", detail: string }
 *   | { kind: "unknown", reason: string }
 * )} LeaseState
 */

/**
 * What a lease means right now. Only `live` is coverage; every other state
 * except `unknown` means the target is free, and `unknown` means neither.
 *
 * TTL is checked before the head, because a lease past its TTL is stale
 * whatever the branch did — that is the point of having a TTL at all: a session
 * dispatched but never booted, against a branch that never moves again, would
 * otherwise hold its target forever.
 *
 * @param {{
 *   lease: ResolvedLease,
 *   head: { known: true, sha: string | null } | { known: false, reason: string },
 *   now: number,
 *   staleClaimHours: number,
 * }} input
 * @returns {LeaseState}
 */
export const leaseState = ({ lease, head, now, staleClaimHours }) => {
  if (!lease.readable) return { kind: "unknown", reason: lease.reason };

  const dispatchedAt = Date.parse(lease.dispatchedAt);

  if (Number.isNaN(dispatchedAt)) {
    return {
      kind: "unknown",
      reason: `the lease commit behind \`${lease.refName}\` has an unreadable timestamp (${lease.dispatchedAt})`,
    };
  }

  const ageHours = (now - dispatchedAt) / HOUR_MS;

  if (ageHours > staleClaimHours) {
    return {
      kind: "staleByTtl",
      detail: `dispatched by \`${lease.agent}\` at ${lease.dispatchedAt} (${ageHours.toFixed(1)}h ago), past the ${staleClaimHours}h TTL`,
    };
  }

  if (lease.pr == null) {
    return {
      kind: "live",
      detail: `held by \`${lease.agent}\` since ${lease.dispatchedAt} (${ageHours.toFixed(1)}h ago)`,
    };
  }

  if (!head.known) {
    return {
      kind: "unknown",
      reason: `the current head of #${lease.pr} could not be established (${head.reason}), so whether \`${lease.refName}\` still matches it is unknown`,
    };
  }

  if (head.sha === null) {
    return {
      kind: "targetGone",
      detail: `#${lease.pr} is not open, so the target \`${lease.refName}\` covers no longer exists`,
    };
  }

  if (head.sha !== lease.head) {
    return {
      kind: "staleByHead",
      detail: `dispatched against \`${lease.head.slice(0, 7)}\` but #${lease.pr} is now at \`${head.sha.slice(0, 7)}\`; the branch moved`,
    };
  }

  return {
    kind: "live",
    detail: `held by \`${lease.agent}\` at \`${lease.head.slice(0, 7)}\` since ${lease.dispatchedAt} (${ageHours.toFixed(1)}h ago)`,
  };
};

/**
 * @typedef {ResolvedLease & { state: LeaseState }} SummarizedLease
 */

/**
 * Every lease paired with what it currently means, resolved against the open
 * pull request listing the caller already has. Nothing here makes a network
 * call: `report.mjs` reuses its own open-pull-request read, and a listing it
 * could not establish turns every pull-request lease into `unknown` rather than
 * into a free target.
 *
 * @param {{
 *   leases: Lookup<ResolvedLease>,
 *   prs: Lookup<{ number: number, headRefOid: string }>,
 *   now: number,
 *   staleClaimHours: number,
 * }} input
 * @returns {{ known: true, items: SummarizedLease[] } | { known: false, reason: string }}
 */
export const summarizeLeases = ({ leases, prs, now, staleClaimHours }) => {
  if (!leases.ok) return { known: false, reason: leases.reason };

  const headByPr = new Map(
    prs.ok ? prs.items.map((pull) => [String(pull.number), pull.headRefOid]) : [],
  );

  return {
    known: true,
    items: leases.items.map((item) => ({
      ...item,
      state: leaseState({
        lease: item,
        head: prs.ok
          ? {
              known: true,
              sha: item.readable && item.pr !== null
                ? (headByPr.get(item.pr) ?? null)
                : null,
            }
          : { known: false, reason: prs.reason },
        now,
        staleClaimHours,
      }),
    })),
  };
};

/**
 * Whether a live lease covers one pull request, for every role that can hold
 * one. This is what the orchestrator's added recommendation condition reads:
 * `covered` means skip, `free` means recommend, and `unknown` means say so in
 * the round's reasoning rather than recommending through it.
 *
 * @param {{
 *   summary: { known: true, items: SummarizedLease[] } | { known: false, reason: string },
 *   pr: string,
 *   role: string,
 * }} input
 * @returns {{ kind: "covered", detail: string } | { kind: "free" } | { kind: "unknown", reason: string }}
 */
export const coverage = ({ summary, pr, role }) => {
  if (!summary.known) return { kind: "unknown", reason: summary.reason };

  for (const lease of summary.items) {
    const matches = lease.readable
      ? lease.role === role && lease.pr === pr
      : lease.refName.endsWith(`pr-${pr}-${role}`) ||
        lease.refName.endsWith(`/${role}`);

    if (!matches) continue;
    if (lease.state.kind === "unknown") {
      return { kind: "unknown", reason: lease.state.reason };
    }
    if (lease.state.kind === "live") {
      return { kind: "covered", detail: lease.state.detail };
    }
  }

  return { kind: "free" };
};

/**
 * The current head of a pull request, distinguishing "not open" from "could not
 * be asked".
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} pr
 * @returns {{ ok: true, state: string, head: string } | { ok: false, open: boolean, reason: string }}
 */
export const pullRequestHead = (gh, pr) => {
  let view;

  try {
    view = JSON.parse(gh("pr", "view", pr, "--json", "number,state,headRefOid"));
  } catch (error) {
    return {
      ok: false,
      open: true,
      reason: `#${pr} could not be read (${describeError(error)})`,
    };
  }

  if (view?.state !== "OPEN") {
    return {
      ok: false,
      open: false,
      reason: `#${pr} is ${String(view?.state ?? "unreadable").toLowerCase()}, so there is nothing to lease`,
    };
  }

  if (typeof view.headRefOid !== "string" || view.headRefOid === "") {
    return {
      ok: false,
      open: true,
      reason: `#${pr} reported no head SHA`,
    };
  }

  return { ok: true, state: view.state, head: view.headRefOid };
};

/**
 * Writes the lease commit and points the ref at it.
 *
 * `create` is the atomic path: `POST /git/refs` refuses a second creation of
 * the same ref, so exactly one caller wins. `takeover` force-updates a ref whose
 * lease this caller has already established is stale, and is deliberately
 * last-writer-wins — two orchestrators taking over the same stale lease at the
 * same instant is the bounded, self-correcting worst case this design accepts,
 * and refusing it would leave a stale lease blocking its target until a janitor
 * pass came round.
 *
 * @param {{
 *   gh: (...args: string[]) => string,
 *   repository: string,
 *   refName: string,
 *   role: string,
 *   pr: string | null,
 *   agentId: string,
 *   head: string,
 *   mode: "create" | "takeover",
 * }} input
 * @returns {{ ok: true, sha: string } | { ok: false, reason: string }}
 */
export const writeLease = ({
  gh,
  repository,
  refName,
  role,
  pr,
  agentId,
  head,
  mode,
}) => {
  let tree;

  try {
    tree = JSON.parse(gh("api", `repos/${repository}/git/commits/${head}`))?.tree
      ?.sha;
  } catch (error) {
    return {
      ok: false,
      reason: `the dispatched head \`${head}\` could not be read (${describeError(error)})`,
    };
  }

  if (typeof tree !== "string" || tree === "") {
    return {
      ok: false,
      reason: `the dispatched head \`${head}\` reported no tree`,
    };
  }

  let sha;

  try {
    sha = JSON.parse(
      gh(
        "api",
        "--method",
        "POST",
        `repos/${repository}/git/commits`,
        "-f",
        `message=${leaseMessage({ role, pr, agentId, head })}`,
        "-f",
        `tree=${tree}`,
        "-f",
        `parents[]=${head}`,
      ),
    )?.sha;
  } catch (error) {
    return {
      ok: false,
      reason: `the lease commit could not be written (${describeError(error)})`,
    };
  }

  if (typeof sha !== "string" || sha === "") {
    return { ok: false, reason: "the lease commit was written without a SHA" };
  }

  try {
    if (mode === "create") {
      gh(
        "api",
        "--method",
        "POST",
        `repos/${repository}/git/refs`,
        "-f",
        `ref=refs/heads/${refName}`,
        "-f",
        `sha=${sha}`,
      );
    } else {
      gh(
        "api",
        "--method",
        "PATCH",
        `repos/${repository}/git/refs/heads/${refName}`,
        "-f",
        `sha=${sha}`,
        "-F",
        "force=true",
      );
    }
  } catch (error) {
    return {
      ok: false,
      reason: `\`refs/heads/${refName}\` could not be ${mode === "create" ? "created" : "updated"} (${describeError(error)})`,
    };
  }

  return { ok: true, sha };
};

const USAGE = [
  "Usage:",
  "  lease.mjs --role <reviewer|fixer|merger> --pr <N> --agent-id <id> [--dry-run]",
  "  lease.mjs --role <janitor|planner> --agent-id <id> [--dry-run]",
  "  lease.mjs --release --role <role> [--pr <N>] --agent-id <id> [--dry-run]",
  "  lease.mjs --sweep [--dry-run]",
].join("\n");

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  /** @param {string} flag */
  const values = (flag) =>
    argv.flatMap((value, index) =>
      value === flag && argv[index + 1] ? [argv[index + 1]] : [],
    );

  return {
    role: values("--role").at(0),
    pr: values("--pr").at(0),
    agentId: values("--agent-id").at(0),
    release: argv.includes("--release"),
    sweep: argv.includes("--sweep"),
    dryRun: argv.includes("--dry-run"),
  };
};

/**
 * @param {{
 *   role?: string,
 *   pr?: string,
 *   agentId?: string,
 *   release: boolean,
 *   sweep: boolean,
 * }} args
 * @returns {string | null} The usage problem, or `null` when the arguments are usable.
 */
export const usageProblem = (args) => {
  if (args.sweep) {
    return args.role || args.pr || args.agentId || args.release
      ? "--sweep takes no other argument than --dry-run."
      : null;
  }

  if (!args.role || !ROLES.includes(args.role)) {
    return `--role must be one of ${ROLES.join(", ")}.`;
  }

  if (!args.agentId) return "Missing required --agent-id <unique-session-id>.";

  // The id lands in a lease commit the loop reads back, so hold it to the same
  // shape `claim.mjs` and `review.mjs` require.
  if (!SAFE_AGENT_ID.test(args.agentId)) {
    return `Agent id "${args.agentId}" must match ${SAFE_AGENT_ID}: letters, digits, dot, underscore, and hyphen only.`;
  }

  if (PULL_REQUEST_ROLES.includes(args.role)) {
    if (!args.pr || !/^\d+$/.test(args.pr)) {
      return `--pr <N> is required for the ${args.role} role.`;
    }
  } else if (args.pr) {
    return `--pr is not accepted for the ${args.role} role: its pass is over everything, so its lease is role-level.`;
  }

  return null;
};

/**
 * @param {{
 *   argv: string[],
 *   config: {
 *     sessionRefPrefix: string,
 *     staleClaimHours: number,
 *     integrationBranch?: string,
 *   },
 *   gh: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 *   now?: () => number,
 * }} input
 * @returns {number} Process exit code.
 */
export const lease = ({
  argv,
  config,
  gh,
  stdout = console.log,
  stderr = console.error,
  now = () => Date.now(),
}) => {
  const args = parseArgs(argv);
  const problem = usageProblem(args);

  if (problem) {
    stderr(problem);
    stderr(USAGE);
    return EXIT.usage;
  }

  const repository = JSON.parse(gh("repo", "view", "--json", "nameWithOwner"))
    .nameWithOwner;

  if (args.sweep) {
    return sweep({
      repository,
      config,
      gh,
      dryRun: args.dryRun,
      stdout,
      stderr,
      now: now(),
    });
  }

  const role = /** @type {string} */ (args.role);
  const agentId = /** @type {string} */ (args.agentId);
  const pr = args.pr ?? null;
  const refName = leaseRefName({ prefix: config.sessionRefPrefix, role, pr });
  const refPath = `refs/heads/${refName}`;

  // Presence is established by listing, always, before anything is written or
  // deleted — never inferred from a create's or a delete's own failure. A
  // branch-scoped credential answers 403 whether or not the ref is there, and
  // reading one as proof either way is how stale warnings get written.
  const leases = readLeases(gh, repository, config.sessionRefPrefix);

  if (!leases.ok) {
    stderr(
      `The lease namespace could not be listed (${leases.reason}), so whether \`${refPath}\` is held could not be established. Nothing was written.`,
    );
    return EXIT.inconclusive;
  }

  const existing = leases.items.find((item) => item.refName === refName) ?? null;

  if (args.release) {
    return releaseLease({
      repository,
      refPath,
      existing,
      agentId,
      gh,
      dryRun: args.dryRun,
      stdout,
      stderr,
    });
  }

  const head = pr === null ? null : pullRequestHead(gh, pr);

  if (head && !head.ok) {
    stderr(`Refusing to lease ${refPath}: ${head.reason}.`);
    return head.open ? EXIT.inconclusive : EXIT.noTarget;
  }

  if (existing) {
    const state = leaseState({
      lease: existing,
      head: head
        ? { known: true, sha: head.head }
        : { known: true, sha: null },
      now: now(),
      staleClaimHours: config.staleClaimHours,
    });

    if (state.kind === "unknown") {
      stderr(
        `Refusing to lease ${refPath}: a lease ref exists there but could not be read (${state.reason}). A lookup that could not be established is not a free target, so nothing was written.`,
      );
      return EXIT.inconclusive;
    }

    if (state.kind === "live") {
      stderr(
        `\`${refPath}\` is already held: ${state.detail}. Somebody else is on this target; there is nothing to dispatch.`,
      );
      return EXIT.held;
    }

    stdout(
      `\`${refPath}\` exists but is stale (${state.detail}); taking it over.`,
    );
  }

  const dispatchedHead = /** @type {string} */ (
    head ? head.head : integrationHead(gh, repository, config)
  );

  if (!dispatchedHead) {
    stderr(
      `Refusing to lease ${refPath}: the head to bind this lease to could not be established. Nothing was written.`,
    );
    return EXIT.inconclusive;
  }

  if (args.dryRun) {
    stdout(
      `Would ${existing ? "take over" : "create"} ${refPath}, bound to \`${dispatchedHead.slice(0, 7)}\` for \`${agentId}\`.`,
    );
    stdout("\n(dry run: no lease commit and no ref were written)");
    return EXIT.ok;
  }

  const written = writeLease({
    gh,
    repository,
    refName,
    role,
    pr,
    agentId,
    head: dispatchedHead,
    mode: existing ? "takeover" : "create",
  });

  if (!written.ok) {
    // A failed create is the one case worth re-establishing rather than
    // reporting: the likeliest cause is another orchestrator winning the same
    // race between the listing above and this call. Which of the two happened
    // is established by listing again, never by reading the failure itself.
    if (!existing) {
      const after = readLeases(gh, repository, config.sessionRefPrefix);
      const now2 = after.ok
        ? (after.items.find((item) => item.refName === refName) ?? null)
        : null;

      if (now2) {
        stderr(
          `\`${refPath}\` is already held: another session created it while this one was writing. There is nothing to dispatch.`,
        );
        return EXIT.held;
      }
    }

    stderr(`Refusing to lease ${refPath}: ${written.reason}.`);
    return EXIT.writeFailed;
  }

  stdout(`LEASE_REF=${refPath}`);
  stdout(`LEASE_SHA=${written.sha}`);
  stdout(`LEASE_HEAD=${dispatchedHead}`);
  stdout(`LEASE_AGENT=${agentId}`);
  return EXIT.ok;
};

/**
 * The integration branch head, which a role-level lease binds to. There is no
 * per-target revision for a janitor or planner pass — it is over everything —
 * so the TTL is what bounds it, and the head only records what the board looked
 * like when the session was dispatched.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {{ integrationBranch?: string }} config
 * @returns {string | null}
 */
export const integrationHead = (gh, repository, config) => {
  try {
    const branch =
      config.integrationBranch ||
      JSON.parse(gh("repo", "view", "--json", "defaultBranchRef"))
        .defaultBranchRef.name;
    const sha = JSON.parse(
      gh("api", `repos/${repository}/git/ref/heads/${branch}`),
    )?.object?.sha;

    return typeof sha === "string" && sha !== "" ? sha : null;
  } catch {
    return null;
  }
};

/**
 * @param {{
 *   repository: string,
 *   refPath: string,
 *   existing: ResolvedLease | null,
 *   agentId: string,
 *   gh: (...args: string[]) => string,
 *   dryRun: boolean,
 *   stdout: (line: string) => void,
 *   stderr: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const releaseLease = ({
  repository,
  refPath,
  existing,
  agentId,
  gh,
  dryRun,
  stdout,
  stderr,
}) => {
  if (!existing) {
    stdout(`No lease at ${refPath}; already clear.`);
    return EXIT.ok;
  }

  // Releasing somebody else's lease re-opens their target to a second dispatch
  // while their session is still running, which is the collision the lease
  // exists to prevent. Ids are self-declared, so this is bookkeeping
  // rather than authentication — but the honest mistake is the one worth
  // catching, and a genuinely abandoned lease is the janitor sweep's job.
  if (existing.readable && existing.agent !== agentId) {
    stderr(
      `Refusing to release ${refPath}: it is held by \`${existing.agent}\`, not \`${agentId}\`. An abandoned lease is released by its TTL through \`lease.mjs --sweep\`, not by another session deleting it.`,
    );
    return EXIT.held;
  }

  if (dryRun) {
    stdout(`Would delete ${refPath}.`);
    stdout("\n(dry run: nothing was deleted)");
    return EXIT.ok;
  }

  try {
    gh("api", "--method", "DELETE", `repos/${repository}/git/${refPath}`);
  } catch (error) {
    stderr(`\`${refPath}\` could not be deleted (${describeError(error)}).`);
    return EXIT.writeFailed;
  }

  stdout(`RELEASED_LEASE=${refPath}`);
  return EXIT.ok;
};

/**
 * The janitor's pass over the lease namespace: a lease whose target no longer
 * exists, or whose TTL has expired, is removed. Nothing else is touched — a
 * lease that is merely stale by head is left alone, because the next acquire
 * takes it over in place and deleting it first would only widen the window this
 * whole mechanism exists to close.
 *
 * A lease this pass could not read is reported and never deleted. It is the same
 * rule as everywhere else here: unreadable is not absent, and it is certainly
 * not abandoned.
 *
 * @param {{
 *   repository: string,
 *   config: { sessionRefPrefix: string, staleClaimHours: number },
 *   gh: (...args: string[]) => string,
 *   dryRun: boolean,
 *   stdout: (line: string) => void,
 *   stderr: (line: string) => void,
 *   now: number,
 * }} input
 * @returns {number} Process exit code.
 */
export const sweep = ({
  repository,
  config,
  gh,
  dryRun,
  stdout,
  stderr,
  now,
}) => {
  const summary = summarizeLeases({
    leases: readLeases(gh, repository, config.sessionRefPrefix),
    prs: openPullRequests(gh),
    now,
    staleClaimHours: config.staleClaimHours,
  });

  if (!summary.known) {
    stderr(
      `The lease namespace could not be listed (${summary.reason}). Nothing was swept.`,
    );
    return EXIT.inconclusive;
  }

  if (summary.items.length === 0) {
    stdout("No session leases exist; nothing to sweep.");
    return EXIT.ok;
  }

  let unreadable = 0;
  let failed = 0;
  let swept = 0;

  for (const item of summary.items) {
    if (item.state.kind === "unknown") {
      unreadable += 1;
      stderr(
        `Leaving ${item.refPath} alone: ${item.state.reason}. An unreadable lease is not an abandoned one.`,
      );
      continue;
    }

    if (item.state.kind === "live" || item.state.kind === "staleByHead") {
      stdout(
        `${item.refPath}: ${item.state.kind === "live" ? "live" : "stale by head, taken over in place by the next acquire"} — ${item.state.detail}.`,
      );
      continue;
    }

    if (dryRun) {
      stdout(`Would delete ${item.refPath} (${item.state.detail}).`);
      swept += 1;
      continue;
    }

    try {
      gh("api", "--method", "DELETE", `repos/${repository}/git/${item.refPath}`);
    } catch (error) {
      failed += 1;
      stderr(
        `\`${item.refPath}\` could not be deleted (${describeError(error)}).`,
      );
      continue;
    }

    swept += 1;
    stdout(`SWEPT_LEASE=${item.refPath} (${item.state.detail})`);
  }

  stdout(
    `Swept ${swept} lease(s)${dryRun ? " (dry run: nothing was deleted)" : ""}; ${unreadable} unreadable, ${failed} delete(s) failed.`,
  );

  if (failed > 0) return EXIT.writeFailed;
  if (unreadable > 0) return EXIT.inconclusive;
  return EXIT.ok;
};

export default lease;

// Local, unpushed evidence that a claimed issue still has a session behind it.
//
// ## Why this exists
//
// Every other liveness signal in this protocol is read from GitHub: the claim
// comment's age, an open pull request, the last push on `agent/<issue>-*`. All
// three are blind to the state that dominates a session's lifetime — commits
// sitting in a local worktree that has not pushed yet. Where pushing is
// expensive, because `pre-push` runs a full gate, "claimed a while ago, nothing
// on the remote" is the *normal* signature of a healthy worker mid-session
// rather than of an abandoned claim.
//
// This was measured before it was fixed: a janitor pass found that all three
// claims it had nominated for release were live work with unpushed commits
// minutes old, and every one of them went on to push and open a pull request.
//
// Unpushed commits are the one artefact in a repository with no second copy, so
// releasing a claim on top of them is the most expensive mistake the janitor
// can make.
//
// ## What this covers, and what it does not
//
// **This binds on one machine only.** `git worktree list` enumerates the
// worktrees of *this* checkout's repository, so the guard fires exactly when
// the janitor and the worker share a box — the common case when an orchestrator
// dispatches every role onto one host. A janitor on a different host reads no
// worktrees at all, gets a successful empty answer, and is left with the same
// GitHub-only evidence it had before; nothing here makes that observer safer.
// `beacon-push.mjs` is the half of the answer that does reach another host.
// `docs/AGENT_LOOP.md` and `.rallypoint/roles/janitor.md` state the same limit
// where a janitor will read it.
//
// It is therefore a *guard*, not a fix for the signal. The general answer is a
// worker pushing early, which makes the evidence visible to every observer.
//
// ## What counts as evidence
//
// Two things, and both are about work that exists nowhere else:
//
// - **Commits the remote does not have.** Measured against the branch's own
//   remote-tracking ref when it has one, and against the integration branch
//   when it does not — a branch that was never pushed has no upstream, which is
//   precisely the state under investigation.
// - **Uncommitted changes.** A dirty tree is unrecoverable in a different way:
//   nothing in git holds it at all.
//
// Neither is aged. A worktree is not a timestamp, and treating an old commit as
// dead work would reintroduce the same guess this module exists to replace —
// the file is either there or it is not. The cost is that an abandoned worktree
// left behind on the box keeps refusing releases for its issue forever; that is
// deliberate, and the refusal names the path so an operator can delete it, or
// the holder can release its own claim with `--agent-id` (which skips every
// check here, per `isSelfRelease`).
//
// Following `lib/release-claim.mjs`'s rule exactly: a lookup that could not be
// established is never folded into "no local work". `git` failing is `ok:
// false`, which resolves to `unknown` and refuses the release.

/**
 * @template T
 * @typedef {{ ok: true, items: T[] } | { ok: false, reason: string }} Lookup
 */

/**
 * @typedef {{
 *   path: string,
 *   branch: string,
 *   unpushedCommits: number,
 *   comparedAgainst: string,
 *   uncommittedChanges: boolean,
 * }} LocalWork
 */

/**
 * `git worktree list --porcelain` emits one blank-line-separated block per
 * worktree, each opening with `worktree <path>` and carrying either
 * `branch refs/heads/<name>` or a bare `detached`. A detached worktree is
 * skipped: it names no issue, so nothing here can attribute its contents.
 *
 * @param {string} output
 * @returns {{ path: string, branch: string | null }[]}
 */
export const parseWorktrees = (output) => {
  /** @type {{ path: string, branch: string | null }[]} */
  const worktrees = [];
  /** @type {{ path: string, branch: string | null } | null} */
  let current = null;

  for (const raw of output.split("\n")) {
    const line = raw.trim();

    if (line.startsWith("worktree ")) {
      if (current) worktrees.push(current);
      current = { path: line.slice("worktree ".length), branch: null };
      continue;
    }

    if (current && line.startsWith("branch ")) {
      current.branch = line.slice("branch ".length).replace(/^refs\/heads\//, "");
    }
  }

  if (current) worktrees.push(current);
  return worktrees;
};

/**
 * The issue number a worktree's branch names, or `null`. Deliberately not
 * `provenance.branchIssue`: this reads a *local* branch name, which is
 * `claim.mjs`'s deterministic `agent/<issue>-<slug>` shape, and importing the
 * pull-request-facing helper here would tie a local check to a remote naming
 * rule that can move independently.
 *
 * @param {string | null} branch
 * @param {string} branchPrefix
 */
export const worktreeIssue = (branch, branchPrefix) => {
  if (!branch) return null;
  const escaped = branchPrefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return branch.match(new RegExp(`^${escaped}(\\d+)-`))?.[1] ?? null;
};

/**
 * @param {(args: string[], options?: { cwd?: string }) => string} git
 * @param {string} cwd
 * @param {string} ref
 */
const refExists = (git, cwd, ref) => {
  try {
    git(["rev-parse", "--verify", "--quiet", `${ref}^{commit}`], { cwd });
    return true;
  } catch {
    return false;
  }
};

/**
 * @param {unknown} error
 */
const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  return (
    String(detail.stderr ?? detail.message ?? error ?? "")
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/**
 * Every local worktree holding work for `issue` that the remote does not have.
 *
 * An empty `items` from a successful read is proof this machine holds no such
 * work — which on a machine with no worktrees at all is the honest answer, and
 * is exactly why this guard is machine-local. Anything that could not be read
 * is `ok: false`.
 *
 * @param {{
 *   git: (args: string[], options?: { cwd?: string }) => string,
 *   issue: string,
 *   branchPrefix: string,
 *   integrationBranch: string,
 *   remote?: string,
 *   cwd?: string,
 * }} input
 * @returns {Lookup<LocalWork>}
 */
export const localIssueWork = ({
  git,
  issue,
  branchPrefix,
  integrationBranch,
  remote = "origin",
  cwd,
}) => {
  /** @type {{ path: string, branch: string | null }[]} */
  let worktrees;

  try {
    worktrees = parseWorktrees(git(["worktree", "list", "--porcelain"], { cwd }));
  } catch (error) {
    return {
      ok: false,
      reason: `local worktrees could not be listed (${describeError(error)}), so whether this machine holds unpushed work for #${issue} was not established`,
    };
  }

  /** @type {LocalWork[]} */
  const items = [];

  for (const worktree of worktrees) {
    if (worktreeIssue(worktree.branch, branchPrefix) !== issue) continue;

    const branch = /** @type {string} */ (worktree.branch);

    try {
      const tracking = `${remote}/${branch}`;
      // A branch that was never pushed has no remote-tracking ref, which is the
      // state under investigation rather than an error. The integration branch
      // is the right fallback: commits it does not contain are commits that
      // exist only here.
      const comparedAgainst = refExists(git, worktree.path, tracking)
        ? tracking
        : `${remote}/${integrationBranch}`;

      if (!refExists(git, worktree.path, comparedAgainst)) {
        return {
          ok: false,
          reason: `neither \`${tracking}\` nor \`${remote}/${integrationBranch}\` could be resolved in \`${worktree.path}\`, so the unpushed commits on \`${branch}\` were not established`,
        };
      }

      const counted = git(
        ["rev-list", "--count", `${comparedAgainst}..HEAD`],
        { cwd: worktree.path },
      );
      const unpushedCommits = Number.parseInt(counted.trim(), 10);

      if (!Number.isFinite(unpushedCommits)) {
        return {
          ok: false,
          reason: `the commit count for \`${branch}\` in \`${worktree.path}\` was unreadable (${counted})`,
        };
      }

      const uncommittedChanges =
        git(["status", "--porcelain"], { cwd: worktree.path }) !== "";

      if (unpushedCommits === 0 && !uncommittedChanges) continue;

      items.push({
        path: worktree.path,
        branch,
        unpushedCommits,
        comparedAgainst,
        uncommittedChanges,
      });
    } catch (error) {
      return {
        ok: false,
        reason: `\`${worktree.path}\` could not be inspected (${describeError(error)}), so whether it holds unpushed work for #${issue} was not established`,
      };
    }
  }

  return { ok: true, items };
};

/**
 * One sentence naming what was found and where, for a refusal a human has to
 * audit. The path is the point: it is what an operator needs to either wait for
 * the session, or delete the worktree and try again.
 *
 * @param {LocalWork[]} items
 * @param {string} issue
 */
export const describeLocalWork = (items, issue) =>
  items
    .map((item) => {
      const parts = [];
      if (item.unpushedCommits > 0) {
        parts.push(
          `${item.unpushedCommits} commit(s) not on \`${item.comparedAgainst}\``,
        );
      }
      if (item.uncommittedChanges) parts.push("uncommitted changes");
      return `\`${item.path}\` is on \`${item.branch}\` with ${parts.join(" and ")}`;
    })
    .join("; ")
    .concat(
      `. That work exists only on this machine, so releasing #${issue} would orphan it`,
    );

export default localIssueWork;

// Whether a pull request the worker is about to open would be reviewable.
//
// `review.mjs record` resolves a pull request to its authoring session through
// `recordableIssue({ linkedIssues, branchIssue })`, and exits 2 when neither the
// branch name nor a closing keyword resolves one — see provenance.mjs. That
// discovery is expensive after the fact: a branch name cannot change once a
// pull request is open without closing and reopening it, and until this
// command existed the defect surfaced only when a reviewer spent a pass on the
// diff and then found the verdict could not be written down.
//
// This module runs the same resolution `record` would, against the branch and
// body the worker is about to use, before either is fixed in place. It imports
// `provenance.mjs` rather than reimplementing the rules: a second parser would
// drift from the one a reviewer actually runs, and would then issue confident
// passes for pull requests `record` refuses.

import {
  authorshipIssues,
  branchIssue as branchIssueOf,
  claimant,
  isPromotionBranch,
  linkedIssues as linkedIssuesOf,
} from "../provenance.mjs";
import {
  closingReferenceDivergence,
  closureDrift,
  closureDriftMessage,
} from "./closing-references.mjs";

export const EXIT = {
  ok: 0,
  usage: 1,
  // Matches `review.mjs record`'s EXIT.unidentifiable: it also exits 2 for both
  // an unresolved authoring issue and a resolved issue with no claim comment.
  refused: 2,
  // Distinct from `refused`: the pull request would be reviewable, but it
  // would land against the wrong branch entirely. Nothing about the body or
  // branch issue resolution is at fault, so conflating this with `refused`
  // would send the reader looking in the wrong place.
  wrongBase: 3,
  // Distinct from `refused` for the same reason `wrongBase` is: on a detached
  // HEAD there is no branch name to judge at all, so reporting the
  // `unidentifiable` message would send the reader to fix a branch name that
  // is very likely already correct.
  detached: 4,
  // GitHub's closing-keyword parser would close an issue the pull request does
  // not declare. Distinct from every code above because nothing about the
  // branch, base, or authorship resolution is wrong — the pull request would be
  // perfectly reviewable, and would silently close an issue nobody asked it to.
  // Its own exit code so a caller can tell "unreviewable" from "reviewable and
  // destructive", which want different remedies from different people.
  closureDrift: 5,
};

// What `git rev-parse --abbrev-ref HEAD` prints when HEAD is detached. It is
// indistinguishable from a branch literally named `HEAD`, which git refuses to
// create, so treating it as the detached signal is unambiguous.
const DETACHED = "HEAD";

/**
 * The branch name a ref belongs to, or `undefined` for a ref that names none.
 * Remote-tracking refs are normalised to the branch they track, so a detached
 * checkout of a branch that exists only on the remote — the shape a session
 * that pushed with an explicit refspec is left in — resolves the same as a
 * local one.
 *
 * @param {string} ref
 */
const branchNameOf = (ref) => {
  if (ref.startsWith("refs/heads/")) return ref.slice("refs/heads/".length);
  if (!ref.startsWith("refs/remotes/")) return undefined;
  const withoutRemote = ref.slice("refs/remotes/".length).split("/");
  withoutRemote.shift();
  const branch = withoutRemote.join("/");
  // `refs/remotes/<remote>/HEAD` is the remote's default-branch symlink, not a
  // branch anybody works on.
  return branch && branch !== DETACHED ? branch : undefined;
};

/**
 * The branch a detached HEAD belongs to, inferred from the refs pointing at
 * the current commit.
 *
 * Anything short of exactly one candidate refuses rather than guessing, and a
 * lookup that threw refuses too — an error is not evidence that no branch
 * points here, the same rule `release-claim.mjs` and `report.mjs` state.
 *
 * @param {(...args: string[]) => string} git
 * @returns {{ ok: true, branch: string }
 *   | { ok: false, reason: "none" | "ambiguous" | "unreadable", candidates: string[] }}
 */
export const detachedBranch = (git) => {
  /** @type {string} */
  let output;

  try {
    output = git(
      "for-each-ref",
      "--format=%(refname)",
      "--points-at",
      "HEAD",
      "refs/heads",
      "refs/remotes",
    );
  } catch {
    return { ok: false, reason: "unreadable", candidates: [] };
  }

  const candidates = [
    ...new Set(
      output
        .split("\n")
        .map((line) => line.trim())
        .filter(Boolean)
        .map(branchNameOf)
        .filter(
          /** @returns {branch is string} */ (branch) => branch !== undefined,
        ),
    ),
  ].sort();

  if (candidates.length === 1) return { ok: true, branch: candidates[0] };
  return {
    ok: false,
    reason: candidates.length ? "ambiguous" : "none",
    candidates,
  };
};

// Record and field separators for `git log --format`. ASCII 0x1e/0x1f cannot
// appear in a commit message written by any tool in this repository, and a
// newline-delimited format cannot work here because the messages themselves are
// multi-line — the narrated closure that caused this check was in a commit
// body, not a subject.
const RECORD = "\u001e";
const FIELD = "\u001f";

/**
 * The commits this pull request would contain: everything on the branch that
 * the base does not already have. That is exactly the set GitHub scans for
 * closing keywords, so a commit merged in *from* the base — somebody else's
 * message, which this session cannot reword and is not responsible for — is
 * excluded by construction rather than by a filter.
 *
 * `origin/<base>` is preferred over a local `<base>`: a session's worktree is
 * cut fresh and its local copy of the base branch, if it has one at all, is
 * whatever the clone happened to bring. A range that cannot be resolved returns
 * `null` and the caller reports the check as not run — an unreadable lookup is
 * not evidence that no commit closes anything, the rule `release-claim.mjs` and
 * `report.mjs` already state for their own lookups.
 *
 * @param {(...args: string[]) => string} git
 * @param {string} base
 * @returns {{ commits: { sha: string, message: string }[], range: string } | null}
 */
export const branchCommits = (git, base) => {
  for (const ref of [`origin/${base}`, base]) {
    /** @type {string} */
    let output;

    try {
      output = git(
        "log",
        `--format=%H${FIELD}%B${RECORD}`,
        `${ref}..HEAD`,
      );
    } catch {
      continue;
    }

    return {
      range: `${ref}..HEAD`,
      commits: output
        .split(RECORD)
        .map((record) => record.trim())
        .filter(Boolean)
        .map((record) => {
          const separator = record.indexOf(FIELD);
          return {
            sha: record.slice(0, separator),
            message: record.slice(separator + 1).trim(),
          };
        }),
    };
  }

  return null;
};

/**
 * What GitHub says an already-open pull request from this branch closes.
 *
 * `null` for the ordinary case — no pull request exists yet, which is when this
 * command is meant to be run — and `null` again for any failure, because the
 * caller only ever prints this and a failed lookup must not turn into a verdict.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} branch
 * @returns {{ number: number, issues: string[] } | null}
 */
export const githubClosingReferences = (gh, branch) => {
  try {
    const pull = JSON.parse(
      gh("pr", "view", branch, "--json", "number,closingIssuesReferences"),
    );

    if (typeof pull?.number !== "number") return null;

    /** @type {{ number?: unknown }[]} */
    const references = Array.isArray(pull.closingIssuesReferences)
      ? pull.closingIssuesReferences
      : [];

    return {
      number: pull.number,
      issues: references.flatMap((reference) =>
        typeof reference?.number === "number" ? [String(reference.number)] : [],
      ),
    };
  } catch {
    return null;
  }
};

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  const bodyIndex = argv.indexOf("--body");
  const baseIndex = argv.indexOf("--base");
  return {
    body: bodyIndex === -1 ? undefined : argv[bodyIndex + 1],
    base: baseIndex === -1 ? undefined : argv[baseIndex + 1],
  };
};

/**
 * @param {{
 *   argv: string[],
 *   config: { branchPrefix: string, integrationBranch: string, promotionBranch?: string },
 *   git: (...args: string[]) => string,
 *   gh: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const preflight = ({
  argv,
  config,
  git,
  gh,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { body, base } = parseArgs(argv);

  if (body === undefined || base === undefined) {
    stderr(
      'Usage: preflight.mjs --body "<prepared pull request body>" --base <intended base branch>',
    );
    return EXIT.usage;
  }

  // `rev-parse --abbrev-ref HEAD` prints the literal `HEAD` on a detached
  // checkout, and every rule below reads a branch *name*: `branchIssue` finds
  // no issue in it and `isPromotionBranch` is false for it, so an unguarded
  // run reports `unidentifiable` — a verdict about a branch that does not
  // exist, issued precisely in the situation that caused the detachment.
  // Detachment is routine here: every session gets its own worktree, and a
  // worktree that cannot check out the branch it needs has no other way
  // forward.
  const checkedOut = git("rev-parse", "--abbrev-ref", "HEAD");
  let branch = checkedOut;

  if (checkedOut === DETACHED) {
    const resolved = detachedBranch(git);

    if (!resolved.ok) {
      stderr(
        "HEAD is detached, so there is no checked-out branch to judge. " +
          {
            none: "No local or remote-tracking branch points at the current commit, so the branch this work belongs to cannot be inferred. Push it (`git push origin HEAD:refs/heads/<branch>`) or check it out, then run this again.",
            ambiguous: `Several branches point at the current commit (${resolved.candidates.map((candidate) => `\`${candidate}\``).join(", ")}), so which one this pull request would be opened from cannot be inferred. Check the intended branch out, then run this again.`,
            unreadable:
              "The refs pointing at the current commit could not be read, so the branch this work belongs to cannot be inferred. An unreadable lookup is not evidence that no branch points here.",
          }[resolved.reason],
      );
      return EXIT.detached;
    }

    branch = resolved.branch;
    stdout(
      `HEAD is detached; inferred branch \`${branch}\` from the refs pointing ` +
        "at the current commit.",
    );
  }

  const branchIssue = branchIssueOf(branch, config.branchPrefix);
  const linked = linkedIssuesOf(body);

  // Evidence for the snapshot promotion head shape. `merge-base
  // --is-ancestor` exits non-zero — so `git` throws — when HEAD is not
  // contained in the snapshotted branch, and it throws too when the
  // remote-tracking ref is missing. Both are "not shown to be contained",
  // which withholds the exemption rather than granting it on a name.
  const promotionEvidence = {
    baseRefName: base,
    /** @param {string} snapshotted */
    containedIn: (snapshotted) => {
      try {
        git(
          "merge-base",
          "--is-ancestor",
          "HEAD",
          `refs/remotes/origin/${snapshotted}`,
        );
        return true;
      } catch {
        return false;
      }
    },
  };

  stdout(`Branch: ${branch}`);
  stdout(`Branch issue: ${branchIssue ? `#${branchIssue}` : "(none)"}`);
  stdout(
    `Body links: ${linked.length ? linked.map((issue) => `#${issue}`).join(", ") : "(none)"}`,
  );
  // Read from config, not `gh repo view --json defaultBranchRef` and not a
  // hardcoded name: every pull request in this protocol targets the
  // integration branch, which the default branch is not guaranteed to be.
  stdout(`Base branch: ${config.integrationBranch}`);
  stdout(`Intended base: ${base}`);

  // Every pull request targets `integrationBranch`, except the two documented
  // promotion shapes (`release` -> `staging`, `staging` -> `main`), which
  // `review.mjs` recognises by head branch alone, not by base — a promotion's
  // base varies (`promotionBranch`, or whatever sits above it) while its head
  // is always `integrationBranch` or `promotionBranch`. Match that rule
  // exactly rather than reimplementing it, so this refuses precisely what
  // `review.mjs` would treat as a non-promotion pull request against the
  // wrong branch.
  if (
    base !== config.integrationBranch &&
    !isPromotionBranch(branch, config, promotionEvidence)
  ) {
    stderr(
      `This pull request would target \`${base}\`, but the configured ` +
        `integration branch is \`${config.integrationBranch}\`. Open it ` +
        `against \`${config.integrationBranch}\` instead, or, if this is a ` +
        `promotion, open it from \`${config.integrationBranch}\`` +
        (config.promotionBranch ? ` or \`${config.promotionBranch}\`` : "") +
        " so it is exempt.",
    );
    return EXIT.wrongBase;
  }

  // Everything below resolves an *authoring issue*, and a promotion pull
  // request has none: nobody runs `claim.mjs` against one, so it carries no
  // closing keyword and its head branch names no issue. `review.mjs record`
  // detects that from the head branch and binds the verdict to the pull
  // request number and head SHA instead, so it "never reaches `2` or `3`" for
  // a promotion (docs/AGENT_LOOP.md, "Promotion pull requests"). Running the
  // resolution anyway sent every promotion down the `unidentifiable` branch
  // and refused it with exit 2 — a refusal whose own message tells the reader
  // to add `Closes #<issue>`, which is exactly wrong here: a promotion closes
  // nothing, and a spurious closing keyword would make the `Close referenced
  // issues` workflow release the claim reservation of an unrelated issue.
  if (isPromotionBranch(branch, config, promotionEvidence)) {
    stdout(
      `Branch \`${branch}\` is a promotion branch, so this pull request is a ` +
        `promotion into \`${base}\`. It resolves to no authoring issue and ` +
        "needs none: `review.mjs record` binds a promotion's verdict to the " +
        "pull request number and head SHA. This pull request would be " +
        "reviewable.",
    );
    return EXIT.ok;
  }

  // `record` has a second authorless shape — a pull request whose
  // *author* is the Dependabot bot — and deliberately does not add one here.
  // This command judges a branch a session is about to open a pull request
  // from, and that session is never Dependabot: the bot opens its own pull
  // requests directly and runs nothing in this repository. So the author of
  // anything reaching this code is human or agent, `record` will not grant the
  // bypass to it, and the resolution below is exactly the answer `record`
  // gives. A `dependabot/`-prefixed branch checked out by a session therefore
  // falls through to `unidentifiable` here and to `EXIT.unidentifiable` there
  // — the two agree, which is the point. Recognising the prefix here would be
  // the one thing the Dependabot path rules out: a confident pass for a pull request
  // `record` would refuse.
  //
  // Several closing keywords is no longer a refusal in `record`, so it
  // must not be one here either — a preflight stricter than the thing it
  // predicts issues confident refusals for pull requests that would in fact
  // record fine, which is the same wasted pass in the other direction.
  const authorship = authorshipIssues({ linkedIssues: linked, branchIssue });

  if (!authorship.ok) {
    stderr(
      {
        mismatch: `Branch \`${branch}\` names issue #${branchIssue}, but the body links ${linked.map((issue) => `#${issue}`).join(", ")} and not #${branchIssue}. \`review.mjs record\` refuses a mismatch between the two.`,
        unidentifiable: `Branch \`${branch}\` does not name a claimed issue (expected \`${config.branchPrefix}<issue>-...\`), and the body has no \`Closes\`/\`Fixes\`/\`Resolves #<issue>\` reference either, so \`review.mjs record\` has nothing to resolve to.`,
      }[authorship.reason],
    );
    return EXIT.refused;
  }

  const claims = authorship.issues.flatMap((issue) => {
    const worker = claimant(
      JSON.parse(gh("issue", "view", issue, "--json", "comments")).comments,
    );

    return worker ? [{ issue, worker }] : [];
  });

  if (claims.length === 0) {
    stderr(
      `${authorship.issues.map((issue) => `#${issue}`).join(" and ")} ` +
        `${authorship.issues.length > 1 ? "resolve" : "resolves"}, but ` +
        `${authorship.issues.length > 1 ? "none carries" : "it carries no"} ` +
        "Rallypoint claim comment, so `review.mjs record` will still refuse " +
        "this pull request.",
    );
    return EXIT.refused;
  }

  stdout(
    `Resolves to ${claims
      .map((claim) => `issue #${claim.issue}, claimed by \`${claim.worker}\``)
      .join("; ")}. This pull request would be reviewable.`,
  );

  // Reviewable is not the same as correct. Everything above asks whether a
  // verdict could be written down for this pull request; this asks what merging
  // it would actually do to the board.
  //
  // It runs last because it is the only check here that can pass a pull request
  // the author must still change: the three above are about a pull request that
  // cannot be reviewed, and reporting "your branch is unresolvable" and "your
  // commit message closes a stranger's issue" in one breath buries the second.
  //
  // Placed in `preflight.mjs` rather than in a CI job because the commit-message
  // half has exactly one moment where it is cheap. A body can be edited after
  // the pull request is open; a message on a pushed branch takes a rebase and a
  // force-push, and once the pull request has merged the issue is already
  // closed and the remedy is a hand repair by an operator.
  const range = branchCommits(git, base);

  if (range === null) {
    stdout(
      `Commit messages: not checked — neither \`origin/${base}\` nor ` +
        `\`${base}\` could be resolved, so the commits this pull request would ` +
        "contain are unknown. GitHub reads them for closing keywords whether " +
        "or not this command could.",
    );
  } else {
    stdout(
      `Commit messages: ${range.commits.length} commit${range.commits.length === 1 ? "" : "s"} in \`${range.range}\``,
    );
  }

  // The already-open case (this command is normally run before the pull request
  // exists). Printed, never a refusal: GitHub is answering about the body
  // already on the pull request, while `--body` is the body about to replace it,
  // so the two differ by exactly the edit in progress.
  const open = githubClosingReferences(gh, branch);

  if (open !== null) {
    const { extra, missing } = closingReferenceDivergence({
      declared: linked,
      github: open.issues,
    });

    stdout(
      `GitHub says pull request #${open.number}, already open from this ` +
        `branch, closes ${open.issues.length ? open.issues.map((issue) => `#${issue}`).join(", ") : "(nothing)"}.`,
    );

    if (extra.length > 0 || missing.length > 0) {
      stdout(
        "  That differs from the prepared body" +
          (extra.length
            ? `; GitHub also closes ${extra.map((issue) => `#${issue}`).join(", ")}`
            : "") +
          (missing.length
            ? `; GitHub does not close ${missing.map((issue) => `#${issue}`).join(", ")}`
            : "") +
          ". If the prepared body is the one being posted, this resolves when " +
          "it is; if it is not, the difference is real and worth a look.",
      );
    }
  }

  const drift = closureDrift({
    body,
    declared: linked,
    commits: range?.commits ?? [],
  });

  if (drift.length > 0) {
    stderr(closureDriftMessage(drift, { declared: linked }));
    return EXIT.closureDrift;
  }

  stdout(
    "No closure drift: GitHub's parser would close nothing this pull request " +
      "does not declare.",
  );
  return EXIT.ok;
};

export default preflight;

// The prerequisite check every Rallypoint entry point runs before its first
// `gh` call.
//
// The decision is pure and the probe is injected, for exactly the reason
// `lib/gh.mjs` states in its own header: no test should be able to spawn a
// process or reach the live repository by importing one of these modules.
//
// Rallypoint drives GitHub through the `gh` CLI, and this repository cannot
// vendor it — it is a signed platform binary with its own release channel and
// its own credential store, so it is a declared prerequisite
// rather than a dependency. Without this, a missing `gh`
// surfaced as a raw `execFileSync` ENOENT several calls into a claim, naming
// neither the binary that was missing nor the way to install it.

// `EX_UNAVAILABLE` from sysexits.h: "a required support program or file does
// not exist". It collides with none of the per-command exit tables in
// `docs/AGENT_LOOP.md`, which never exceed 9, so a merge gate branching on
// those codes cannot mistake an absent prerequisite for a real verdict.
//
// Not 127, the shell's "command not found", despite it reading better here.
// Package-manager `run` wrappers propagate most child exit codes faithfully —
// 5 arrives as 5, 69 as 69 — but collapse 127 to 1, and 1 is `usage` in every
// one of those tables. So wherever these scripts are invoked through an `npm
// run`/`pnpm run` alias rather than directly, 127 would reach the caller as a
// plausible, wrong answer.
export const EXIT_MISSING_PREREQUISITE = 69;

export const GH_INSTALL_URL = "https://github.com/cli/cli#installation";

/**
 * `execFileSync` reports a missing binary as the string `ENOENT` on
 * `error.code`, while a `gh` that ran and exited non-zero puts a number there.
 * The two are told apart by type, not by value.
 *
 * @param {unknown} error
 */
const spawnCode = (error) => {
  const { code } = /** @type {{ code?: unknown }} */ (error ?? {});
  return typeof code === "string" ? code : "";
};

/**
 * The first informative line of a failure, so the message stays one screen
 * rather than a stack.
 *
 * @param {unknown} error
 */
const firstLine = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr || detail.message || "").trim();
  return text.split("\n")[0] ?? "";
};

/** @param {string} problem */
export const missingGhMessage = (problem) =>
  [
    `Rallypoint needs the GitHub CLI (\`gh\`): ${problem}.`,
    "",
    "`gh` cannot be vendored into this repository, so it is a declared",
    "prerequisite rather than a dependency. Install it, then authenticate:",
    "",
    `  ${GH_INSTALL_URL}`,
    "  gh auth login",
    "",
  ].join("\n");

/**
 * Establishes that `gh` is present and runnable. Presence only: an installed
 * but unauthenticated `gh` runs, and its own error already names that problem
 * clearly, so this check does not duplicate it.
 *
 * @param {{ probe: () => unknown }} input `probe` runs `gh --version`.
 * @returns {{ ok: true } | { ok: false, message: string }}
 */
export const checkGh = ({ probe }) => {
  try {
    probe();
    return { ok: true };
  } catch (error) {
    const code = spawnCode(error);

    if (code === "ENOENT") {
      return { ok: false, message: missingGhMessage("not found on PATH") };
    }

    if (code === "EACCES" || code === "EPERM") {
      return {
        ok: false,
        message: missingGhMessage("found on PATH but not executable"),
      };
    }

    const detail = firstLine(error);
    return {
      ok: false,
      message: missingGhMessage(
        detail ? `\`gh --version\` failed: ${detail}` : "`gh --version` failed",
      ),
    };
  }
};

export default checkGh;

// Attaches a retroactive claim comment to an issue that already has an open
// pull request referencing it but no Rallypoint claim comment to identify its
// authoring session.
//
// `review.mjs record` refuses permanently when `workerAgent()` cannot resolve
// a claimant from the linked issue's comments, and until now nothing let
// anyone attach one after the fact. Pull requests hit this regularly: their pull
// requests were reviewed in full, but no claim comment existed to
// bind the verdict to, and the only way through was a human editing GitHub
// state by hand outside any documented process.
//
// This does not authenticate the id it posts. Every agent id in this loop is
// self-declared -- `review.mjs`'s header already states the self-review
// guard is bookkeeping, not authentication, and this command inherits that
// same limitation. What it does guard against is defaulting to the
// *reconciling* session's own id: `--agent-id` is mandatory, exactly like
// `claim.mjs`, so the caller must name whose session actually authored the
// branch rather than have the tool assume it was the one running right now.
//
// Two structural refusals keep this from being usable to fabricate a claim
// after the fact: it never overwrites an issue that already carries a claim
// comment, and it never guesses between several open pull requests that
// reference the same issue -- authorship would be ambiguous, so nothing is
// posted.
//
// `--pull <n>` is the other entry point. The caller of `--issue`
// already has to know the authoring issue number, which is exactly what is
// missing when a pull request was opened outside the claim flow with no
// `agent/<issue>-...` branch and a body that either has no closing keyword or
// one nobody has cross-checked yet. With
// `--pull`, the issue is resolved the same way `review.mjs record` and
// `preflight.mjs` resolve it: via `recordableIssue()`, reusing the identical
// branch/body signals rather than a second parser. Resolution failure is a
// third structural refusal, alongside the two above: a pull request whose
// branch and body disagree, or name several issues, or name none, is refused
// rather than guessed at.

import {
  branchIssue,
  claimant,
  linkedIssues,
  recordableIssue,
  referencingPullRequests,
  SAFE_AGENT_ID,
} from "../provenance.mjs";
import { openPullRequests } from "./release-claim.mjs";

// Exit codes are a public interface, matching the table in
// docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  alreadyClaimed: 2, // the issue already carries a Rallypoint claim comment
  noReferencingPullRequest: 3, // no open pull request references the issue
  ambiguousPullRequests: 4, // more than one open pull request references it
  inconclusive: 5, // the open pull request listing could not be established
  pullRequestNotOpen: 6, // --pull named a pull request that is not open
  unresolvableIssue: 7, // --pull's branch/body do not resolve to one issue
};

const USAGE =
  "Usage: reconcile.mjs (--issue <n> | --pull <n>) --agent-id " +
  "<authoring-session-id> [--dry-run]";

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  /** @param {string} flag */
  const values = (flag) =>
    argv.flatMap((value, index) =>
      value === flag && argv[index + 1] ? [argv[index + 1]] : [],
    );

  return {
    issue: values("--issue").at(0),
    pull: values("--pull").at(0),
    agentId: values("--agent-id").at(0),
    dryRun: argv.includes("--dry-run"),
  };
};

/** @param {unknown} error */
const describeError = (error) =>
  error instanceof Error ? error.message : String(error);

/**
 * Resolves `--pull <n>` to an issue number by reading the pull request itself
 * and running the same `recordableIssue()` rule `record` and `preflight` use
 * -- never a second parser. Returns the issue on success, or the exit code
 * and message to refuse with.
 *
 * @param {{
 *   pull: string,
 *   config: { branchPrefix: string },
 *   gh: (...args: string[]) => string,
 * }} input
 * @returns {{ ok: true, issue: string } | { ok: false, code: number, message: string }}
 */
export const resolveIssueFromPull = ({ pull, config, gh }) => {
  /** @type {{ number: number, headRefName: string, body: string | null, state: string }} */
  let view;

  try {
    view = JSON.parse(
      gh("pr", "view", pull, "--json", "number,headRefName,body,state"),
    );
  } catch (error) {
    return {
      ok: false,
      code: EXIT.inconclusive,
      message: `Pull request #${pull} could not be read (${describeError(error)}).`,
    };
  }

  if (view.state !== "OPEN") {
    return {
      ok: false,
      code: EXIT.pullRequestNotOpen,
      message:
        `Pull request #${pull} is ${view.state.toLowerCase()}, not open; ` +
        "reconcile only an open pull request.",
    };
  }

  const linked = linkedIssues(view.body);
  const branch = branchIssue(view.headRefName, config.branchPrefix);
  const recordable = recordableIssue({ linkedIssues: linked, branchIssue: branch });

  if (!recordable.ok) {
    const message = {
      "ambiguous-body":
        `Pull request #${pull}'s body links several issues ` +
        `(${linked.map((issue) => `#${issue}`).join(", ")}); authorship is ` +
        "ambiguous, so nothing was resolved.",
      mismatch:
        `Pull request #${pull}'s branch \`${view.headRefName}\` names issue ` +
        `#${branch}, but its body links #${linked[0]}. Reconcile a mismatch ` +
        "between the two by hand rather than picking one.",
      unidentifiable:
        `Pull request #${pull}'s branch \`${view.headRefName}\` does not ` +
        `name a claimed issue (expected \`${config.branchPrefix}<issue>-...\`), ` +
        "and its body has no `Closes`/`Fixes`/`Resolves #<issue>` reference " +
        "either, so there is nothing to reconcile against.",
    }[recordable.reason];

    return { ok: false, code: EXIT.unresolvableIssue, message };
  }

  return { ok: true, issue: recordable.issue };
};

// Which open pull requests reference the given issue. The predicate itself
// lives in `provenance.mjs` alongside the two signals it reads, so a pull
// request this command can reconcile is one `record` would actually recognise
// afterward and one `claim.mjs` would already have refused to hand out.
// Re-exported here because it has always been part of this module's interface.
export { referencingPullRequests };

/**
 * @param {{
 *   agentId: string,
 *   issue: string,
 *   pull: { number: number },
 * }} input
 */
export const claimComment = ({ agentId, issue, pull }) =>
  [
    `Claimed by Rallypoint agent \`${agentId}\`.`,
    "",
    "**Retroactive/backfilled claim.** This comment was posted by " +
      "`reconcile.mjs` after the fact, not before implementation, because " +
      `pull request #${pull.number} was already open against #${issue} with ` +
      "no prior Rallypoint claim comment to identify its authoring session. " +
      "It exists solely so `review.mjs record` can identify that session and " +
      `bind a verdict to #${pull.number}'s current head SHA.`,
  ].join("\n");

/**
 * @param {{
 *   argv: string[],
 *   config: { branchPrefix: string },
 *   gh: (...args: string[]) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 * }} input
 * @returns {number} Process exit code.
 */
export const reconcile = ({
  argv,
  config,
  gh,
  stdout = console.log,
  stderr = console.error,
}) => {
  const { issue: issueArg, pull: pullArg, agentId, dryRun } = parseArgs(argv);

  if (issueArg && pullArg) {
    stderr(`${USAGE}\n--issue and --pull are mutually exclusive; pass one.`);
    return EXIT.usage;
  }

  if ((!issueArg && !pullArg) || !agentId) {
    stderr(USAGE);
    return EXIT.usage;
  }

  if (issueArg && !/^\d+$/.test(issueArg)) {
    stderr(USAGE);
    return EXIT.usage;
  }

  if (pullArg && !/^\d+$/.test(pullArg)) {
    stderr(USAGE);
    return EXIT.usage;
  }

  // The id lands in a comment `review.mjs` reads back, so hold it to the same
  // shape `claim.mjs` and `review.mjs` require.
  if (!SAFE_AGENT_ID.test(agentId)) {
    stderr(
      `Agent id "${agentId}" must match ${SAFE_AGENT_ID}: letters, digits, ` +
        "dot, underscore, and hyphen only.",
    );
    return EXIT.usage;
  }

  // `issueArg` is validated non-empty and numeric above whenever `pullArg` is
  // not given, but that validation happened in separate `if` statements, which
  // checkJs does not carry forward as a narrowing of `issueArg`'s type here.
  // Route both selectors through the same `{ ok, issue } | { ok, code,
  // message }` shape instead of assigning a possibly-`undefined` value, so the
  // rest of this function reads `issue` as the plain `string` it always is by
  // this point.
  const resolved = pullArg
    ? resolveIssueFromPull({ pull: pullArg, config, gh })
    : { ok: /** @type {const} */ (true), issue: /** @type {string} */ (issueArg) };

  if (!resolved.ok) {
    stderr(resolved.message);
    return resolved.code;
  }

  const issue = resolved.issue;

  const { comments } = JSON.parse(
    gh("issue", "view", issue, "--json", "comments"),
  );

  if (claimant(comments)) {
    stderr(
      `Issue #${issue} already carries a Rallypoint claim comment; refusing ` +
        "to post a conflicting one. This command never overwrites or " +
        "duplicates an existing claim -- resolve a wrong one by hand.",
    );
    return EXIT.alreadyClaimed;
  }

  const pullRequests = openPullRequests(gh);

  if (!pullRequests.ok) {
    stderr(
      `Refusing to reconcile #${issue}: ${pullRequests.reason}. A lookup ` +
        "that could not be established is not evidence that exactly one " +
        "pull request references this issue.",
    );
    return EXIT.inconclusive;
  }

  const matches = referencingPullRequests({
    pulls: pullRequests.items,
    issue,
    branchPrefix: config.branchPrefix,
  });

  if (matches.length === 0) {
    stderr(
      `No open pull request references issue #${issue}; nothing to reconcile.`,
    );
    return EXIT.noReferencingPullRequest;
  }

  if (matches.length > 1) {
    stderr(
      `#${matches.map((pull) => `${pull.number}`).join(", #")} all ` +
        `reference issue #${issue}; authorship is ambiguous, so nothing was ` +
        "posted. Reconcile only once a single open pull request remains.",
    );
    return EXIT.ambiguousPullRequests;
  }

  const [pull] = matches;
  const body = claimComment({ agentId, issue, pull });

  if (dryRun) {
    stdout(body);
    stdout("\n(dry run: nothing was posted)");
    return EXIT.ok;
  }

  gh("issue", "comment", issue, "--body", body);
  stdout(`Reconciled issue #${issue} against #${pull.number} for agent \`${agentId}\`.`);
  return EXIT.ok;
};

export default reconcile;

// Releasing a stale claim, with every call to `gh` injected.
//
// This is the janitor's half of the claim protocol, and it runs in the opposite
// order from `lib/claim.mjs`'s rollback. That is deliberate, and the difference
// is the whole reason this module exists.
//
// It has a second caller: the holder of a claim releasing its own
// reservation, e.g. a worker standing down onto `status:blocked` because the
// work turned out to need an operator decision. `assessForRelease` is where
// that path splits off — when the claim comment's recorded agent id matches
// the caller's `--agent-id`, the `staleClaimHours` guess about whether a
// session is still running is skipped entirely, because the caller *is* that
// session and has just said it is not. A different agent id — the janitor's
// usual case — gets every check below unchanged.
//
// `claim.mjs` compensates a *partial* claim: the reservation exists and the
// issue may already read `status:claimed`, so it restores the issue first and
// releases the reservation last. A janitor undoes a *complete* claim, so the
// safe order is the inverse:
//
// | Order                     | If the second step fails      | Recoverable? |
// | ------------------------- | ----------------------------- | ------------ |
// | Delete ref -> flip labels | claimed, assigned, no ref     | Yes          |
// | Flip labels -> delete ref | ready, unassigned, ref live   | No           |
//
// The second row is unrecoverable because `lib/claim.mjs` reads a failed ref
// creation as "another session holds it" and skips the issue without touching
// it — including under an explicit `--issue <N>` — while the absent
// `status:claimed` label hides the issue from the next janitor pass too. So the
// reservation goes first, and a reservation that cannot be confirmed gone
// aborts before a single issue field is touched.
//
// Clearing the assignee is not cosmetic either: `lib/claim.mjs` filters out
// every assigned issue, so a release that clears `status:claimed` and leaves the
// issue assigned is a silent no-op.
//
// ## The invariant this module keeps failing, and what to check first
//
// Every piece of evidence here must answer *whose session is this about* before
// it is used. Four defects have shipped from this file, and all four are the
// same mistake: something true about one session read as true about another, or
// this session's own evidence thrown away with it.
//
// | # | The evidence            | Wrongly concluded                     |
// | - | ----------------------- | ------------------------------------- |
// | 1 | A merged branch's final push | a live session            |
// | 2 | An earlier session's settled pull request | a claim minutes old was dead |
// | 3 | A live push, dropped with its stale settle | released under an active worker |
// | 4 | A push predating the claim | the claiming session had ended |
// | 5 | Nothing on the remote at all | no session was running        |
//
// Row 5 is the one that is not about attribution but about *reach*: every
// signal above is read from GitHub, and a worker here commits locally and
// pushes late, so none of them can see a live session at all until it pushes.
// `lib/local-work.mjs` supplies the missing evidence and states plainly which
// machine it binds on.
//
// Two timestamps decide it, and both comparisons are here for that reason: a
// branch commit is this session's only if it postdates `claimedAt`, and a
// settled pull request concerns this claim only if it also postdates it. Every
// tie resolves to "not evidence", because GitHub stamps to the second and the
// order inside one is unknowable — the same reading `wasReopenedAfterMerge` in
// `close-referenced-issues.mjs` takes of its own tie.
//
// A change here that adds a signal should say, in the diff, which session that
// signal belongs to. If it cannot, it is not evidence.

import { CLAIM, SAFE_AGENT_ID, branchIssue, linkedIssues } from "../provenance.mjs";
import { describeLocalWork, localIssueWork } from "./local-work.mjs";

// Exit codes are a public interface, as they are for `review.mjs`. Keep them in
// sync with the table in docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  notClaimed: 2, // closed, or neither a live claim nor a stale assignee exists
  active: 3, // proven live: an open pull request, a push inside the window, or unpushed local work here
  notStale: 4, // the claim itself is younger than `staleClaimHours`
  inconclusive: 5, // eligibility could not be established, so nothing was done
  refBlocked: 6, // the reservation was not confirmed gone; no issue mutation
  restoreFailed: 7, // reservation gone, issue restore failed; still reads claimed
};

const HOUR_MS = 3_600_000;
// Every automated claim is assigned through `@me`, so when several agent
// sessions share one GitHub account, every protocol-owned assignment carries
// that one login. `config.sharedIdentity` names it.
//
// An absent reservation proves only that *protocol-owned* assignment is stale;
// it says nothing about any additional human assignee. That is exactly why the
// login has to be known rather than assumed: without it, clearing "the stale
// assignee" would sooner or later clear a person's. So when the config does not
// name one, no assignee is ever treated as protocol-owned and this backstop
// declines instead of guessing.
/**
 * @param {{ sharedIdentity?: unknown }} config
 * @returns {string | null}
 */
const sharedProtocolLogin = (config) =>
  typeof config?.sharedIdentity === "string" && config.sharedIdentity.trim()
    ? config.sharedIdentity.trim()
    : null;

// The page size asked of every listing endpoint. A response that fills the page
// cannot prove absence — the pull request or branch that would have refused the
// release may simply be on the next page — so a full page is treated as an
// answer that could not be established rather than as an empty one.
const PAGE = 100;

/**
 * The first informative line of a `gh` failure. `execFileSync` puts the useful
 * part on `stderr` and leaves `message` as the command line.
 *
 * @param {unknown} error
 */
const describeError = (error) => {
  const detail = /** @type {{ stderr?: unknown, message?: unknown }} */ (
    error ?? {}
  );
  const text = String(detail.stderr ?? detail.message ?? error ?? "").trim();
  return (
    text
      .split("\n")
      .map((line) => line.trim())
      .find((line) => line !== "")
      ?.slice(0, 200) ?? "no detail reported"
  );
};

/**
 * A lookup that distinguishes an established answer from one that could not be
 * established. Acceptance criterion 4 is exactly this distinction: an empty
 * array from a successful query is proof of absence, and everything else — an
 * error, a non-array body, a response that filled its page — is not.
 *
 * @template T
 * @typedef {{ ok: true, items: T[] } | { ok: false, reason: string }} Lookup
 */

/**
 * @param {() => string} query
 * @param {string} subject
 * @param {number} [page] Page size the query asked for, so truncation is judged
 *   against the limit actually used rather than this module's default.
 * @returns {Lookup<any>}
 */
export const listing = (query, subject, page = PAGE) => {
  let parsed;

  try {
    parsed = JSON.parse(query());
  } catch (error) {
    return { ok: false, reason: `${subject} could not be listed (${describeError(error)})` };
  }

  if (!Array.isArray(parsed)) {
    return { ok: false, reason: `the ${subject} listing was not a JSON array` };
  }

  if (parsed.length >= page) {
    return {
      ok: false,
      reason: `the ${subject} listing filled its page of ${page}, so it may be truncated`,
    };
  }

  return { ok: true, items: parsed };
};

/**
 * Refs whose name starts with `prefix`.
 *
 * A 403 on a ref *delete* says nothing about whether the ref exists — a
 * branch-scoped credential answers 403 either way, and reading one as proof of
 * existence is how stale warnings get written. Existence is established
 * by listing, never inferred from a mutation's failure.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {string} prefix
 * @returns {Lookup<{ ref?: string, object?: { sha?: string } }>}
 */
export const matchingRefs = (gh, repository, prefix) =>
  listing(
    () =>
      gh(
        "api",
        `repos/${repository}/git/matching-refs/heads/${prefix}?per_page=${PAGE}`,
      ),
    `refs under \`${prefix}\``,
  );

/**
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {string} refName Reservation ref without the `refs/heads/` prefix.
 * @returns {{ kind: "present" | "absent" } | { kind: "unknown", reason: string }}
 */
export const reservationPresence = (gh, repository, refName) => {
  const refs = matchingRefs(gh, repository, refName);

  if (!refs.ok) return { kind: "unknown", reason: refs.reason };

  // `matching-refs` matches on prefix: asking for `…/issue-2` also returns
  // `…/issue-26` and `…/issue-214`. Only an exact hit is this issue's
  // reservation, and taking a prefix neighbour for one would abort a release
  // that should have proceeded — or, worse, report a reservation deleted.
  return {
    kind: refs.items.some((ref) => ref.ref === `refs/heads/${refName}`)
      ? "present"
      : "absent",
  };
};

/**
 * The last commit time of every issue branch for this issue.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {{ branchPrefix: string }} config
 * @param {string} issue
 * @returns {Lookup<{ name: string, committedAt: string }>}
 */
export const issueBranches = (gh, repository, config, issue) => {
  const refs = matchingRefs(gh, repository, `${config.branchPrefix}${issue}-`);

  if (!refs.ok) return refs;

  /** @type {{ name: string, committedAt: string }[]} */
  const items = [];

  for (const ref of refs.items) {
    const name = String(ref.ref ?? "").replace(/^refs\/heads\//, "");

    // The trailing hyphen in the prefix already excludes `agent/2360-…` from a
    // query for issue 236, but the branch parser is the authority on which
    // issue a branch name claims, so ask it rather than trusting the prefix.
    if (branchIssue(name, config.branchPrefix) !== issue) continue;

    let commit;

    try {
      commit = JSON.parse(
        gh("api", `repos/${repository}/commits/${ref.object?.sha ?? ""}`),
      );
    } catch (error) {
      return {
        ok: false,
        reason: `the last commit on \`${name}\` could not be read (${describeError(error)})`,
      };
    }

    const committedAt =
      commit?.commit?.committer?.date ?? commit?.commit?.author?.date;

    if (typeof committedAt !== "string") {
      return {
        ok: false,
        reason: `the last commit on \`${name}\` reported no timestamp`,
      };
    }

    items.push({ name, committedAt });
  }

  return { ok: true, items };
};

/**
 * `author` is requested for `report.mjs`'s `wouldFailRecord` classification
 *, which has to tell a pull request with no resolvable authoring issue
 * apart from one that legitimately has none — a Dependabot pull request, which
 * `isDependabotAuthor` in `provenance.mjs` recognises by authorship rather than
 * by branch name. Every other caller ignores the field.
 *
 * @param {(...args: string[]) => string} gh
 * @returns {Lookup<{ number: number, headRefName: string, headRefOid: string, body: string | null, updatedAt: string, author?: unknown }>}
 */
export const openPullRequests = (gh) =>
  listing(
    () =>
      gh(
        "pr",
        "list",
        "--state",
        "open",
        "--limit",
        String(PAGE),
        "--json",
        "number,headRefName,headRefOid,body,updatedAt,author",
      ),
    "open pull requests",
  );

/**
 * Whether each issue branch still has a pull request in flight.
 *
 * `issueBranches` above answers "when did this branch last move", which is the
 * wrong question on its own: the final push of a branch whose pull request has
 * since merged is the *most* recent commit a dead session ever makes, so read
 * alone it makes an ended session look maximally alive. This answers the
 * question that disambiguates it.
 *
 * Three outcomes, and only one of them ends the session:
 *
 * - `settled` — every pull request for the branch is merged or closed. The
 *   session that pushed is over, whatever the commit clock says.
 * - `open` — a pull request is still open. Handled earlier by the open-pull-
 *   request check, and never released regardless of branch age.
 * - `none` — no pull request exists yet. A worker that has pushed but not yet
 *   opened one is mid-flight, so its push still proves life.
 *
 * `settledAt` is the newest merge or close among them, and the caller must
 * compare it against the branch's last commit rather than trusting `settled`
 * alone. `gh pr list --head` matches by branch *name* across all time, and
 * `claim.mjs` derives `agent/<issue>-<slug>` deterministically, so a re-claimed
 * issue reuses the name its previous session used. Without the comparison, a
 * new live session that has pushed but not yet opened its pull request reads as
 * `settled` off the *previous* session's merged one and gets released out from
 * under itself — the collision the reservation exists to prevent. The
 * `Refs`-not-`Closes` fix in `close-referenced-issues.mjs` deliberately grows
 * that population, since those issues stay open to be re-claimed with a merged
 * pull request already on their branch name.
 *
 * @param {(...args: string[]) => string} gh
 * @param {{ name: string }[]} branches
 * @returns {Lookup<{ name: string, state: "settled" | "open" | "none", settledAt: string | null, pullRequests: number[] }>}
 */
export const branchPullRequests = (gh, branches) => {
  /** @type {{ name: string, state: "settled" | "open" | "none", settledAt: string | null, pullRequests: number[] }[]} */
  const items = [];

  for (const { name } of branches) {
    const found = listing(
      () =>
        gh(
          "pr",
          "list",
          "--head",
          name,
          "--state",
          "all",
          "--limit",
          String(PAGE),
          "--json",
          "number,state,mergedAt,closedAt",
        ),
      `pull requests for \`${name}\``,
    );

    if (!found.ok) return found;

    // An unrecognised state is not a settled one. Only `MERGED` and `CLOSED`
    // end a session, and reading anything else as settled would release a
    // claim on a pull request that is still in flight. A draft reports `OPEN`,
    // so it lands here correctly.
    const settled = found.items.every(
      (pull) => pull.state === "MERGED" || pull.state === "CLOSED",
    );

    const stamps = found.items.flatMap((pull) => {
      const at = Date.parse(String(pull.mergedAt ?? pull.closedAt ?? ""));
      return Number.isNaN(at) ? [] : [at];
    });

    // A settled pull request whose own settle time could not be read is not
    // usable evidence: the comparison the caller has to make needs a timestamp,
    // and an absent one is an answer that was not established.
    if (settled && found.items.length > 0 && stamps.length !== found.items.length) {
      return {
        ok: false,
        reason: `a pull request for \`${name}\` reported no merge or close timestamp`,
      };
    }

    items.push({
      name,
      state: found.items.length === 0 ? "none" : settled ? "settled" : "open",
      settledAt:
        settled && stamps.length > 0
          ? new Date(Math.max(...stamps)).toISOString()
          : null,
      pullRequests: found.items.map((pull) => Number(pull.number)),
    });
  }

  return { ok: true, items };
};

/**
 * The pair of branch lookups `assess` reads, gathered in one place because the
 * second is derived from the first and both callers must ask them the same way.
 * A branch listing that could not be established carries straight through, so
 * the derived lookup never reports an absence the first one could not prove.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {{ branchPrefix: string }} config
 * @param {string} issue
 */
export const branchEvidence = (gh, repository, config, issue) => {
  const branches = issueBranches(gh, repository, config, issue);

  return {
    branches,
    branchPullRequestState: branches.ok
      ? branchPullRequests(gh, branches.items)
      : branches,
  };
};

/**
 * The last Rallypoint claim comment on an issue. Last wins, matching
 * `provenance.claimant`: a released issue can be claimed again, and the newest
 * claim is the one whose age decides staleness.
 *
 * @param {{ body?: string | null, createdAt?: string }[] | undefined} comments
 * @returns {{ agent: string, createdAt: string } | null}
 */
export const lastClaim = (comments) =>
  (comments ?? [])
    .flatMap((comment) => {
      const agent = (comment.body ?? "").match(CLAIM)?.at(1);
      return agent && typeof comment.createdAt === "string"
        ? [{ agent, createdAt: comment.createdAt }]
        : [];
    })
    .at(-1) ?? null;

/**
 * Whether `agentId` is releasing the reservation it itself holds.
 *
 * The `staleClaimHours` gate exists to stop a janitor from reclaiming work out
 * from under a session that is still running — a *guess*, aged off a comment
 * timestamp, standing in for evidence nobody else can get any other way. That
 * reasoning has nothing to say about the holder releasing its own claim: the
 * holder is the one authority on whether its own session is still working, and
 * saying so by calling this command with its own `--agent-id` is stronger
 * evidence than any of the proxies `assess` gathers. This is the only thing
 * that establishes "own" — the claim comment's recorded agent id matching the
 * caller's, nothing inferred.
 *
 * A `null` claim (no readable claim comment) never counts as self-release: the
 * holder must be established, not assumed, same as every other path through
 * this module.
 *
 * @param {{ agent: string, createdAt: string } | null} claim
 * @param {string} agentId
 * @returns {claim is { agent: string, createdAt: string }}
 */
export const isSelfRelease = (claim, agentId) =>
  claim !== null && claim.agent === agentId;

/**
 * @typedef {(
 *   | { kind: "stale", claim: { agent: string, createdAt: string }, evidence: string[] }
 *   | { kind: "active", reason: string }
 *   | { kind: "notStale", reason: string }
 *   | { kind: "unknown", reason: string }
 * )} Assessment
 */

/**
 * Whether a claim may be released, decided only from evidence that was
 * positively established. Every path that could not establish something
 * resolves to `unknown`, which refuses the release.
 *
 * @param {{
 *   issue: string,
 *   now: number,
 *   staleClaimHours: number,
 *   branchPrefix: string,
 *   claim: { agent: string, createdAt: string } | null,
 *   pullRequests: Lookup<{ number: number, headRefName: string, body: string | null, updatedAt: string }>,
 *   branches: Lookup<{ name: string, committedAt: string }>,
 *   branchPullRequestState: Lookup<{ name: string, state: "settled" | "open" | "none", settledAt: string | null, pullRequests: number[] }>,
 *   localWork: Lookup<import("./local-work.mjs").LocalWork>,
 * }} input
 * @returns {Assessment}
 */
export const assess = ({
  issue,
  now,
  staleClaimHours,
  branchPrefix,
  claim,
  pullRequests,
  branches,
  branchPullRequestState,
  localWork,
}) => {
  if (!claim) {
    return {
      kind: "unknown",
      reason: `#${issue} carries no Rallypoint claim comment, so the age of its claim cannot be established`,
    };
  }

  const claimedAt = Date.parse(claim.createdAt);

  if (Number.isNaN(claimedAt)) {
    return {
      kind: "unknown",
      reason: `the claim comment on #${issue} has an unreadable timestamp (${claim.createdAt})`,
    };
  }

  if (!pullRequests.ok) return { kind: "unknown", reason: pullRequests.reason };

  // Any open pull request naming the issue proves the work is live. Commit
  // recency is deliberately not consulted for one: a branch that has not moved
  // for days because it is waiting on a reviewer is the healthy case, and
  // GitHub bumps `updatedAt` for review comments and pushes alike, so a quiet
  // branch under an open pull request is awaiting review rather than abandoned.
  // Releasing it is the collision the reservation exists to prevent — it is
  // the collision this module has caused more than once.
  const live = pullRequests.items.filter(
    (pull) =>
      branchIssue(pull.headRefName, branchPrefix) === issue ||
      linkedIssues(pull.body).includes(issue),
  );

  if (live.length > 0) {
    const latest = live.map((pull) => pull.updatedAt).sort().at(-1);
    return {
      kind: "active",
      reason: `open pull request ${live.map((pull) => `#${pull.number}`).join(", ")} references #${issue} (last activity ${latest}); an open pull request awaiting review is not idle`,
    };
  }

  // Local, unpushed work outranks every remote signal below it, including the
  // settled-pull-request proof that a session ended. A worktree
  // holding commits the remote does not have is not a guess about liveness: the
  // commits are there, they exist nowhere else, and whether the session that
  // wrote them is still breathing does not change what releasing the claim
  // would cost. Janitor candidates are found in exactly this state routinely.
  //
  // Checked after the open-pull-request rule purely so the more informative
  // reason wins when both apply, and before the branch loop so it cannot be
  // overtaken by a settled pull request on a reused branch name.
  if (!localWork.ok) return { kind: "unknown", reason: localWork.reason };

  if (localWork.items.length > 0) {
    return {
      kind: "active",
      reason: `unpushed local work for #${issue} is on this machine: ${describeLocalWork(localWork.items, issue)}`,
    };
  }

  if (!branches.ok) return { kind: "unknown", reason: branches.reason };

  const threshold = now - staleClaimHours * HOUR_MS;

  /** @type {string[]} */
  const settledEvidence = [];
  /** @type {Set<string>} */
  const settledBranches = new Set();
  // Branches in the window whose last commit predates the claim: not this
  // session's work, so neither evidence that it ended nor proof it is running.
  /** @type {Set<string>} */
  const notThisSession = new Set();

  for (const branch of branches.items) {
    const committedAt = Date.parse(branch.committedAt);

    if (Number.isNaN(committedAt)) {
      return {
        kind: "unknown",
        reason: `the last commit on \`${branch.name}\` has an unreadable timestamp (${branch.committedAt})`,
      };
    }

    if (committedAt <= threshold) continue;

    // A push inside the window is only proof of life while the branch still
    // has a pull request in flight. Once every pull request for it has merged
    // or closed, that push is the last thing an ended session did, not a sign
    // of a running one — an issue can sit in that state with the proof asserted
    // minutes after the merge that ended the session.
    if (!branchPullRequestState.ok) {
      return { kind: "unknown", reason: branchPullRequestState.reason };
    }

    const state = branchPullRequestState.items.find(
      (candidate) => candidate.name === branch.name,
    );

    if (state === undefined) {
      return {
        kind: "unknown",
        reason: `the pull request state of \`${branch.name}\` was not established`,
      };
    }

    if (state.state !== "settled") {
      return {
        kind: "active",
        reason: `\`${branch.name}\` was pushed at ${branch.committedAt}, inside the ${staleClaimHours}h window`,
      };
    }

    const settledAt = Date.parse(state.settledAt ?? "");

    if (Number.isNaN(settledAt)) {
      return {
        kind: "unknown",
        reason: `\`${branch.name}\` has no readable merge or close time, so it cannot be established whether its last push came before or after its pull request ended`,
      };
    }

    // The settle has to postdate the *claim* to say anything about it.
    //
    // Guarding the push alone is not enough, and this is the hole the second
    // review round found. `delete_branch_on_merge` is false on this repository,
    // so a merged session's branch outlives it; a re-claim reuses the name, and
    // for the first several minutes the new session has claimed but not yet
    // pushed. The surviving branch's last commit is then inside the window and
    // predates its own merge, so it would land in `settledEvidence` and — via
    // the `notStale` yield below — release a claim minutes old. That is the
    // same collision as above, reached through the population defect 2's own fix
    // creates: `Refs`-not-`Closes` issues that stay open and get re-claimed
    // with a merged pull request already on their deterministic branch name.
    //
    // An earlier session's pull request is simply not evidence about this
    // claim, so it is skipped rather than counted either way. Equal timestamps
    // skip too: GitHub stamps to the second and the order inside it is
    // unknowable, so the safe side of the tie is "not evidence", the same
    // reading `wasReopenedAfterMerge` takes of its own tie.
    // Not `continue`. Skipping the branch outright would discard its push as
    // well as its settle, and the push may be this session's own proof of life
    // — the third instance of one class of defect this code has produced:
    // evidence about one session attributed to, or withheld from, another. With
    // the settle discarded the ordinary rule applies again, and a commit inside
    // the window means someone is working.
    if (settledAt <= claimedAt) {
      return {
        kind: "active",
        reason: `\`${branch.name}\` was pushed at ${branch.committedAt}, inside the ${staleClaimHours}h window (its last pull request ended at ${state.settledAt}, before this claim, so it says nothing about this session)`,
      };
    }

    // The push has to predate the settle to have been part of that session.
    // A commit at or after it is a new session on a reused branch name, and
    // releasing on it would take the issue away from a worker actively pushing.
    if (committedAt >= settledAt) {
      return {
        kind: "active",
        reason: `\`${branch.name}\` was pushed at ${branch.committedAt}, at or after its last pull request ended at ${state.settledAt}, so a later session is working on it`,
      };
    }

    // The push must postdate the claim to be the claiming session's. `claim.mjs`
    // runs before the branch exists, so a commit older than the claim provably
    // belongs to someone else, and "that push ended the session" would be a
    // statement about a session that had not started yet.
    //
    // `continue` is safe here and cannot leak into a release on age alone. Being
    // in this loop body means `committedAt > threshold`; if `committedAt` is also
    // `<= claimedAt` then `claimedAt > threshold`, so the claim is younger than
    // `staleClaimHours` and the age check below returns `notStale`. A branch that
    // is in the window and older than the claim is arithmetically impossible when
    // the claim itself is outside it.
    //
    // Skipping rather than returning `active` is the honest verdict: the branch
    // says nothing either way, so the age threshold should be what decides, and
    // the refusal names the real reason.
    if (committedAt <= claimedAt) {
      notThisSession.add(branch.name);
      continue;
    }

    settledBranches.add(branch.name);
    settledEvidence.push(
      `\`${branch.name}\` was pushed at ${branch.committedAt}, inside the ${staleClaimHours}h window, but its pull request (${state.pullRequests.map((number) => `#${number}`).join(", ")}) ended at ${state.settledAt} with no commit after it, so that push ended the session rather than proving one is running.`,
    );
  }

  // The age threshold is a *guess* at whether a session is still running.
  // A settled pull request is positive proof that it is not, so it outranks
  // the guess: without this, a session that claims, pushes, merges, and ends
  // inside the window stays claimed for the remainder of it — which is exactly
  // the shape this rule exists for; fixing only the branch check above would
  // not have moved it, because such a claim is often well inside the threshold.
  if (claimedAt > threshold && settledEvidence.length === 0) {
    return {
      kind: "notStale",
      reason: `#${issue} was claimed by \`${claim.agent}\` at ${claim.createdAt}, less than ${staleClaimHours}h ago`,
    };
  }

  return {
    kind: "stale",
    claim,
    evidence: [
      settledEvidence.length > 0
        ? `Claimed by \`${claim.agent}\` at ${claim.createdAt}. The claim is not being released on age — it is released because the session that held it provably ended.`
        : `Claimed by \`${claim.agent}\` at ${claim.createdAt}, older than the ${staleClaimHours}h \`staleClaimHours\` threshold.`,
      ...settledEvidence,
      `No open pull request names #${issue} (${pullRequests.items.length} open pull request(s) read in full).`,
      // Stated even when it found nothing, because its reach is the thing a
      // reader has to weigh: it binds only on the machine this ran from, and a
      // session holding unpushed commits on another host is invisible to it.
      `No worktree on the machine this ran from holds unpushed work for #${issue}. This check does not reach any other host.`,
      // Only the branches the window actually cleared are described that way.
      // A branch released on settled-pull-request grounds is inside the window
      // by definition, and has already said so above; repeating it here as
      // "outside the window" would put two contradictory claims about the same
      // branch in one block of evidence a reviewer is meant to audit.
      ...(() => {
        const byAge = branches.items.filter(
          (branch) =>
            !settledBranches.has(branch.name) &&
            !notThisSession.has(branch.name),
        );

        // Described for what it is. These are inside the window, so calling
        // them "outside" would put two contradictory claims about one branch in
        // a block a reviewer is meant to audit — the same trap the settled
        // branches avoid just above.
        const foreign = [...notThisSession].map(
          (name) =>
            `\`${name}\` moved inside the window but before this claim was made, so it is not this session's work and proves nothing either way.`,
        );

        if (branches.items.length === 0) {
          return [`No issue branch \`${branchPrefix}${issue}-*\` exists.`];
        }

        return byAge.length === 0
          ? foreign
          : [
              byAge
                .map(
                  (branch) =>
                    `\`${branch.name}\` last moved at ${branch.committedAt}, outside the window.`,
                )
                .join(" "),
              ...foreign,
            ];
      })(),
    ],
  };
};

/**
 * `humanLabel` is set when the issue carries `needs:human`, in which case the
 * release does not return the issue to the claimable pool and the
 * comment has to say so — a reader auditing this comment would otherwise
 * reasonably conclude it is claimable again.
 *
 * Since the readiness label was removed, the release is purely subtractive: it removes `status:claimed`
 * and the assignee and adds nothing, because claimability is derived from the
 * absence of a hold label rather than declared by `status:ready`. So this is
 * now a statement about what the *remaining* labels mean, not about a
 * restoration that was withheld.
 *
 * @param {{
 *   agentId: string,
 *   issue: string,
 *   refPath: string,
 *   evidence: string[],
 *   reservation: "deleted" | "absent" | "planned",
 *   humanLabel?: string | null,
 * }} input
 */
export const explanation = ({
  agentId,
  issue,
  refPath,
  evidence,
  reservation,
  humanLabel = null,
}) =>
  [
    `Claim on #${issue} released by Rallypoint janitor \`${agentId}\`.`,
    "",
    ...(humanLabel
      ? [
          `#${issue} carries \`${humanLabel}\`, so it does **not** return to the` +
            " claimable pool: the reservation is released and the claim label" +
            " and assignee cleared, but that label holds it out until an" +
            " operator resolves what it is waiting on. Handing the next worker" +
            " an issue no agent session can advance is the failure this avoids.",
          "",
        ]
      : []),
    "Evidence:",
    "",
    ...evidence.map((line) => `- ${line}`),
    "",
    {
      deleted: `The reservation \`${refPath}\` was deleted before this issue was touched.`,
      absent: `The reservation \`${refPath}\` was already absent; only the issue needed restoring.`,
      planned: `The reservation \`${refPath}\` would be deleted before this issue is touched.`,
    }[reservation],
    "The reservation always goes first: a failure after that point leaves the" +
      " issue readable as `status:claimed` for the next janitor pass, whereas" +
      " the reverse order strands it as claimable with a live reservation" +
      " that no claim attempt can get past.",
  ].join("\n");

/**
 * The comment posted for an **orphaned** reservation: a live ref behind an
 * open issue that does not carry `status:claimed` (report.mjs's
 * `unclaimable` classification) — for example one moved to `status:blocked`
 * after its worker found the claim could not proceed. There is no
 * `status:claimed` removal to make here, because the
 * issue was never left claimed; no label is changed, so the wording says that
 * explicitly rather than reusing `explanation`'s claim-release framing.
 *
 * The assignee is a different matter and this comment used to get it wrong,
 * asserting that none was cleared. An assignee is set at claim time
 * and means nothing once the reservation is gone, while `lib/claim.mjs`
 * filters out every assigned issue — so leaving it set turns the issue into one
 * that reads as claimable on every board while `claim.mjs` refuses it.
 *
 * @param {{
 *   agentId: string,
 *   issue: string,
 *   refPath: string,
 *   evidence: string[],
 *   claimedLabel: string,
 *   reservation: "deleted" | "planned",
 *   assignees: string[],
 * }} input
 */
export const orphanExplanation = ({
  agentId,
  issue,
  refPath,
  evidence,
  claimedLabel,
  reservation,
  assignees,
}) =>
  [
    `Orphaned reservation on #${issue} released by Rallypoint janitor \`${agentId}\`.`,
    "",
    `#${issue} does not carry \`${claimedLabel}\`, so this is not a claim` +
      " release and **no label was changed**. The stray reservation" +
      ` \`${refPath}\` ${reservation === "deleted" ? "was deleted" : "would be deleted"}.`,
    "",
    assignees.length === 0
      ? "The issue carried no assignee, so none needed clearing."
      : `${assignees.map((login) => `\`${login}\``).join(", ")}` +
        (reservation === "deleted"
          ? ` ${assignees.length === 1 ? "was" : "were"} unassigned as well.`
          : " would be unassigned as well.") +
        " An assignee outlives the claim that set it, and `claim.mjs` filters" +
        " out every assigned issue — so an issue left assigned after its" +
        " reservation is gone is unclaimable no matter which label it carries.",
    "",
    "Evidence:",
    "",
    ...evidence.map((line) => `- ${line}`),
  ].join("\n");

const USAGE =
  "Usage: release-claim.mjs --issue <open-issue-number> --agent-id <unique-session-id> [--dry-run]";

/** @param {string[]} argv */
export const parseArgs = (argv) => {
  /** @param {string} flag */
  const values = (flag) =>
    argv.flatMap((value, index) =>
      value === flag && argv[index + 1] ? [argv[index + 1]] : [],
    );

  return {
    issue: values("--issue").at(0),
    agentId: values("--agent-id").at(0),
    dryRun: argv.includes("--dry-run"),
  };
};

/**
 * The audit record for the backstop case: an open issue is still assigned
 * after its reservation ref has gone. The absent ref is the proof that the
 * claim ended; no age heuristic applies, and no label changes.
 *
 * @param {{
 *   agentId: string,
 *   issue: string,
 *   refPath: string,
 *   assignees: string[],
 *   humanLabel: string | null,
 *   sharedIdentity: string,
 *   action: "planned" | "cleared",
 * }} input
 */
export const staleAssigneeExplanation = ({
  agentId,
  issue,
  refPath,
  assignees,
  humanLabel,
  sharedIdentity,
  action,
}) => `Rallypoint janitor \`${agentId}\` ${
  action === "planned" ? "would clear" : "cleared"
} stale assignee${assignees.length === 1 ? "" : "s"} ${assignees
  .map((login) => `\`${login}\``)
  .join(", ")} from #${issue}.

- The claim reservation \`${refPath}\` is absent. \`${sharedIdentity}\` is this repository's shared claim-protocol identity, so the absent reservation proves the claim ended for \`${sharedIdentity}\`; the \`staleClaimHours\` heuristic is neither needed nor consulted. Any other assignee is outside that proof and remains untouched.
- No label was changed.${
  humanLabel
    ? ` \`${humanLabel}\` still holds the issue out of the claimable pool; it does not preserve an assignee left by an ended claim.`
    : ""
}`;

/**
 * Clears the assignee left after a claim reservation has already disappeared.
 * `reservationPresence` is deliberately the same exact-ref authority used by
 * every release path. `report.mjs` only nominates this repair and remains
 * read-only; this function re-establishes the proof immediately before acting.
 *
 * @param {{
 *   issue: string,
 *   agentId: string,
 *   refName: string,
 *   refPath: string,
 *   repository: string,
 *   assignees: string[],
 *   humanLabel: string | null,
 *   config: { sharedIdentity?: unknown },
 *   gh: (...args: string[]) => string,
 *   dryRun: boolean,
 *   stdout: (line: string) => void,
 *   stderr: (line: string) => void,
 * }} input
 */
export const clearStaleAssignee = ({
  issue,
  agentId,
  refName,
  refPath,
  repository,
  assignees,
  humanLabel,
  config,
  gh,
  dryRun,
  stdout,
  stderr,
}) => {
  const sharedIdentity = sharedProtocolLogin(config);

  // Declining here is the whole safety property. Without a named identity there
  // is no way to tell a protocol assignment from a person's, and this is the
  // one path that removes assignees.
  if (sharedIdentity === null) {
    stderr(
      `Refusing to clear the assignee on #${issue}: \`sharedIdentity\` is not set in \`.rallypoint/config.json\`, so no assignee can be shown to be protocol-owned rather than a person's. Set it to the login your agent sessions authenticate as, or clear the assignee by hand.`,
    );
    return EXIT.inconclusive;
  }

  const presence = reservationPresence(gh, repository, refName);

  if (presence.kind === "unknown") {
    stderr(
      `Refusing to clear the assignee on #${issue}: whether \`${refPath}\` exists could not be established (${presence.reason}). Nothing was changed.`,
    );
    return EXIT.refBlocked;
  }

  if (presence.kind === "present") {
    stderr(
      `Refusing to clear the assignee on #${issue}: reservation \`${refPath}\` is live, so the claim has not ended.`,
    );
    return EXIT.active;
  }

  const protocolAssignees = assignees.filter(
    (login) => login === sharedIdentity,
  );

  if (protocolAssignees.length === 0) {
    stderr(
      `Issue #${issue} is not assigned to the shared Rallypoint identity \`${sharedIdentity}\` and has no reservation \`${refPath}\`; there is no proven protocol assignee to clear. Any other assignee was left unchanged.`,
    );
    return EXIT.notClaimed;
  }

  const explanation = staleAssigneeExplanation({
    agentId,
    issue,
    refPath,
    assignees: protocolAssignees,
    humanLabel,
    sharedIdentity,
    action: dryRun ? "planned" : "cleared",
  });

  if (dryRun) {
    stdout(explanation);
    stdout("\n(dry run: nothing was edited or commented)");
    return EXIT.ok;
  }

  try {
    gh(
      "issue",
      "edit",
      issue,
      ...protocolAssignees.flatMap((login) => ["--remove-assignee", login]),
    );
  } catch (error) {
    stderr(
      `Issue #${issue} could not be unassigned (${describeError(error)}). Nothing else was changed.`,
    );
    return EXIT.restoreFailed;
  }

  stdout(`Unassigned ${protocolAssignees.join(", ")} from #${issue}.`);

  try {
    gh("issue", "comment", issue, "--body", explanation);
  } catch (error) {
    stderr(
      `The shared Rallypoint identity was unassigned from #${issue}, but the required audit comment could not be posted (${describeError(error)}). The unassignment may already be visible and was not rolled back, because reassigning could collide with a new claim. The repair is incomplete: post the audit explanation by hand, then rerun the janitor pass.`,
    );
    stderr(`Missing audit explanation:\n${explanation}`);
    return EXIT.restoreFailed;
  }

  stdout(`CLEARED_STALE_ASSIGNEE=${issue}`);
  return EXIT.ok;
};

/**
 * The eligibility check both release paths run, with the self-release
 * shortcut applied before either of them spends a single `gh` call on
 * evidence the holder's own say-so already outweighs.
 *
 * A self-release is not "instantly stale" in the sense `assess` means it —
 * nothing aged past `staleClaimHours` — so this returns a `stale` verdict
 * carrying its own evidence line instead, which is what lets a self-release
 * flow through the same explanation-building code below unchanged while still
 * reading honestly to whoever audits the resulting comment.
 *
 * @param {{
 *   issue: string,
 *   now: number,
 *   staleClaimHours: number,
 *   branchPrefix: string,
 *   claim: { agent: string, createdAt: string } | null,
 *   agentId: string,
 *   gh: (...args: string[]) => string,
 *   git?: (args: string[], options?: { cwd?: string }) => string,
 *   repository: string,
 *   config: { branchPrefix: string, integrationBranch?: string },
 * }} input
 * @returns {Assessment}
 */
export const assessForRelease = ({
  issue,
  now,
  staleClaimHours,
  branchPrefix,
  claim,
  agentId,
  gh,
  git,
  repository,
  config,
}) => {
  if (isSelfRelease(claim, agentId)) {
    return {
      kind: "stale",
      claim,
      evidence: [
        `Released by its own holder \`${agentId}\`, matching the agent id recorded in the claim comment at ${claim?.createdAt}. The holder of a claim is the one authority on whether its own session is still running, so the ${staleClaimHours}h \`staleClaimHours\` threshold does not apply.`,
      ],
    };
  }

  return assess({
    issue,
    now,
    staleClaimHours,
    branchPrefix,
    claim,
    pullRequests: openPullRequests(gh),
    // A caller that supplied no `git` runner gets `unknown`, not an empty
    // answer. Defaulting the other way would let a caller silently lose the
    // local-work guard by omission, which is the failure mode this module has
    // shipped four times already in other forms.
    localWork: git
      ? localIssueWork({
          git,
          issue,
          branchPrefix,
          integrationBranch: config.integrationBranch ?? "main",
        })
      : {
          ok: false,
          reason: `no local \`git\` runner was supplied, so whether this machine holds unpushed work for #${issue} was not established`,
        },
    ...branchEvidence(gh, repository, config, issue),
  });
};

/**
 * Releases a reservation for an open issue that carries neither
 * `status:claimed` nor any hold label (§ "A third case" in `releaseClaim`).
 * Eligibility is proven exactly like an ordinary release — the same open
 * pull request and issue branch checks, aged off the same last claim comment
 * — because the reservation still exists to prevent a second worker from
 * colliding with whatever session is looking at this issue.
 *
 * Success touches the ref and the assignee, in that order, and no label. The
 * label is genuinely not this command's business: `claim.mjs`'s state machine
 * moved on from this issue, and there is no `status:claimed` for it to
 * restore. The assignee is, because it is an artefact of the claim that has
 * just ended and `lib/claim.mjs` refuses every assigned issue — the
 * same reasoning the ordinary release path applies below, and the one
 * `close-referenced-issues.mjs` applies to the `Refs #<issue>` merge shape.
 * Ordering matches the rest of this module for the same reason: a failure
 * between the two steps must leave the reservation gone rather than live.
 *
 * @param {{
 *   issue: string,
 *   agentId: string,
 *   refName: string,
 *   refPath: string,
 *   repository: string,
 *   view: {
 *     assignees: { login?: string }[],
 *     comments: { body?: string | null, createdAt?: string }[],
 *   },
 *   config: {
 *     branchPrefix: string,
 *     staleClaimHours: number,
 *     labels: { claimed: string },
 *   },
 *   gh: (...args: string[]) => string,
 *   git?: (args: string[], options?: { cwd?: string }) => string,
 *   dryRun: boolean,
 *   stdout: (line: string) => void,
 *   stderr: (line: string) => void,
 *   now: number,
 * }} input
 * @returns {number} Process exit code.
 */
export const releaseOrphanedReservation = ({
  issue,
  agentId,
  refName,
  refPath,
  repository,
  view,
  config,
  gh,
  git,
  dryRun,
  stdout,
  stderr,
  now,
}) => {
  const assessment = assessForRelease({
    issue,
    now,
    staleClaimHours: config.staleClaimHours,
    branchPrefix: config.branchPrefix,
    claim: lastClaim(view.comments),
    agentId,
    gh,
    git,
    repository,
    config,
  });

  if (assessment.kind === "unknown") {
    stderr(
      `Refusing to release #${issue}: ${assessment.reason}. A lookup that could not be established is not evidence of absence, so nothing was changed.`,
    );
    return EXIT.inconclusive;
  }

  if (assessment.kind === "active") {
    stderr(`Refusing to release #${issue}: ${assessment.reason}.`);
    return EXIT.active;
  }

  if (assessment.kind === "notStale") {
    stderr(`Refusing to release #${issue}: ${assessment.reason}.`);
    return EXIT.notStale;
  }

  /** @type {string[]} */
  const assignees = view.assignees.flatMap((assignee) =>
    assignee.login ? [assignee.login] : [],
  );

  if (dryRun) {
    stdout(
      orphanExplanation({
        agentId,
        issue,
        refPath,
        evidence: assessment.evidence,
        claimedLabel: config.labels.claimed,
        reservation: "planned",
        assignees,
      }),
    );
    stdout(`\n(dry run: nothing was deleted, edited, or commented)`);
    return EXIT.ok;
  }

  try {
    gh("api", "--method", "DELETE", `repos/${repository}/git/${refPath}`);
  } catch (error) {
    stderr(
      `Refusing to release #${issue}: \`${refPath}\` could not be deleted (${describeError(error)}). No issue state was changed.`,
    );
    return EXIT.refBlocked;
  }

  const after = reservationPresence(gh, repository, refName);

  if (after.kind !== "absent") {
    const detail = after.kind === "unknown" ? after.reason : "it is still listed";
    stderr(
      `Refusing to release #${issue}: the delete of \`${refPath}\` reported success but the ref could not be confirmed gone (${detail}).`,
    );
    return EXIT.refBlocked;
  }

  stdout(
    `Deleted orphaned reservation ${refPath}. Issue #${issue} carried no \`status:claimed\` label to remove.`,
  );

  // Step two, and unlike the ordinary release it is only ever about the
  // assignee. An issue with none needs no edit at all — issuing one anyway
  // would put a pointless entry in the issue's timeline and give this path a
  // failure mode it does not otherwise have.
  if (assignees.length > 0) {
    try {
      gh(
        "issue",
        "edit",
        issue,
        ...assignees.flatMap((login) => ["--remove-assignee", login]),
      );
    } catch (error) {
      stderr(
        `Reservation ${refPath} was deleted but #${issue} could not be unassigned (${describeError(error)}).` +
          " It is still assigned, so `claim.mjs` will refuse it. Re-run this" +
          " command: the absent reservation is now positive proof that the claim" +
          " ended, and the stale-assignee backstop will retry only the unassign.",
      );
      return EXIT.restoreFailed;
    }

    stdout(`Unassigned ${assignees.join(", ")} from #${issue}.`);
  }

  try {
    gh(
      "issue",
      "comment",
      issue,
      "--body",
      orphanExplanation({
        agentId,
        issue,
        refPath,
        evidence: assessment.evidence,
        claimedLabel: config.labels.claimed,
        reservation: "deleted",
        assignees,
      }),
    );
  } catch (error) {
    stderr(
      `Released #${issue}, but the explanation comment could not be posted (${describeError(error)}). Post it by hand.`,
    );
  }

  stdout(`RELEASED_ISSUE=${issue}`);
  stdout(`RELEASED_REF=${refPath}`);
  return EXIT.ok;
};

/**
 * @param {{
 *   argv: string[],
 *   config: {
 *     branchPrefix: string,
 *     claimRefPrefix: string,
 *     staleClaimHours: number,
 *     labels: { claimed: string, human: string },
 *   },
 *   gh: (...args: string[]) => string,
 *   git?: (args: string[], options?: { cwd?: string }) => string,
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 *   now?: () => number,
 * }} input
 * @returns {number} Process exit code.
 */
export const releaseClaim = ({
  argv,
  config,
  gh,
  git,
  stdout = console.log,
  stderr = console.error,
  now = () => Date.now(),
}) => {
  const { issue, agentId, dryRun } = parseArgs(argv);

  if (!issue || !/^\d+$/.test(issue) || !agentId) {
    stderr(USAGE);
    return EXIT.usage;
  }

  // The id lands in a comment the loop reads back, so hold it to the same shape
  // `claim.mjs` and `review.mjs` require.
  if (!SAFE_AGENT_ID.test(agentId)) {
    stderr(
      `Agent id "${agentId}" must match ${SAFE_AGENT_ID}: letters, digits, dot, underscore, and hyphen only.`,
    );
    return EXIT.usage;
  }

  const repository = JSON.parse(gh("repo", "view", "--json", "nameWithOwner"))
    .nameWithOwner;
  const view = JSON.parse(
    gh("issue", "view", issue, "--json", "state,labels,assignees,comments"),
  );

  if (view.state !== "OPEN") {
    stderr(
      `Issue #${issue} is ${String(view.state).toLowerCase()}; there is no live claim to release. Use cleanup.mjs to remove the reservation for a closed issue.`,
    );
    return EXIT.notClaimed;
  }

  /** @type {string[]} */
  const labels = view.labels.map(
    (/** @type {{ name: string }} */ label) => label.name,
  );

  // A claim release is defined only for a claimed issue. An open issue that
  // does not carry `status:claimed` while its reservation is still live —
  // `status:blocked` is the common one, but since the readiness label was removed an issue carrying no
  // label at all is equally this case — has already moved past `claim.mjs`'s
  // label state machine, so there is no `status:claimed` removal to make; only
  // the stray reservation itself is an orphan (report.mjs's `unclaimable`
  // classification). That is releasable on its own, subject to the same
  // activity proof as a normal release.
  //
  // Before the readiness label was removed a `status:ready` issue was carved out of this as the
  // "stranded" state and refused, so that `status:claimed` could be restored by
  // hand and the release stay auditable. There is no such label to carve on
  // now, and the orphan path's own explanatory comment carries the audit trail
  // the refusal was protecting.
  if (!labels.includes(config.labels.claimed)) {
    const refName = `${config.claimRefPrefix}${issue}`;
    const refPath = `refs/heads/${refName}`;
    const presence = reservationPresence(gh, repository, refName);

    if (presence.kind === "unknown") {
      stderr(
        `Refusing to release #${issue}: whether \`${refPath}\` exists could not be established (${presence.reason}). No issue state was changed.`,
      );
      return EXIT.refBlocked;
    }

    if (presence.kind === "absent") {
      const assignees = view.assignees.flatMap(
        (/** @type {{ login?: string }} */ assignee) =>
          assignee.login ? [assignee.login] : [],
      );

      return clearStaleAssignee({
        issue,
        agentId,
        refName,
        refPath,
        repository,
        assignees,
        humanLabel: labels.includes(config.labels.human)
          ? config.labels.human
          : null,
        config,
        gh,
        dryRun,
        stdout,
        stderr,
      });
    }

    return releaseOrphanedReservation({
      issue,
      agentId,
      refName,
      refPath,
      repository,
      view,
      config,
      gh,
      git,
      dryRun,
      stdout,
      stderr,
      now: now(),
    });
  }

  const assessment = assessForRelease({
    issue,
    now: now(),
    staleClaimHours: config.staleClaimHours,
    branchPrefix: config.branchPrefix,
    claim: lastClaim(view.comments),
    agentId,
    gh,
    git,
    repository,
    config,
  });

  if (assessment.kind === "unknown") {
    stderr(
      `Refusing to release #${issue}: ${assessment.reason}. A lookup that could not be established is not evidence of absence, so nothing was changed.`,
    );
    return EXIT.inconclusive;
  }

  if (assessment.kind === "active") {
    stderr(`Refusing to release #${issue}: ${assessment.reason}.`);
    return EXIT.active;
  }

  if (assessment.kind === "notStale") {
    stderr(`Refusing to release #${issue}: ${assessment.reason}.`);
    return EXIT.notStale;
  }

  const refName = `${config.claimRefPrefix}${issue}`;
  const refPath = `refs/heads/${refName}`;

  // Whether the issue stays out of the claimable pool after this release, which
  // since the readiness label was removed is a fact to *report* rather than a decision to make.
  // `needs:human` is one of the hold labels `lib/claimable.mjs` filters on, so
  // an issue carrying it is held out by that label alone — this release adds
  // nothing and withholds nothing. The comment still says so, because a reader
  // auditing a release wants to know whether the issue is claimable again and
  // the answer here is no.
  const humanLabel = labels.includes(config.labels.human)
    ? config.labels.human
    : null;

  if (dryRun) {
    stdout(
      explanation({
        agentId,
        issue,
        refPath,
        evidence: assessment.evidence,
        reservation: "planned",
        humanLabel,
      }),
    );
    stdout(`\n(dry run: nothing was deleted, edited, or commented)`);
    return EXIT.ok;
  }

  // Step one, and it is allowed to be the only step. Every abort below happens
  // before any issue mutation, which is acceptance criterion 6: losing the
  // ability to delete the ref must never produce a half-release.
  const before = reservationPresence(gh, repository, refName);

  if (before.kind === "unknown") {
    stderr(
      `Refusing to release #${issue}: whether \`${refPath}\` exists could not be established (${before.reason}). No issue state was changed.`,
    );
    return EXIT.refBlocked;
  }

  if (before.kind === "present") {
    try {
      gh("api", "--method", "DELETE", `repos/${repository}/git/${refPath}`);
    } catch (error) {
      stderr(
        `Refusing to release #${issue}: \`${refPath}\` could not be deleted (${describeError(error)}). No issue state was changed, so #${issue} still reads \`${config.labels.claimed}\` and stays visible to a janitor that can delete it.`,
      );
      return EXIT.refBlocked;
    }

    // Confirm by listing rather than by the delete's own exit status, for the
    // same reason existence is established by listing: the credential that can
    // fail a delete can also fail it unhelpfully.
    const after = reservationPresence(gh, repository, refName);

    if (after.kind !== "absent") {
      const detail =
        after.kind === "unknown" ? after.reason : "it is still listed";
      stderr(
        `Refusing to release #${issue}: the delete of \`${refPath}\` reported success but the ref could not be confirmed gone (${detail}). No issue state was changed.`,
      );
      return EXIT.refBlocked;
    }

    stdout(`Deleted reservation ${refPath}.`);
  } else {
    stdout(`Reservation ${refPath} is already absent; restoring the issue only.`);
  }

  // Step two. Clearing the assignee is mandatory: `lib/claim.mjs` filters out
  // every assigned issue, so a restore that leaves it assigned is a silent
  // no-op that returns the issue to a backlog nobody can draw from.
  /** @type {string[]} */
  const assignees = view.assignees
    .map((/** @type {{ login?: string }} */ assignee) => assignee.login)
    .filter((/** @type {string | undefined} */ login) => Boolean(login));

  try {
    gh(
      "issue",
      "edit",
      issue,
      ...assignees.flatMap((login) => ["--remove-assignee", login]),
      "--remove-label",
      config.labels.claimed,
    );
  } catch (error) {
    stderr(
      `Reservation ${refPath} was deleted but issue #${issue} could not be restored (${describeError(error)}). It still reads \`${config.labels.claimed}\`, which is the recoverable half of this failure: re-run this command to finish the release.`,
    );
    return EXIT.restoreFailed;
  }

  if (humanLabel) {
    stdout(
      `#${issue} carries \`${humanLabel}\`, so it is released but still not claimable.`,
    );
  }

  try {
    gh(
      "issue",
      "comment",
      issue,
      "--body",
      explanation({
        agentId,
        issue,
        refPath,
        evidence: assessment.evidence,
        reservation: before.kind === "present" ? "deleted" : "absent",
        humanLabel,
      }),
    );
  } catch (error) {
    // The release itself is complete and coherent. A missing explanation is a
    // record to restore by hand, not a reason to report failure.
    stderr(
      `Released #${issue}, but the explanation comment could not be posted (${describeError(error)}). Post it by hand.`,
    );
  }

  stdout(`RELEASED_ISSUE=${issue}`);
  stdout(`RELEASED_REF=${refPath}`);
  return EXIT.ok;
};

export default releaseClaim;

// The coordination-state report, with every call to `gh` and `review.mjs check`
// injected.
//
// Claim state is spread across four sources that can disagree — the
// reservation ref, the `status:*` label, the assignee, and any open pull
// request — and reading all four by hand is tedious enough that nobody does it
//. Every incident this command answers for has the same shape: a written
// note, or a single query, stood in for reading the state, and the state had
// moved.
//
// The rule this module exists to keep, copied from `lib/release-claim.mjs`
// because it is the same rule: an error, a non-array body, or a response that
// filled its page is not evidence of absence. A source that could not be read
// is reported as `unknown`, never folded into "absent", and no classification
// below is ever derived from an assumption that a failed read means nothing was
// there.
//
// The sources are not equally current, and that is its own defect class
//. `matching-refs` is the strongly-consistent git data API;
// `gh issue list` is served by the search index and lags. Where the two
// disagree in the direction only that lag can explain, this module re-reads the
// single issue with `gh issue view`, which is not search-backed, before
// classifying it — see `viewIssue`. It confirms disagreements rather than
// suppressing them: only a direct read that positively contradicts the listing
// changes an answer, and a read that could not be made leaves the issue
// reported.
//
// This command is strictly read-only. It calls `gh` only to list state and
// shells out to `review.mjs check` only in its read-only `check` mode; it never
// edits a label, an assignee, or a ref.

import {
  CLAIM,
  authorshipIssues,
  branchIssue,
  isDependabotAuthor,
  isPromotionBranch,
  linkedIssues,
  referencingPullRequests as referencingPulls,
} from "../provenance.mjs";
import { parseVerdicts } from "../verdicts.mjs";
import {
  coverage,
  PULL_REQUEST_ROLES,
  readLeases,
  summarizeLeases,
} from "./lease.mjs";
import { ISSUE_PAGE, heldBy } from "./claimable.mjs";
import { parseBlockedBy, readBlockerStates } from "./blocked-by.mjs";
import { describeLocalWork, localIssueWork } from "./local-work.mjs";
import { listing, matchingRefs, openPullRequests } from "./release-claim.mjs";

// Exit codes are a public interface, as they are for `release-claim.mjs` and
// `review.mjs`. Keep this in sync with the table in docs/AGENT_LOOP.md.
export const EXIT = {
  ok: 0,
  usage: 1,
  disagreements: 2, // at least one classified disagreement was found
  unknown: 3, // no disagreement was found, but a source could not be read
};

const HOUR_MS = 3_600_000;
const PAGE = 100;

/**
 * @template T
 * @typedef {{ ok: true, items: T[] } | { ok: false, reason: string }} Lookup
 */

/**
 * The issue number encoded in a reservation ref name, or `null` if the ref does
 * not match the configured prefix followed by nothing but digits. Reservation
 * refs carry no slug — `rallypoint-claims/issue-42`, never `…-42-a-slug` — so
 * the match is anchored at both ends, unlike `provenance.branchIssue`, which
 * only anchors the prefix because an issue branch always has a slug after it.
 *
 * @param {string | null | undefined} refName e.g. `refs/heads/rallypoint-claims/issue-42`
 * @param {string} prefix e.g. `rallypoint-claims/issue-`
 */
export const reservationIssue = (refName, prefix) => {
  const escaped = prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return (
    (refName ?? "")
      .replace(/^refs\/heads\//, "")
      .match(new RegExp(`^${escaped}(\\d+)$`))?.[1] ?? null
  );
};

/**
 * Every Rallypoint claim comment on an issue, oldest first, each carrying the
 * comment's own id as a fingerprint distinct from the agent id in its body.
 * Agent ids are self-declared and reused across sessions (`review.mjs`
 * documents the same limitation for its self-review guard), so the comment id
 * is what actually distinguishes one claiming session from another that
 * happened to pick the same id.
 *
 * @param {{ id?: string, body?: string | null, createdAt?: string, url?: string }[] | undefined} comments
 */
export const claimComments = (comments) =>
  (comments ?? []).flatMap((comment) => {
    const agent = (comment.body ?? "").match(CLAIM)?.at(1);
    return agent
      ? [
          {
            agent,
            createdAt: comment.createdAt,
            fingerprint: comment.id ?? comment.url ?? null,
          },
        ]
      : [];
  });

/**
 * The most recent claim comment. A released issue can be reclaimed, and the
 * newest claim is the one whose age and fingerprint describe the live claim.
 *
 * @param {{ id?: string, body?: string | null, createdAt?: string, url?: string }[] | undefined} comments
 */
export const lastClaimComment = (comments) => claimComments(comments).at(-1) ?? null;

/**
 * Every reservation ref under `prefix`, each resolved to the issue number it
 * encodes. A ref outside that shape (should never happen; kept defensive
 * because a listing that returns something unexpected is exactly the case this
 * module refuses to guess about) is dropped rather than reported against a
 * fabricated issue number.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {string} prefix
 * @returns {Lookup<{ ref: string, sha: string | null, issue: string }>}
 */
export const listReservationRefs = (gh, repository, prefix) => {
  const refs = matchingRefs(gh, repository, prefix);

  if (!refs.ok) return refs;

  return {
    ok: true,
    items: refs.items.flatMap((ref) => {
      const issue = reservationIssue(ref.ref, prefix);
      return issue === null
        ? []
        : [{ ref: ref.ref ?? "", sha: ref.object?.sha ?? null, issue }];
    }),
  };
};

/**
 * Open issues carrying `label`, with the fields the report needs from each.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} label
 * @returns {Lookup<{
 *   number: number,
 *   title: string,
 *   labels: { name: string }[],
 *   assignees: { login?: string }[],
 *   comments: { id?: string, body?: string | null, createdAt?: string, url?: string }[],
 * }>}
 */
export const listIssuesByLabel = (gh, label) =>
  listing(
    () =>
      gh(
        "issue",
        "list",
        "--state",
        "open",
        "--label",
        label,
        "--limit",
        String(PAGE),
        "--json",
        "number,title,labels,assignees,comments",
      ),
    `\`${label}\` issues`,
  );

/**
 * Every open issue, whatever its labels.
 *
 * The claimable pool is defined by the *absence* of a hold label and
 * `gh issue list` can only ask for labels an issue must have, so the
 * filtering happens in `lib/claimable.mjs` against this listing rather than in
 * the query. `listIssuesByLabel` above is still used for `status:claimed`,
 * which is a positive test and stays one.
 *
 * @param {(...args: string[]) => string} gh
 * @returns {Lookup<{
 *   number: number,
 *   title: string,
 *   labels: { name: string }[],
 *   assignees: { login?: string }[],
 *   comments: { id?: string, body?: string | null, createdAt?: string, url?: string }[],
 * }>}
 */
export const listOpenIssues = (gh) =>
  listing(
    () =>
      gh(
        "issue",
        "list",
        "--state",
        "open",
        "--limit",
        String(ISSUE_PAGE),
        "--json",
        "number,title,labels,assignees,comments",
      ),
    "open issues",
    // `ISSUE_PAGE`, not this module's `PAGE`: the limit truncation is judged
    // against must be the limit the query actually asked for, and this is the
    // one listing here that is not label-narrowed. Inheriting `PAGE` would have
    // put every pool classification behind a 100-issue cliff.
    ISSUE_PAGE,
  );

/**
 * Open blocked issues with bodies, which carry the Blocked-By declaration.
 * @param {(...args: string[]) => string} gh
 * @param {string} label
 * @returns {Lookup<{ number: number, labels: unknown, body?: string }>}
 */
export const listBlockedIssues = (gh, label) =>
  listing(
    () =>
      gh(
        "issue",
        "list",
        "--state",
        "open",
        "--label",
        label,
        "--limit",
        String(PAGE),
        "--json",
        "number,title,labels,body",
      ),
    `\`${label}\` issues`,
  );

/**
 * Every **open** issue that has at least one assignee, whatever its labels.
 *
 * The other issue lookups here are label-scoped, which is exactly why this one
 * is not: the state it exists to find is an assigned issue carrying
 * `status:claimed` no more than any hold label, so no label-scoped query would
 * ever return it. `--assignee "*"` is `gh`'s wildcard for "assigned to
 * anybody".
 *
 * @param {(...args: string[]) => string} gh
 * @returns {Lookup<{
 *   number: number,
 *   title: string,
 *   labels: { name: string }[],
 *   assignees: { login?: string }[],
 * }>}
 */
export const listAssignedOpenIssues = (gh) =>
  listing(
    () =>
      gh(
        "issue",
        "list",
        "--state",
        "open",
        "--assignee",
        "*",
        "--limit",
        String(PAGE),
        "--json",
        "number,title,labels,assignees",
      ),
    "assigned open issues",
  );

/**
 * One issue's live state, read directly rather than through a listing.
 *
 * **Why this exists.** Every other issue lookup in this module goes
 * through `gh issue list`, which is served by GitHub's search index and is
 * eventually consistent. `listReservationRefs` reads the git data API, which is
 * strongly consistent. `claim.mjs` creates the reservation ref *first* — that
 * ordering is the whole of its atomicity guarantee and is not negotiable
 * — and relabels the issue one `gh` round trip later. For that window, and for
 * however long the search index then lags, the two sources describe different
 * instants of the same claim: the ref is already there while the listing still
 * shows the issue unheld, already assigned, and not yet `status:claimed`.
 *
 * One healthy in-flight claim therefore trips `unclaimable`, `stranded`, and
 * `assigneeDrift` at once — three classifications, one shared premise, which is
 * that a label listing is a statement about *now*. It is not.
 *
 * `gh issue view` is not search-backed, so it settles the question the listing
 * could only guess at. It is called only for an issue a listing has *already*
 * put under suspicion, so the cost is one call per disagreement, not per issue.
 *
 * A read that fails is `ok: false` and the caller leaves the issue **reported**
 * — the module's standing rule, and the safe direction here: a real
 * disagreement that stays on the report costs a janitor one look, while a
 * suppressed one strands a reservation nobody goes looking for.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} issueNumber
 * @returns {{ ok: true, issue: LabeledIssue & { title: string } } | { ok: false, reason: string }}
 */
export const viewIssue = (gh, issueNumber) => {
  try {
    const parsed = JSON.parse(
      gh(
        "issue",
        "view",
        issueNumber,
        "--json",
        "number,title,labels,assignees,comments",
      ),
    );

    if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
      return {
        ok: false,
        reason: `\`gh issue view ${issueNumber}\` returned no issue object`,
      };
    }

    return {
      ok: true,
      issue: {
        number: Number(parsed.number ?? issueNumber),
        title: parsed.title ?? "",
        labels: Array.isArray(parsed.labels) ? parsed.labels : null,
        assignees: Array.isArray(parsed.assignees) ? parsed.assignees : [],
        comments: Array.isArray(parsed.comments) ? parsed.comments : [],
      },
    };
  } catch (error) {
    const detail =
      /** @type {{ stderr?: string, message?: string }} */ (error).stderr ??
      /** @type {{ message?: string }} */ (error).message ??
      String(error);
    return { ok: false, reason: `\`gh issue view ${issueNumber}\` failed: ${detail}` };
  }
};

/**
 * Closed issues carrying `label`. `gh issue list --label` only ANDs multiple
 * values, so a caller after every `status:*` label runs this once per label
 * and merges — `listClosedIssuesWithStatusLabels` below does exactly that.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} label
 * @returns {Lookup<{ number: number, title: string, labels: { name: string }[] }>}
 */
export const listClosedIssuesByLabel = (gh, label) =>
  listing(
    () =>
      gh(
        "issue",
        "list",
        "--state",
        "closed",
        "--label",
        label,
        "--limit",
        String(PAGE),
        "--json",
        "number,title,labels",
      ),
    `closed \`${label}\` issues`,
  );

/**
 * Every closed issue that still carries at least one of `labels`, deduplicated
 * by issue number. Each per-label query already returns the issue's full label
 * set, not just the matched label, so one entry per issue is enough to see
 * every stale `status:*` label it carries — a second query finding the same
 * issue under a different label would only repeat the same row.
 *
 * A label whose own query fails is reported as a failure rather than folded
 * into "no closed issues carry it", matching the "unknown, never absent" rule
 * the rest of this module keeps.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string[]} labels
 * @returns {{ items: { number: number, title: string, labels: { name: string }[] }[], failures: string[] }}
 */
export const listClosedIssuesWithStatusLabels = (gh, labels) => {
  /** @type {Map<number, { number: number, title: string, labels: { name: string }[] }>} */
  const byNumber = new Map();
  /** @type {string[]} */
  const failures = [];

  for (const label of labels) {
    const result = listClosedIssuesByLabel(gh, label);

    if (!result.ok) {
      failures.push(`closed \`${label}\` issues could not be listed: ${result.reason}`);
      continue;
    }

    for (const issue of result.items) byNumber.set(issue.number, issue);
  }

  return { items: [...byNumber.values()], failures };
};

// The subset of `config.labels` that are actually `status:*` labels —
// `human` (`needs:human`), `approved` (`review:approved`), and
// `mergedUnreviewed` (`merged:unreviewed`) are configured labels but not this
// family, and a closed issue is expected to keep `merged:unreviewed` and
// `review:approved` after it closes.
const STATUS_LABEL_KEYS = /** @type {const} */ ([
  "claimed",
  "blocked",
  "changesRequested",
  "deferred",
]);

/**
 * @param {{
 *   labels: {
 *     claimed: string,
 *     blocked?: string,
 *     changesRequested?: string,
 *     deferred?: string,
 *   },
 * }} config
 * @returns {string[]}
 */
export const statusLabelNames = (config) =>
  STATUS_LABEL_KEYS.flatMap((key) =>
    config.labels[key] ? [/** @type {string} */ (config.labels[key])] : [],
  );

/**
 * A pull request's reviews, normalized to the shape `verdicts.parseVerdicts`
 * reads — `verdicts.mjs` stays free of `gh` calls, so the snake_case ->
 * camelCase mapping lives at the call site here, the same as `review.mjs`
 * does for its own `check` command.
 *
 * @param {(...args: string[]) => string} gh
 * @param {string} repository
 * @param {number} pr
 * @returns {Lookup<{ body: string | null, submittedAt: string | null, commitId: string | null }>}
 */
export const pullRequestReviews = (gh, repository, pr) => {
  const raw = listing(
    () => gh("api", "--paginate", `repos/${repository}/pulls/${pr}/reviews`),
    `reviews for #${pr}`,
  );

  if (!raw.ok) return raw;

  return {
    ok: true,
    items: raw.items.map(
      (/** @type {{ body: string | null, submitted_at: string | null, commit_id: string | null }} */ review) => ({
        body: review.body,
        submittedAt: review.submitted_at,
        commitId: review.commit_id,
      }),
    ),
  };
};

/**
 * @typedef {(
 *   | "unclaimable"
 *   | "unprotected"
 *   | "stranded"
 *   | "unclaimedWithOpenPr"
 *   | "unreservedWithOpenPr"
 *   | "janitorCandidate"
 *   | "assigneeDrift"
 *   | "needsFixer"
 *   | "closedWithStatusLabel"
 *   | "wouldFailRecord"
 *   | "blockedWithClearedDependencies"
 *   | "holdWithoutReason"
 * )} DisagreementKind
 */

/**
 * `issue` is the issue this disagreement is about. `wouldFailRecord` is the one
 * kind that may have none — a pull request whose branch and body between them
 * resolve no authoring issue is exactly what it reports — and it says
 * `"unknown"` there rather than inventing one. It carries `pull` as well, since
 * the pull request number is the identifier that actually locates it; every
 * other kind omits that field.
 *
 * @typedef {{ kind: DisagreementKind, issue: string, detail: string, pull?: number }} Disagreement
 */

/**
 * @typedef {{
 *   number: number,
 *   labels?: unknown,
 *   assignees: { login?: string }[],
 *   comments: { id?: string, body?: string | null, createdAt?: string, url?: string }[],
 * }} LabeledIssue
 */

/**
 * Every open pull request that names `issueNumber`, either by its
 * `agent/<issue>-` branch name — which `claim.mjs` writes and nobody can edit
 * afterwards — or by a `Closes #<issue>` reference in its body. The predicate
 * itself lives in `provenance.mjs`, shared with `claim.mjs` and
 * `reconcile.mjs`, so this link is computed the same way here as it is by
 * `review.mjs`; this wrapper only keeps the positional call shape the
 * classifications below already read with.
 *
 * @template {{ number: number, headRefName: string, body: string | null }} Pull
 * @param {Pull[]} pulls
 * @param {string} issueNumber
 * @param {string} branchPrefix
 * @returns {Pull[]}
 */
const referencingPullRequests = (pulls, issueNumber, branchPrefix) =>
  referencingPulls({ pulls, issue: issueNumber, branchPrefix });

/**
 * Classifies every disagreement between the four sources, rather than dumping
 * raw rows. Every rule that depends on a source guards that source's `ok` flag
 * first: a source this run could not read is never treated as if it had come
 * back empty, so a classification that needs it simply does not fire, and the
 * gap is surfaced separately as `unknowns`.
 *
 * @param {{
 *   config: {
 *     labels: { claimed: string, blocked?: string, deferred?: string, human?: string },
 *     branchPrefix: string,
 *     staleClaimHours: number,
 *     integrationBranch?: string | null,
 *     promotionBranch?: string | null,
 *   },
 *   now: number,
 *   refs: Lookup<{ ref: string, sha: string | null, issue: string }>,
 *   claimed: Lookup<LabeledIssue>,
 *   openIssues: Lookup<LabeledIssue>,
 *   prs: Lookup<{ number: number, headRefName: string, headRefOid: string, body: string | null, updatedAt: string, author?: unknown }>,
 *   reviewsByPr: Map<number, Lookup<{ body: string | null, submittedAt: string | null, commitId: string | null }>> | null,
 *   closedStatus?: { items: { number: number, labels: unknown }[], failures: string[] } | null,
 *   assignedOpen?: Lookup<{ number: number, labels: unknown, assignees: { login?: string }[] }> | null,
 *   localWork?: ((issue: string) => Lookup<import("./local-work.mjs").LocalWork>) | null,
 *   confirmIssue?: ((issue: string) => ReturnType<typeof viewIssue>) | null,
 *   blocked?: Lookup<{ number: number, labels: unknown, body?: string }> | null,
 *   blockerState?: ((blockers: string[]) => Map<string, import("./blocked-by.mjs").BlockerState>) | null,
 * }} input
 */
export const classify = ({
  config,
  now,
  refs,
  claimed,
  openIssues,
  prs,
  reviewsByPr,
  closedStatus = null,
  assignedOpen = null,
  localWork = null,
  confirmIssue = null,
  blocked = null,
  blockerState = null,
}) => {
  // Every `status:claimed` issue with no open pull request behind it, whatever
  // its age. `janitorCandidate` below is the subset the age threshold has
  // already cleared, and it stays the human-facing classification; this is the
  // set a pass should *offer* to `release-claim.mjs`, which is the single
  // authority on eligibility and refuses harmlessly when a claim is not
  // releasable yet.
  //
  // The two differ, and the wider set exists for a reason. A session that
  // claims, pushes, merges, and ends inside the window leaves a claim that
  // `release-claim.mjs` now releases on settled-pull-request grounds while this
  // classifier — which reads only the claim's age — would never nominate it.
  // Duplicating the settled-branch rule here would put two copies of it in the
  // repository, which is exactly how `report.mjs` and `release-claim.mjs`
  // answers drift apart.
  /** @type {string[]} */
  const claimCandidates = [];
  // Claims this machine can prove are alive from unpushed local work, held out
  // of `janitorCandidate` below rather than asserted stale. Reported in
  // its own section: suppressing them silently would be the same dishonesty in
  // the other direction.
  /** @type {{ issue: string, detail: string }[]} */
  const localWorkHeld = [];
  /** @type {Disagreement[]} */
  const disagreements = [];
  /** @type {string[]} */
  const unknowns = [];

  if (!refs.ok) {
    unknowns.push(`reservation refs could not be listed: ${refs.reason}`);
  }
  if (!claimed.ok) {
    unknowns.push(
      `\`${config.labels.claimed}\` issues could not be listed: ${claimed.reason}`,
    );
  }
  if (!openIssues.ok) {
    unknowns.push(`open issues could not be listed: ${openIssues.reason}`);
  }
  if (!prs.ok) {
    unknowns.push(`open pull requests could not be listed: ${prs.reason}`);
  }

  const refByIssue = new Map(
    refs.ok ? refs.items.map((ref) => [ref.issue, ref]) : [],
  );
  const claimedByIssue = new Map(
    claimed.ok ? claimed.items.map((issue) => [String(issue.number), issue]) : [],
  );
  // The claimable pool, derived rather than read off a label: an open
  // issue carrying none of `status:claimed`, `status:blocked`, `status:deferred`
  // or `needs:human`. Assignees are deliberately *not* filtered here — an
  // assigned pool issue is the `assigneeDrift` classification below, and
  // dropping it from this map would delete the evidence for it.
  //
  // An issue whose labels could not be read is left out, matching
  // `isClaimable`: absent from the pool is the conservative answer, and the
  // read failure is reported as its own unknown rather than folded into a
  // classification.
  const poolByIssue = new Map(
    openIssues.ok
      ? openIssues.items.flatMap((issue) => {
          const held = heldBy(issue, config);

          if (held === null) {
            unknowns.push(
              `#${issue.number}'s labels could not be read, so whether it is ` +
                "in the claimable pool cannot be established.",
            );
            return [];
          }

          return held.length === 0
            ? [/** @type {[string, typeof issue]} */ ([String(issue.number), issue])]
            : [];
        })
      : [],
  );

  // Claims caught mid-flight: a reservation ref the strongly-consistent git
  // data API already returns, against a label listing that has not caught up
  // (see `viewIssue` for the mechanism). Held out of the three
  // classifications the lag produces, and reported in their own section — the
  // same shape `localWorkHeld` uses, because a suppression nobody can
  // see is the failure mode both of these exist to avoid.
  /** @type {{ issue: string, detail: string }[]} */
  const claimsInFlight = [];
  /** @type {Set<string>} */
  const inFlight = new Set();

  // The confirming read runs *only* where the two sources already disagree —
  // a ref with no `status:claimed` issue behind it in the listing. That is the
  // footprint of the lag and also the footprint of every genuine `unclaimable`,
  // so nothing is suppressed that the direct read did not positively contradict.
  //
  // Three outcomes, and only one of them changes an answer:
  //
  // - the direct read says `status:claimed`: the listing lagged. The issue is
  //   moved into the claimed set, which is where it actually is, so
  //   `unclaimable`, `stranded`, and `assigneeDrift` all stop firing from the
  //   one correction rather than being suppressed one at a time.
  // - the direct read agrees with the listing: a real disagreement. Untouched.
  // - the read failed, or its labels were unreadable: `unknown`, never
  //   "absent". The issue stays classified exactly as the listing said, so a
  //   confirming read this run could not make never hides a defect.
  if (confirmIssue && refs.ok && claimed.ok) {
    for (const issueNumber of refByIssue.keys()) {
      if (claimedByIssue.has(issueNumber)) continue;

      const confirmed = confirmIssue(issueNumber);

      if (!confirmed.ok) {
        unknowns.push(
          `#${issueNumber} has a live reservation and does not carry ` +
            `\`${config.labels.claimed}\` in the issue listing, but the direct ` +
            `read that would confirm it failed (${confirmed.reason}); it is ` +
            "reported below as the listing described it.",
        );
        continue;
      }

      const labels = Array.isArray(confirmed.issue.labels)
        ? confirmed.issue.labels
        : null;

      if (labels === null) {
        unknowns.push(
          `#${issueNumber}'s labels could not be read on the confirming direct ` +
            "read, so whether its reservation is orphaned or its claim merely " +
            "in flight cannot be established; it is reported below as the " +
            "listing described it.",
        );
        continue;
      }

      if (!labels.some((label) => label?.name === config.labels.claimed)) continue;

      claimedByIssue.set(issueNumber, confirmed.issue);
      poolByIssue.delete(issueNumber);
      inFlight.add(issueNumber);
      claimsInFlight.push({
        issue: issueNumber,
        detail:
          `#${issueNumber} reads unheld in the ` +
          "search-backed issue listing while its reservation " +
          `\`${refByIssue.get(issueNumber)?.ref}\` is live, but a direct ` +
          `\`gh issue view\` shows \`${config.labels.claimed}\`: the claim is in ` +
          "flight and the listing is lagging behind it. Nothing is owed. Do " +
          "not restore a label, release the reservation, or run " +
          "`release-claim.mjs` on it — a second writer on a live claim is the " +
          "exact collision the reservation ref exists to prevent.",
      });
    }
  }

  // ref with no `status:claimed` issue behind it -> unclaimable (the stranding case).
  //
  // A pool issue is skipped here because `stranded` below reports it, and the
  // two would otherwise fire together on every one of them. Since the readiness label was removed, the
  // pool is defined by the *absence* of `status:claimed`, so every stranded
  // issue is necessarily also an unclaimable one — `stranded` became a strict
  // subset rather than a sibling, and left unguarded the commonest janitor case
  // of all — an orphaned reservation — would appear twice under two headings
  // implying two different remedies.
  //
  // The split is kept rather than collapsed because the two are not equally
  // urgent. A held issue with an orphan ref is inert: the hold keeps
  // `claim.mjs` away from it regardless. A *claimable* issue with an orphan ref
  // is offered to a session and then silently skipped when the reservation
  // collides, which is the state a stranded reservation can sit in for weeks.
  if (refs.ok && claimed.ok) {
    for (const [issueNumber, ref] of refByIssue) {
      if (openIssues.ok && poolByIssue.has(issueNumber)) continue;

      if (!claimedByIssue.has(issueNumber)) {
        disagreements.push({
          kind: "unclaimable",
          issue: issueNumber,
          detail:
            `reservation \`${ref.ref}\` (${ref.sha ?? "sha unknown"}) exists ` +
            `but #${issueNumber} does not carry \`${config.labels.claimed}\`.`,
        });
      }
    }
  }

  // `status:claimed` with no ref -> unprotected: a second session could claim
  // it, since only the ref stops a second `claim.mjs` reservation.
  if (refs.ok && claimed.ok) {
    for (const issueNumber of claimedByIssue.keys()) {
      if (!refByIssue.has(issueNumber)) {
        disagreements.push({
          kind: "unprotected",
          issue: issueNumber,
          detail:
            `#${issueNumber} carries \`${config.labels.claimed}\` with no ` +
            "reservation ref; a second session could claim it.",
        });
      }
    }
  }

  // A pool issue with a live ref -> stranded: it advertises as available and
  // is silently skipped by `claim.mjs`.
  if (refs.ok && openIssues.ok) {
    for (const [issueNumber, ref] of Array.from(poolByIssue.keys()).flatMap(
      (issueNumber) =>
        refByIssue.has(issueNumber)
          ? [/** @type {[string, { ref: string }]} */ ([issueNumber, refByIssue.get(issueNumber)])]
          : [],
    )) {
      disagreements.push({
        kind: "stranded",
        issue: issueNumber,
        detail:
          `#${issueNumber} carries no hold label while reservation ` +
          `\`${ref.ref}\` is live; it advertises as claimable and is silently ` +
          "skipped.",
      });
    }
  }

  // A pool issue, an open pull request already referencing it, and no
  // reservation ref -> the work is underway but nothing reserves it.
  //
  // Every other rule misses this state. `stranded` needs a ref, and there is
  // none; `assigneeDrift` for a pool issue needs an assignee, and `claim.mjs`
  // never ran so nothing was ever assigned; `janitorCandidate` and `needsFixer`
  // iterate `claimedByIssue` only, so an issue that was never claimed is outside
  // their loops entirely. It is the one place the claimable pool and the open
  // pull request list disagree with nothing in between them to notice.
  //
  // Two different states satisfy that condition, and they take opposite
  // recoveries. The claim comment is what separates them, and the
  // listing already carries `comments`, so the answer is in hand right here:
  //
  // - No claim comment: nothing ever ran `claim.mjs` for this issue. It costs
  //   twice — `claim.mjs` can still hand the issue to a second session, because
  //   only a ref stops a second reservation, and `review.mjs record` refuses the
  //   resulting pull request with exit `2` for want of a claim comment on the
  //   linked issue. `rallypoint:reconcile` backfills the comment; that is
  //   `unclaimedWithOpenPr`.
  // - A claim comment present: only the reservation ref is missing, which is
  //   what a `release-claim` on an issue whose pull request outlived the release
  //   leaves behind. Authorship resolves, so `review.mjs record` is unaffected,
  //   and `rallypoint:reconcile` refuses this shape outright with its own exit
  //   `2` ("already has a claim comment") — the recovery the single old
  //   classification recommended could therefore never succeed here. That is
  //   `unreservedWithOpenPr`, and it is benign; see its detail below.
  if (refs.ok && openIssues.ok && prs.ok) {
    for (const [issueNumber, issue] of poolByIssue) {
      // A ref here already reports as `stranded`; the same issue must not be
      // counted under two kinds.
      if (refByIssue.has(issueNumber)) continue;

      const referencing = referencingPullRequests(
        prs.items,
        issueNumber,
        config.branchPrefix,
      );

      if (referencing.length === 0) continue;

      const pulls = referencing.map((pull) => `#${pull.number}`).join(", ");
      const claim = lastClaimComment(issue.comments);

      disagreements.push(
        claim
          ? {
              kind: "unreservedWithOpenPr",
              issue: issueNumber,
              detail:
                `#${issueNumber} is claimable with no reservation ` +
                `ref while pull request ${pulls} already references it, but its claim ` +
                `comment (\`${claim.agent}\`) is intact, so authorship resolves and ` +
                "`review.mjs record` is unaffected. Only the reservation ref is " +
                "missing. `rallypoint:reconcile` does not apply — it refuses an issue " +
                "that already carries a claim comment with its own exit 2. No janitor " +
                "action: nothing re-creates a reservation ref, and this state clears " +
                `itself when ${pulls} merges. \`claim.mjs\`'s open-pull-request filter ` +
                " keeps the issue from being handed to a second session " +
                'until then (docs/AGENT_LOOP.md, "Coordination-state report").',
            }
          : {
              kind: "unclaimedWithOpenPr",
              issue: issueNumber,
              detail:
                `#${issueNumber} is claimable with no reservation ` +
                `ref and no claim comment while pull request ${pulls} already ` +
                "references it, so `review.mjs record` will refuse the branch with " +
                "exit 2 for want of one. Recover with " +
                `\`node .rallypoint/scripts/reconcile.mjs --issue ${issueNumber} ` +
                "--agent-id <authoring-session-id>` (docs/AGENT_LOOP.md, " +
                '"Reconciling a missing claim comment").',
            },
      );
    }
  }

  // An open pull request `review.mjs record` would refuse outright.
  //
  // The two classifications above start from an *issue* and ask what the pull
  // request queue says about it, so a pull request that resolves no issue at
  // all is outside both loops by construction — there is no issue to iterate
  // from. That is exactly the shape that costs the most: a reviewer reads the
  // whole diff, forms a verdict, and only then discovers `record` has nowhere
  // to put it. `docs/AGENT_LOOP.md` named this a known gap until this rule
  // closed it.
  //
  // The judgement is `authorshipIssues` from `provenance.mjs` — the function
  // `record`'s own refusal gate calls (`review.mjs:503`), so this predicts the
  // refusal rather than approximating it. Deliberately **not**
  // `recordableIssue`: `record` calls that one only to pick the issue a label
  // is reconciled onto, where a null result is tolerated rather than refused.
  // So `recordableIssue`'s third reason, `ambiguous-body` — a branchless pull
  // request whose body closes several issues — is a shape `record` accepts,
  // and is exactly the multi-issue pull request the loop deliberately made
  // reviewable. Flagging it would withhold a reviewer from the one shape that
  // change was made to stop stranding.
  //
  // It reads only the branch name and the body, which the pull request listing
  // already carries, so no extra network call is made and `--skip-pr-checks`
  // does not suppress it. That also bounds what it can prove: `record` refuses
  // a third way, when no referenced issue carries a claim comment
  // (`review.mjs:524`), which needs the issue's comments and is invisible
  // here. Silence from this rule is not a promise that `record` will accept.
  //
  // Two pull request shapes legitimately resolve no issue and are not defects:
  //
  // - A **promotion** (`release` -> `staging`, `staging` -> `main`). Nobody
  //   runs `claim.mjs` against one, and `record` has its own path for it
  //.
  // - A **Dependabot** pull request, which has no authoring agent session at
  //   all. Recognised by authorship rather than by branch name, for the
  //   reason `provenance.mjs` gives: a branch name is not proof of authorship.
  //   An `author` this run could not read is reported as unknown rather than
  //   assumed human — assuming would flag every Dependabot pull request on a
  //   transport that does not return the field.
  if (prs.ok) {
    for (const pull of prs.items) {
      // No snapshot-promotion evidence is passed. This summariser is a
      // pure function over already-fetched lookups and holds no transport, so
      // containment cannot be established here, and the fail-closed rule then
      // withholds the exemption. The cost is one advisory "resolves no
      // authoring issue" line against an open snapshot promotion — noise on a
      // report, not a gate: nothing here labels, merges, or refuses anything.
      // Threading a transport into this function to remove that line is a
      // larger change than the defect warrants and is not folded in here.
      if (isPromotionBranch(pull.headRefName, config)) continue;

      const authorship = authorshipIssues({
        linkedIssues: linkedIssues(pull.body),
        branchIssue: branchIssue(pull.headRefName, config.branchPrefix),
      });

      // Asked first, and only then is the author consulted: a pull request
      // `record` would accept needs no exemption, so an unreadable author on
      // one of those is not a gap in this run's knowledge and reporting it
      // would be noise on every healthy pull request.
      if (authorship.ok) continue;

      if (pull.author === undefined) {
        unknowns.push(
          `#${pull.number} (${pull.headRefName}) resolves no authoring issue, ` +
            "but its author could not be read, so whether that is a defect or " +
            "a Dependabot pull request — which legitimately has none — " +
            "cannot be established.",
        );
        continue;
      }

      if (isDependabotAuthor(pull.author)) continue;

      const branch = branchIssue(pull.headRefName, config.branchPrefix);

      disagreements.push({
        kind: "wouldFailRecord",
        issue: branch ?? "unknown",
        pull: pull.number,
        detail:
          `pull request #${pull.number} (${pull.headRefName}) resolves no ` +
          `authoring issue (\`${authorship.reason}\`), so \`review.mjs record\` ` +
          "will refuse a verdict on it and a reviewer's pass is wasted. " +
          (authorship.reason === "mismatch"
            ? `Its branch names #${branch} while its body's closing keywords ` +
              `point only at ${linkedIssues(pull.body)
                .map((issue) => `#${issue}`)
                .join(", ")}; add \`Closes #${branch}\` to the body.`
            : "Neither its branch name nor a closing keyword in its body " +
              "names an issue; a branch cannot be renamed after the pull " +
              "request is open, so recovering this means adding a " +
              "`Closes #<issue>` line to the body."),
      });
    }
  }

  // `status:claimed` with the assignee cleared, or a claimable issue still
  // assigned -> the silent no-op `claim.mjs` filters candidates on.
  if (claimed.ok) {
    for (const [issueNumber, issue] of claimedByIssue) {
      if (issue.assignees.length === 0) {
        disagreements.push({
          kind: "assigneeDrift",
          issue: issueNumber,
          detail: `#${issueNumber} carries \`${config.labels.claimed}\` with no assignee.`,
        });
      }
    }
  }
  if (openIssues.ok) {
    for (const [issueNumber, issue] of poolByIssue) {
      if (issue.assignees.length > 0) {
        disagreements.push({
          kind: "assigneeDrift",
          issue: issueNumber,
          detail:
            `#${issueNumber} carries no hold label but is still assigned; ` +
            "`claim.mjs` filters every assigned issue out of the pool, so it " +
            "reads as claimable on the board and is invisible to a claim attempt.",
        });
      }
    }
  }

  // The same trap, on an issue a hold label keeps out of the pool. The
  // two rules above read the `status:claimed` set and the claimable pool, so an
  // assigned open issue in neither — one carrying `status:blocked`,
  // `status:deferred` or `needs:human` — is outside both loops, and that is a
  // state the loop reaches by two ordinary routes, not by corruption:
  //
  // - A **reopened** issue. Closing never clears the assignee — that is the norm
  //   and not worth repairing at close time, since it records who did the work.
  //   Reopening one hands back an open, assigned, unreserved issue.
  // - A **worker standing down**, which `worker.md` tells it to do by moving the
  //   issue to `status:blocked` + `needs:human` and releasing its reservation.
  //   That release used to leave the assignee behind, and issues in this state
  //   accumulate quietly.
  //
  // Nothing is refused while the issue sits here, because the hold label keeps
  // `claim.mjs` away from it regardless. It springs when somebody clears the
  // hold: the issue then reads as free on every board while every claim attempt
  // passes over it as somebody's work in progress. An issue can sit like that for
  // weeks. Since the readiness label was removed, clearing a hold is the *only*
  // step needed to make an
  // issue claimable — there is no second label to add, so no second moment at
  // which a person might notice the stale assignee.
  //
  // Reported, never repaired — clearing an assignee is a statement about whose
  // work an issue is, which is the one thing this module must not decide.
  if (assignedOpen) {
    if (!assignedOpen.ok) {
      unknowns.push(
        `assigned open issues could not be listed: ${assignedOpen.reason}. ` +
          `An issue assigned while carrying neither \`${config.labels.claimed}\` ` +
          "nor a hold label cannot be detected this run.",
      );
    } else {
      for (const issue of assignedOpen.items) {
        const issueNumber = String(issue.number);

        // This listing is search-backed too, so a claim confirmed in flight
        // above can arrive here still wearing its pre-claim labels. Its
        // assignee is the one `claim.mjs` has just set.
        if (inFlight.has(issueNumber)) continue;

        const labels = Array.isArray(issue.labels) ? issue.labels : null;

        if (labels === null) {
          unknowns.push(
            `#${issueNumber} is assigned, but its labels could not be read, so ` +
              "whether its assignee is stale cannot be established.",
          );
          continue;
        }

        const names = labels.map((label) => label?.name);

        // `status:claimed` + assigned is the healthy state this whole protocol
        // aims at. A *pool* issue that is assigned is the rule directly above;
        // firing here too would report one issue twice for one assignee.
        if (names.includes(config.labels.claimed)) continue;
        if (poolByIssue.has(issueNumber)) continue;

        const logins = issue.assignees
          .flatMap((assignee) => (assignee.login ? [assignee.login] : []))
          .map((login) => `\`${login}\``);

        disagreements.push({
          kind: "assigneeDrift",
          issue: issueNumber,
          detail:
            `#${issueNumber} is assigned (${logins.join(", ") || "assignee login unreadable"}) ` +
            `while carrying neither \`${config.labels.claimed}\` nor any hold ` +
            "label this report could read, so the assignee outlived the claim " +
            "that set it. Nothing is refused today — but clear the hold and " +
            "this issue advertises as free while every claim attempt passes " +
            "over it as somebody's work in progress.",
        });
      }
    }
  }

  // `status:claimed`, no open pull request, older than `staleClaimHours` ->
  // janitor candidate, with the evidence attached. A claim comment this run
  // cannot read or cannot age is reported as unknown, never folded into "not a
  // candidate".
  if (claimed.ok && prs.ok) {
    for (const [issueNumber, issue] of claimedByIssue) {
      const referencing = referencingPullRequests(
        prs.items,
        issueNumber,
        config.branchPrefix,
      );

      if (referencing.length > 0) continue;

      // A claim confirmed in flight seconds ago is the one thing this set must
      // not contain. `janitor-pass.mjs` offers every `claimCandidate` to
      // `release-claim.mjs`, and today only incidental refusals — no claim
      // comment yet, or an age under `staleClaimHours` — stand between that
      // offer and a released live claim. Neither of them knows a claim is in
      // flight; this does. It is also why the confirming read moves the
      // issue into the claimed set rather than merely dropping three
      // classifications: moving it without this would trade one wrong answer
      // for a worse one.
      if (inFlight.has(issueNumber)) continue;

      claimCandidates.push(issueNumber);

      const claim = lastClaimComment(issue.comments);

      if (!claim) {
        unknowns.push(
          `#${issueNumber} carries \`${config.labels.claimed}\` with no ` +
            "Rallypoint claim comment, so its claim age cannot be established.",
        );
        continue;
      }

      const claimedAt = Date.parse(claim.createdAt ?? "");

      if (Number.isNaN(claimedAt)) {
        unknowns.push(
          `#${issueNumber}'s claim comment has an unreadable timestamp ` +
            `(${claim.createdAt}).`,
        );
        continue;
      }

      const ageHours = (now - claimedAt) / HOUR_MS;

      if (ageHours <= config.staleClaimHours) continue;

      // Neither input above can see a session that has not pushed yet, and on
      // this repository that is most of a session's life. Where local
      // evidence is available it decides, and where it is not the wording says
      // so rather than asserting a staleness this classifier cannot establish.
      const local = localWork ? localWork(issueNumber) : null;

      if (local && local.ok && local.items.length > 0) {
        localWorkHeld.push({
          issue: issueNumber,
          detail:
            `#${issueNumber} claimed by \`${claim.agent}\` at ${claim.createdAt} ` +
            `(${ageHours.toFixed(1)}h ago) with no open pull request, but ` +
            `${describeLocalWork(local.items, issueNumber)}.`,
        });
        continue;
      }

      const liveness =
        local === null
          ? "This run read no local worktrees, so whether a session is running was not established."
          : local.ok
            ? "No worktree on this machine holds unpushed work for it; a session on another host is not visible to this check."
            : `Local worktrees could not be read (${local.reason}), so whether a session is running was not established.`;

      disagreements.push({
        kind: "janitorCandidate",
        issue: issueNumber,
        detail:
          `#${issueNumber} claimed by \`${claim.agent}\` at ${claim.createdAt} ` +
          `(${ageHours.toFixed(1)}h ago); no open pull request references it, ` +
          `past the ${config.staleClaimHours}h staleClaimHours threshold. ` +
          `${liveness} \`release-claim.mjs\` is the authority on whether it may be released.`,
      });
    }
  }

  // `status:claimed` with an open pull request whose latest verdict at its
  // current head is `request-changes` -> needs a fixer. A verdict is bound to
  // the head SHA it was recorded against (`review.mjs`, `verdicts.mjs`), so
  // filtering to `entry.sha === pull.headRefOid` already establishes "no push
  // since that review" — a push moves the head and the old verdict no longer
  // matches it. `reviewsByPr` is `null` when the caller skipped the per-PR
  // network pass (`--skip-pr-checks`); this classification simply does not run
  // then, the same as `summarizePullRequests` is skipped.
  if (claimed.ok && prs.ok && reviewsByPr) {
    for (const issueNumber of claimedByIssue.keys()) {
      const referencing = referencingPullRequests(
        prs.items,
        issueNumber,
        config.branchPrefix,
      );

      for (const pull of referencing) {
        const reviews = reviewsByPr.get(pull.number);

        if (!reviews) {
          unknowns.push(
            `#${pull.number}'s reviews were not fetched, so whether #${issueNumber} ` +
              "needs a fixer cannot be established.",
          );
          continue;
        }

        if (!reviews.ok) {
          unknowns.push(
            `#${pull.number}'s reviews could not be listed: ${reviews.reason}`,
          );
          continue;
        }

        const latest = parseVerdicts(reviews.items)
          .filter((entry) => entry.sha === pull.headRefOid)
          .at(-1);

        if (latest?.verdict === "request-changes") {
          disagreements.push({
            kind: "needsFixer",
            issue: issueNumber,
            detail:
              `#${issueNumber} (PR #${pull.number}) has a request-changes verdict ` +
              `from \`${latest.reviewer}\` at \`${pull.headRefOid.slice(0, 7)}\` and ` +
              "no push since; it is claimed but nobody is working the fix.",
          });
        }
      }
    }
  }

  // A closed issue still carrying a `status:*` label — nothing in the loop
  // above ever looks at closed issues, since every other classification reads
  // `gh issue list --state open` (`listIssuesByLabel`). An issue that closes natively when its pull request
  // merges with a `Closes #<issue>` keyword can keep a stale status label: `report.mjs`'s own survey never fetches a closed issue, so
  // it structurally could not have landed in any of the classifications above,
  // and no other script touches a label left on an issue that was never
  // claimed through the protocol (`close-referenced-issues.mjs` only reacts to
  // `status:claimed`, which such an issue never carried). Reported, and repairable with
  // `clear-status-labels.mjs`, which this classification's detail names.
  if (closedStatus) {
    for (const reason of closedStatus.failures) unknowns.push(reason);

    for (const issue of closedStatus.items) {
      const labels = Array.isArray(issue.labels) ? issue.labels : null;

      if (labels === null) {
        unknowns.push(
          `#${issue.number}'s labels could not be read, so whether it carries ` +
            "a stale status:* label after closing cannot be established.",
        );
        continue;
      }

      const stale = labels.flatMap((label) =>
        typeof label?.name === "string" && label.name.startsWith("status:")
          ? [label.name]
          : [],
      );

      if (stale.length === 0) continue;

      const issueNumber = String(issue.number);

      disagreements.push({
        kind: "closedWithStatusLabel",
        issue: issueNumber,
        detail:
          `#${issueNumber} is closed but still carries ${stale.map((name) => `\`${name}\``).join(", ")}; ` +
          "nothing clears a status label off an issue that closed without passing through the claim " +
          `protocol. Clear it with \`node .rallypoint/scripts/clear-status-labels.mjs --issue ${issueNumber}\`.`,
      });
    }
  }

  if (blocked) {
    if (!blocked.ok) {
      unknowns.push(
        `\`${config.labels.blocked}\` issues could not be listed: ${blocked.reason}. Whether any cleared dependency remains held cannot be established this run.`,
      );
    } else {
      for (const issue of blocked.items) {
        const issueNumber = String(issue.number);
        const declaration = parseBlockedBy(issue.body);

        if (declaration.kind === "absent") {
          disagreements.push({
            kind: "holdWithoutReason",
            issue: issueNumber,
            detail: `#${issueNumber} carries \`${config.labels.blocked}\` with no \`Blocked-By:\` trailer. Add the dependency trailer, or use \`${config.labels.deferred ?? "status:deferred"}\` for a deliberate hold that does not clear automatically.`,
          });
          continue;
        }
        if (declaration.kind === "unparseable") {
          unknowns.push(
            `#${issueNumber}'s \`Blocked-By:\` trailer could not be parsed — ${declaration.reason}. The line reads \`${declaration.line}\`; no writer will touch it until corrected.`,
          );
          continue;
        }

        const states = blockerState ? blockerState(declaration.blockers) : new Map();
        const unreadable = declaration.blockers.filter(
          (blocker) => (states.get(blocker)?.state ?? "unknown") === "unknown",
        );
        if (unreadable.length > 0) {
          unknowns.push(
            `#${issueNumber}'s blockers could not all be read (${unreadable.map((blocker) => `#${blocker}`).join(", ")}), so whether its dependencies cleared cannot be established.`,
          );
          continue;
        }
        if (declaration.blockers.some((blocker) => states.get(blocker)?.state !== "CLOSED")) continue;

        const labels = Array.isArray(issue.labels)
          ? issue.labels.map((label) => label?.name)
          : [];
        const human = config.labels.human && labels.includes(config.labels.human);
        disagreements.push({
          kind: "blockedWithClearedDependencies",
          issue: issueNumber,
          detail:
            `#${issueNumber} remains \`${config.labels.blocked}\` although ${declaration.blockers.map((blocker) => `#${blocker}`).join(", ")} ${declaration.blockers.length === 1 ? "is" : "are"} closed. ` +
            (human
              ? `It also carries \`${config.labels.human}\`, which vetoes automatic removal; the operator holding it must decide.`
              : `Run \`node .rallypoint/scripts/unblock-cleared.mjs --issue ${issueNumber}\`; removing the hold makes it claimable by the derived-pool rule.`),
        });
      }
    }
  }

  if (openIssues.ok && config.labels.deferred) {
    for (const issue of openIssues.items) {
      const labels = Array.isArray(issue.labels) ? issue.labels.map((label) => label?.name) : [];
      if (!labels.includes(config.labels.deferred)) continue;
      if (Array.isArray(issue.comments) && issue.comments.length > 0) continue;
      disagreements.push({
        kind: "holdWithoutReason",
        issue: String(issue.number),
        detail: `#${issue.number} carries \`${config.labels.deferred}\` with no comment recording the deliberate hold. Record the condition, or remove the hold label if nothing blocks the issue.`,
      });
    }
  }

  return {
    disagreements,
    unknowns,
    refByIssue,
    claimedByIssue,
    poolByIssue,
    claimCandidates,
    localWorkHeld,
    claimsInFlight,
  };
};

// `review.mjs check`'s own documented exit codes (docs/AGENT_LOOP.md). `1` is a
// usage error from this report's own invocation, not a verdict about the pull
// request, and is reported plainly rather than folded into a meaning about the
// PR. Codes `2`, `3`, `9`, and `12` belong to `record`, not `check`, and never
// appear here; an undocumented code is reported as such rather than guessed at.
//
// This is a *consumer* of `REVIEW_EXIT_CODES` in `review-exit-codes.mjs`, which
// is the single authority. The wording here is deliberately its own:
// this table is read by an orchestrator deciding whether to dispatch a merger,
// so it phrases each code as a board state in a few words, where
// A merge audit would phrase the same code as an after-the-fact judgement on a
// merge. What is derived from the authority is
// exhaustiveness, never the strings — `report.test.mjs` asserts that every code
// `check` can answer about a pull request's review state is mapped here, so a
// new code cannot reach this consumer's `undocumented exit code` fallback the
// way a previously unmapped code did. Add a new code to `review-exit-codes.mjs`; the suite
// will then require a line here.
/** @type {Record<number, string>} */
export const CHECK_MEANINGS = {
  0: "approved at head, waiting to merge",
  1: "usage error calling review.mjs check",
  4: "stale review:approved label left in place (rerun with --strip-stale)",
  5: "no approve verdict at head",
  6: "the approve at head came from the branch author",
  7: "branch author unidentifiable; independence cannot be established",
  8: "hand-recorded verdict at head this script cannot read",
  // No verdict recorded at this exact head, but the branch's own
  // contribution to the integration branch is provably unchanged since an
  // earlier verdict — the push only merged the integration branch in. `10`
  // is mergeable, the same as `0`; a survey should report it as waiting to
  // merge, not as "revised, awaiting re-review". `11` is the same proof for
  // a request-changes verdict: not mergeable, but distinct from `5` because
  // the feedback was seen and never addressed, which is exactly the signal
  // this classification exists to preserve — see docs/AGENT_LOOP.md,
  // "Carried verdicts".
  10: "approved at an earlier head; carries forward, waiting to merge",
  11: "request-changes carries forward from an earlier head; unaddressed, not unreviewed",
  // A contested approve. Mergeable, exactly like
  // `0` — `merger.md`'s table says "Merge exactly like `0`" — so a survey must
  // not report it as an unknown state. It says so rather than reading as a
  // plain `0` because an orchestrator deciding whether to dispatch a merger
  // wants to know the approve overrode a dissent on the record.
  13: "approved at head over an explicitly superseded dissent; mergeable, waiting to merge",
};

/**
 * @typedef {{ number: number, headRefName: string, code: number | null, meaning: string, output: string }} PullRequestCheck
 */

/**
 * @typedef {(
 *   | { known: true, results: PullRequestCheck[] }
 *   | { known: false, reason: string, skipped?: boolean }
 * )} PullRequestSummary
 */

/**
 * Runs `review.mjs check` for every open pull request and summarizes its exit
 * code. `checkPullRequest` is injected so tests never shell out, and a run this
 * command could not launch or interpret reports `code: null` rather than being
 * folded into any documented meaning.
 *
 * @param {{
 *   prs: Lookup<{ number: number, headRefName: string }>,
 *   checkPullRequest: (pr: number) => { code: number | null, output: string },
 * }} input
 * @returns {PullRequestSummary}
 */
export const summarizePullRequests = ({ prs, checkPullRequest }) => {
  if (!prs.ok) {
    return { known: false, reason: prs.reason };
  }

  const results = prs.items.map((pull) => {
    const { code, output } = checkPullRequest(pull.number);
    return {
      number: pull.number,
      headRefName: pull.headRefName,
      code,
      meaning:
        code === null
          ? "review.mjs check could not be run"
          : (CHECK_MEANINGS[code] ?? `undocumented exit code ${code}`),
      output,
    };
  });

  return { known: true, results };
};

/**
 * @typedef {import("./lease.mjs").SummarizedLease} SummarizedLease
 */

/**
 * @typedef {(
 *   | { known: true, items: SummarizedLease[] }
 *   | { known: false, reason: string }
 * )} LeaseSummary
 */

/**
 * Every reason a lease could not be read, phrased for the `unknowns` list.
 *
 * A lease the report could not interpret is not a free target and is not a
 * disagreement either — it is a source that could not be established, which is
 * the third state this command has always kept. The orchestrator's rule for it
 * is the same as for every other `unknown`: say so in the round's reasoning
 * rather than recommending through it.
 *
 * @param {LeaseSummary} summary
 */
export const leaseUnknowns = (summary) =>
  summary.known
    ? summary.items.flatMap((item) =>
        item.state.kind === "unknown" ? [item.state.reason] : [],
      )
    : [`session leases could not be listed: ${summary.reason}`];

/**
 * The session-lease section: what has already been dispatched, per open pull
 * request and per targetless role.
 *
 * This is what closes the orchestrator's blind interval. A pull request needing a reviewer and a
 * pull request already covered by a live reviewer lease look identical in every
 * other section of this report — the verdict has not landed yet in either case —
 * so a second orchestrator surveying the same board recommends the same session
 * again unless it can read this.
 *
 * @param {{ leases: LeaseSummary, prs: Lookup<{ number: number, headRefName: string }> }} input
 */
export const formatLeases = ({ leases, prs }) => {
  /** @type {string[]} */
  const lines = [];

  if (!leases.known) {
    lines.push(`Unknown: ${leases.reason}`);
    lines.push("");
    lines.push(
      "Not a clear namespace. Treat every target below as unknown rather than free.",
    );
    return lines;
  }

  if (leases.items.length === 0) {
    lines.push("No session leases exist; nothing has been dispatched.");
  } else {
    for (const item of leases.items) {
      lines.push(
        `- ${item.refPath}: ${
          item.state.kind === "unknown"
            ? `unknown — ${item.state.reason}`
            : `${item.state.kind} — ${item.state.detail}`
        }`,
      );
    }
  }

  lines.push("");
  lines.push("### Live coverage per open pull request");
  lines.push("");

  if (!prs.ok) {
    lines.push(`Unknown: ${prs.reason}`);
    return lines;
  }

  if (prs.items.length === 0) {
    lines.push("No open pull requests.");
    return lines;
  }

  for (const pull of prs.items) {
    // `coverage` is the same function the orchestrator's condition reads, so
    // this line and that decision cannot drift apart. It reports `covered` only
    // for a live lease at the current head, `free` for absent or stale, and
    // `unknown` for a lease that exists but could not be read — including an
    // unreadable one, which is matched by ref name rather than dropped. An
    // unreadable lease reported as `free` would be exactly the fold this
    // command refuses everywhere else.
    const covered = PULL_REQUEST_ROLES.map((role) => {
      const state = coverage({ summary: leases, pr: String(pull.number), role });
      return `${role}=${state.kind}`;
    });

    lines.push(`- #${pull.number} (${pull.headRefName}): ${covered.join(", ")}`);
  }

  return lines;
};

const USAGE = "Usage: report.mjs [--skip-pr-checks] [--json]";

/**
 * `--json` prints the same survey as a machine-readable object instead of
 * prose, so `janitor-pass.mjs` can act on the classifications rather than
 * re-deriving them by parsing the prose back out. It changes the output format
 * only: the same sources are read, the same classifications made, and the same
 * exit code returned, so it stays as read-only as the prose form.
 *
 * @param {string[]} argv
 */
export const parseArgs = (argv) => {
  const skipPrChecks = argv.includes("--skip-pr-checks");
  const json = argv.includes("--json");
  const unknown = argv.filter(
    (value) => value !== "--skip-pr-checks" && value !== "--json",
  );
  return { skipPrChecks, json, ok: unknown.length === 0 };
};

/** @param {Disagreement[]} disagreements */
const groupByKind = (disagreements) => {
  /** @type {Map<DisagreementKind, Disagreement[]>} */
  const groups = new Map();
  for (const item of disagreements) {
    const list = groups.get(item.kind) ?? [];
    list.push(item);
    groups.set(item.kind, list);
  }
  return groups;
};

const KIND_TITLES = {
  unclaimable: "Unclaimable reservations (ref with no status:claimed issue)",
  unprotected: "Unprotected claims (status:claimed with no reservation ref)",
  stranded:
    "Stranded claimable issues (no hold label, with a live reservation)",
  unclaimedWithOpenPr:
    "Unclaimed work in flight (claimable, an open pull request, no reservation ref, no claim comment)",
  unreservedWithOpenPr:
    "Unreserved work in flight, benign (claimable, an open pull request, no reservation ref, claim comment intact)",
  janitorCandidate:
    "Janitor candidates (claim past staleClaimHours, no open pull request, no local evidence of a live session — liveness is not established here; release-claim.mjs decides)",
  assigneeDrift: "Assignee drift (status vs. assignee disagree)",
  needsFixer: "Needs a fixer (request-changes verdict, no push since)",
  closedWithStatusLabel:
    "Closed issues with a stale status:* label (closed without clearing it)",
  wouldFailRecord:
    "Unreviewable pull requests (review.mjs record would refuse the verdict — do not spend a review pass before fixing the body)",
  blockedWithClearedDependencies:
    "Blocked behind a dependency that has already cleared",
  holdWithoutReason:
    "Held with nothing recorded to act on",
};

/**
 * Composes the full text report from every section already computed. Kept
 * separate from `report` so the text shape can be asserted in isolation.
 *
 * @param {{
 *   disagreements: Disagreement[],
 *   unknowns: string[],
 *   refByIssue: Map<string, { ref: string, sha: string | null }>,
 *   claimedByIssue: Map<string, LabeledIssue>,
 *   poolByIssue?: Map<string, LabeledIssue> | null,
 *   prSummary: PullRequestSummary,
 *   leases: LeaseSummary,
 *   prs: Lookup<{ number: number, headRefName: string }>,
 *   localWorkHeld?: { issue: string, detail: string }[],
 *   claimsInFlight?: { issue: string, detail: string }[],
 * }} input
 */
export const formatReport = ({
  disagreements,
  unknowns,
  refByIssue,
  claimedByIssue,
  poolByIssue = null,
  prSummary,
  leases,
  prs,
  localWorkHeld = [],
  claimsInFlight = [],
}) => {
  /** @type {string[]} */
  const lines = [];

  lines.push("## Coordination state");
  lines.push("");
  if (refByIssue.size === 0 && claimedByIssue.size === 0) {
    lines.push("No reservation refs and no status:claimed issues.");
  } else {
    const issues = new Set([...refByIssue.keys(), ...claimedByIssue.keys()]);
    for (const issueNumber of [...issues].sort((a, b) => Number(a) - Number(b))) {
      const ref = refByIssue.get(issueNumber);
      const issue = claimedByIssue.get(issueNumber);
      const claim = issue ? lastClaimComment(issue.comments) : null;
      const assignees = issue
        ? issue.assignees.map((a) => a.login).filter(Boolean).join(", ") || "none"
        : "n/a";
      lines.push(
        `- #${issueNumber}: ref=${ref ? `${ref.ref}@${ref.sha ?? "?"}` : "none"}, ` +
          `status:claimed=${issue ? "yes" : "no"}, assignee=${assignees}, ` +
          `claim=${claim ? `${claim.agent} (${claim.fingerprint ?? "no fingerprint"})` : "none"}`,
      );
    }
  }

  lines.push("");
  lines.push("## Disagreements");
  lines.push("");
  if (disagreements.length === 0) {
    lines.push("None found.");
  } else {
    const groups = groupByKind(disagreements);
    for (const [kind, items] of groups) {
      lines.push(`### ${KIND_TITLES[kind] ?? kind}`);
      for (const item of items) lines.push(`- ${item.detail}`);
      lines.push("");
    }
  }

  lines.push("## Claims in flight (confirmed live by a direct read)");
  lines.push("");
  if (claimsInFlight.length === 0) {
    lines.push(
      "None. Every reservation with no `status:claimed` issue behind it in the " +
        "listing was confirmed against a direct read, or the confirming read " +
        'itself failed and is named under "Unreadable sources".',
    );
  } else {
    lines.push(
      "The issue listing is search-backed and lags; these were re-read " +
        "directly and carry `status:claimed` right now. Nothing is owed on " +
        "them and no janitor command applies:",
    );
    for (const item of claimsInFlight) lines.push(`- ${item.detail}`);
  }

  lines.push("");
  lines.push("## Live local work (held out of the janitor candidates)");
  lines.push("");
  if (localWorkHeld.length === 0) {
    lines.push(
      "None on this machine. This section only ever sees the host this ran on \u2014 " +
        "a session holding unpushed commits elsewhere is invisible here.",
    );
  } else {
    lines.push(
      "Past `staleClaimHours` with no open pull request, but provably alive: " +
        "do not release these.",
    );
    for (const item of localWorkHeld) lines.push(`- ${item.detail}`);
  }

  lines.push("");
  lines.push("## Unreadable sources");
  lines.push("");
  lines.push(
    unknowns.length === 0
      ? "None. Every source above was established, not assumed."
      : "Reported as unknown, never as absent:",
  );
  for (const reason of unknowns) lines.push(`- ${reason}`);

  // The claimable pool, printed rather than left for the reader to re-derive.
  //
  // `readyBacklog` and its min/max range went with `status:ready`, and
  // the first draft of that change printed nothing in their place — which sent
  // `orchestrator.md` to a hand-run `gh` query for the number it sizes worker
  // rounds from. A hand query is a second implementation of the pool rule, and
  // it can disagree with `claim.mjs`; re-deriving by hand is precisely the
  // drift `lib/claimable.mjs` exists to remove. No range is applied — how many
  // sessions the queue can absorb is a judgement `maxOpenPullRequests` bounds,
  // not a property of the backlog's depth.
  lines.push("");
  lines.push("## Claimable pool");
  lines.push("");

  if (poolByIssue === null) {
    lines.push(
      "Unknown: the open-issue listing could not be established this run, so " +
        "the pool could not be counted. It is not reported as zero.",
    );
  } else {
    const assigned = [...poolByIssue.values()].filter(
      (issue) => issue.assignees.length > 0,
    ).length;
    const offerable = poolByIssue.size - assigned;

    lines.push(
      `${offerable} issue(s) carry no hold label and no assignee, so \`claim.mjs\` can offer them.` +
        (assigned > 0
          ? ` A further ${assigned} carry no hold label but are still assigned, and are reported above as \`assigneeDrift\` — they read as claimable on the board and are offered to nobody.`
          : ""),
    );
  }

  lines.push("");
  lines.push("## Open pull requests (review.mjs check)");
  lines.push("");
  if (!prSummary.known) {
    lines.push(
      prSummary.skipped
        ? "Skipped (--skip-pr-checks)."
        : `Unknown: ${prSummary.reason}`,
    );
  } else if (prSummary.results.length === 0) {
    lines.push("No open pull requests.");
  } else {
    for (const result of prSummary.results) {
      lines.push(
        `- #${result.number} (${result.headRefName}): exit ${result.code ?? "?"} — ${result.meaning}`,
      );
    }
  }

  lines.push("");
  lines.push("## Session leases (already dispatched)");
  lines.push("");
  lines.push(...formatLeases({ leases, prs }));

  return lines.join("\n");
};

/**
 * @param {{
 *   argv?: string[],
 *   config: {
 *     labels: {
 *       claimed: string,
 *       blocked?: string,
 *       changesRequested?: string,
 *       deferred?: string,
 *     },
 *     branchPrefix: string,
 *     claimRefPrefix: string,
 *     sessionRefPrefix: string,
 *     staleClaimHours: number,
 *     integrationBranch?: string | null,
 *     promotionBranch?: string | null,
 *   },
 *   gh: (...args: string[]) => string,
 *   git?: ((args: string[], options?: { cwd?: string }) => string) | null,
 *   checkPullRequest: (pr: number) => { code: number | null, output: string },
 *   stdout?: (line: string) => void,
 *   stderr?: (line: string) => void,
 *   now?: () => number,
 * }} input
 * @returns {number} Process exit code.
 */
export const report = ({
  argv = [],
  config,
  gh,
  git = null,
  checkPullRequest,
  stdout = console.log,
  stderr = console.error,
  now = () => Date.now(),
}) => {
  const args = parseArgs(argv);

  if (!args.ok) {
    stderr(USAGE);
    return EXIT.usage;
  }

  const repository = JSON.parse(gh("repo", "view", "--json", "nameWithOwner"))
    .nameWithOwner;

  // One instant for the whole survey. A report is a snapshot, and two sections
  // aged against two different clock reads would be two snapshots.
  const at = now();

  const refs = listReservationRefs(gh, repository, config.claimRefPrefix);
  const claimed = listIssuesByLabel(gh, config.labels.claimed);
  const openIssues = listOpenIssues(gh);
  const prs = openPullRequests(gh);
  const closedStatus = listClosedIssuesWithStatusLabels(
    gh,
    statusLabelNames(config),
  );
  const assignedOpen = listAssignedOpenIssues(gh);
  const blocked = config.labels.blocked
    ? listBlockedIssues(gh, config.labels.blocked)
    : null;

  // Fetching reviews is a per-PR network call, the same cost `checkPullRequest`
  // already pays below, so it is skipped by the same flag.
  const reviewsByPr = args.skipPrChecks
    ? null
    : new Map(
        prs.ok
          ? prs.items.map((pull) => [
              pull.number,
              pullRequestReviews(gh, repository, pull.number),
            ])
          : [],
      );

  // One `matching-refs` call establishes the whole session namespace; the
  // per-lease commit reads behind it resolve each lease's dispatch time and
  // head, and are bounded by the number of sessions actually in flight. This
  // stays inside the read-only contract: nothing here creates, updates, or
  // deletes a ref.
  const leases = summarizeLeases({
    leases: readLeases(gh, repository, config.sessionRefPrefix),
    prs,
    now: at,
    staleClaimHours: config.staleClaimHours,
  });

  // Read lazily, per issue, and only for the claims that reach the staleness
  // question at all \u2014 `git worktree list` plus a couple of `rev-list` calls per
  // worktree is cheap, but running it over every claimed issue would not be.
  // Absent `git` (a caller that injected none) the classification says so in
  // its own wording rather than pretending the check ran.
  const localWork = git
    ? /** @param {string} issue */ (issue) =>
        localIssueWork({
          git,
          issue,
          branchPrefix: config.branchPrefix,
          integrationBranch: config.integrationBranch ?? "main",
        })
    : null;

  const {
    disagreements,
    unknowns,
    refByIssue,
    claimedByIssue,
    poolByIssue,
    claimCandidates,
    localWorkHeld,
    claimsInFlight,
  } = classify({
    config,
    now: at,
    refs,
    claimed,
    openIssues,
    prs,
    reviewsByPr,
    closedStatus,
    assignedOpen,
    localWork,
    // Strongly consistent, and called only for an issue the listings have
    // already put under suspicion — one call per disagreement, not per issue
    //.
    confirmIssue: /** @param {string} issue */ (issue) => viewIssue(gh, issue),
    blocked,
    blockerState: /** @param {string[]} blockers */ (blockers) =>
      readBlockerStates({ gh, blockers }),
  });
  /** @type {PullRequestSummary} */
  const prSummary = args.skipPrChecks
    ? { known: false, skipped: true, reason: "skipped via --skip-pr-checks" }
    : summarizePullRequests({ prs, checkPullRequest });

  const allUnknowns = [...unknowns, ...leaseUnknowns(leases)];

  stdout(
    args.json
      ? JSON.stringify(
          {
            disagreements,
            claimCandidates,
            localWorkHeld,
            claimsInFlight,
            unknowns: allUnknowns,
            claimablePool: openIssues.ok
              ? [...poolByIssue.values()].filter(
                  (issue) => issue.assignees.length === 0,
                ).length
              : null,
            // `refName` is the one field both halves of a `ResolvedLease`
            // carry; an unreadable lease has no agent to report, and saying so
            // is the point rather than a gap to fill in.
            leases: leases.known
              ? leases.items.map((lease) => ({
                  ref: lease.refName,
                  agent: lease.readable ? lease.agent : null,
                  state: lease.state.kind,
                }))
              : { known: false, reason: leases.reason },
          },
          null,
          2,
        )
      : formatReport({
          disagreements,
          unknowns: allUnknowns,
          refByIssue,
          claimedByIssue,
          poolByIssue: openIssues.ok ? poolByIssue : null,
          prSummary,
          leases,
          prs,
          localWorkHeld,
          claimsInFlight,
        }),
  );

  if (disagreements.length > 0) return EXIT.disagreements;
  if (allUnknowns.length > 0) return EXIT.unknown;
  return EXIT.ok;
};

export default report;

// The synchronous request runner the API transport is built on, plus the rules
// for deciding whether this environment has a credential worth sending.
//
// Kept apart from `api.mjs` so the transport's translation rules can be tested
// with a stub and no test can reach the network by importing one of them.

import { execFileSync } from "node:child_process";
import process from "node:process";

// What a GitHub credential looks like: the `gh*_` prefixed tokens GitHub issues
// today, the newer fine-grained form, or a classic 40-character hex PAT.
//
// This is a check for "is this a credential", not for "is this valid". It exists
// because environments hand these variables placeholder values — this one sets
// `GH_TOKEN=proxy-injected` — and sending a placeholder as a Bearer token turns a
// clear authorization failure into a misleading `401 Bad credentials`.
const TOKEN = /^(?:gh[pousr]_[A-Za-z0-9]{16,}|github_pat_[A-Za-z0-9_]{16,}|[0-9a-f]{40})$/;

/** @param {string | undefined} candidate */
export const looksLikeToken = (candidate) => TOKEN.test(candidate ?? "");

/**
 * The credential to send, or the empty string when there is none worth sending.
 * An empty string is not a failure: an environment may authenticate the request
 * some other way, and if nothing does, GitHub says so in a way worth reading.
 *
 * @param {Record<string, string | undefined>} [env]
 */
export const credential = (env = process.env) =>
  [env.GH_TOKEN, env.GITHUB_TOKEN].find(looksLikeToken) ?? "";

/**
 * `owner/repo` for the checkout this command runs in.
 *
 * `gh` infers this from the git remote, so this does too rather than requiring
 * configuration. The remote may be rewritten by a proxy — an agent session sees
 * `http://127.0.0.1:PORT/git/OWNER/REPO` — so the last two path segments are
 * what identify the repository, not the host.
 *
 * @param {{ env?: Record<string, string | undefined>, remote?: string }} [input]
 * @returns {string} `owner/repo`, or the empty string when it cannot be read.
 */
export const repositoryFrom = ({ env = process.env, remote } = {}) => {
  if (env.GITHUB_REPOSITORY) return env.GITHUB_REPOSITORY;

  const url = remote ?? "";
  const segments = url
    .replace(/\.git$/, "")
    .replace(/^git@[^:]+:/, "")
    .split("/")
    .filter((segment) => segment !== "");

  return segments.length >= 2 ? segments.slice(-2).join("/") : "";
};

/**
 * A `request` for `createTransport` that performs each call in a child process.
 *
 * @param {{
 *   token?: string,
 *   baseUrl?: string,
 *   timeoutMs?: number,
 * }} [options]
 * @returns {(call: { method: string, path: string, body?: unknown }) => { status: number, body: unknown, nextPath?: string | null }}
 */
export const syncRequest = ({ token, baseUrl, timeoutMs = 30_000 } = {}) => {
  const runner = new URL("./fetch-once.mjs", import.meta.url).pathname;

  return (call) => {
    try {
      const output = execFileSync(process.execPath, [runner], {
        input: JSON.stringify({
          ...call,
          baseUrl,
          token: token ?? credential(),
        }),
        encoding: "utf8",
        timeout: timeoutMs,
        // Node's built-in fetch ignores HTTPS_PROXY unless asked. Every agent
        // session routes outbound HTTPS through one, so without this the request
        // times out rather than failing usefully.
        env: { ...process.env, NODE_USE_ENV_PROXY: "1" },
        // The child's stderr is captured rather than inherited: proxy support is
        // still flagged experimental, so it emits a warning on every request, and
        // a claim makes several. It is surfaced below when it is actually needed.
        stdio: ["pipe", "pipe", "pipe"],
      });

      return JSON.parse(output);
    } catch (error) {
      // A child that could not complete is a transport failure, not an HTTP
      // result — an HTTP refusal exits 0 and is reported as a status. Keep
      // whatever it managed to say: this is the layer where a proxy or a TLS
      // problem surfaces, and those are diagnosed from the child's own words.
      const said = /** @type {{ stderr?: string }} */ (error).stderr?.trim();

      throw new Error(
        `Could not reach the GitHub API for ${call.method} ${call.path}` +
          (said ? `:\n${said}` : `: ${String(error)}`),
      );
    }
  };
};

export default syncRequest;

// The single authority for `review.mjs`'s exit codes.
//
// Exit codes are a public interface in this loop: the merge gate branches on
// them, `report.mjs` turns them into an orchestrator survey line, and
// a merge audit can turn them into a clean/flagged verdict about a merge that
// already happened. They are easily enumerated in several independent places
// with nothing keeping them in step:
//
//   1. `EXIT` in `.rallypoint/scripts/review.mjs` — the authority, but a
//      module-private const no consumer could read
//   2. `docs/AGENT_LOOP.md`'s "Review" exit-code table (prose)
//   3. `.rallypoint/roles/merger.md`'s exit-code table (prose)
//   4. `CHECK_MEANINGS` in `lib/report.mjs` (consumer)
//   5. any further consumer a repository adds
//
// What that cost, in practice: a new code — contested approve — shipped into
// `EXIT` and into both prose tables and reached *no* consumer. Each fell through
// to its undocumented-code branch and failed closed as `unknown`, so a properly
// reviewed merge, whose approve had explicitly superseded an earlier dissent,
// was labelled unreviewed, and orchestrator surveys reported it as an unknown
// state. Nothing failed loudly: an unmapped code has a perfectly
// reasonable-looking fallback, which is exactly what makes this drift silent.
//
// This module is the structural fix. `review.mjs` derives its `EXIT` from the
// table below rather than declaring one, every consumer is asserted exhaustive
// over it, and the prose tables are asserted to list exactly the codes it
// defines. Adding a code here is what makes the suite name every consumer and
// document still owing it a decision.
//
// **What this deliberately does not centralise is the wording.** Each consumer
// phrases a code for its own audience — `report.mjs` for an orchestrator
// deciding whether to dispatch a merger, a merge audit for an after-the-fact
// judgement on a merge — and the `meaning` field here is a third
// phrasing, for the prose tables and for anyone reading this file. Folding them
// into one shared sentence would flatten distinctions the codes exist to carry:
// `5` and `11` differ by "nobody reviewed this" versus "a reviewer asked for
// changes and nothing addressed them", and the audit says so at length where the
// survey says it in six words. What is derived is *exhaustiveness*, not strings.
//
// Codes `69` (a missing `gh`) and `75` (a stale checkout) are deliberately
// absent: they sit outside every exit table in `docs/AGENT_LOOP.md` by design,
// far enough clear that adding a code here cannot collide with them. See that
// document's "Prerequisites" section.

/**
 * One exit code `review.mjs` can answer with.
 *
 * `key` is the name `review.mjs`'s `EXIT` map exposes it under, and is absent
 * for `0` alone — success is `process.exit(0)`, never `EXIT.something`.
 *
 * `owner` is which subcommand can produce it: `record`, `check`, or `both`. It
 * is what `docs/AGENT_LOOP.md`'s table prints in its Command column, and what
 * keeps a reader from looking for `12` in a `check` consumer.
 *
 * `checkVerdict` is narrower and is the field the exhaustiveness assertions
 * read: true when the code is an answer `check` gives *about a pull request's
 * review state*, which a consumer of `check` results must therefore have decided
 * what to do with. `1` is owned by both subcommands and is not one — it is a
 * usage error in the caller's own invocation, not a verdict about the pull
 * request — so a consumer may map it or not, as it prefers.
 *
 * @typedef {{
 *   code: number,
 *   key?: string,
 *   owner: "record" | "check" | "both",
 *   checkVerdict: boolean,
 *   meaning: string,
 * }} ReviewExitCode
 */

/** @type {readonly ReviewExitCode[]} */
export const REVIEW_EXIT_CODES = Object.freeze([
  {
    code: 0,
    owner: "both",
    checkVerdict: true,
    meaning: "success; for `check`, an independent approve at the current head",
  },
  {
    code: 1,
    key: "usage",
    owner: "both",
    checkVerdict: false,
    meaning: "usage error",
  },
  {
    code: 2,
    key: "unidentifiable",
    owner: "record",
    checkVerdict: false,
    meaning: "no `Closes #<issue>` reference resolving an authoring session, or no claim comment on one",
  },
  {
    code: 3,
    key: "selfReview",
    owner: "record",
    checkVerdict: false,
    meaning: "refused: the reviewer claimed the linked issue",
  },
  {
    code: 4,
    key: "staleLabel",
    owner: "check",
    checkVerdict: true,
    meaning: "stale `review:approved` left in place; rerun with `--strip-stale`",
  },
  {
    code: 5,
    key: "noVerdict",
    owner: "check",
    checkVerdict: true,
    meaning: "no approve verdict at the current head",
  },
  {
    code: 6,
    key: "selfApproved",
    owner: "check",
    checkVerdict: true,
    meaning: "the approve at the head came from the branch author, or a subagent it dispatched",
  },
  {
    code: 7,
    key: "unknownAuthor",
    owner: "check",
    checkVerdict: true,
    meaning: "author unidentifiable, so independence cannot be established",
  },
  {
    code: 8,
    key: "unreadable",
    owner: "check",
    checkVerdict: true,
    meaning: "hand-recorded verdict at the head this script cannot read",
  },
  {
    code: 9,
    key: "raced",
    owner: "record",
    checkVerdict: false,
    meaning: "the branch moved while the verdict was being written; nothing kept",
  },
  {
    code: 10,
    key: "carriedApprove",
    owner: "check",
    checkVerdict: true,
    meaning: "carried: no verdict at the head, but an approve carries forward",
  },
  {
    code: 11,
    key: "carriedRequestChanges",
    owner: "check",
    checkVerdict: true,
    meaning: "carried: no verdict at the head, but a request-changes carries forward",
  },
  {
    code: 12,
    key: "contested",
    owner: "record",
    checkVerdict: false,
    meaning: "refused: an unsuperseded request-changes from a different reviewer sits at this head",
  },
  {
    code: 13,
    key: "contestedApprove",
    owner: "check",
    checkVerdict: true,
    meaning: "approved at the head, but the winning approve explicitly superseded a dissent",
  },
]);

/**
 * `review.mjs`'s `EXIT` map, derived rather than declared.
 *
 * `review.mjs` imports this instead of writing its own object literal, so the
 * table above cannot become a sixth copy of the codes it exists to be the
 * authority for. `0` has no key and is absent by construction: success is
 * `process.exit(0)`.
 *
 * @type {Readonly<Record<string, number>>}
 */
export const EXIT = Object.freeze(
  Object.fromEntries(
    REVIEW_EXIT_CODES.filter((entry) => entry.key !== undefined).map((entry) => [
      entry.key,
      entry.code,
    ]),
  ),
);

/**
 * Every code a consumer of `review.mjs check` results has to have an opinion
 * about, ascending. See `checkVerdict` on the typedef above for why `1` is not
 * among them.
 *
 * @type {readonly number[]}
 */
export const CHECK_VERDICT_CODES = Object.freeze(
  REVIEW_EXIT_CODES.filter((entry) => entry.checkVerdict).map((entry) => entry.code),
);

/** @type {readonly number[]} */
export const ALL_EXIT_CODES = Object.freeze(REVIEW_EXIT_CODES.map((entry) => entry.code));

/**
 * Asserts that a consumer's table of `check` exit codes is exhaustive over this
 * authority, throwing with a message naming what is missing or stray.
 *
 * This is the guarantee an enumerated list does not have: a new code cannot exist without
 * every consumer of `check` results having to decide what it means. It fails on
 * the *next* code to be added, at the moment it is added, rather than at the
 * moment a real merge is misclassified because of it.
 *
 * Called from each consumer's unit test rather than at module load. Throwing at
 * import time would take out `report.mjs` and the merge audit — live coordination
 * tooling — over a bookkeeping omission, turning a silent misreport into an
 * outage. Where the unit suite runs in the gate every branch passes before it
 * reaches a reviewer, the omission is caught before it ships either way.
 *
 * A consumer may map codes beyond the required set — `report.mjs` maps `1`,
 * because a survey wants to say "usage error calling review.mjs check" rather
 * than "undocumented exit code 1" — but every code it maps must be one this
 * authority defines. A mapping for a code that does not exist is as much a sign
 * of drift as a missing one.
 *
 * @param {Record<number | string, unknown>} mapping
 * @param {string} label how to name the mapping in a failure message
 * @returns {void}
 */
export const assertExhaustiveCheckMapping = (mapping, label) => {
  const mapped = new Set(Object.keys(mapping).map(Number));

  const missing = CHECK_VERDICT_CODES.filter((code) => !mapped.has(code));
  if (missing.length > 0) {
    throw new Error(
      `${label} does not map \`review.mjs check\` exit code(s) ${missing.join(", ")}. ` +
        "An unmapped code falls through to an `unknown` fallback that looks reasonable and is wrong — " +
        "Add each one to this consumer, in its own words.",
    );
  }

  const stray = [...mapped].filter((code) => !ALL_EXIT_CODES.includes(code)).sort((a, b) => a - b);
  if (stray.length > 0) {
    throw new Error(
      `${label} maps exit code(s) ${stray.join(", ")}, which \`review.mjs\` does not define. ` +
        "Remove them, or add them to REVIEW_EXIT_CODES if they are real.",
    );
  }
};

/**
 * Narrows a Markdown document to one `## ` section, by heading text.
 *
 * `docs/AGENT_LOOP.md` carries three separate exit-code tables — `freshness.mjs`
 * answers `0`-`4`, `lease.mjs` answers `0`-`5`, and `review.mjs` answers
 * `0`-`13` — all in the same shape. Reading exit codes out of that document
 * without slicing first would silently union all three and pass whatever it was
 * asked, which is the opposite of what a coupling test is for. Returns `null`
 * when the heading is absent, so a caller reports a missing section rather than
 * asserting over an empty string.
 *
 * `### ` subsections are kept: the Review section's carried-verdict, contested,
 * promotion, and Dependabot subsections all qualify what the table means, and
 * none of them starts a table of its own.
 *
 * @param {string} markdown
 * @param {string} heading exact `## ` heading text, without the marker
 * @returns {string | null}
 */
export const sliceSection = (markdown, heading) => {
  const lines = markdown.split("\n");
  const start = lines.findIndex((line) => line.trim() === `## ${heading}`);
  if (start === -1) {
    return null;
  }

  const rest = lines.slice(start + 1);
  const end = rest.findIndex((line) => line.startsWith("## "));
  return (end === -1 ? rest : rest.slice(0, end)).join("\n");
};

/**
 * Extracts the exit codes a prose table lists, from a Markdown document.
 *
 * `docs/AGENT_LOOP.md` and `.rallypoint/roles/merger.md` both carry a
 * hand-maintained table of these codes, and both are read by agents as
 * specifications — `merger.md`'s in particular is what a merger session branches
 * on when deciding whether to merge. Neither was compared against anything
 * Slice with `sliceSection` first where the document holds more
 * than one exit-code table.
 *
 * The shape both tables share is a leading cell holding nothing but a
 * backticked number, which is what this matches. Anchored to the start of a line
 * so that a `13` appearing mid-sentence in surrounding prose is not read as a
 * table row.
 *
 * @param {string} markdown
 * @returns {number[]} ascending, deduplicated
 */
export const exitCodesInProseTable = (markdown) => {
  const codes = new Set(
    [...markdown.matchAll(/^\|\s*`(\d+)`\s*\|/gmu)].map((match) => Number(match[1])),
  );
  return [...codes].sort((a, b) => a - b);
};

#!/usr/bin/env node

// Reports whether the current branch and a prepared pull request body would
// let `review.mjs record` resolve an authoring session. The decision lives in
// `lib/preflight.mjs`; this file supplies argv, the parsed config, and real
// `git`/`gh`. Strictly read-only: it renames no branch, edits no body, and
// opens nothing.

import process from "node:process";

import { preflight } from "./lib/preflight.mjs";
import { gh, git, loadConfig } from "./lib/gh.mjs";

process.exit(
  preflight({ argv: process.argv.slice(2), config: loadConfig(), git, gh }),
);

// Who authored the branch under review.
//
// Split out of `review.mjs` so the rules that identify a pull request's author
// are testable without a live `gh`. Nothing in this loop gates on that
// identity anymore — any claimed session may review any pull request,
// including one it authored — but the identity itself still matters: it is
// what a request-changes verdict is traced back to when deciding who should
// pick up the fix, and what `reconcile.mjs`/`preflight.mjs` exist to recover
// or predict.

// GitHub's closing keywords. Anchored to the start of a line, with an optional
// list marker, so a reference inside prose ("this closes #999 in spirit")
// cannot be mistaken for the real link. `\b` rather than an end-of-line anchor,
// because the loop's own convention writes "Closes #104. Refs #80, #83."
export const CLOSING_KEYWORD =
  /^[^\S\n]*[-*]?[^\S\n]*(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)[^\S\n]+#(\d+)\b/gim;

// Code in a pull request body is illustration, not instruction. This
// repository's own PR bodies quote the `Closes #<issue>` convention, and
// counting those references would refuse the pull request as ambiguous.
//
// Fenced regions only. Blanking indented lines as well would also blank
// markdown list continuations, refusing a legitimately formatted body — the
// same failure shape as an over-tight anchor. The line-start keyword anchor
// already excludes prose, and a decoy reference is author-controlled and
// caught by the branch cross-check.
//
// `lib/blocked-by.mjs` briefly imported this to decide which text in an
// **issue** body is live, and does not any more. Not because a second
// stripper is cheap — it is not — but because the two callers want different
// answers, and asking one function for both is what produced three consecutive
// fail-open holes there. This helper answers "give me the body with code taken
// out, to scan for a keyword", so it **removes** the region; that caller
// anchors a pattern to a line start, and a removal joins the text either side
// of it and invents line starts the body never had. It also needs the two
// exclusions below to go the other way — an unterminated fence and an HTML
// comment must hide their contents when a label edit is at stake, and must not
// when a `Closes #<issue>` line is. So it scans the body's own lines itself
// and states its reach there. Keep this helper's contract as it is rather than
// widening it back toward that caller's.
//
// A fence that is never closed leaves its contents live, here as everywhere
// else this regex is used. That is a known limit rather than an oversight, but
// not for want of a definition: CommonMark ends an unterminated fence at the end
// of the document, so matching it would be a one-character change. What that
// costs is the reason it is not made — `linkedIssues` reads closing keywords out
// of every pull request body through this helper, and a single stray ``` in a
// body would then blank everything after it, silently dropping the
// `Closes #<issue>` line the whole coordination loop is built on. Leaving the
// tail live fails closed for that caller; blanking it does not. It is why every
// caller pairs this with an anchor tight enough that ordinary prose cannot match
// on its own.
/** @param {string | null | undefined} body */
const withoutCode = (body) =>
  (body ?? "").replace(/^[^\S\n]*(```|~~~)[\s\S]*?^[^\S\n]*\1/gm, "");

// `claim.mjs` always writes this as the first line of the claim comment.
// Anchored to the start of the body: an unanchored match would let a later
// comment quoting a forged claim take precedence under last-wins.
export const CLAIM = /^Claimed by Rallypoint agent `([^`\n]+)`/;

// Agent ids land in a verdict block, where a newline or a comment terminator
// would truncate the recorded value and make it differ from the id the guard
// actually checked.
export const SAFE_AGENT_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

/** @param {string | null | undefined} body */
export const linkedIssues = (body) => [
  ...new Set(
    [...withoutCode(body).matchAll(CLOSING_KEYWORD)].map((match) => match[1]),
  ),
];

// One issue or nothing. Several distinct references is an ambiguity to refuse,
// not one to resolve by picking.
/** @param {string | null | undefined} body */
export const linkedIssue = (body) => {
  const issues = linkedIssues(body);
  return issues.length === 1 ? issues[0] : null;
};

// The last claim wins: the janitor releases stale claims, so an issue can be
// re-claimed and the second claimant is the one that authored the branch.
/** @param {{ body?: string | null }[]} comments */
export const claimant = (comments) =>
  comments
    .flatMap((comment) => (comment.body ?? "").match(CLAIM)?.at(1) ?? [])
    .at(-1) ?? null;

// `claim.mjs` encodes the claimed issue in the branch name. That is a stronger
// signal of authorship than the pull request body, which can be edited after
// the fact.
/**
 * @param {string | null | undefined} headRefName
 * @param {string} prefix
 */
export const branchIssue = (headRefName, prefix) => {
  const escaped = prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return headRefName?.match(new RegExp(`^${escaped}(\\d+)-`))?.[1] ?? null;
};

// Which open pull requests reference an issue, by the issue number `claim.mjs`
// encodes into the branch name or by a closing keyword in the body.
//
// This lives here, next to `branchIssue` and `linkedIssues`, because it is the
// same pair of signals `review.mjs` reads and every caller needs to read them
// identically: `claim.mjs` refuses a candidate an open pull request already
// covers, `report.mjs` classifies that state as `unclaimedWithOpenPr` or
// `unreservedWithOpenPr` depending on whether a claim comment is there to read
//, and `reconcile.mjs` recovers the first of the two. Three copies of
// the predicate is exactly how
// those three answers drift apart from each other and from `record`'s.
/**
 * @template {{ headRefName?: string | null, body?: string | null }} Pull
 * @param {{ pulls: Pull[], issue: string, branchPrefix: string }} input
 * @returns {Pull[]}
 */
export const referencingPullRequests = ({ pulls, issue, branchPrefix }) =>
  pulls.filter(
    (pull) =>
      branchIssue(pull.headRefName, branchPrefix) === issue ||
      linkedIssues(pull.body).includes(issue),
  );

// Every issue whose claim comment could name this branch's author.
//
// A pull request may legitimately close more than one issue, commonly when
// the second has been folded into the first by
// operator decision — and `record` used to refuse such a pull request outright
// as ambiguous, leaving a completed review with nowhere to put its verdict
//. The ambiguity was real but the refusal was aimed at the wrong
// question: the guard exists to stop a session approving its own work, and
// that needs the *set* of agent ids that claimed any referenced issue, not a
// single issue to name.
//
// So this returns the set, and the self-review guard refuses if the reviewer
// appears anywhere in it. What stays refused is a body that points somewhere
// else entirely: if the branch names an issue, the body's closing keywords
// must include it, because pointing `Closes` exclusively at a stranger's issue
// would compare the reviewer against a stranger's claim — a bypass needing no
// forgery at all.
/**
 * @param {{
 *   linkedIssues: string[],
 *   branchIssue: string | null,
 * }} input
 * @returns {{ ok: true, issues: string[] } | { ok: false, reason: "mismatch" | "unidentifiable" }}
 */
export const authorshipIssues = ({ linkedIssues, branchIssue }) => {
  if (
    branchIssue &&
    linkedIssues.length > 0 &&
    !linkedIssues.includes(branchIssue)
  ) {
    return { ok: false, reason: "mismatch" };
  }

  const issues = [
    ...new Set([...(branchIssue ? [branchIssue] : []), ...linkedIssues]),
  ];

  return issues.length > 0
    ? { ok: true, issues }
    : { ok: false, reason: "unidentifiable" };
};

// Which single issue a label should be reconciled against.
//
// `record` used to hard-require a `Closes #<issue>` reference and exit before
// consulting the branch name at all, so a pull request whose branch
// unambiguously names its issue was un-reviewable when its body said `Refs #N`
// instead. That is a legitimate shape: partial deliveries that
// deliberately do not close their issue, and the protocol does not forbid it
//.
//
// The branch name is the stronger signal — `claim.mjs` writes it at claim time
// and nobody can edit it afterwards — so it is enough on its own. What stays
// refused is anything genuinely ambiguous, because resolving ambiguity by
// picking is how a reviewer ends up compared against a stranger's claim.
/**
 * @param {{
 *   linkedIssues: string[],
 *   branchIssue: string | null,
 * }} input
 * @returns {{ ok: true, issue: string } | { ok: false, reason: "ambiguous-body" | "mismatch" | "unidentifiable" }}
 */
export const recordableIssue = ({ linkedIssues, branchIssue }) => {
  const authorship = authorshipIssues({ linkedIssues, branchIssue });

  if (!authorship.ok) return authorship;

  // The branch name settles it whenever it is there: `authorshipIssues` has
  // already established the body does not point away from it.
  if (branchIssue) return { ok: true, issue: branchIssue };

  // No branch issue and several closing keywords: the set is known but which
  // one a *label* belongs on is not, and picking is how a label lands on a
  // stranger's issue. `record` no longer refuses this shape — it checks the
  // whole set — but the issue-side `status:changes-requested` reconciliation
  // has no answer here and deliberately does nothing.
  return authorship.issues.length === 1
    ? { ok: true, issue: authorship.issues[0] }
    : { ok: false, reason: "ambiguous-body" };
};

// A promotion pull request's head branch IS an integration/promotion branch —
// `release` -> `staging`, or `staging` -> `main` — rather than an
// individually claimed `agent/<issue>-slug` branch. Nobody runs `claim.mjs`
// against a promotion, so it carries no `Closes #<issue>` reference and no
// claim comment, and `recordableIssue`/`claimant` above have nothing to read.
// That is not an error to refuse; it is a different pull request shape that
// needs its own path through `record`/`check`.
//
// A promotion also has a second, **snapshot** head shape:
// `promotion/<snapshotted branch>-<suffix>`, e.g.
// `promotion/release-2026-08-09`, pinned at one commit of `release`. A
// promotion whose head IS `release` moves every time anything merges into
// `release`; each head move cancels the CI run and re-queues it from the back,
// and voids any recorded verdict, since promotions deliberately get no
// carried-verdict treatment. A pinned snapshot fixes both.
//
// Recognition of that shape is **conjunctive, and never by branch name alone**
// — the same rule the Dependabot note below states, and for the same reason. A
// bare `startsWith("promotion/")` would be a self-review bypass: any session
// could name its branch `promotion/anything`, open it against `staging`, and
// skip both the authoring-issue resolution and the independence guarantee. So
// all three must hold:
//
//   1. the head parses as `promotion/<snapshotted>-<suffix>`, where
//      `<snapshotted>` is `integrationBranch` or `promotionBranch`;
//   2. the base is neither `integrationBranch` nor the snapshotted branch
//      itself — a promotion moves work *up* the chain, so a `promotion/*` head
//      opened against `release` is an ordinary pull request wearing a costume;
//   3. the head commit is genuinely contained in the branch it claims to
//      snapshot, which the caller establishes through `containedIn`.
//
// (3) is what makes the name unforgeable: a snapshot of `release` holds by
// definition no commit that is not already on `release`, so arbitrary content
// cannot ride in under a promotion-shaped name. Without evidence the snapshot
// shape is **not** recognised — this fails closed, so a caller that cannot
// verify containment simply keeps the old exact-name behaviour rather than
// granting an unproven exemption.
//
// `baseRefName: null` means the caller has no base in view at all (there is no
// pull request), which only `freshness.mjs` does. That is not a weakening: a
// base nobody has stated is a base nobody can forge, and containment is still
// required there.

// The prefix is `promotionSnapshotPrefix` in `.rallypoint/config.json`, with
// this as the fallback for a config that does not set it. Reading it
// from configuration changes no guarantee above: the prefix establishes only
// condition 1, and conditions 2 and 3 are what the exemption actually rests on.
// `validateConfig` rejects a prefix overlapping `branchPrefix` in either
// direction, so configuration cannot make a claimed `agent/*` branch parse as a
// snapshot head. A non-string or empty value here falls back rather than
// matching everything — an empty prefix would make every branch name a
// candidate for condition 1.
const DEFAULT_SNAPSHOT_PREFIX = "promotion/";

/**
 * The branch a `<promotionSnapshotPrefix><snapshotted>-<suffix>` head claims to
 * snapshot, or `null` when the head is not that shape. Pure string parsing — it
 * establishes only condition 1 above and proves nothing on its own.
 *
 * @param {string | null | undefined} headRefName
 * @param {{
 *   integrationBranch?: string | null,
 *   promotionBranch?: string | null,
 *   promotionSnapshotPrefix?: string | null,
 * }} config
 * @returns {string | null}
 */
export const snapshottedBranch = (headRefName, config) => {
  if (typeof headRefName !== "string") return null;

  const prefix =
    typeof config.promotionSnapshotPrefix === "string" &&
    config.promotionSnapshotPrefix !== ""
      ? config.promotionSnapshotPrefix
      : DEFAULT_SNAPSHOT_PREFIX;

  if (!headRefName.startsWith(prefix)) return null;

  const rest = headRefName.slice(prefix.length);

  for (const branch of [config.integrationBranch, config.promotionBranch]) {
    if (typeof branch !== "string" || branch === "") continue;
    // `<snapshotted>-<suffix>` with a non-empty suffix. A bare
    // `promotion/release` names no snapshot instant and is not the shape.
    if (rest.startsWith(`${branch}-`) && rest.length > branch.length + 1) {
      return branch;
    }
  }

  return null;
};

/**
 * @param {string | null | undefined} headRefName
 * @param {{
 *   integrationBranch?: string | null,
 *   promotionBranch?: string | null,
 *   promotionSnapshotPrefix?: string | null,
 * }} config
 * @param {{
 *   baseRefName: string | null,
 *   containedIn: (branch: string) => boolean,
 * }} [evidence] Omit where the caller cannot establish containment: the
 *   snapshot shape is then not recognised, and the exact-name behaviour is
 *   unchanged.
 */
export const isPromotionBranch = (headRefName, config, evidence) => {
  if (headRefName == null) return false;

  if (headRefName === config.integrationBranch) return true;
  if (config.promotionBranch != null && headRefName === config.promotionBranch)
    return true;

  if (evidence == null || typeof evidence.containedIn !== "function")
    return false;

  const snapshotted = snapshottedBranch(headRefName, config);

  if (snapshotted == null) return false;

  const { baseRefName } = evidence;

  if (baseRefName != null) {
    if (baseRefName === config.integrationBranch) return false;
    if (baseRefName === snapshotted) return false;
  }

  return evidence.containedIn(snapshotted) === true;
};

// A Dependabot pull request has no authoring agent session at all.
// Nobody ran `claim.mjs`, there is no issue, and the head branch is
// `dependabot/npm_and_yarn/...` rather than an `agent/<issue>-slug` branch —
// so, exactly as for a promotion above, `recordableIssue`/`claimant` have
// nothing to read and the self-review guard has no worker identity to compare
// a reviewer against. Recognition is by **authorship**, never by the branch
// name: a branch name is not proof of authorship, and matching
// `dependabot/` alone would let any session acquire the bypass by naming its
// branch cleverly.
//
// The two transports report the author slightly differently, and this accepts
// both. `gh pr view --json author` strips the suffix and reports
// `{ login: "dependabot", is_bot: true }` — or `app/dependabot` in some
// versions — while the REST transport in `lib/api.mjs` maps GitHub's
// `user: { login: "dependabot[bot]", type: "Bot" }`. `is_bot` is required
// either way, so a human account registered under the login `dependabot`
// does not qualify.
const DEPENDABOT_LOGINS = new Set(["dependabot", "dependabot-preview"]);

/**
 * @param {unknown} author The `author` field of `gh pr view --json author`.
 */
export const isDependabotAuthor = (author) => {
  if (author == null || typeof author !== "object") return false;

  const { is_bot: isBot, login } = /** @type {{ is_bot?: unknown, login?: unknown }} */ (author);

  if (isBot !== true || typeof login !== "string") return false;

  return DEPENDABOT_LOGINS.has(
    login
      .toLowerCase()
      .replace(/^app\//, "")
      .replace(/\[bot\]$/, ""),
  );
};

